#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum KbuildProcfsReadClass {
    /// Global filesystem-type registry.
    Filesystems,
    /// Numeric process virtual-memory map.
    ProcessMaps,
    /// Numeric process memory-size counters.
    ProcessStatm,
    /// Numeric process cgroup membership.
    ProcessCgroup,
    /// Cgroup-v2 CPU quota controller value.
    CgroupCpuMax,
    /// Host virtual-memory overcommit policy.
    VmOvercommitMemory,
}

/// Sanitized procfs read counts for one owner, executable, and value class.
///
/// `action_index` is absent for the analyzer subtree. Executable paths and
/// procfs contents remain private; only domain-separated identities leave the
/// raw stream.
#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct KbuildProcfsReadGroup {
    action_index: Option<u64>,
    executable_digest: [u8; 32],
    class: KbuildProcfsReadClass,
    read_observations: u64,
    distinct_values: u64,
}

#[cfg(unix)]
impl KbuildProcfsReadGroup {
    /// Owning graph action, or `None` for analysis.
    pub fn action_index(self) -> Option<u64> {
        self.action_index
    }

    /// Domain- and stream-separated identity of exact executable path bytes.
    pub fn executable_digest(self) -> [u8; 32] {
        self.executable_digest
    }

    /// Recognized procfs observation class.
    pub fn class(self) -> KbuildProcfsReadClass {
        self.class
    }

    /// Successful unwitnessed reads in this group.
    pub fn read_observations(self) -> u64 {
        self.read_observations
    }

    /// Distinct `(byte count, content digest)` values in this group.
    pub fn distinct_values(self) -> u64 {
        self.distinct_values
    }
}

/// Exact, non-authorizing ownership census for recognized procfs read gaps.
///
/// Every unwitnessed regular-file read must belong to one group. File mappings,
/// directory enumerations, and unrecognized regular-file gaps still reject.
/// A boundary-crossing value is the same procfs class and value observed under
/// more than one analyzer/action ownership boundary. This seal diagnoses
/// policy scope; it cannot authorize snapshot admission or replay.
#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct KbuildProcfsReadCensusSeal {
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    census_digest: [u8; 32],
    read_observations: u64,
    analyzer_observations: u64,
    action_observations: u64,
    distinct_actions: u64,
    boundary_crossing_values: u64,
    groups: Vec<KbuildProcfsReadGroup>,
}

