#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct KbuildProcfsAnalysisWitnessSeal {
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    census_digest: [u8; 32],
    witness_digest: [u8; 32],
    read_observations: u64,
    distinct_values: u64,
    analysis_manifest: DependencyManifest,
}

