/// Complete-generation assertions reported by the Kbuild adapter.
///
/// Counts are observations, not unique paths, unless the field explicitly says
/// persistent paths. These values are cross-checked where independent evidence
/// exists, but are not themselves a capture-completeness certificate.
#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KbuildGraphCaptureCoverage {
    /// Complete process lifecycles observed by the adapter.
    pub process_lifecycles_observed: u64,
    /// Non-footer process-stream records observed by the adapter.
    pub stream_records_observed: u64,
    /// Stream records assigned a supported input, effect, or lifecycle meaning.
    pub stream_records_classified: u64,
    /// Kbuild command boundaries observed in the generation.
    pub command_boundaries_observed: u64,
    /// Observed command boundaries represented in `actions[*].commands`.
    pub command_boundaries_captured: u64,
    /// Logical actions represented after overlap coalescing.
    pub logical_actions_captured: u64,
    /// Kbuild receipts discovered for observed logical actions.
    pub receipts_discovered: u64,
    /// Discovered receipts ingested into represented actions.
    pub receipts_ingested: u64,
    /// Represented logical actions with no retained Kbuild receipt.
    pub receiptless_actions: u64,
    /// Unique definite-or-conservative mutation-candidate paths.
    ///
    /// The field name predates conservative `O_CREAT` candidate accounting;
    /// this count does not prove that every named path was changed.
    pub persistent_writes_observed: u64,
    /// Mutation-candidate paths assigned one represented owner.
    pub persistent_writes_attributed: u64,
    /// Observable records that the adapter could not classify safely.
    pub unmodeled_observations: u64,
}

#[cfg(unix)]
impl KbuildGraphCaptureCoverage {
    fn require_closed(self) -> Result<()> {
        require_equal_coverage(
            "classified stream records",
            self.stream_records_classified,
            self.stream_records_observed,
        )?;
        require_equal_coverage(
            "observed command boundaries",
            self.command_boundaries_observed,
            self.command_boundaries_captured,
        )?;
        require_equal_coverage(
            "discovered receipts",
            self.receipts_discovered,
            self.receipts_ingested,
        )?;
        let evidenced_boundaries = self
            .receipts_ingested
            .checked_add(self.receiptless_actions)
            .context("Kbuild evidenced logical-action count overflowed")?;
        require_equal_coverage(
            "receipt and receiptless logical actions",
            evidenced_boundaries,
            self.logical_actions_captured,
        )?;
        if self.logical_actions_captured == 0
            || self.logical_actions_captured > self.command_boundaries_captured
        {
            anyhow::bail!("Kbuild logical-action coverage is inconsistent");
        }
        require_equal_coverage(
            "observed mutation-candidate paths",
            self.persistent_writes_observed,
            self.persistent_writes_attributed,
        )?;
        if self.unmodeled_observations != 0 {
            anyhow::bail!(
                "Kbuild graph capture has {} unmodeled observations",
                self.unmodeled_observations
            );
        }
        Ok(())
    }

    fn require_complete(
        self,
        capture: &KbuildActionGraphCapture,
        stream: ProcessCaptureStreamSeal,
    ) -> Result<()> {
        self.require_closed()?;
        let action_count = u64::try_from(capture.actions.len())
            .context("Kbuild captured-action count does not fit u64")?;
        let command_count = capture.actions.iter().try_fold(0_u64, |count, action| {
            count
                .checked_add(
                    u64::try_from(action.commands.len())
                        .context("Kbuild captured-command count does not fit u64")?,
                )
                .context("Kbuild captured-command count overflowed")
        })?;
        require_equal_coverage(
            "captured command boundaries",
            self.command_boundaries_captured,
            command_count,
        )?;
        require_equal_coverage(
            "captured logical actions",
            self.logical_actions_captured,
            action_count,
        )?;
        let mut receipt_count = 0_u64;
        for (action_index, action) in capture.actions.iter().enumerate() {
            match action.receipt_path.as_ref() {
                None => {}
                Some(receipt_path)
                    if action.persistent_outputs.contains(receipt_path)
                        && native_adapter::is_command_receipt(receipt_path) =>
                {
                    receipt_count = receipt_count
                        .checked_add(1)
                        .context("Kbuild receipt-backed action count overflowed")?;
                }
                Some(receipt_path) if !action.persistent_outputs.contains(receipt_path) => {
                    anyhow::bail!(
                        "Kbuild action {action_index} names a command receipt outside its outputs"
                    );
                }
                Some(_) => {
                    anyhow::bail!(
                        "Kbuild action {action_index} designates a non-receipt output as its \
                         command receipt"
                    );
                }
            }
        }
        let receiptless_count = action_count
            .checked_sub(receipt_count)
            .context("Kbuild receipt-backed action count exceeds action count")?;
        require_equal_coverage(
            "receipt and receiptless logical actions",
            self.receipts_ingested
                .checked_add(self.receiptless_actions)
                .context("Kbuild evidenced logical-action count overflowed")?,
            action_count,
        )?;
        let persistent_paths = capture
            .actions
            .iter()
            .flat_map(|action| &action.persistent_outputs)
            .collect::<BTreeSet<_>>();
        let persistent_path_count = u64::try_from(persistent_paths.len())
            .context("Kbuild persistent-path count does not fit u64")?;
        require_equal_coverage(
            "process lifecycles",
            self.process_lifecycles_observed,
            stream.process_count(),
        )?;
        require_equal_coverage(
            "observed stream records",
            self.stream_records_observed,
            stream.record_count(),
        )?;
        require_equal_coverage(
            "captured receipt-backed logical actions",
            self.receipts_ingested,
            receipt_count,
        )?;
        require_equal_coverage(
            "captured receiptless logical actions",
            self.receiptless_actions,
            receiptless_count,
        )?;
        if self.persistent_writes_attributed < persistent_path_count {
            anyhow::bail!(
                "Kbuild graph capture attributed mutation-candidate paths coverage is {}/at \
                 least {persistent_path_count}",
                self.persistent_writes_attributed
            );
        }
        Ok(())
    }
}

#[cfg(unix)]
fn require_equal_coverage(description: &str, observed: u64, required: u64) -> Result<()> {
    if observed != required {
        anyhow::bail!("Kbuild graph capture {description} coverage is {observed}/{required}");
    }
    Ok(())
}

