#[cfg(unix)]
struct DigestingReader<R> {
    inner: R,
    hasher: blake3::Hasher,
    bytes: u64,
}

#[cfg(unix)]
impl<R> DigestingReader<R> {
    fn new(inner: R) -> Self {
        Self {
            inner,
            hasher: blake3::Hasher::new(),
            bytes: 0,
        }
    }

    fn finish(self) -> (R, [u8; 32], u64) {
        (self.inner, *self.hasher.finalize().as_bytes(), self.bytes)
    }
}

#[cfg(unix)]
impl<R: Read> Read for DigestingReader<R> {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        let bytes = self.inner.read(buffer)?;
        self.bytes = self
            .bytes
            .checked_add(u64::try_from(bytes).map_err(io::Error::other)?)
            .ok_or_else(|| io::Error::other("Kbuild graph byte count overflowed"))?;
        self.hasher.update(&buffer[..bytes]);
        Ok(bytes)
    }
}

#[cfg(unix)]
fn validate_private_capture_parent(path: &Path, description: &str) -> Result<()> {
    let parent = path
        .parent()
        .with_context(|| format!("{description} has no parent"))?;
    let metadata =
        std::fs::symlink_metadata(parent).with_context(|| format!("stat {description} parent"))?;
    if !metadata.file_type().is_dir() {
        anyhow::bail!("{description} parent is not a directory");
    }
    use std::os::unix::fs::MetadataExt as _;

    if metadata.uid() != nix::unistd::Uid::effective().as_raw() || metadata.mode() & 0o077 != 0 {
        anyhow::bail!("{description} parent is not owner-private");
    }
    Ok(())
}

#[cfg(unix)]
fn stable_capture_metadata(before: &std::fs::Metadata, after: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::MetadataExt as _;

    before.file_type().is_file()
        && after.file_type().is_file()
        && before.dev() == after.dev()
        && before.ino() == after.ino()
        && before.len() == after.len()
        && before.mode() == after.mode()
        && before.uid() == after.uid()
        && before.gid() == after.gid()
        && before.nlink() == after.nlink()
        && before.mtime() == after.mtime()
        && before.mtime_nsec() == after.mtime_nsec()
        && before.ctime() == after.ctime()
        && before.ctime_nsec() == after.ctime_nsec()
}

#[cfg(unix)]
fn load_kbuild_graph_capture(
    path: &Path,
    expected_digest: [u8; 32],
    max_graph_bytes: u64,
) -> Result<KbuildActionGraphCapture> {
    validate_private_capture_parent(path, "Kbuild graph capture")?;
    let mut options = OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;

        options.custom_flags(nix::libc::O_CLOEXEC | nix::libc::O_NOFOLLOW);
    }
    let file = options
        .open(path)
        .with_context(|| format!("open Kbuild graph capture {}", path.display()))?;
    let before = file.metadata().context("stat open Kbuild graph capture")?;
    use std::os::unix::fs::MetadataExt as _;

    if !before.file_type().is_file() {
        anyhow::bail!("Kbuild graph capture is not a regular file");
    }
    if before.uid() != nix::unistd::Uid::effective().as_raw()
        || before.mode() & 0o077 != 0
        || before.nlink() != 1
    {
        anyhow::bail!("Kbuild graph capture is not an owner-private single-link file");
    }
    if before.len() > max_graph_bytes {
        anyhow::bail!("Kbuild graph capture exceeds its regular-file budget");
    }
    let read_limit = max_graph_bytes
        .checked_add(1)
        .context("Kbuild graph byte budget overflowed")?;
    let mut reader = DigestingReader::new(file.take(read_limit));
    let capture: KbuildActionGraphCapture =
        serde_json::from_reader(&mut reader).context("decode observed Kbuild action graph")?;
    let (limited, digest, bytes) = reader.finish();
    let file = limited.into_inner();
    let after = file
        .metadata()
        .context("restat open Kbuild graph capture")?;
    if bytes != before.len() || !stable_capture_metadata(&before, &after) {
        anyhow::bail!("Kbuild graph capture changed while it was read");
    }
    if digest != expected_digest {
        anyhow::bail!("Kbuild graph capture digest does not match its envelope");
    }
    Ok(capture)
}

#[cfg(unix)]
#[derive(Debug)]
struct ExpectedInvocation {
    executable: Vec<u8>,
    argv: Vec<Vec<u8>>,
    environment: Vec<Vec<u8>>,
    working_directory: Vec<u8>,
}

#[cfg(unix)]
impl ExpectedInvocation {
    fn from_capture(invocation: &CapturedInvocation) -> Result<Self> {
        let executable =
            canonical_existing(&invocation.executable, "captured invocation executable")?;
        let working_directory = canonical_existing(
            &invocation.working_directory,
            "captured invocation directory",
        )?;
        let mut environment = Vec::with_capacity(invocation.environment.len());
        for variable in &invocation.environment {
            if variable.name.is_empty()
                || variable.name.contains(&0)
                || variable.name.contains(&b'=')
                || variable.value.contains(&0)
            {
                anyhow::bail!("captured invocation has an invalid environment entry");
            }
            let mut entry = Vec::with_capacity(variable.name.len() + 1 + variable.value.len());
            entry.extend_from_slice(&variable.name);
            entry.push(b'=');
            entry.extend_from_slice(&variable.value);
            environment.push(entry);
        }
        Ok(Self {
            executable: os_bytes(executable.as_os_str()),
            argv: invocation.argv.clone(),
            environment,
            working_directory: os_bytes(working_directory.as_os_str()),
        })
    }

    fn matches(&self, invocation: &rush_observe::CapturedInvocation) -> bool {
        self.executable == invocation.executable
            && self.argv == invocation.argv
            && self.environment == invocation.environment
            && self.working_directory == invocation.working_directory
    }
}

