#[cfg(unix)]
fn kbuild_executable_digest(stream_digest: [u8; 32], executable: &[u8]) -> Result<[u8; 32]> {
    let length = u64::try_from(executable.len())
        .context("Kbuild executable identity length does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-executable-identity.v1\0");
    hasher.update(&stream_digest);
    hasher.update(&length.to_le_bytes());
    hasher.update(executable);
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(unix)]
fn kbuild_cgroup_cpu_max_target(target: &[u8]) -> bool {
    let Some(relative) = target
        .strip_prefix(b"/sys/fs/cgroup/")
        .and_then(|relative| relative.strip_suffix(b"/cpu.max"))
    else {
        return false;
    };
    !relative.is_empty()
        && relative
            .split(|byte| *byte == b'/')
            .all(|component| !component.is_empty() && component != b"." && component != b"..")
}

#[cfg(unix)]
fn kbuild_procfs_read_class(target: &[u8]) -> Option<KbuildProcfsReadClass> {
    if target == b"/proc/filesystems" {
        return Some(KbuildProcfsReadClass::Filesystems);
    }
    if target == b"/proc/sys/vm/overcommit_memory" {
        return Some(KbuildProcfsReadClass::VmOvercommitMemory);
    }
    if kbuild_cgroup_cpu_max_target(target) {
        return Some(KbuildProcfsReadClass::CgroupCpuMax);
    }
    let relative = target.strip_prefix(b"/proc/")?;
    for (suffix, class) in [
        (b"/maps".as_slice(), KbuildProcfsReadClass::ProcessMaps),
        (b"/statm".as_slice(), KbuildProcfsReadClass::ProcessStatm),
        (b"/cgroup".as_slice(), KbuildProcfsReadClass::ProcessCgroup),
    ] {
        let Some(process) = relative.strip_suffix(suffix) else {
            continue;
        };
        if !process.is_empty() && process.iter().all(u8::is_ascii_digit) {
            return Some(class);
        }
    }
    None
}

#[cfg(unix)]
fn kbuild_procfs_self_descriptor(
    attempt: &rush_observe::CapturedOpenAttempt,
) -> Result<Option<(i32, KbuildProcfsSelfDescriptor)>> {
    let CapturedOpenOutcome::Opened {
        descriptor,
        identity,
        mount_id,
        ..
    } = &attempt.outcome
    else {
        return Ok(None);
    };
    let Some(class) = kbuild_procfs_read_class(&identity.target) else {
        return Ok(None);
    };
    let self_path = match class {
        KbuildProcfsReadClass::ProcessMaps => b"/proc/self/maps".as_slice(),
        KbuildProcfsReadClass::ProcessStatm => b"/proc/self/statm".as_slice(),
        KbuildProcfsReadClass::ProcessCgroup => b"/proc/self/cgroup".as_slice(),
        KbuildProcfsReadClass::Filesystems
        | KbuildProcfsReadClass::VmOvercommitMemory
        | KbuildProcfsReadClass::CgroupCpuMax => {
            return Ok(None)
        }
    };
    if identity.kind != CapturedDescriptorKind::RegularFile {
        return Ok(None);
    }
    let allowed_flags = u64::try_from(libc::O_LARGEFILE | libc::O_CLOEXEC)
        .context("Kbuild procfs open flags do not fit u64")?;
    let access_mask =
        u64::try_from(libc::O_ACCMODE).context("Kbuild procfs access mask does not fit u64")?;
    if !matches!(
        attempt.request.system_call,
        CapturedOpenSystemCall::Open | CapturedOpenSystemCall::OpenAt
    ) || attempt.request.path != self_path
        || attempt.request.directory.is_some()
        || attempt.request.flags & !allowed_flags != 0
        || attempt.request.flags & access_mask != 0
        || attempt.request.mode != 0
        || attempt.request.resolve != 0
        || *descriptor < 0
        || identity.inode == 0
        || *mount_id == 0
    {
        return Ok(None);
    }
    Ok(Some((
        *descriptor,
        KbuildProcfsSelfDescriptor {
            open_syscall_index: attempt.syscall_index,
            class,
            device: identity.device,
            inode: identity.inode,
            mount_id: *mount_id,
        },
    )))
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KbuildRecordClass {
    Lifecycle,
    Invocation,
    ExecAttempt,
    PathOpenAttempt,
    QueryOrReadAttempt,
    DescriptorStateAttempt,
    ProcessStateAttempt,
    SignalDelivery,
    CwdMutationAttempt,
    NamespaceMutationAttempt,
    MetadataMutationAttempt,
    MappingAttempt,
    WriteAttempt,
    UnmodeledSyscallAttempt,
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KbuildRecordOutcome {
    ProcessExitedZero,
    ProcessExitedNonzero,
    ProcessSignaled,
    AttemptSucceeded(KbuildRecordClass),
    AttemptFailed(KbuildRecordClass),
    AttemptTerminated(KbuildRecordClass),
}

#[cfg(unix)]
impl KbuildAttemptOutcomeCensus {
    fn increment(&mut self, outcome: KbuildRecordOutcome, description: &str) -> Result<()> {
        self.attempt_count = self
            .attempt_count
            .checked_add(1)
            .with_context(|| format!("Kbuild {description} outcome count overflowed"))?;
        let count = match outcome {
            KbuildRecordOutcome::AttemptSucceeded(_) => &mut self.successful_attempts,
            KbuildRecordOutcome::AttemptFailed(_) => &mut self.failed_attempts,
            KbuildRecordOutcome::AttemptTerminated(_) => &mut self.terminal_attempts,
            _ => anyhow::bail!("Kbuild {description} has a non-attempt outcome"),
        };
        *count = count
            .checked_add(1)
            .with_context(|| format!("Kbuild {description} result count overflowed"))?;
        Ok(())
    }

    fn require_internal_total(self, description: &str) -> Result<()> {
        let total = self
            .successful_attempts
            .checked_add(self.failed_attempts)
            .and_then(|total| total.checked_add(self.terminal_attempts))
            .with_context(|| format!("Kbuild {description} result total overflowed"))?;
        if total != self.attempt_count {
            anyhow::bail!("Kbuild {description} outcome partition is incomplete");
        }
        Ok(())
    }
}

#[cfg(unix)]
impl KbuildProcessOutcomeCensus {
    fn increment(&mut self, outcome: KbuildRecordOutcome) -> Result<()> {
        self.process_count = self
            .process_count
            .checked_add(1)
            .context("Kbuild process outcome count overflowed")?;
        let count = match outcome {
            KbuildRecordOutcome::ProcessExitedZero => &mut self.exited_zero,
            KbuildRecordOutcome::ProcessExitedNonzero => &mut self.exited_nonzero,
            KbuildRecordOutcome::ProcessSignaled => &mut self.signaled,
            _ => anyhow::bail!("Kbuild process finish has a syscall outcome"),
        };
        *count = count
            .checked_add(1)
            .context("Kbuild process result count overflowed")?;
        Ok(())
    }

    fn require_internal_total(self) -> Result<()> {
        let total = self
            .exited_zero
            .checked_add(self.exited_nonzero)
            .and_then(|value| value.checked_add(self.signaled))
            .context("Kbuild process result total overflowed")?;
        if total != self.process_count {
            anyhow::bail!("Kbuild process outcome partition is incomplete");
        }
        Ok(())
    }
}

#[cfg(unix)]
impl KbuildOwnedOutcomeCensus {
    fn terminal_attempt_count(self) -> Result<u64> {
        [
            self.exec_attempts,
            self.path_open_attempts,
            self.query_or_read_attempts,
            self.descriptor_state_attempts,
            self.process_state_attempts,
            self.cwd_mutation_attempts,
            self.namespace_mutation_attempts,
            self.metadata_mutation_attempts,
            self.mapping_attempts,
            self.write_attempts,
            self.unmodeled_syscall_attempts,
        ]
        .into_iter()
        .try_fold(0_u64, |total, outcomes| {
            total
                .checked_add(outcomes.terminal_attempts)
                .context("Kbuild terminal-attempt count overflowed")
        })
    }

    fn increment(&mut self, outcome: KbuildRecordOutcome) -> Result<()> {
        let class = match outcome {
            KbuildRecordOutcome::ProcessExitedZero
            | KbuildRecordOutcome::ProcessExitedNonzero
            | KbuildRecordOutcome::ProcessSignaled => {
                return self.process_finishes.increment(outcome);
            }
            KbuildRecordOutcome::AttemptSucceeded(class)
            | KbuildRecordOutcome::AttemptFailed(class)
            | KbuildRecordOutcome::AttemptTerminated(class) => class,
        };
        let (census, description) = match class {
            KbuildRecordClass::ExecAttempt => (&mut self.exec_attempts, "exec attempt"),
            KbuildRecordClass::PathOpenAttempt => {
                (&mut self.path_open_attempts, "path-open attempt")
            }
            KbuildRecordClass::QueryOrReadAttempt => {
                (&mut self.query_or_read_attempts, "query-or-read attempt")
            }
            KbuildRecordClass::DescriptorStateAttempt => (
                &mut self.descriptor_state_attempts,
                "descriptor-state attempt",
            ),
            KbuildRecordClass::ProcessStateAttempt => {
                (&mut self.process_state_attempts, "process-state attempt")
            }
            KbuildRecordClass::SignalDelivery => {
                anyhow::bail!("Kbuild signal delivery has a syscall outcome")
            }
            KbuildRecordClass::CwdMutationAttempt => {
                (&mut self.cwd_mutation_attempts, "cwd-mutation attempt")
            }
            KbuildRecordClass::NamespaceMutationAttempt => (
                &mut self.namespace_mutation_attempts,
                "namespace-mutation attempt",
            ),
            KbuildRecordClass::MetadataMutationAttempt => (
                &mut self.metadata_mutation_attempts,
                "metadata-mutation attempt",
            ),
            KbuildRecordClass::MappingAttempt => (&mut self.mapping_attempts, "mapping attempt"),
            KbuildRecordClass::WriteAttempt => (&mut self.write_attempts, "write attempt"),
            KbuildRecordClass::UnmodeledSyscallAttempt => (
                &mut self.unmodeled_syscall_attempts,
                "unmodeled syscall attempt",
            ),
            KbuildRecordClass::Lifecycle | KbuildRecordClass::Invocation => {
                anyhow::bail!("Kbuild non-attempt record has a syscall outcome")
            }
        };
        census.increment(outcome, description)
    }

    fn require_matches(
        self,
        owned: KbuildOwnedStreamCensus,
        records: KbuildOwnedRecordCensus,
    ) -> Result<()> {
        self.process_finishes.require_internal_total()?;
        if self.process_finishes.process_count != owned.process_count
            || records.lifecycle_records
                != self
                    .process_finishes
                    .process_count
                    .checked_mul(2)
                    .context("Kbuild lifecycle outcome total overflowed")?
        {
            anyhow::bail!("Kbuild process outcomes do not match owned lifecycles");
        }
        for (outcomes, expected, description) in [
            (self.exec_attempts, records.exec_attempts, "exec"),
            (
                self.path_open_attempts,
                records.path_open_attempts,
                "path-open",
            ),
            (
                self.query_or_read_attempts,
                records.query_or_read_attempts,
                "query-or-read",
            ),
            (
                self.descriptor_state_attempts,
                records.descriptor_state_attempts,
                "descriptor-state",
            ),
            (
                self.process_state_attempts,
                records.process_state_attempts,
                "process-state",
            ),
            (
                self.cwd_mutation_attempts,
                records.cwd_mutation_attempts,
                "cwd-mutation",
            ),
            (
                self.namespace_mutation_attempts,
                records.namespace_mutation_attempts,
                "namespace-mutation",
            ),
            (
                self.metadata_mutation_attempts,
                records.metadata_mutation_attempts,
                "metadata-mutation",
            ),
            (self.mapping_attempts, records.mapping_attempts, "mapping"),
            (self.write_attempts, records.write_attempts, "write"),
            (
                self.unmodeled_syscall_attempts,
                records.unmodeled_syscall_attempts,
                "unmodeled syscall",
            ),
        ] {
            outcomes.require_internal_total(description)?;
            if outcomes.attempt_count != expected {
                anyhow::bail!("Kbuild {description} outcomes do not match classified records");
            }
        }
        Ok(())
    }
}

#[cfg(unix)]
impl KbuildOwnedRecordCensus {
    fn increment(&mut self, class: KbuildRecordClass) -> Result<()> {
        self.record_count = self
            .record_count
            .checked_add(1)
            .context("Kbuild classified record count overflowed")?;
        let (count, description) = match class {
            KbuildRecordClass::Lifecycle => (&mut self.lifecycle_records, "lifecycle"),
            KbuildRecordClass::Invocation => (&mut self.invocation_records, "invocation"),
            KbuildRecordClass::ExecAttempt => (&mut self.exec_attempts, "exec attempt"),
            KbuildRecordClass::PathOpenAttempt => {
                (&mut self.path_open_attempts, "path-open attempt")
            }
            KbuildRecordClass::QueryOrReadAttempt => {
                (&mut self.query_or_read_attempts, "query or read attempt")
            }
            KbuildRecordClass::DescriptorStateAttempt => (
                &mut self.descriptor_state_attempts,
                "descriptor state attempt",
            ),
            KbuildRecordClass::ProcessStateAttempt => {
                (&mut self.process_state_attempts, "process state attempt")
            }
            KbuildRecordClass::SignalDelivery => (&mut self.signal_deliveries, "signal delivery"),
            KbuildRecordClass::CwdMutationAttempt => {
                (&mut self.cwd_mutation_attempts, "cwd mutation attempt")
            }
            KbuildRecordClass::NamespaceMutationAttempt => (
                &mut self.namespace_mutation_attempts,
                "namespace mutation attempt",
            ),
            KbuildRecordClass::MetadataMutationAttempt => (
                &mut self.metadata_mutation_attempts,
                "metadata mutation attempt",
            ),
            KbuildRecordClass::MappingAttempt => (&mut self.mapping_attempts, "mapping attempt"),
            KbuildRecordClass::WriteAttempt => (&mut self.write_attempts, "write attempt"),
            KbuildRecordClass::UnmodeledSyscallAttempt => (
                &mut self.unmodeled_syscall_attempts,
                "unmodeled syscall attempt",
            ),
        };
        *count = count
            .checked_add(1)
            .with_context(|| format!("Kbuild {description} count overflowed"))?;
        Ok(())
    }

    fn try_add(&mut self, other: Self) -> Result<()> {
        macro_rules! add_field {
            ($field:ident) => {
                self.$field = self.$field.checked_add(other.$field).context(concat!(
                    "Kbuild ",
                    stringify!($field),
                    " count overflowed"
                ))?;
            };
        }
        add_field!(record_count);
        add_field!(lifecycle_records);
        add_field!(invocation_records);
        add_field!(exec_attempts);
        add_field!(path_open_attempts);
        add_field!(query_or_read_attempts);
        add_field!(descriptor_state_attempts);
        add_field!(process_state_attempts);
        add_field!(signal_deliveries);
        add_field!(cwd_mutation_attempts);
        add_field!(namespace_mutation_attempts);
        add_field!(metadata_mutation_attempts);
        add_field!(mapping_attempts);
        add_field!(write_attempts);
        add_field!(unmodeled_syscall_attempts);
        Ok(())
    }

    fn require_internal_total(self) -> Result<()> {
        let classified = [
            self.lifecycle_records,
            self.invocation_records,
            self.exec_attempts,
            self.path_open_attempts,
            self.query_or_read_attempts,
            self.descriptor_state_attempts,
            self.process_state_attempts,
            self.signal_deliveries,
            self.cwd_mutation_attempts,
            self.namespace_mutation_attempts,
            self.metadata_mutation_attempts,
            self.mapping_attempts,
            self.write_attempts,
            self.unmodeled_syscall_attempts,
        ]
        .into_iter()
        .try_fold(0_u64, |total, count| {
            total
                .checked_add(count)
                .context("Kbuild record-family total overflowed")
        })?;
        if classified != self.record_count {
            anyhow::bail!("Kbuild record-family partition is incomplete");
        }
        Ok(())
    }

    fn modeled_syscall_count(self) -> Result<u64> {
        [
            self.exec_attempts,
            self.path_open_attempts,
            self.query_or_read_attempts,
            self.descriptor_state_attempts,
            self.process_state_attempts,
            self.cwd_mutation_attempts,
            self.namespace_mutation_attempts,
            self.metadata_mutation_attempts,
            self.mapping_attempts,
            self.write_attempts,
        ]
        .into_iter()
        .try_fold(0_u64, |total, count| {
            total
                .checked_add(count)
                .context("Kbuild modeled-syscall count overflowed")
        })
    }
}

#[cfg(unix)]
fn kbuild_process_state_attempt_census(census: ProcessCaptureStreamCensus) -> Result<u64> {
    [
        census.memory_state_attempts,
        census.thread_state_attempts,
        census.signal_state_attempts,
        census.umask_attempts,
        census.credential_attempts,
        census.futex_wake_attempts,
        census.process_creation_attempts,
        census.child_wait_attempts,
        census.process_identity_attempts,
        census.lifecycle_exit_attempts,
    ]
    .into_iter()
    .try_fold(0_u64, |total, count| {
        total
            .checked_add(count)
            .context("Kbuild process-state count overflowed")
    })
}

#[cfg(unix)]
fn kbuild_descriptor_state_attempt_census(census: ProcessCaptureStreamCensus) -> Result<u64> {
    [
        census.close_attempts,
        census.seek_attempts,
        census.file_advice_attempts,
        census.fcntl_attempts,
        census.ioctl_attempts,
        census.pipe_attempts,
        census.epoll_create_attempts,
        census.socket_create_attempts,
        census.socket_connect_attempts,
        census.dup2_attempts,
    ]
    .into_iter()
    .try_fold(0_u64, |total, count| {
        total
            .checked_add(count)
            .context("Kbuild descriptor-state count overflowed")
    })
}

#[cfg(unix)]
fn partition_kbuild_xattr_attempts(total: u64, metadata_mutations: u64) -> Result<(u64, u64)> {
    let queries = total
        .checked_sub(metadata_mutations)
        .context("Kbuild metadata-xattr count exceeds the sealed xattr census")?;
    Ok((queries, metadata_mutations))
}

#[cfg(unix)]
fn kbuild_stream_record_census(
    stream: rush_observe::ProcessCaptureStreamSeal,
    metadata_xattr_attempts: u64,
) -> Result<KbuildOwnedRecordCensus> {
    let census = stream.census();
    let (query_xattr_attempts, metadata_xattr_attempts) =
        partition_kbuild_xattr_attempts(census.xattr_attempts, metadata_xattr_attempts)?;
    let query_or_read_attempts = [
        census.newfstatat_attempts,
        census.fstat_attempts,
        census.getrandom_attempts,
        census.runtime_observation_attempts,
        census.prlimit_attempts,
        census.statx_attempts,
        query_xattr_attempts,
        census.readlink_attempts,
        census.access_attempts,
        census.getcwd_attempts,
        census.filesystem_status_attempts,
        census.read_attempts,
        census.getdents64_attempts,
    ]
    .into_iter()
    .try_fold(0_u64, |total, count| {
        total
            .checked_add(count)
            .context("Kbuild query-or-read count overflowed")
    })?;
    let namespace_mutation_attempts = [
        census.path_removal_attempts,
        census.directory_creation_attempts,
        census.path_rename_attempts,
        census.symbolic_link_creation_attempts,
    ]
    .into_iter()
    .try_fold(0_u64, |total, count| {
        total
            .checked_add(count)
            .context("Kbuild namespace-mutation count overflowed")
    })?;
    let metadata_mutation_attempts = census
        .path_mode_change_attempts
        .checked_add(census.descriptor_timestamp_change_attempts)
        .and_then(|count| count.checked_add(metadata_xattr_attempts))
        .context("Kbuild metadata-mutation count overflowed")?;
    let expected = KbuildOwnedRecordCensus {
        record_count: stream.record_count(),
        lifecycle_records: stream
            .process_count()
            .checked_mul(2)
            .context("Kbuild lifecycle-record count overflowed")?,
        invocation_records: census.invocations,
        exec_attempts: census.exec_attempts,
        path_open_attempts: census.open_attempts,
        query_or_read_attempts,
        descriptor_state_attempts: kbuild_descriptor_state_attempt_census(census)?,
        process_state_attempts: kbuild_process_state_attempt_census(census)?,
        signal_deliveries: census.signal_deliveries,
        cwd_mutation_attempts: census.cwd_change_attempts,
        namespace_mutation_attempts,
        metadata_mutation_attempts,
        mapping_attempts: census.mmap_attempts,
        write_attempts: census.write_attempts,
        unmodeled_syscall_attempts: census.unmodeled_syscall_attempts,
    };
    expected.require_internal_total()?;
    Ok(expected)
}

#[cfg(unix)]
fn update_kbuild_record_census(hasher: &mut blake3::Hasher, census: KbuildOwnedRecordCensus) {
    for count in [
        census.record_count,
        census.lifecycle_records,
        census.invocation_records,
        census.exec_attempts,
        census.path_open_attempts,
        census.query_or_read_attempts,
        census.descriptor_state_attempts,
        census.process_state_attempts,
        census.signal_deliveries,
        census.cwd_mutation_attempts,
        census.namespace_mutation_attempts,
        census.metadata_mutation_attempts,
        census.mapping_attempts,
        census.write_attempts,
        census.unmodeled_syscall_attempts,
    ] {
        hasher.update(&count.to_le_bytes());
    }
}

#[cfg(unix)]
fn kbuild_record_classification_digest(
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    analyzer: KbuildOwnedRecordCensus,
    actions: &[KbuildActionRecordCensus],
) -> Result<[u8; 32]> {
    let action_count =
        u64::try_from(actions.len()).context("Kbuild classified action count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-record-classification.v19\0");
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    update_kbuild_record_census(&mut hasher, analyzer);
    hasher.update(&action_count.to_le_bytes());
    for action in actions {
        hasher.update(&action.action_index.to_le_bytes());
        update_kbuild_record_census(&mut hasher, action.records);
    }
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(unix)]
fn update_kbuild_attempt_outcomes(hasher: &mut blake3::Hasher, census: KbuildAttemptOutcomeCensus) {
    for count in [
        census.attempt_count,
        census.successful_attempts,
        census.failed_attempts,
        census.terminal_attempts,
    ] {
        hasher.update(&count.to_le_bytes());
    }
}

#[cfg(unix)]
fn update_kbuild_owned_outcomes(hasher: &mut blake3::Hasher, census: KbuildOwnedOutcomeCensus) {
    for count in [
        census.process_finishes.process_count,
        census.process_finishes.exited_zero,
        census.process_finishes.exited_nonzero,
        census.process_finishes.signaled,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    for outcomes in [
        census.exec_attempts,
        census.path_open_attempts,
        census.query_or_read_attempts,
        census.descriptor_state_attempts,
        census.process_state_attempts,
        census.cwd_mutation_attempts,
        census.namespace_mutation_attempts,
        census.metadata_mutation_attempts,
        census.mapping_attempts,
        census.write_attempts,
        census.unmodeled_syscall_attempts,
    ] {
        update_kbuild_attempt_outcomes(hasher, outcomes);
    }
}

#[cfg(unix)]
fn kbuild_record_outcome_digest(
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    classification_digest: [u8; 32],
    analyzer: KbuildOwnedOutcomeCensus,
    actions: &[KbuildActionOutcomeCensus],
) -> Result<[u8; 32]> {
    let action_count =
        u64::try_from(actions.len()).context("Kbuild outcome action count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-record-outcomes.v8\0");
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&classification_digest);
    update_kbuild_owned_outcomes(&mut hasher, analyzer);
    hasher.update(&action_count.to_le_bytes());
    for action in actions {
        hasher.update(&action.action_index.to_le_bytes());
        update_kbuild_owned_outcomes(&mut hasher, action.outcomes);
    }
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(unix)]
fn kbuild_syscall_coverage_digest(
    stream_digest: [u8; 32],
    classification_digest: [u8; 32],
    outcome_digest: [u8; 32],
    modeled_syscalls: u64,
    syscall_entries: u64,
    syscall_exits: u64,
    terminal_syscalls: u64,
) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-syscall-coverage.v1\0");
    hasher.update(&stream_digest);
    hasher.update(&classification_digest);
    hasher.update(&outcome_digest);
    for count in [
        modeled_syscalls,
        syscall_entries,
        syscall_exits,
        terminal_syscalls,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    *hasher.finalize().as_bytes()
}

#[cfg(unix)]
fn kbuild_process_assignment_digest(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignments: &BTreeMap<CapturedProcessId, KbuildProcessOwner>,
) -> Result<[u8; 32]> {
    let process_count =
        u64::try_from(assignments.len()).context("Kbuild owned process count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-process-ownership.v1\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&process_count.to_le_bytes());
    for (process, owner) in assignments {
        hasher.update(&process.to_le_bytes());
        match owner {
            KbuildProcessOwner::Analyzer => {
                hasher.update(&[0]);
            }
            KbuildProcessOwner::Action(action_index) => {
                hasher.update(&[1]);
                hasher.update(&action_index.to_le_bytes());
            }
        };
    }
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(unix)]
fn update_kbuild_process_owner(hasher: &mut blake3::Hasher, owner: KbuildProcessOwner) {
    match owner {
        KbuildProcessOwner::Analyzer => {
            hasher.update(&[0]);
        }
        KbuildProcessOwner::Action(action_index) => {
            hasher.update(&[1]);
            hasher.update(&action_index.to_le_bytes());
        }
    };
}

#[cfg(unix)]
fn normalized_kbuild_input_target(raw: &[u8], description: &str) -> Result<PathBuf> {
    if raw.is_empty() || raw.contains(&0) || raw.ends_with(b" (deleted)") {
        anyhow::bail!("Kbuild {description} has an ambiguous target");
    }
    normalized_absolute_path(&bytes_path(raw), description)
}

#[cfg(unix)]
fn normalized_kbuild_open_request_path(
    request: &rush_observe::CapturedOpenRequest,
) -> Option<PathBuf> {
    if request.path.is_empty() || request.path.contains(&0) {
        return None;
    }
    let requested = bytes_path(&request.path);
    let absolute = if requested.is_absolute() {
        requested
    } else {
        let directory = request.directory.as_deref()?;
        let directory = normalized_kbuild_input_target(directory, "open-request directory").ok()?;
        directory.join(requested)
    };
    normalized_absolute_path(&absolute, "open-request path").ok()
}

#[cfg(unix)]
fn kbuild_direct_directory_descriptor_binding(
    stream_ordinal: u64,
    attempt: &rush_observe::CapturedOpenAttempt,
) -> Result<Option<(i32, KbuildDirectoryDescriptorBinding)>> {
    let CapturedOpenOutcome::Opened {
        descriptor,
        identity,
        mount_id,
        ..
    } = &attempt.outcome
    else {
        return Ok(None);
    };
    if identity.kind != CapturedDescriptorKind::Directory || identity.inode == 0 || *mount_id == 0 {
        return Ok(None);
    }
    let Some(requested) = normalized_kbuild_open_request_path(&attempt.request) else {
        return Ok(None);
    };
    let resolved =
        normalized_kbuild_input_target(&identity.target, "opened directory descriptor target")?;
    if requested != resolved {
        return Ok(None);
    }
    Ok(Some((
        *descriptor,
        KbuildDirectoryDescriptorBinding {
            path: resolved,
            object: kbuild_descriptor_input_object(identity, Some(*mount_id))?,
            open_syscall_index: attempt.syscall_index,
            open_stream_ordinal: stream_ordinal,
        },
    )))
}

#[cfg(unix)]
fn is_resolved_procfs_process_fd_directory(target: &[u8]) -> bool {
    let Some(process) = target
        .strip_prefix(b"/proc/")
        .and_then(|suffix| suffix.strip_suffix(b"/fd"))
    else {
        return false;
    };
    !process.is_empty() && process[0] != b'0' && process.iter().all(u8::is_ascii_digit)
}

#[cfg(unix)]
fn kbuild_procfs_self_fd_directory_binding(
    stream_ordinal: u64,
    attempt: &rush_observe::CapturedOpenAttempt,
) -> Result<Option<(i32, KbuildProcfsDirectoryDescriptorBinding)>> {
    let CapturedOpenOutcome::Opened {
        descriptor,
        identity,
        mount_id,
        file_value,
    } = &attempt.outcome
    else {
        return Ok(None);
    };
    let expected_flags = u64::try_from(libc::O_NONBLOCK | libc::O_CLOEXEC | libc::O_DIRECTORY)
        .context("Kbuild procfs directory flags do not fit u64")?;
    if attempt.request.system_call != CapturedOpenSystemCall::OpenAt
        || attempt.request.path != b"/proc/self/fd"
        || attempt.request.directory.is_some()
        || attempt.request.flags != expected_flags
        || attempt.request.mode != 0
        || attempt.request.resolve != 0
        || *descriptor < 0
        || !is_resolved_procfs_process_fd_directory(&identity.target)
        || identity.kind != CapturedDescriptorKind::Directory
        || identity.inode == 0
        || *mount_id == 0
        || file_value.is_some()
    {
        return Ok(None);
    }
    Ok(Some((
        *descriptor,
        KbuildProcfsDirectoryDescriptorBinding {
            path: bytes_path(&identity.target),
            object: kbuild_descriptor_input_object(identity, Some(*mount_id))?,
            open_syscall_index: attempt.syscall_index,
            open_stream_ordinal: stream_ordinal,
            open_attempt: attempt.clone(),
        },
    )))
}

#[cfg(unix)]
fn kbuild_mapped_input_object(identity: &CapturedMappedFileIdentity) -> KbuildInputObjectIdentity {
    KbuildInputObjectIdentity {
        device: identity.device,
        inode: identity.inode,
        mount_id: Some(identity.mount_id),
        kind: KbuildInputObjectKind::RegularFile,
    }
}

#[cfg(unix)]
fn kbuild_descriptor_input_object(
    identity: &rush_observe::CapturedDescriptorIdentity,
    mount_id: Option<u64>,
) -> Result<KbuildInputObjectIdentity> {
    let kind = match identity.kind {
        CapturedDescriptorKind::RegularFile => KbuildInputObjectKind::RegularFile,
        CapturedDescriptorKind::Directory => KbuildInputObjectKind::Directory,
        _ => anyhow::bail!("Kbuild input value has an unsupported object type"),
    };
    Ok(KbuildInputObjectIdentity {
        device: identity.device,
        inode: identity.inode,
        mount_id,
        kind,
    })
}

#[cfg(unix)]
fn kbuild_output_object(
    identity: &rush_observe::CapturedDescriptorIdentity,
    mount_id: u64,
) -> Result<KbuildOutputObjectIdentity> {
    if identity.kind != CapturedDescriptorKind::RegularFile || identity.inode == 0 || mount_id == 0
    {
        anyhow::bail!("Kbuild output mutation has an invalid VFS object identity");
    }
    Ok(KbuildOutputObjectIdentity {
        device: identity.device,
        inode: identity.inode,
        mount_id,
    })
}

#[cfg(unix)]
fn kbuild_input_value_census(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    observations: &[KbuildInputObservation],
    mutation_candidates: &BTreeMap<KbuildProcessOwner, BTreeSet<PathBuf>>,
    directory_effect_paths: &BTreeSet<PathBuf>,
) -> Result<KbuildInputValueCensusSeal> {
    let observation_count = u64::try_from(observations.len())
        .context("Kbuild input-value observation count does not fit u64")?;
    for (index, observation) in observations.iter().enumerate() {
        if observation.ordinal
            != u64::try_from(index).context("Kbuild input-value ordinal does not fit u64")?
        {
            anyhow::bail!("Kbuild input-value observations have a non-canonical order");
        }
    }
    if observations
        .windows(2)
        .any(|pair| pair[0].stream_ordinal > pair[1].stream_ordinal)
    {
        anyhow::bail!("Kbuild input-value observations are not in stream order");
    }
    let mut mutation_owners = BTreeMap::new();
    for (owner, paths) in mutation_candidates {
        for path in paths {
            if mutation_owners.insert(path.clone(), *owner).is_some() {
                anyhow::bail!("Kbuild input-value mutation path has multiple owners");
            }
        }
    }

    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-input-value-census.v4\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&observation_count.to_le_bytes());
    let mut whole_file_observations = 0_u64;
    let mut directory_observations = 0_u64;
    let mut object_identity_observations = 0_u64;
    let mut mount_identity_observations = 0_u64;
    let mut executable_observations = 0_u64;
    let mut analyzer_observations = 0_u64;
    let mut action_observations = 0_u64;
    let mut external_observations = 0_u64;
    let mut mutation_path_observations = 0_u64;
    let mut cross_owner_mutation_path_observations = 0_u64;
    let mut external_values = BTreeMap::new();
    let mut external_objects = BTreeMap::new();
    let mut external_mounts = BTreeMap::new();
    let mut mutation_paths = BTreeSet::new();

    for observation in observations {
        if observation.object.mount_id.is_none() {
            anyhow::bail!("Kbuild input value has incomplete mount provenance");
        }
        update_kbuild_process_owner(&mut hasher, observation.owner);
        hasher.update(&observation.process.to_le_bytes());
        hasher.update(&observation.ordinal.to_le_bytes());
        hasher.update(&observation.stream_ordinal.to_le_bytes());
        hasher.update(&[match observation.class {
            KbuildInputObservationClass::Executable => 0,
            KbuildInputObservationClass::ExecMapping => 1,
            KbuildInputObservationClass::Open => 2,
            KbuildInputObservationClass::Mmap => 3,
            KbuildInputObservationClass::Read => 4,
            KbuildInputObservationClass::Directory => 5,
        }]);
        let path = os_bytes(observation.path.as_os_str());
        let path_bytes =
            u64::try_from(path.len()).context("Kbuild input-value path length does not fit u64")?;
        hasher.update(&path_bytes.to_le_bytes());
        hasher.update(&path);
        hasher.update(&observation.object.device.to_le_bytes());
        hasher.update(&observation.object.inode.to_le_bytes());
        match observation.object.mount_id {
            Some(mount_id) => {
                hasher.update(&[1]);
                hasher.update(&mount_id.to_le_bytes());
                mount_identity_observations = mount_identity_observations
                    .checked_add(1)
                    .context("Kbuild mount-identity observation count overflowed")?;
            }
            None => {
                hasher.update(&[0]);
            }
        }
        hasher.update(&[match observation.object.kind {
            KbuildInputObjectKind::RegularFile => 0,
            KbuildInputObjectKind::Directory => 1,
        }]);
        object_identity_observations = object_identity_observations
            .checked_add(1)
            .context("Kbuild object-identity observation count overflowed")?;
        match observation.value {
            KbuildObservedInputValue::WholeFile {
                bytes,
                digest,
                mode,
            } => {
                if observation.object.kind != KbuildInputObjectKind::RegularFile
                    || mode & libc::S_IFMT != libc::S_IFREG
                {
                    anyhow::bail!("Kbuild whole-file input value is not a regular file");
                }
                hasher.update(&[0]);
                hasher.update(&bytes.to_le_bytes());
                hasher.update(&digest);
                hasher.update(&mode.to_le_bytes());
                whole_file_observations = whole_file_observations
                    .checked_add(1)
                    .context("Kbuild whole-file observation count overflowed")?;
            }
            KbuildObservedInputValue::Directory {
                entries,
                digest,
                listing_digest,
            } => {
                if observation.object.kind != KbuildInputObjectKind::Directory {
                    anyhow::bail!("Kbuild directory input value has the wrong object type");
                }
                hasher.update(&[1]);
                hasher.update(&entries.to_le_bytes());
                hasher.update(&digest);
                hasher.update(&listing_digest);
                directory_observations = directory_observations
                    .checked_add(1)
                    .context("Kbuild directory observation count overflowed")?;
            }
        }
        if observation.class == KbuildInputObservationClass::Executable {
            executable_observations = executable_observations
                .checked_add(1)
                .context("Kbuild executable observation count overflowed")?;
        }
        match observation.owner {
            KbuildProcessOwner::Analyzer => {
                analyzer_observations = analyzer_observations
                    .checked_add(1)
                    .context("Kbuild analyzer input-value count overflowed")?;
            }
            KbuildProcessOwner::Action(_) => {
                action_observations = action_observations
                    .checked_add(1)
                    .context("Kbuild action input-value count overflowed")?;
            }
        }
        if let Some(mutating_owner) = mutation_owners.get(&observation.path) {
            mutation_path_observations = mutation_path_observations
                .checked_add(1)
                .context("Kbuild mutation-path observation count overflowed")?;
            mutation_paths.insert(observation.path.clone());
            if *mutating_owner != observation.owner {
                cross_owner_mutation_path_observations = cross_owner_mutation_path_observations
                    .checked_add(1)
                    .context("Kbuild cross-owner input-value count overflowed")?;
            }
        } else {
            external_observations = external_observations
                .checked_add(1)
                .context("Kbuild external input-value count overflowed")?;
            let captured_directory_effect = observation.object.kind
                == KbuildInputObjectKind::Directory
                && directory_effect_paths.contains(&observation.path);
            match external_values.entry(observation.path.clone()) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(observation.value);
                }
                std::collections::btree_map::Entry::Occupied(entry)
                    if *entry.get() != observation.value && !captured_directory_effect =>
                {
                    anyhow::bail!("Kbuild external input value changed during capture");
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
            }
            let object = (
                observation.object.device,
                observation.object.inode,
                observation.object.kind,
            );
            match external_objects.entry(observation.path.clone()) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(object);
                }
                std::collections::btree_map::Entry::Occupied(entry) if *entry.get() != object => {
                    anyhow::bail!("Kbuild external input object changed during capture");
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
            }
            if let Some(mount_id) = observation.object.mount_id {
                match external_mounts.entry(observation.path.clone()) {
                    std::collections::btree_map::Entry::Vacant(entry) => {
                        entry.insert(mount_id);
                    }
                    std::collections::btree_map::Entry::Occupied(entry)
                        if *entry.get() != mount_id =>
                    {
                        anyhow::bail!("Kbuild external input mount changed during capture");
                    }
                    std::collections::btree_map::Entry::Occupied(_) => {}
                }
            }
        }
    }

    if observation_count != object_identity_observations
        || observation_count
            != whole_file_observations
                .checked_add(directory_observations)
                .context("Kbuild input-value type count overflowed")?
        || observation_count
            != analyzer_observations
                .checked_add(action_observations)
                .context("Kbuild input-value owner count overflowed")?
        || observation_count
            != external_observations
                .checked_add(mutation_path_observations)
                .context("Kbuild input-value path-class count overflowed")?
    {
        anyhow::bail!("Kbuild input-value census is internally inconsistent");
    }

    Ok(KbuildInputValueCensusSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        census_digest: *hasher.finalize().as_bytes(),
        observations: observation_count,
        object_identity_observations,
        mount_identity_observations,
        whole_file_observations,
        directory_observations,
        executable_observations,
        analyzer_observations,
        action_observations,
        external_observations,
        mutation_path_observations,
        cross_owner_mutation_path_observations,
        distinct_external_paths: u64::try_from(external_values.len())
            .context("Kbuild external input path count does not fit u64")?,
        distinct_external_objects: u64::try_from(
            external_objects
                .values()
                .copied()
                .collect::<BTreeSet<_>>()
                .len(),
        )
        .context("Kbuild external input object count does not fit u64")?,
        distinct_mutation_paths: u64::try_from(mutation_paths.len())
            .context("Kbuild mutation input path count does not fit u64")?,
    })
}

#[cfg(unix)]
fn kbuild_procfs_read_census(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    observations: &[KbuildProcfsReadObservation],
) -> Result<KbuildProcfsReadCensusSeal> {
    let read_observations =
        u64::try_from(observations.len()).context("Kbuild procfs read count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-procfs-read-census.v1\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&read_observations.to_le_bytes());

    let mut grouped: BTreeMap<KbuildProcfsReadGroupKey, (u64, BTreeSet<KbuildProcfsValue>)> =
        BTreeMap::new();
    let mut owners_by_value: BTreeMap<KbuildProcfsValue, BTreeSet<KbuildProcessOwner>> =
        BTreeMap::new();
    let mut analyzer_observations = 0_u64;
    let mut action_observations = 0_u64;
    let mut actions = BTreeSet::new();
    for observation in observations {
        update_kbuild_process_owner(&mut hasher, observation.owner);
        hasher.update(&observation.process.to_le_bytes());
        hasher.update(&observation.syscall_index.to_le_bytes());
        hasher.update(&observation.executable_digest);
        hasher.update(&[match observation.value.class {
            KbuildProcfsReadClass::Filesystems => 0,
            KbuildProcfsReadClass::ProcessMaps => 1,
            KbuildProcfsReadClass::ProcessStatm => 2,
            KbuildProcfsReadClass::VmOvercommitMemory => 3,
            KbuildProcfsReadClass::ProcessCgroup => 4,
            KbuildProcfsReadClass::CgroupCpuMax => 5,
        }]);
        hasher.update(&observation.value.bytes.to_le_bytes());
        hasher.update(&observation.value.digest);
        match observation.owner {
            KbuildProcessOwner::Analyzer => {
                analyzer_observations = analyzer_observations
                    .checked_add(1)
                    .context("Kbuild analyzer procfs read count overflowed")?;
            }
            KbuildProcessOwner::Action(action_index) => {
                action_observations = action_observations
                    .checked_add(1)
                    .context("Kbuild action procfs read count overflowed")?;
                actions.insert(action_index);
            }
        }
        let group = grouped
            .entry(KbuildProcfsReadGroupKey {
                owner: observation.owner,
                executable_digest: observation.executable_digest,
                class: observation.value.class,
            })
            .or_default();
        group.0 = group
            .0
            .checked_add(1)
            .context("Kbuild procfs group read count overflowed")?;
        group.1.insert(observation.value);
        owners_by_value
            .entry(observation.value)
            .or_default()
            .insert(observation.owner);
    }
    let groups = grouped
        .into_iter()
        .map(|(key, (read_observations, values))| {
            Ok(KbuildProcfsReadGroup {
                action_index: match key.owner {
                    KbuildProcessOwner::Analyzer => None,
                    KbuildProcessOwner::Action(index) => Some(index),
                },
                executable_digest: key.executable_digest,
                class: key.class,
                read_observations,
                distinct_values: u64::try_from(values.len())
                    .context("Kbuild procfs group value count does not fit u64")?,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let boundary_crossing_values = u64::try_from(
        owners_by_value
            .values()
            .filter(|owners| owners.len() > 1)
            .count(),
    )
    .context("Kbuild boundary-crossing procfs value count does not fit u64")?;
    Ok(KbuildProcfsReadCensusSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        census_digest: *hasher.finalize().as_bytes(),
        read_observations,
        analyzer_observations,
        action_observations,
        distinct_actions: u64::try_from(actions.len())
            .context("Kbuild procfs action count does not fit u64")?,
        boundary_crossing_values,
        groups,
    })
}

#[cfg(unix)]
fn kbuild_procfs_analysis_witness(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    census: &KbuildProcfsReadCensusSeal,
    observations: &[KbuildProcfsReadObservation],
) -> Result<KbuildProcfsAnalysisWitnessSeal> {
    let analyzer_observations = observations
        .iter()
        .filter(|observation| observation.owner == KbuildProcessOwner::Analyzer)
        .collect::<Vec<_>>();
    let read_observations = u64::try_from(analyzer_observations.len())
        .context("Kbuild procfs witness count does not fit u64")?;
    if read_observations != census.analyzer_observations {
        anyhow::bail!("Kbuild procfs witness does not cover the analyzer census");
    }

    let mut groups: BTreeMap<
        (
            CapturedProcessId,
            i32,
            u64,
            u64,
            [u8; 32],
            KbuildProcfsReadClass,
            Option<u64>,
        ),
        Vec<KbuildProcfsReadObservation>,
    > = BTreeMap::new();
    for observation in analyzer_observations {
        match observation.value.class {
            KbuildProcfsReadClass::Filesystems => {}
            KbuildProcfsReadClass::ProcessMaps
            | KbuildProcfsReadClass::ProcessStatm
            | KbuildProcfsReadClass::ProcessCgroup
                if observation.self_open_syscall_index.is_some() => {}
            KbuildProcfsReadClass::ProcessMaps
            | KbuildProcfsReadClass::ProcessStatm
            | KbuildProcfsReadClass::ProcessCgroup => {
                anyhow::bail!(
                    "Kbuild numeric-process procfs read has no authenticated self identity"
                );
            }
            KbuildProcfsReadClass::VmOvercommitMemory
            | KbuildProcfsReadClass::CgroupCpuMax => {}
        }
        groups
            .entry((
                observation.process,
                observation.descriptor,
                observation.device,
                observation.inode,
                observation.executable_digest,
                observation.value.class,
                observation.self_open_syscall_index,
            ))
            .or_default()
            .push(*observation);
    }

    let mut values = BTreeSet::new();
    let mut filesystems_values = BTreeSet::new();
    let mut overcommit_values = BTreeSet::new();
    let mut cgroup_cpu_max_values = BTreeSet::new();
    let mut binding_hasher = blake3::Hasher::new();
    binding_hasher.update(b"rush.kbuild-procfs-read-bindings.v1\0");
    for (group, reads) in &mut groups {
        reads.sort_by_key(|read| read.syscall_index);
        let class = group.5;
        if class == KbuildProcfsReadClass::Filesystems && reads.len() != 2 {
            anyhow::bail!(
                "Kbuild /proc/filesystems witness is not one complete-value read followed by EOF"
            );
        }
        if class == KbuildProcfsReadClass::VmOvercommitMemory && reads.len() != 1 {
            anyhow::bail!("Kbuild overcommit witness is not one exact policy-byte read");
        }
        if matches!(
            class,
            KbuildProcfsReadClass::ProcessMaps
                | KbuildProcfsReadClass::ProcessStatm
                | KbuildProcfsReadClass::ProcessCgroup
        ) && group.6.is_none_or(|open| open >= reads[0].syscall_index)
        {
            anyhow::bail!(
                "Kbuild numeric-process procfs read has no prior authenticated self open"
            );
        }

        binding_hasher.update(&group.0.to_le_bytes());
        binding_hasher.update(&group.1.to_le_bytes());
        binding_hasher.update(&group.2.to_le_bytes());
        binding_hasher.update(&group.3.to_le_bytes());
        binding_hasher.update(&group.4);
        binding_hasher.update(&[match class {
            KbuildProcfsReadClass::Filesystems => 0,
            KbuildProcfsReadClass::ProcessMaps => 1,
            KbuildProcfsReadClass::ProcessStatm => 2,
            KbuildProcfsReadClass::VmOvercommitMemory => 3,
            KbuildProcfsReadClass::ProcessCgroup => 4,
            KbuildProcfsReadClass::CgroupCpuMax => 5,
        }]);
        match group.6 {
            Some(open) => {
                binding_hasher.update(&[1]);
                binding_hasher.update(&open.to_le_bytes());
            }
            None => {
                binding_hasher.update(&[0]);
            }
        }

        for read in reads.iter() {
            binding_hasher.update(&read.syscall_index.to_le_bytes());
            binding_hasher.update(&read.requested_bytes.to_le_bytes());
            binding_hasher.update(&read.value.bytes.to_le_bytes());
            binding_hasher.update(&read.value.digest);
        }

        if class == KbuildProcfsReadClass::VmOvercommitMemory {
            let read = reads[0];
            let value = (b'0'..=b'2')
                .find(|candidate| read.value.digest == *blake3::hash(&[*candidate]).as_bytes())
                .context("Kbuild overcommit witness has an invalid policy byte")?;
            if read.system_call != CapturedReadSystemCall::Read
                || !read.uses_descriptor_offset
                || read.offset != Some(0)
                || read.requested_bytes != 1
                || read.flags != 0
                || read.value.bytes != 1
            {
                anyhow::bail!("Kbuild overcommit witness is not one exact policy-byte read");
            }
            values.insert(read.value);
            overcommit_values.insert(value);
            continue;
        }

        let final_pass_start = reads
            .iter()
            .enumerate()
            .rev()
            .find_map(|(index, read)| (read.offset == Some(0)).then_some(index))
            .context("Kbuild procfs read sequence has no offset-zero pass")?;
        let (prefix_reads, complete_reads) = reads.split_at(final_pass_start);
        if complete_reads.is_empty() {
            anyhow::bail!("Kbuild procfs complete-value read proof is malformed");
        }

        let mut bytes = 0_u64;
        let mut data_reads = 0_u64;
        let mut sole_data_digest = None;
        let mut sequence_hasher = blake3::Hasher::new();
        sequence_hasher.update(b"rush.kbuild-procfs-read-sequence.v1\0");
        for (index, read) in complete_reads.iter().enumerate() {
            let last = index + 1 == complete_reads.len();
            let eof = read.value.bytes == 0 && read.value.digest == *blake3::hash(&[]).as_bytes();
            let short = read.value.bytes > 0 && read.value.bytes < read.requested_bytes;
            if read.system_call != CapturedReadSystemCall::Read
                || !read.uses_descriptor_offset
                || read.offset != Some(bytes)
                || read.requested_bytes == 0
                || read.flags != 0
                || read.value.class != class
                || read.value.bytes > read.requested_bytes
                || (last && !eof && !short)
                || (!last && read.value.bytes == 0)
                || (index > 0
                    && complete_reads[index - 1].syscall_index.checked_add(1)
                        != Some(read.syscall_index))
            {
                anyhow::bail!("Kbuild procfs complete-value read proof is malformed");
            }
            if read.value.bytes > 0 {
                sequence_hasher.update(&read.value.bytes.to_le_bytes());
                sequence_hasher.update(&read.value.digest);
                data_reads = data_reads
                    .checked_add(1)
                    .context("Kbuild procfs data-read count overflowed")?;
                sole_data_digest = Some(read.value.digest);
                bytes = bytes
                    .checked_add(read.value.bytes)
                    .context("Kbuild procfs complete-value byte count overflowed")?;
            }
        }
        for prefix in prefix_reads {
            if prefix.system_call != CapturedReadSystemCall::Read
                || !prefix.uses_descriptor_offset
                || prefix.requested_bytes == 0
                || prefix.flags != 0
                || prefix.value.class != class
                || prefix.value.bytes == 0
                || !complete_reads.iter().any(|read| {
                    read.offset == prefix.offset
                        && read.value.bytes == prefix.value.bytes
                        && read.value.digest == prefix.value.digest
                })
            {
                anyhow::bail!("Kbuild procfs prefix read does not match the complete pass");
            }
        }
        let digest = if data_reads == 1 {
            sole_data_digest.context("Kbuild procfs proof has no data read")?
        } else if data_reads > 1 {
            *sequence_hasher.finalize().as_bytes()
        } else {
            anyhow::bail!("Kbuild procfs proof has no data read")
        };
        let value = KbuildProcfsValue {
            class,
            bytes,
            digest,
        };
        values.insert(value);
        if class == KbuildProcfsReadClass::Filesystems {
            filesystems_values.insert((bytes, digest));
        }
        if class == KbuildProcfsReadClass::CgroupCpuMax {
            cgroup_cpu_max_values.insert((bytes, digest));
        }
    }
    if filesystems_values.len() > 1 {
        anyhow::bail!("Kbuild analyzer observed inconsistent /proc/filesystems values");
    }
    if overcommit_values.len() > 1 {
        anyhow::bail!("Kbuild analyzer observed inconsistent overcommit policy values");
    }
    let dependencies = filesystems_values
        .iter()
        .map(|(bytes, digest)| Dependency::LinuxProcFilesystems {
            bytes: *bytes,
            digest: *digest,
        })
        .chain(
            overcommit_values
                .iter()
                .map(|value| Dependency::LinuxProcVmOvercommitMemory { value: *value }),
        )
        .chain((!cgroup_cpu_max_values.is_empty()).then(|| {
            Dependency::LinuxCgroupV2CpuMax {
                values: cgroup_cpu_max_values.iter().copied().collect(),
            }
        }))
        .collect();
    let analysis_manifest = DependencyManifest::from_deps(dependencies);
    let distinct_values =
        u64::try_from(values.len()).context("Kbuild procfs value count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-procfs-analysis-witness.v5\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&census.census_digest);
    hasher.update(&read_observations.to_le_bytes());
    hasher.update(&distinct_values.to_le_bytes());
    hasher.update(binding_hasher.finalize().as_bytes());
    hasher.update(&analysis_manifest.fingerprint());
    Ok(KbuildProcfsAnalysisWitnessSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        census_digest: census.census_digest,
        witness_digest: *hasher.finalize().as_bytes(),
        read_observations,
        distinct_values,
        analysis_manifest,
    })
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct KbuildProcfsDirectorySequenceKey {
    action_index: u64,
    process: CapturedProcessId,
    descriptor: i32,
    open_stream_ordinal: u64,
}

#[cfg(unix)]
#[derive(Debug, Default)]
struct KbuildProcfsMandatoryActionEvidence {
    read_observations: u64,
    directory_observations: u64,
    directory_openings: u64,
    executable_identities: BTreeSet<[u8; 32]>,
    read_classes: BTreeSet<KbuildProcfsReadClass>,
    directory_classes: BTreeSet<KbuildProcfsDirectoryClass>,
}

#[cfg(unix)]
fn is_canonical_self_descriptor_member_vector(descriptor: i32, members: &[Vec<u8>]) -> bool {
    let Ok(last_descriptor) = usize::try_from(descriptor) else {
        return false;
    };
    let Some(descriptor_count) = last_descriptor.checked_add(1) else {
        return false;
    };
    if descriptor < 3 || members.len() != descriptor_count {
        return false;
    }
    // Retained directory members are sorted by name bytes, not FD number.
    let mut expected = (0..descriptor_count)
        .map(|descriptor| descriptor.to_string().into_bytes())
        .collect::<Vec<_>>();
    expected.sort();
    members == expected
}

#[cfg(unix)]
fn require_kbuild_procfs_directory_execution_sequence(
    checkpoints: &[&KbuildProcfsDirectoryCheckpoint],
) -> Result<()> {
    if checkpoints.len() != 2 {
        anyhow::bail!("Kbuild procfs directory opening has an incomplete enumeration sequence");
    }
    let first = checkpoints[0];
    let eof = checkpoints[1];
    // libc may stat the directory descriptor and initialize allocator state
    // between open and its first read. The retained anchor proves descriptor
    // lineage across that gap, and position zero proves that no entries were
    // consumed. Keep the value-bearing read and EOF attempt consecutive.
    if first.anchor != eof.anchor
        || first.open_attempt != eof.open_attempt
        || first.executable_digest != eof.executable_digest
        || first.observation.value != eof.observation.value
        || first.members != eof.members
        || !is_canonical_self_descriptor_member_vector(first.anchor.descriptor, &first.members)
        || first.anchor.open_stream_ordinal >= first.observation.stream_ordinal
        || first.observation.stream_ordinal >= eof.observation.stream_ordinal
        || first.anchor.open_syscall_index >= first.attempt.syscall_index
        || first.attempt.syscall_index.checked_add(1) != Some(eof.attempt.syscall_index)
    {
        anyhow::bail!("Kbuild procfs directory opening has a noncanonical execution sequence");
    }
    let CapturedGetdents64Outcome::Enumerated {
        returned_bytes: first_bytes,
        position_after: first_position_after,
        entries: first_entries,
        directory_value: first_value,
    } = &first.attempt.outcome
    else {
        anyhow::bail!("Kbuild procfs directory opening has no first enumeration");
    };
    let CapturedGetdents64Outcome::Enumerated {
        returned_bytes: eof_bytes,
        position_after: eof_position_after,
        entries: eof_entries,
        directory_value: eof_value,
    } = &eof.attempt.outcome
    else {
        anyhow::bail!("Kbuild procfs directory opening has no EOF enumeration");
    };
    let delivered_names = first_entries
        .iter()
        .map(|entry| entry.name.as_slice())
        .collect::<Vec<_>>();
    let expected_entries = first
        .members
        .len()
        .checked_add(2)
        .and_then(|entries| u64::try_from(entries).ok())
        .context("Kbuild procfs directory entry count overflowed")?;
    let mut delivered_members = delivered_names.get(2..).unwrap_or_default().to_vec();
    delivered_members.sort();
    let KbuildObservedInputValue::Directory { entries, .. } = first.observation.value else {
        anyhow::bail!("Kbuild procfs directory opening has no retained directory value");
    };
    if entries != expected_entries
        || first.attempt.request.position_before != Some(0)
        || *first_bytes == 0
        || *first_position_after <= 0
        || delivered_names.first().copied() != Some(b".".as_slice())
        || delivered_names.get(1).copied() != Some(b"..".as_slice())
        || !delivered_members
            .iter()
            .copied()
            .eq(first.members.iter().map(Vec::as_slice))
        || eof.attempt.request.requested_bytes == 0
        || eof.attempt.request.position_before != Some(*first_position_after)
        || *eof_bytes != 0
        || *eof_position_after != *first_position_after
        || !eof_entries.is_empty()
        || first_value != eof_value
    {
        anyhow::bail!("Kbuild procfs directory opening did not prove its exact descriptor census");
    }
    Ok(())
}

#[cfg(unix)]
fn kbuild_procfs_mandatory_execution_policy(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    census: &KbuildProcfsReadCensusSeal,
    observations: &[KbuildProcfsReadObservation],
    directories: &KbuildProcfsDirectoryCensus,
    action_count: u64,
) -> Result<KbuildProcfsMandatoryExecutionSeal> {
    if census.graph_digest != graph_digest
        || census.stream_digest != stream_digest
        || census.assignment_digest != assignment_digest
        || directories.seal.graph_digest != graph_digest
        || directories.seal.stream_digest != stream_digest
        || directories.seal.assignment_digest != assignment_digest
    {
        anyhow::bail!("Kbuild procfs execution policy has inconsistent identity");
    }
    require_kbuild_procfs_directory_census(directories)?;
    if directories.seal.analyzer_observations != 0 {
        anyhow::bail!("Kbuild analyzer procfs directory has no execution policy");
    }

    let mut grouped = BTreeMap::<u64, KbuildProcfsMandatoryActionEvidence>::new();
    let mut read_observations = 0_u64;
    let mut directory_observations = 0_u64;
    let mut sequences =
        BTreeMap::<KbuildProcfsDirectorySequenceKey, Vec<&KbuildProcfsDirectoryCheckpoint>>::new();
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-procfs-mandatory-execution.v4\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&census.census_digest);
    hasher.update(&directories.seal.census_digest);
    for observation in observations {
        let KbuildProcessOwner::Action(action_index) = observation.owner else {
            continue;
        };
        if action_index >= action_count {
            anyhow::bail!("Kbuild procfs read has an unknown action owner");
        }
        match observation.value.class {
            KbuildProcfsReadClass::Filesystems => {}
            KbuildProcfsReadClass::VmOvercommitMemory => {}
            KbuildProcfsReadClass::CgroupCpuMax => {}
            KbuildProcfsReadClass::ProcessMaps
            | KbuildProcfsReadClass::ProcessStatm
            | KbuildProcfsReadClass::ProcessCgroup
                if observation
                    .self_open_syscall_index
                    .is_some_and(|open| open < observation.syscall_index) => {}
            KbuildProcfsReadClass::ProcessMaps
            | KbuildProcfsReadClass::ProcessStatm
            | KbuildProcfsReadClass::ProcessCgroup => {
                anyhow::bail!(
                    "Kbuild mandatory numeric-process read has no authenticated self identity"
                );
            }
        }
        read_observations = read_observations
            .checked_add(1)
            .context("Kbuild mandatory procfs read count overflowed")?;
        let group = grouped.entry(action_index).or_default();
        group.read_observations = group
            .read_observations
            .checked_add(1)
            .context("Kbuild action procfs read count overflowed")?;
        group
            .executable_identities
            .insert(observation.executable_digest);
        group.read_classes.insert(observation.value.class);

        hasher.update(&action_index.to_le_bytes());
        hasher.update(&observation.process.to_le_bytes());
        hasher.update(&observation.syscall_index.to_le_bytes());
        hasher.update(&observation.executable_digest);
        hasher.update(&[match observation.value.class {
            KbuildProcfsReadClass::Filesystems => 0,
            KbuildProcfsReadClass::ProcessMaps => 1,
            KbuildProcfsReadClass::ProcessStatm => 2,
            KbuildProcfsReadClass::VmOvercommitMemory => 3,
            KbuildProcfsReadClass::ProcessCgroup => 4,
            KbuildProcfsReadClass::CgroupCpuMax => 5,
        }]);
        match observation.self_open_syscall_index {
            Some(open) => {
                hasher.update(&[1]);
                hasher.update(&open.to_le_bytes());
            }
            None => {
                hasher.update(&[0]);
            }
        }
    }
    for checkpoint in directories.checkpoints.values() {
        let KbuildProcessOwner::Action(action_index) = checkpoint.observation.owner else {
            anyhow::bail!("Kbuild analyzer procfs directory has no mandatory execution owner");
        };
        if action_index >= action_count {
            anyhow::bail!("Kbuild procfs directory has an unknown action owner");
        }
        directory_observations = directory_observations
            .checked_add(1)
            .context("Kbuild mandatory procfs directory count overflowed")?;
        let group = grouped.entry(action_index).or_default();
        group.directory_observations = group
            .directory_observations
            .checked_add(1)
            .context("Kbuild action procfs directory count overflowed")?;
        group
            .executable_identities
            .insert(checkpoint.executable_digest);
        group
            .directory_classes
            .insert(KbuildProcfsDirectoryClass::ProcessFileDescriptors);
        sequences
            .entry(KbuildProcfsDirectorySequenceKey {
                action_index,
                process: checkpoint.observation.process,
                descriptor: checkpoint.anchor.descriptor,
                open_stream_ordinal: checkpoint.anchor.open_stream_ordinal,
            })
            .or_default()
            .push(checkpoint);
    }
    let directory_openings = u64::try_from(sequences.len())
        .context("Kbuild mandatory procfs directory opening count does not fit u64")?;
    for (key, checkpoints) in &mut sequences {
        checkpoints.sort_by_key(|checkpoint| checkpoint.observation.stream_ordinal);
        require_kbuild_procfs_directory_execution_sequence(checkpoints)?;
        let group = grouped
            .get_mut(&key.action_index)
            .context("Kbuild procfs directory sequence lost its action evidence")?;
        group.directory_openings = group
            .directory_openings
            .checked_add(1)
            .context("Kbuild action procfs directory opening count overflowed")?;
    }
    if read_observations != census.action_observations {
        anyhow::bail!("Kbuild mandatory policy does not cover the action procfs census");
    }
    if directory_observations != directories.seal.action_observations {
        anyhow::bail!("Kbuild mandatory policy does not cover the procfs directory census");
    }
    let distinct_actions = u64::try_from(grouped.len())
        .context("Kbuild mandatory procfs action count does not fit u64")?;
    let expected_actions = observations
        .iter()
        .filter_map(|observation| match observation.owner {
            KbuildProcessOwner::Analyzer => None,
            KbuildProcessOwner::Action(action_index) => Some(action_index),
        })
        .chain(directories.checkpoints.values().filter_map(|checkpoint| {
            match checkpoint.observation.owner {
                KbuildProcessOwner::Analyzer => None,
                KbuildProcessOwner::Action(action_index) => Some(action_index),
            }
        }))
        .collect::<BTreeSet<_>>();
    if grouped.keys().copied().collect::<BTreeSet<_>>() != expected_actions {
        anyhow::bail!("Kbuild mandatory policy action partition is incomplete");
    }

    hasher.update(&read_observations.to_le_bytes());
    hasher.update(&directory_observations.to_le_bytes());
    hasher.update(&directory_openings.to_le_bytes());
    hasher.update(&distinct_actions.to_le_bytes());
    let mut actions = Vec::with_capacity(grouped.len());
    for (action_index, evidence) in grouped {
        let filesystems_reads = observations
            .iter()
            .filter(|observation| {
                observation.owner == KbuildProcessOwner::Action(action_index)
                    && observation.value.class == KbuildProcfsReadClass::Filesystems
            })
            .copied()
            .collect::<Vec<_>>();
        let process_maps_executable_identities = observations
            .iter()
            .filter(|observation| {
                observation.owner == KbuildProcessOwner::Action(action_index)
                    && observation.value.class == KbuildProcfsReadClass::ProcessMaps
            })
            .map(|observation| observation.executable_digest)
            .collect::<BTreeSet<_>>();
        if evidence
            .read_classes
            .contains(&KbuildProcfsReadClass::Filesystems)
            != !filesystems_reads.is_empty()
        {
            anyhow::bail!("Kbuild action has incomplete /proc/filesystems evidence");
        }
        if evidence
            .read_classes
            .contains(&KbuildProcfsReadClass::ProcessMaps)
            != !process_maps_executable_identities.is_empty()
        {
            anyhow::bail!("Kbuild action has incomplete /proc/self/maps evidence");
        }
        let executable_identities = u64::try_from(evidence.executable_identities.len())
            .context("Kbuild mandatory executable count does not fit u64")?;
        let class_count = u64::try_from(evidence.read_classes.len())
            .context("Kbuild mandatory procfs class count does not fit u64")?;
        let directory_class_count = u64::try_from(evidence.directory_classes.len())
            .context("Kbuild mandatory procfs directory class count does not fit u64")?;
        hasher.update(&action_index.to_le_bytes());
        hasher.update(&evidence.read_observations.to_le_bytes());
        hasher.update(&evidence.directory_observations.to_le_bytes());
        hasher.update(&evidence.directory_openings.to_le_bytes());
        hasher.update(&executable_identities.to_le_bytes());
        for executable in &evidence.executable_identities {
            hasher.update(executable);
        }
        hasher.update(&class_count.to_le_bytes());
        for class in &evidence.read_classes {
            hasher.update(&[match class {
                KbuildProcfsReadClass::Filesystems => 0,
                KbuildProcfsReadClass::ProcessMaps => 1,
                KbuildProcfsReadClass::ProcessStatm => 2,
                KbuildProcfsReadClass::VmOvercommitMemory => 3,
                KbuildProcfsReadClass::ProcessCgroup => 4,
                KbuildProcfsReadClass::CgroupCpuMax => 5,
            }]);
        }
        hasher.update(&directory_class_count.to_le_bytes());
        for class in &evidence.directory_classes {
            hasher.update(&[match class {
                KbuildProcfsDirectoryClass::ProcessFileDescriptors => 0,
            }]);
        }
        actions.push(KbuildProcfsMandatoryAction {
            action_index,
            read_observations: evidence.read_observations,
            directory_observations: evidence.directory_observations,
            directory_openings: evidence.directory_openings,
            executable_identities,
            classes: evidence.read_classes.into_iter().collect(),
            directory_classes: evidence.directory_classes.into_iter().collect(),
            filesystems_reads,
            process_maps_executable_identities,
        });
    }
    Ok(KbuildProcfsMandatoryExecutionSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        census_digest: census.census_digest,
        directory_census_digest: directories.seal.census_digest,
        policy_digest: *hasher.finalize().as_bytes(),
        read_observations,
        directory_observations,
        directory_openings,
        actions,
    })
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy)]
struct KbuildMutationCandidateDigestBasis {
    graph: [u8; 32],
    stream: [u8; 32],
    assignment: [u8; 32],
    classification: [u8; 32],
    outcome: [u8; 32],
    coverage: [u8; 32],
}

#[cfg(unix)]
fn kbuild_mutation_candidate_attribution_digest_with_analyzer(
    basis: KbuildMutationCandidateDigestBasis,
    events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    analyzer_candidate_events: u64,
    analyzer_transient_paths: u64,
    actions: &[KbuildActionMutationCandidateCensus],
) -> Result<[u8; 32]> {
    let event_count =
        u64::try_from(events.len()).context("Kbuild mutation-event count does not fit u64")?;
    let action_count =
        u64::try_from(actions.len()).context("Kbuild mutation action count does not fit u64")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-mutation-candidate-attribution.v11\0");
    for digest in [
        basis.graph,
        basis.stream,
        basis.assignment,
        basis.classification,
        basis.outcome,
        basis.coverage,
    ] {
        hasher.update(&digest);
    }
    hasher.update(&event_count.to_le_bytes());
    for (owner, candidate) in events {
        match owner {
            KbuildProcessOwner::Analyzer => {
                hasher.update(&[0]);
            }
            KbuildProcessOwner::Action(action_index) => {
                hasher.update(&[1]);
                hasher.update(&action_index.to_le_bytes());
            }
        };
        hasher.update(&candidate.process.to_le_bytes());
        hasher.update(&candidate.stream_ordinal.to_le_bytes());
        hasher.update(&candidate.syscall_index.to_le_bytes());
        hasher.update(&[kbuild_mutation_candidate_kind_tag(candidate.kind)]);
        match (candidate.kind, candidate.object) {
            (
                KbuildMutationCandidateKind::CreateOrTruncateOpen
                | KbuildMutationCandidateKind::DescriptorWrite
                | KbuildMutationCandidateKind::SharedWritableMapping
                | KbuildMutationCandidateKind::DescriptorModeChange
                | KbuildMutationCandidateKind::DescriptorTimestampChange
                | KbuildMutationCandidateKind::DescriptorXattrChange,
                Some(object),
            ) => {
                hasher.update(&[1]);
                hasher.update(&object.device.to_le_bytes());
                hasher.update(&object.inode.to_le_bytes());
                hasher.update(&object.mount_id.to_le_bytes());
            }
            (
                KbuildMutationCandidateKind::PathRemoval
                | KbuildMutationCandidateKind::DirectoryCreation
                | KbuildMutationCandidateKind::PathRenameSource
                | KbuildMutationCandidateKind::PathRenameDestination
                | KbuildMutationCandidateKind::SymbolicLinkCreation
                | KbuildMutationCandidateKind::PathModeChange,
                None,
            ) => {
                hasher.update(&[0]);
            }
            _ => anyhow::bail!("Kbuild mutation candidate has an invalid object identity"),
        }
        let path_bytes = u64::try_from(candidate.relative.len())
            .context("Kbuild mutation-candidate path length does not fit u64")?;
        hasher.update(&path_bytes.to_le_bytes());
        hasher.update(&candidate.relative);
    }
    hasher.update(&analyzer_candidate_events.to_le_bytes());
    hasher.update(&analyzer_transient_paths.to_le_bytes());
    hasher.update(&action_count.to_le_bytes());
    for action in actions {
        hasher.update(&action.action_index.to_le_bytes());
        hasher.update(&action.candidate_events.to_le_bytes());
        hasher.update(&action.unique_paths.to_le_bytes());
        hasher.update(&action.persistent_paths.to_le_bytes());
        hasher.update(&action.transient_paths.to_le_bytes());
    }
    Ok(*hasher.finalize().as_bytes())
}

#[cfg(all(unix, test))]
fn kbuild_mutation_candidate_attribution_digest(
    basis: KbuildMutationCandidateDigestBasis,
    events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    actions: &[KbuildActionMutationCandidateCensus],
) -> Result<[u8; 32]> {
    kbuild_mutation_candidate_attribution_digest_with_analyzer(basis, events, 0, 0, actions)
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KbuildMutationCandidateKind {
    CreateOrTruncateOpen,
    DescriptorWrite,
    SharedWritableMapping,
    PathRemoval,
    DescriptorModeChange,
    DirectoryCreation,
    PathRenameSource,
    PathRenameDestination,
    SymbolicLinkCreation,
    PathModeChange,
    DescriptorTimestampChange,
    DescriptorXattrChange,
}

#[cfg(unix)]
impl KbuildMutationCandidateKind {
    fn label(self) -> &'static str {
        match self {
            Self::CreateOrTruncateOpen => "create-or-truncate open",
            Self::DescriptorWrite => "descriptor write",
            Self::SharedWritableMapping => "writable shared mapping",
            Self::PathRemoval => "path removal",
            Self::DescriptorModeChange => "descriptor mode change",
            Self::DirectoryCreation => "directory creation",
            Self::PathRenameSource => "rename source",
            Self::PathRenameDestination => "rename destination",
            Self::SymbolicLinkCreation => "symbolic-link creation",
            Self::PathModeChange => "path mode change",
            Self::DescriptorTimestampChange => "descriptor timestamp change",
            Self::DescriptorXattrChange => "descriptor extended-attribute change",
        }
    }
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct KbuildOutputObjectIdentity {
    device: u64,
    inode: u64,
    mount_id: u64,
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KbuildInputProvenanceClass {
    ExternalSeed,
    AnalyzerBootstrapDirectory,
    AnalyzerPostCandidateDirectory,
    SameOwnerPreMutation,
    SameOwnerPostCandidate,
    CrossOwnerMutation,
}

#[cfg(unix)]
#[derive(Debug, Clone)]
struct KbuildMutationCandidate {
    process: CapturedProcessId,
    stream_ordinal: u64,
    syscall_index: u64,
    kind: KbuildMutationCandidateKind,
    object: Option<KbuildOutputObjectIdentity>,
    path: PathBuf,
    relative: Vec<u8>,
}

#[cfg(unix)]
#[derive(Debug, Clone)]
struct KbuildInputMutationIndex {
    exact_paths: BTreeMap<PathBuf, (KbuildProcessOwner, u64)>,
    directory_effects: BTreeMap<PathBuf, KbuildDirectoryEffectTimeline>,
    directory_epoch_effects: BTreeMap<PathBuf, KbuildDirectoryEffectTimeline>,
    directory_epoch_events: BTreeMap<PathBuf, Vec<KbuildDirectoryEffectEvent>>,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum KbuildDirectoryEffectSubject {
    DirectoryObject,
    Member(Vec<u8>),
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct KbuildDirectoryEffectDescriptor {
    kind_tag: u8,
    subject: KbuildDirectoryEffectSubject,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct KbuildDirectoryEffectEvent {
    owner: KbuildProcessOwner,
    process: CapturedProcessId,
    syscall_index: u64,
    stream_ordinal: u64,
    kind: KbuildMutationCandidateKind,
    subject: KbuildDirectoryEffectSubject,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct KbuildDirectoryEffectTimeline {
    owners: BTreeSet<KbuildProcessOwner>,
    first_stream_ordinal: u64,
    last_stream_ordinal: u64,
}

#[cfg(unix)]
impl KbuildDirectoryEffectTimeline {
    fn record(
        effects: &mut BTreeMap<PathBuf, Self>,
        path: PathBuf,
        owner: KbuildProcessOwner,
        stream_ordinal: u64,
    ) {
        let effect = effects.entry(path).or_insert_with(|| Self {
            owners: BTreeSet::new(),
            first_stream_ordinal: stream_ordinal,
            last_stream_ordinal: stream_ordinal,
        });
        effect.owners.insert(owner);
        effect.first_stream_ordinal = effect.first_stream_ordinal.min(stream_ordinal);
        effect.last_stream_ordinal = effect.last_stream_ordinal.max(stream_ordinal);
    }
}

#[cfg(unix)]
impl KbuildInputMutationIndex {
    fn from_events(
        mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    ) -> Result<Self> {
        let mut syscall_batches = BTreeMap::<
            (CapturedProcessId, u64, u64),
            (KbuildProcessOwner, Vec<KbuildMutationCandidateKind>),
        >::new();
        for (owner, mutation) in mutation_events {
            let entry = syscall_batches
                .entry((
                    mutation.process,
                    mutation.syscall_index,
                    mutation.stream_ordinal,
                ))
                .or_insert_with(|| (*owner, Vec::new()));
            if entry.0 != *owner {
                anyhow::bail!("Kbuild mutation syscall batch has different owners");
            }
            entry.1.push(mutation.kind);
        }
        for (_, kinds) in syscall_batches.values() {
            let rename_sources = kinds
                .iter()
                .filter(|kind| **kind == KbuildMutationCandidateKind::PathRenameSource)
                .count();
            let rename_destinations = kinds
                .iter()
                .filter(|kind| **kind == KbuildMutationCandidateKind::PathRenameDestination)
                .count();
            if rename_sources != 0 || rename_destinations != 0 {
                if kinds.len() != 2 || rename_sources != 1 || rename_destinations != 1 {
                    anyhow::bail!("Kbuild rename syscall batch is incomplete");
                }
            } else if kinds.len() != 1 {
                anyhow::bail!("Kbuild mutation syscall batch repeats a non-rename effect");
            }
        }
        let mut exact_paths = BTreeMap::new();
        let mut directory_effects = BTreeMap::new();
        let mut directory_epoch_effects = BTreeMap::new();
        let mut directory_epoch_events: BTreeMap<PathBuf, Vec<KbuildDirectoryEffectEvent>> =
            BTreeMap::new();
        for (owner, mutation) in mutation_events {
            match exact_paths.entry(mutation.path.clone()) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert((*owner, mutation.stream_ordinal));
                }
                std::collections::btree_map::Entry::Occupied(mut entry) => {
                    if entry.get().0 != *owner {
                        anyhow::bail!("Kbuild input provenance mutation path has multiple owners");
                    }
                    if mutation.stream_ordinal < entry.get().1 {
                        entry.get_mut().1 = mutation.stream_ordinal;
                    }
                }
            }

            if matches!(
                mutation.kind,
                KbuildMutationCandidateKind::CreateOrTruncateOpen
                    | KbuildMutationCandidateKind::PathRemoval
                    | KbuildMutationCandidateKind::DirectoryCreation
                    | KbuildMutationCandidateKind::PathRenameSource
                    | KbuildMutationCandidateKind::PathRenameDestination
                    | KbuildMutationCandidateKind::SymbolicLinkCreation
            ) {
                let parent = mutation
                    .path
                    .parent()
                    .context("Kbuild mutation candidate has no parent directory")?
                    .to_path_buf();
                KbuildDirectoryEffectTimeline::record(
                    &mut directory_effects,
                    parent.clone(),
                    *owner,
                    mutation.stream_ordinal,
                );
                KbuildDirectoryEffectTimeline::record(
                    &mut directory_epoch_effects,
                    parent.clone(),
                    *owner,
                    mutation.stream_ordinal,
                );
                let member = mutation
                    .path
                    .file_name()
                    .map(os_bytes)
                    .context("Kbuild directory effect has no member name")?;
                if member.is_empty()
                    || member.contains(&0)
                    || member.contains(&b'/')
                    || member.as_slice() == b"."
                    || member.as_slice() == b".."
                {
                    anyhow::bail!("Kbuild directory effect has an invalid member name");
                }
                directory_epoch_events.entry(parent).or_default().push(
                    KbuildDirectoryEffectEvent {
                        owner: *owner,
                        process: mutation.process,
                        syscall_index: mutation.syscall_index,
                        stream_ordinal: mutation.stream_ordinal,
                        kind: mutation.kind,
                        subject: KbuildDirectoryEffectSubject::Member(member),
                    },
                );
            }
            if matches!(
                mutation.kind,
                KbuildMutationCandidateKind::PathRemoval
                    | KbuildMutationCandidateKind::DirectoryCreation
                    | KbuildMutationCandidateKind::PathRenameSource
                    | KbuildMutationCandidateKind::PathRenameDestination
            ) {
                KbuildDirectoryEffectTimeline::record(
                    &mut directory_epoch_effects,
                    mutation.path.clone(),
                    *owner,
                    mutation.stream_ordinal,
                );
                directory_epoch_events
                    .entry(mutation.path.clone())
                    .or_default()
                    .push(KbuildDirectoryEffectEvent {
                        owner: *owner,
                        process: mutation.process,
                        syscall_index: mutation.syscall_index,
                        stream_ordinal: mutation.stream_ordinal,
                        kind: mutation.kind,
                        subject: KbuildDirectoryEffectSubject::DirectoryObject,
                    });
            }
        }
        for events in directory_epoch_events.values_mut() {
            if events
                .windows(2)
                .any(|pair| pair[0].stream_ordinal > pair[1].stream_ordinal)
            {
                anyhow::bail!("Kbuild directory effect events are not in stream order");
            }
            events.sort_by(|left, right| {
                (
                    left.stream_ordinal,
                    left.process,
                    left.syscall_index,
                    kbuild_mutation_candidate_kind_tag(left.kind),
                    left.owner,
                    &left.subject,
                )
                    .cmp(&(
                        right.stream_ordinal,
                        right.process,
                        right.syscall_index,
                        kbuild_mutation_candidate_kind_tag(right.kind),
                        right.owner,
                        &right.subject,
                    ))
            });
        }
        Ok(Self {
            exact_paths,
            directory_effects,
            directory_epoch_effects,
            directory_epoch_events,
        })
    }

    fn classify(&self, observation: &KbuildInputObservation) -> KbuildInputProvenanceClass {
        if let Some((owner, first_mutation)) = self.exact_paths.get(&observation.path) {
            return if *owner != observation.owner {
                KbuildInputProvenanceClass::CrossOwnerMutation
            } else if observation.stream_ordinal < *first_mutation {
                KbuildInputProvenanceClass::SameOwnerPreMutation
            } else {
                KbuildInputProvenanceClass::SameOwnerPostCandidate
            };
        }
        if observation.object.kind != KbuildInputObjectKind::Directory {
            return KbuildInputProvenanceClass::ExternalSeed;
        }
        let Some(effect) = self.directory_effects.get(&observation.path) else {
            return KbuildInputProvenanceClass::ExternalSeed;
        };
        if observation.owner == KbuildProcessOwner::Analyzer {
            if observation.stream_ordinal < effect.first_stream_ordinal {
                KbuildInputProvenanceClass::AnalyzerBootstrapDirectory
            } else {
                KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory
            }
        } else if effect.owners.len() == 1 && effect.owners.contains(&observation.owner) {
            if observation.stream_ordinal < effect.first_stream_ordinal {
                KbuildInputProvenanceClass::SameOwnerPreMutation
            } else {
                KbuildInputProvenanceClass::SameOwnerPostCandidate
            }
        } else {
            KbuildInputProvenanceClass::CrossOwnerMutation
        }
    }
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KbuildProcessEventKey {
    process: CapturedProcessId,
    syscall_index: u64,
    stream_ordinal: u64,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct KbuildDirectoryEffectBatch {
    owner: KbuildProcessOwner,
    event: KbuildProcessEventKey,
    effects: Vec<KbuildDirectoryEffectDescriptor>,
}

#[cfg(unix)]
fn kbuild_directory_effect_batches(
    effects: &[KbuildDirectoryEffectEvent],
) -> Result<Vec<KbuildDirectoryEffectBatch>> {
    let mut grouped = BTreeMap::<
        (u64, CapturedProcessId, u64),
        (
            KbuildProcessOwner,
            BTreeSet<KbuildDirectoryEffectDescriptor>,
        ),
    >::new();
    for effect in effects {
        let key = (effect.stream_ordinal, effect.process, effect.syscall_index);
        let entry = grouped
            .entry(key)
            .or_insert_with(|| (effect.owner, BTreeSet::new()));
        if entry.0 != effect.owner {
            anyhow::bail!("Kbuild directory co-effects have different owners");
        }
        entry.1.insert(KbuildDirectoryEffectDescriptor {
            kind_tag: kbuild_mutation_candidate_kind_tag(effect.kind),
            subject: effect.subject.clone(),
        });
    }
    Ok(grouped
        .into_iter()
        .map(
            |((stream_ordinal, process, syscall_index), (owner, effects))| {
                KbuildDirectoryEffectBatch {
                    owner,
                    event: KbuildProcessEventKey {
                        process,
                        syscall_index,
                        stream_ordinal,
                    },
                    effects: effects.into_iter().collect(),
                }
            },
        )
        .collect())
}

#[cfg(unix)]
fn update_kbuild_directory_effect_descriptors(
    hasher: &mut blake3::Hasher,
    effects: &[KbuildDirectoryEffectDescriptor],
) -> Result<()> {
    hasher.update(
        &u64::try_from(effects.len())
            .context("Kbuild directory batch effect count does not fit u64")?
            .to_le_bytes(),
    );
    for effect in effects {
        hasher.update(&[effect.kind_tag]);
        match &effect.subject {
            KbuildDirectoryEffectSubject::DirectoryObject => {
                hasher.update(&[0]);
            }
            KbuildDirectoryEffectSubject::Member(member) => {
                hasher.update(&[1]);
                hash_kbuild_bytes(hasher, member)?;
            }
        }
    }
    Ok(())
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KbuildProcessCreationBoundary {
    parent: CapturedProcessId,
    syscall_index: u64,
    stream_ordinal: u64,
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KbuildProcessReapBoundary {
    parent: CapturedProcessId,
    syscall_index: u64,
    stream_ordinal: u64,
    status: u32,
}

#[cfg(unix)]
#[derive(Debug, Clone, Default)]
struct KbuildProcessCausality {
    creations: BTreeMap<CapturedProcessId, KbuildProcessCreationBoundary>,
    reaps: BTreeMap<CapturedProcessId, KbuildProcessReapBoundary>,
    finishes: BTreeMap<CapturedProcessId, (u64, CapturedProcessOutcome)>,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct KbuildProcessBranchDiagnostic {
    common_ancestor: CapturedProcessId,
    left_branch_child: CapturedProcessId,
    right_branch_child: CapturedProcessId,
    left_finish: Option<(u64, CapturedProcessOutcome)>,
    left_reap: Option<KbuildProcessReapBoundary>,
    right_creation: Option<KbuildProcessCreationBoundary>,
}

#[cfg(unix)]
fn kbuild_wait_status_matches_process_outcome(
    status: u32,
    outcome: CapturedProcessOutcome,
) -> bool {
    match outcome {
        CapturedProcessOutcome::Exited(exit_status)
            if (0..=i32::from(u8::MAX)).contains(&exit_status) =>
        {
            status == (exit_status as u32) << 8
        }
        CapturedProcessOutcome::Signaled(signal) if (1..=64).contains(&signal) => {
            let signal = signal as u32;
            status == signal || status == (signal | 0x80)
        }
        _ => false,
    }
}

#[cfg(unix)]
impl KbuildProcessCausality {
    fn new(
        parents: &BTreeMap<CapturedProcessId, Option<CapturedProcessId>>,
        creations: BTreeMap<CapturedProcessId, KbuildProcessCreationBoundary>,
        reaps: BTreeMap<CapturedProcessId, KbuildProcessReapBoundary>,
        finishes: BTreeMap<CapturedProcessId, (u64, CapturedProcessOutcome)>,
    ) -> Result<Self> {
        let expected_creations = parents.values().filter(|parent| parent.is_some()).count();
        if creations.len() != expected_creations {
            anyhow::bail!("Kbuild process causality has incomplete creation boundaries");
        }
        for (process, parent) in parents {
            match parent {
                Some(parent)
                    if creations
                        .get(process)
                        .is_some_and(|boundary| boundary.parent == *parent) => {}
                Some(_) => {
                    anyhow::bail!("Kbuild process parent differs from its creation boundary")
                }
                None if creations.contains_key(process) => {
                    anyhow::bail!("Kbuild root process has a creation boundary")
                }
                None => {}
            }
        }
        if finishes.len() != parents.len()
            || parents
                .keys()
                .any(|process| !finishes.contains_key(process))
        {
            anyhow::bail!("Kbuild process causality has incomplete finish boundaries");
        }
        for (child, reap) in &reaps {
            if !creations
                .get(child)
                .is_some_and(|creation| creation.parent == reap.parent)
            {
                anyhow::bail!("Kbuild child reap has no matching direct creation boundary");
            }
            let (finish_ordinal, outcome) = finishes
                .get(child)
                .context("Kbuild reaped child has no finish boundary")?;
            if *finish_ordinal >= reap.stream_ordinal {
                anyhow::bail!("Kbuild child reap does not follow the child finish boundary");
            }
            let (parent_finish_ordinal, _) = finishes
                .get(&reap.parent)
                .context("Kbuild child reap has no parent finish boundary")?;
            if reap.stream_ordinal >= *parent_finish_ordinal {
                anyhow::bail!("Kbuild child reap does not precede the parent finish boundary");
            }
            if !kbuild_wait_status_matches_process_outcome(reap.status, *outcome) {
                anyhow::bail!("Kbuild child reap status differs from the child outcome");
            }
        }
        Ok(Self {
            creations,
            reaps,
            finishes,
        })
    }

    fn process_chain(&self, process: CapturedProcessId) -> Result<Vec<CapturedProcessId>> {
        let mut chain = vec![process];
        let mut current = process;
        while let Some(boundary) = self.creations.get(&current) {
            if chain.contains(&boundary.parent) {
                anyhow::bail!("Kbuild process creation graph has a cycle");
            }
            chain.push(boundary.parent);
            current = boundary.parent;
        }
        chain.reverse();
        Ok(chain)
    }

    fn branch_diagnostic(
        &self,
        left: CapturedProcessId,
        right: CapturedProcessId,
    ) -> Result<Option<KbuildProcessBranchDiagnostic>> {
        let left_chain = self.process_chain(left)?;
        let right_chain = self.process_chain(right)?;
        let shared = left_chain
            .iter()
            .zip(&right_chain)
            .take_while(|(left, right)| left == right)
            .count();
        if shared == 0 || shared == left_chain.len() || shared == right_chain.len() {
            return Ok(None);
        }
        let common_ancestor = left_chain[shared - 1];
        let left_branch_child = left_chain[shared];
        let right_branch_child = right_chain[shared];
        Ok(Some(KbuildProcessBranchDiagnostic {
            common_ancestor,
            left_branch_child,
            right_branch_child,
            left_finish: self.finishes.get(&left_branch_child).copied(),
            left_reap: self.reaps.get(&left_branch_child).copied(),
            right_creation: self.creations.get(&right_branch_child).copied(),
        }))
    }

    fn event_precedes_process_finish(
        &self,
        event: KbuildProcessEventKey,
        process: CapturedProcessId,
    ) -> Result<bool> {
        let chain = self.process_chain(event.process)?;
        if !chain.contains(&process) {
            return Ok(false);
        }
        let Some((finish_ordinal, _)) = self.finishes.get(&event.process) else {
            return Ok(false);
        };
        if event.stream_ordinal >= *finish_ordinal {
            anyhow::bail!("Kbuild causal event does not precede its process finish boundary");
        }
        let mut current = event.process;
        while current != process {
            let Some(reap) = self.reaps.get(&current) else {
                return Ok(false);
            };
            current = reap.parent;
        }
        Ok(true)
    }

    fn definitely_before(
        &self,
        before: KbuildProcessEventKey,
        after: KbuildProcessEventKey,
    ) -> Result<bool> {
        if before.process == after.process {
            return Ok(before.syscall_index < after.syscall_index);
        }
        let before_chain = self.process_chain(before.process)?;
        let after_chain = self.process_chain(after.process)?;
        let shared = before_chain
            .iter()
            .zip(&after_chain)
            .take_while(|(left, right)| left == right)
            .count();
        if shared == 0 {
            return Ok(false);
        }
        if shared == before_chain.len() {
            let child = after_chain
                .get(shared)
                .context("Kbuild descendant chain has no branch child")?;
            let (parent, create_index) = self
                .creations
                .get(child)
                .map(|boundary| (boundary.parent, boundary.syscall_index))
                .context("Kbuild descendant has no creation boundary")?;
            return Ok(parent == before.process && before.syscall_index < create_index);
        }
        if shared == after_chain.len() {
            let child = before_chain
                .get(shared)
                .context("Kbuild ancestor chain has no branch child")?;
            let Some(reap) = self.reaps.get(child) else {
                return Ok(false);
            };
            return Ok(reap.parent == after.process
                && self.event_precedes_process_finish(before, *child)?
                && reap.syscall_index < after.syscall_index);
        }
        let common = before_chain[shared - 1];
        let before_child = before_chain[shared];
        let after_child = after_chain[shared];
        let Some(reap) = self.reaps.get(&before_child) else {
            return Ok(false);
        };
        let creation = self
            .creations
            .get(&after_child)
            .context("Kbuild sibling branch has no creation boundary")?;
        Ok(reap.parent == common
            && creation.parent == common
            && self.event_precedes_process_finish(before, before_child)?
            && reap.syscall_index < creation.syscall_index)
    }
}

#[cfg(unix)]
fn kbuild_input_provenance_partition(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census: &KbuildInputValueCensusSeal,
    mutation_attribution_digest: [u8; 32],
    observations: &[KbuildInputObservation],
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
) -> Result<KbuildInputProvenancePartitionSeal> {
    if input_census.graph_digest != graph_digest
        || input_census.stream_digest != stream_digest
        || input_census.assignment_digest != assignment_digest
    {
        anyhow::bail!("Kbuild input provenance has inconsistent census identity");
    }
    if mutation_events
        .windows(2)
        .any(|pair| pair[0].1.stream_ordinal > pair[1].1.stream_ordinal)
    {
        anyhow::bail!("Kbuild mutation events are not in stream order");
    }

    let mutation_index = KbuildInputMutationIndex::from_events(mutation_events)?;

    let observations_count = u64::try_from(observations.len())
        .context("Kbuild input-provenance observation count does not fit u64")?;
    if observations_count != input_census.observations {
        anyhow::bail!("Kbuild input provenance does not cover the input census");
    }
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-input-provenance-partition.v3\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&input_census.census_digest);
    hasher.update(&mutation_attribution_digest);
    hasher.update(&observations_count.to_le_bytes());

    let mut external_seed_observations = 0_u64;
    let mut analyzer_external_seed_observations = 0_u64;
    let mut action_external_seed_observations = 0_u64;
    let mut analyzer_bootstrap_directory_observations = 0_u64;
    let mut analyzer_post_candidate_directory_observations = 0_u64;
    let mut same_owner_pre_mutation_observations = 0_u64;
    let mut same_owner_post_candidate_observations = 0_u64;
    let mut cross_owner_mutation_observations = 0_u64;
    let unclassified_observations = 0_u64;
    let mut external_seed_paths = BTreeSet::new();
    let mut analyzer_bootstrap_directories = BTreeSet::new();
    let mut analyzer_post_candidate_directories = BTreeSet::new();
    let mut pre_mutation_paths = BTreeSet::new();
    let mut post_candidate_paths = BTreeSet::new();
    let mut cross_owner_paths = BTreeSet::new();
    let mut observed_exact_mutation_paths = BTreeSet::new();
    let mut observed_directory_effect_paths = BTreeSet::new();
    let mut exact_mutation_observations = 0_u64;
    let mut exact_cross_owner_observations = 0_u64;
    let mut directory_effect_observations = 0_u64;

    for observation in observations {
        let exact_mutation = mutation_index.exact_paths.contains_key(&observation.path);
        let directory_effect = !exact_mutation
            && observation.object.kind == KbuildInputObjectKind::Directory
            && mutation_index
                .directory_effects
                .contains_key(&observation.path);
        let class = mutation_index.classify(observation);
        hasher.update(&observation.ordinal.to_le_bytes());
        hasher.update(&[match class {
            KbuildInputProvenanceClass::ExternalSeed => 0,
            KbuildInputProvenanceClass::SameOwnerPreMutation => 1,
            KbuildInputProvenanceClass::SameOwnerPostCandidate => 2,
            KbuildInputProvenanceClass::CrossOwnerMutation => 3,
            KbuildInputProvenanceClass::AnalyzerBootstrapDirectory => 4,
            KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => 5,
        }]);
        if exact_mutation {
            exact_mutation_observations = exact_mutation_observations
                .checked_add(1)
                .context("Kbuild exact mutation observation count overflowed")?;
            observed_exact_mutation_paths.insert(observation.path.clone());
            if class == KbuildInputProvenanceClass::CrossOwnerMutation {
                exact_cross_owner_observations = exact_cross_owner_observations
                    .checked_add(1)
                    .context("Kbuild exact cross-owner observation count overflowed")?;
            }
        } else if directory_effect {
            directory_effect_observations = directory_effect_observations
                .checked_add(1)
                .context("Kbuild directory-effect observation count overflowed")?;
            observed_directory_effect_paths.insert(observation.path.clone());
        }
        match class {
            KbuildInputProvenanceClass::ExternalSeed => {
                external_seed_observations = external_seed_observations
                    .checked_add(1)
                    .context("Kbuild external-seed observation count overflowed")?;
                external_seed_paths.insert(observation.path.clone());
                match observation.owner {
                    KbuildProcessOwner::Analyzer => {
                        analyzer_external_seed_observations = analyzer_external_seed_observations
                            .checked_add(1)
                            .context("Kbuild analyzer seed count overflowed")?;
                    }
                    KbuildProcessOwner::Action(_) => {
                        action_external_seed_observations = action_external_seed_observations
                            .checked_add(1)
                            .context("Kbuild action seed count overflowed")?;
                    }
                }
            }
            KbuildInputProvenanceClass::AnalyzerBootstrapDirectory => {
                analyzer_bootstrap_directory_observations =
                    analyzer_bootstrap_directory_observations
                        .checked_add(1)
                        .context("Kbuild analyzer bootstrap count overflowed")?;
                analyzer_bootstrap_directories.insert(observation.path.clone());
            }
            KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => {
                analyzer_post_candidate_directory_observations =
                    analyzer_post_candidate_directory_observations
                        .checked_add(1)
                        .context("Kbuild analyzer post-candidate count overflowed")?;
                analyzer_post_candidate_directories.insert(observation.path.clone());
            }
            KbuildInputProvenanceClass::SameOwnerPreMutation => {
                same_owner_pre_mutation_observations = same_owner_pre_mutation_observations
                    .checked_add(1)
                    .context("Kbuild pre-mutation observation count overflowed")?;
                pre_mutation_paths.insert(observation.path.clone());
            }
            KbuildInputProvenanceClass::SameOwnerPostCandidate => {
                same_owner_post_candidate_observations = same_owner_post_candidate_observations
                    .checked_add(1)
                    .context("Kbuild post-candidate observation count overflowed")?;
                post_candidate_paths.insert(observation.path.clone());
            }
            KbuildInputProvenanceClass::CrossOwnerMutation => {
                cross_owner_mutation_observations = cross_owner_mutation_observations
                    .checked_add(1)
                    .context("Kbuild cross-owner observation count overflowed")?;
                cross_owner_paths.insert(observation.path.clone());
            }
        }
    }

    let external_owner_total = analyzer_external_seed_observations
        .checked_add(action_external_seed_observations)
        .context("Kbuild external-seed owner count overflowed")?;
    let semantic_mutation_observation_total = same_owner_pre_mutation_observations
        .checked_add(same_owner_post_candidate_observations)
        .and_then(|count| count.checked_add(cross_owner_mutation_observations))
        .context("Kbuild mutation-path provenance count overflowed")?;
    let classified_total = external_seed_observations
        .checked_add(analyzer_bootstrap_directory_observations)
        .and_then(|count| count.checked_add(analyzer_post_candidate_directory_observations))
        .and_then(|count| count.checked_add(semantic_mutation_observation_total))
        .and_then(|count| count.checked_add(unclassified_observations))
        .context("Kbuild input-provenance partition count overflowed")?;
    let census_external_observations = external_seed_observations
        .checked_add(directory_effect_observations)
        .context("Kbuild census-external observation count overflowed")?;
    let mut census_external_paths = external_seed_paths.clone();
    census_external_paths.extend(observed_directory_effect_paths.iter().cloned());
    if classified_total != observations_count
        || external_owner_total != external_seed_observations
        || census_external_observations != input_census.external_observations
        || exact_mutation_observations != input_census.mutation_path_observations
        || exact_cross_owner_observations != input_census.cross_owner_mutation_path_observations
        || census_external_paths.len()
            != usize::try_from(input_census.distinct_external_paths)
                .context("Kbuild external path count does not fit usize")?
        || observed_exact_mutation_paths.len()
            != usize::try_from(input_census.distinct_mutation_paths)
                .context("Kbuild mutation path count does not fit usize")?
    {
        anyhow::bail!("Kbuild input-provenance partition is internally inconsistent");
    }

    let distinct_external_seed_paths = u64::try_from(external_seed_paths.len())
        .context("Kbuild distinct external-seed path count does not fit u64")?;
    let distinct_analyzer_bootstrap_directories =
        u64::try_from(analyzer_bootstrap_directories.len())
            .context("Kbuild distinct analyzer-bootstrap count does not fit u64")?;
    let distinct_analyzer_post_candidate_directories =
        u64::try_from(analyzer_post_candidate_directories.len())
            .context("Kbuild distinct analyzer post-candidate count does not fit u64")?;
    let distinct_pre_mutation_paths = u64::try_from(pre_mutation_paths.len())
        .context("Kbuild distinct pre-mutation path count does not fit u64")?;
    let distinct_post_candidate_paths = u64::try_from(post_candidate_paths.len())
        .context("Kbuild distinct post-candidate path count does not fit u64")?;
    let distinct_cross_owner_paths = u64::try_from(cross_owner_paths.len())
        .context("Kbuild distinct cross-owner path count does not fit u64")?;
    for count in [
        external_seed_observations,
        analyzer_external_seed_observations,
        action_external_seed_observations,
        analyzer_bootstrap_directory_observations,
        analyzer_post_candidate_directory_observations,
        same_owner_pre_mutation_observations,
        same_owner_post_candidate_observations,
        cross_owner_mutation_observations,
        unclassified_observations,
        distinct_external_seed_paths,
        distinct_analyzer_bootstrap_directories,
        distinct_analyzer_post_candidate_directories,
        distinct_pre_mutation_paths,
        distinct_post_candidate_paths,
        distinct_cross_owner_paths,
    ] {
        hasher.update(&count.to_le_bytes());
    }

    Ok(KbuildInputProvenancePartitionSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census_digest: input_census.census_digest,
        mutation_attribution_digest,
        partition_digest: *hasher.finalize().as_bytes(),
        observations: observations_count,
        external_seed_observations,
        analyzer_external_seed_observations,
        action_external_seed_observations,
        analyzer_bootstrap_directory_observations,
        analyzer_post_candidate_directory_observations,
        same_owner_pre_mutation_observations,
        same_owner_post_candidate_observations,
        cross_owner_mutation_observations,
        unclassified_observations,
        distinct_external_seed_paths,
        distinct_analyzer_bootstrap_directories,
        distinct_analyzer_post_candidate_directories,
        distinct_pre_mutation_paths,
        distinct_post_candidate_paths,
        distinct_cross_owner_paths,
    })
}

#[cfg(unix)]
fn update_kbuild_generated_observation(
    hasher: &mut blake3::Hasher,
    observation: &KbuildInputObservation,
) -> Result<()> {
    hasher.update(&observation.ordinal.to_le_bytes());
    hasher.update(&observation.stream_ordinal.to_le_bytes());
    hasher.update(&[match observation.class {
        KbuildInputObservationClass::Executable => 0,
        KbuildInputObservationClass::ExecMapping => 1,
        KbuildInputObservationClass::Open => 2,
        KbuildInputObservationClass::Mmap => 3,
        KbuildInputObservationClass::Read => 4,
        KbuildInputObservationClass::Directory => 5,
    }]);
    hasher.update(&observation.object.device.to_le_bytes());
    hasher.update(&observation.object.inode.to_le_bytes());
    hasher.update(
        &observation
            .object
            .mount_id
            .context("Kbuild cross-owner observation has no mount identity")?
            .to_le_bytes(),
    );
    hasher.update(&[match observation.object.kind {
        KbuildInputObjectKind::RegularFile => 0,
        KbuildInputObjectKind::Directory => 1,
    }]);
    match observation.value {
        KbuildObservedInputValue::WholeFile {
            bytes,
            digest,
            mode,
        } => {
            hasher.update(&[0]);
            hasher.update(&bytes.to_le_bytes());
            hasher.update(&digest);
            hasher.update(&mode.to_le_bytes());
        }
        KbuildObservedInputValue::Directory {
            entries,
            digest,
            listing_digest,
        } => {
            hasher.update(&[1]);
            hasher.update(&entries.to_le_bytes());
            hasher.update(&digest);
            hasher.update(&listing_digest);
        }
    }
    Ok(())
}

#[cfg(unix)]
fn kbuild_generated_regular_file_matches(
    observation: &KbuildInputObservation,
    output: &KbuildFinalOutputValue,
) -> bool {
    let KbuildObservedInputValue::WholeFile {
        bytes,
        digest,
        mode,
    } = observation.value
    else {
        return false;
    };
    observation.object.kind == KbuildInputObjectKind::RegularFile
        && observation.object.device == output.object.device
        && observation.object.inode == output.object.inode
        && observation.object.mount_id == Some(output.object.mount_id)
        && output.kind == KbuildFinalOutputKind::RegularFile
        && bytes == output.bytes
        && digest == output.digest
        && mode == output.mode
}

#[cfg(unix)]
fn kbuild_generated_directory_matches(
    observation: &KbuildInputObservation,
    output: &KbuildFinalOutputValue,
) -> bool {
    matches!(
        observation.value,
        KbuildObservedInputValue::Directory { .. }
    ) && observation.object.kind == KbuildInputObjectKind::Directory
        && observation.object.device == output.object.device
        && observation.object.inode == output.object.inode
        && observation.object.mount_id == Some(output.object.mount_id)
        && output.kind == KbuildFinalOutputKind::Directory
}

#[cfg(unix)]
fn kbuild_directory_epoch_boundary(
    observation: &KbuildInputObservation,
    mutation_index: &KbuildInputMutationIndex,
) -> Result<Option<(u64, u64, BTreeSet<KbuildProcessOwner>)>> {
    if !matches!(
        observation.value,
        KbuildObservedInputValue::Directory { .. }
    ) {
        return Ok(None);
    }
    let Some(effect) = mutation_index
        .directory_epoch_effects
        .get(&observation.path)
    else {
        return Ok(None);
    };
    if effect.owners.is_empty() || effect.first_stream_ordinal > effect.last_stream_ordinal {
        anyhow::bail!("Kbuild directory epoch candidate has malformed effect boundaries");
    }
    Ok(Some((
        effect.first_stream_ordinal,
        effect.last_stream_ordinal,
        effect.owners.clone(),
    )))
}

#[cfg(unix)]
fn kbuild_process_event_relation(
    causality: &KbuildProcessCausality,
    left: KbuildProcessEventKey,
    right: KbuildProcessEventKey,
) -> Result<u8> {
    let left_before = causality.definitely_before(left, right)?;
    let right_before = causality.definitely_before(right, left)?;
    match (left_before, right_before) {
        (true, false) => Ok(0),
        (false, true) => Ok(1),
        (false, false) => Ok(2),
        (true, true) => anyhow::bail!("Kbuild process causality contains a cycle"),
    }
}

#[cfg(unix)]
fn kbuild_mutation_candidate_kind_tag(kind: KbuildMutationCandidateKind) -> u8 {
    match kind {
        KbuildMutationCandidateKind::CreateOrTruncateOpen => 0,
        KbuildMutationCandidateKind::DescriptorWrite => 1,
        KbuildMutationCandidateKind::PathRemoval => 2,
        KbuildMutationCandidateKind::DescriptorModeChange => 3,
        KbuildMutationCandidateKind::DirectoryCreation => 4,
        KbuildMutationCandidateKind::PathRenameSource => 5,
        KbuildMutationCandidateKind::PathRenameDestination => 6,
        KbuildMutationCandidateKind::SymbolicLinkCreation => 7,
        KbuildMutationCandidateKind::PathModeChange => 8,
        KbuildMutationCandidateKind::DescriptorTimestampChange => 9,
        KbuildMutationCandidateKind::SharedWritableMapping => 10,
        KbuildMutationCandidateKind::DescriptorXattrChange => 11,
    }
}

#[cfg(unix)]
fn kbuild_directory_membership_effect_class(kind_tag: u8) -> Result<(u8, bool)> {
    match kind_tag {
        0 => Ok((0, false)),
        2 | 5 => Ok((2, true)),
        4 | 7 => Ok((1, true)),
        6 => Ok((3, false)),
        _ => anyhow::bail!("Kbuild directory effect has no membership semantics"),
    }
}

#[cfg(unix)]
fn kbuild_membership_neutral_actions(
    batches: &[KbuildDirectoryEffectBatch],
    members: &[Vec<u8>],
    action_count: u64,
) -> Result<BTreeSet<u64>> {
    kbuild_membership_neutral_actions_projected(
        batches,
        members,
        action_count,
        &BTreeSet::new(),
    )
}

#[cfg(unix)]
fn kbuild_membership_neutral_actions_projected(
    batches: &[KbuildDirectoryEffectBatch],
    members: &[Vec<u8>],
    action_count: u64,
    ignored_members: &BTreeSet<Vec<u8>>,
) -> Result<BTreeSet<u64>> {
    let mut final_membership = BTreeMap::<u64, BTreeMap<Vec<u8>, bool>>::new();
    let mut directory_object_actions = BTreeSet::new();
    for batch in batches {
        let KbuildProcessOwner::Action(action_index) = batch.owner else {
            continue;
        };
        if action_index >= action_count {
            anyhow::bail!("Kbuild directory membership owner exceeds the graph");
        }
        for effect in &batch.effects {
            match &effect.subject {
                KbuildDirectoryEffectSubject::DirectoryObject => {
                    directory_object_actions.insert(action_index);
                }
                KbuildDirectoryEffectSubject::Member(member) => {
                    if ignored_members.contains(member) {
                        continue;
                    }
                    let present = match effect.kind_tag {
                        0 | 4 | 6 | 7 => true,
                        2 | 5 => false,
                        _ => {
                            anyhow::bail!("Kbuild directory member effect has no final membership")
                        }
                    };
                    final_membership
                        .entry(action_index)
                        .or_default()
                        .insert(member.clone(), present);
                }
            }
        }
    }

    Ok(final_membership
        .into_iter()
        .filter_map(|(action_index, final_members)| {
            (!directory_object_actions.contains(&action_index)
                && final_members
                    .iter()
                    .all(|(member, present)| members.binary_search(member).is_ok() == *present))
            .then_some(action_index)
        })
        .collect())
}

#[cfg(unix)]
fn kbuild_analyzer_transient_directory_projection(
    directory: &Path,
    members: &[Vec<u8>],
    batches: &[KbuildDirectoryEffectBatch],
    action_count: u64,
    action_transient_paths: &BTreeSet<(u64, PathBuf)>,
) -> Result<(BTreeSet<Vec<u8>>, [u8; 32])> {
    let mut transient_members = BTreeSet::new();
    let mut protected_members = BTreeSet::new();
    for batch in batches {
        match batch.owner {
            KbuildProcessOwner::Analyzer => {
                for effect in &batch.effects {
                    if let KbuildDirectoryEffectSubject::Member(member) = &effect.subject {
                        protected_members.insert(member.clone());
                    }
                }
            }
            KbuildProcessOwner::Action(action_index) => {
                if action_index >= action_count {
                    anyhow::bail!("Kbuild transient directory owner exceeds the graph");
                }
                for effect in &batch.effects {
                    if let KbuildDirectoryEffectSubject::Member(member) = &effect.subject {
                        let path = directory.join(bytes_path(member));
                        if action_transient_paths.contains(&(action_index, path)) {
                            transient_members.insert(member.clone());
                        } else {
                            protected_members.insert(member.clone());
                        }
                    }
                }
            }
        }
    }
    let ignored_members = transient_members
        .difference(&protected_members)
        .cloned()
        .collect::<BTreeSet<_>>();
    let projected_members = members
        .iter()
        .filter(|member| !ignored_members.contains(*member))
        .cloned()
        .collect::<Vec<_>>();
    let listing_digest = captured_directory_listing_digest(&projected_members)?;
    Ok((ignored_members, listing_digest))
}

#[cfg(unix)]
fn kbuild_analyzer_receipt_completion_projection(
    directory: &Path,
    members: &[Vec<u8>],
    batches: &[KbuildDirectoryEffectBatch],
    relations: &[u8],
    ignored_members: &BTreeSet<Vec<u8>>,
    before_actions: &BTreeSet<u64>,
    after_actions: &BTreeSet<u64>,
    unresolved_actions: &BTreeSet<u64>,
    action_receipt_paths: &BTreeSet<(u64, PathBuf)>,
) -> Result<(BTreeSet<u64>, BTreeSet<Vec<u8>>)> {
    if batches.len() != relations.len() {
        anyhow::bail!("Kbuild receipt completion relation count changed");
    }
    let mut completed_actions = BTreeSet::new();
    let mut added_members = BTreeSet::new();
    for action_index in before_actions.iter().filter(|action_index| {
        after_actions.contains(*action_index) || unresolved_actions.contains(*action_index)
    }) {
        let receipt_members = action_receipt_paths
            .iter()
            .filter_map(|(owner, path)| {
                (*owner == *action_index && path.parent() == Some(directory))
                    .then(|| path.file_name().map(os_bytes))
                    .flatten()
            })
            .collect::<BTreeSet<_>>();
        if receipt_members.is_empty()
            || receipt_members.iter().any(|member| {
                members.binary_search(member).is_ok() || ignored_members.contains(member)
            })
        {
            continue;
        }
        let mut saw_before_nonreceipt = false;
        let mut pending_receipt_members = BTreeSet::new();
        let mut valid = true;
        for (batch, relation) in batches.iter().zip(relations.iter().copied()) {
            for effect in &batch.effects {
                let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
                    if batch.owner == KbuildProcessOwner::Action(*action_index) {
                        valid = false;
                    }
                    continue;
                };
                if receipt_members.contains(member)
                    && batch.owner != KbuildProcessOwner::Action(*action_index)
                {
                    valid = false;
                }
                if batch.owner != KbuildProcessOwner::Action(*action_index)
                    || ignored_members.contains(member)
                {
                    continue;
                }
                match (relation, receipt_members.contains(member)) {
                    (0, false) => saw_before_nonreceipt = true,
                    (1 | 2, true) => {
                        pending_receipt_members.insert(member.clone());
                    }
                    _ => valid = false,
                }
            }
        }
        if valid && saw_before_nonreceipt && !pending_receipt_members.is_empty() {
            completed_actions.insert(*action_index);
            added_members.extend(pending_receipt_members);
        }
    }
    Ok((completed_actions, added_members))
}

#[cfg(test)]
mod membership_neutral_action_tests {
    use super::*;

    fn batch(
        action_index: u64,
        stream_ordinal: u64,
        effects: Vec<KbuildDirectoryEffectDescriptor>,
    ) -> KbuildDirectoryEffectBatch {
        KbuildDirectoryEffectBatch {
            owner: KbuildProcessOwner::Action(action_index),
            event: KbuildProcessEventKey {
                process: action_index + 1,
                syscall_index: stream_ordinal,
                stream_ordinal,
            },
            effects,
        }
    }

    fn member(kind_tag: u8, name: &[u8]) -> KbuildDirectoryEffectDescriptor {
        KbuildDirectoryEffectDescriptor {
            kind_tag,
            subject: KbuildDirectoryEffectSubject::Member(name.to_vec()),
        }
    }

    #[test]
    fn proves_only_membership_neutral_action_effects() {
        let batches = vec![
            batch(0, 1, vec![member(4, b"temporary")]),
            batch(0, 2, vec![member(2, b"temporary")]),
            batch(1, 3, vec![member(2, b"retained")]),
            batch(1, 4, vec![member(7, b"retained")]),
            batch(2, 5, vec![member(4, b"new-output")]),
            batch(
                3,
                6,
                vec![KbuildDirectoryEffectDescriptor {
                    kind_tag: 4,
                    subject: KbuildDirectoryEffectSubject::DirectoryObject,
                }],
            ),
        ];
        let neutral =
            kbuild_membership_neutral_actions(&batches, &[b"retained".to_vec()], 4).unwrap();
        assert_eq!(neutral, BTreeSet::from([0, 1]));
    }

    #[test]
    fn projects_exclusively_action_transient_members_present_or_absent() {
        let directory = Path::new("/output");
        let members = vec![b"stable".to_vec(), b"temporary".to_vec()];
        let transient = BTreeSet::from([(0, directory.join("temporary"))]);
        let batches = vec![batch(0, 1, vec![member(0, b"temporary")])];
        let (ignored, digest) = kbuild_analyzer_transient_directory_projection(
            directory,
            &members,
            &batches,
            2,
            &transient,
        )
        .unwrap();
        assert_eq!(ignored, BTreeSet::from([b"temporary".to_vec()]));
        assert_eq!(
            digest,
            captured_directory_listing_digest(&[b"stable".to_vec()]).unwrap()
        );

        let absent_members = vec![b"stable".to_vec()];
        let absent = vec![
            batch(0, 1, vec![member(0, b"temporary")]),
            batch(0, 2, vec![member(2, b"temporary")]),
        ];
        let (ignored, digest) = kbuild_analyzer_transient_directory_projection(
            directory,
            &absent_members,
            &absent,
            2,
            &transient,
        )
        .unwrap();
        assert_eq!(ignored, BTreeSet::from([b"temporary".to_vec()]));
        assert_eq!(
            digest,
            captured_directory_listing_digest(&absent_members).unwrap()
        );

        let mixed = vec![batch(
            0,
            1,
            vec![member(0, b"temporary"), member(0, b"stable")],
        )];
        let (ignored, digest) = kbuild_analyzer_transient_directory_projection(
            directory,
            &members,
            &mixed,
            2,
            &transient,
        )
        .unwrap();
        assert_eq!(ignored, BTreeSet::from([b"temporary".to_vec()]));
        assert_eq!(
            digest,
            captured_directory_listing_digest(&[b"stable".to_vec()]).unwrap()
        );

        let shared = vec![
            batch(0, 1, vec![member(0, b"temporary")]),
            batch(1, 2, vec![member(0, b"temporary")]),
        ];
        let (ignored, digest) = kbuild_analyzer_transient_directory_projection(
            directory,
            &members,
            &shared,
            2,
            &transient,
        )
        .unwrap();
        assert!(ignored.is_empty());
        assert_eq!(digest, captured_directory_listing_digest(&members).unwrap());
    }

    #[test]
    fn completes_only_exclusive_persistent_action_receipts() {
        let directory = Path::new("/output");
        let members = vec![b"generated.c".to_vec()];
        let batches = vec![
            batch(0, 1, vec![member(0, b"generated.c")]),
            batch(0, 2, vec![member(0, b".generated.c.cmd")]),
        ];
        let before = BTreeSet::from([0]);
        let after = BTreeSet::from([0]);
        let receipts = BTreeSet::from([(0, directory.join(".generated.c.cmd"))]);
        let (completed, added) = kbuild_analyzer_receipt_completion_projection(
            directory,
            &members,
            &batches,
            &[0, 1],
            &BTreeSet::new(),
            &before,
            &after,
            &BTreeSet::new(),
            &receipts,
        )
        .unwrap();
        assert_eq!(completed, BTreeSet::from([0]));
        assert_eq!(added, BTreeSet::from([b".generated.c.cmd".to_vec()]));

        let duplicate_receipt_batches = vec![
            batch(0, 1, vec![member(0, b"generated.c")]),
            batch(0, 2, vec![member(0, b".generated.c.cmd")]),
            batch(0, 3, vec![member(0, b".generated.c.cmd")]),
        ];
        let unresolved = BTreeSet::from([0]);
        let (completed, added) = kbuild_analyzer_receipt_completion_projection(
            directory,
            &members,
            &duplicate_receipt_batches,
            &[0, 2, 1],
            &BTreeSet::new(),
            &before,
            &after,
            &unresolved,
            &receipts,
        )
        .unwrap();
        assert_eq!(completed, BTreeSet::from([0]));
        assert_eq!(added, BTreeSet::from([b".generated.c.cmd".to_vec()]));

        let unsafe_batches = vec![
            batch(0, 1, vec![member(0, b"generated.c")]),
            batch(0, 2, vec![member(0, b"unexpected")]),
        ];
        let (completed, added) = kbuild_analyzer_receipt_completion_projection(
            directory,
            &members,
            &unsafe_batches,
            &[0, 1],
            &BTreeSet::new(),
            &before,
            &after,
            &BTreeSet::new(),
            &receipts,
        )
        .unwrap();
        assert!(completed.is_empty());
        assert!(added.is_empty());
    }

    #[test]
    fn resolves_action_relations_after_transient_projection() {
        let batches = vec![
            batch(0, 1, vec![member(2, b"temporary")]),
            batch(0, 2, vec![member(0, b"persistent-after")]),
            batch(0, 3, vec![member(0, b"persistent-ambiguous")]),
        ];
        let mut relations = vec![0, 1, 2];
        kbuild_resolve_projected_action_directory_relations(
            &batches,
            &mut relations,
            None,
            &BTreeSet::from([b"temporary".to_vec()]),
        );
        assert_eq!(relations, vec![0, 1, 1]);
    }

    #[test]
    fn proves_ambiguous_create_only_through_a_causal_removal_fence() {
        let open = batch(0, 1, vec![member(0, b"temporary")]);
        let removal = batch(0, 2, vec![member(2, b"temporary")]);
        let observation = KbuildProcessEventKey {
            process: 1,
            syscall_index: 3,
            stream_ordinal: 3,
        };
        let causality = KbuildProcessCausality::default();

        assert_eq!(
            kbuild_removal_fenced_ambiguous_create_relation(
                &open,
                &[open.clone(), removal],
                &causality,
                observation,
                &[],
            )
            .unwrap(),
            Some(0)
        );
        assert_eq!(
            kbuild_removal_fenced_ambiguous_create_relation(
                &open,
                std::slice::from_ref(&open),
                &causality,
                observation,
                &[],
            )
            .unwrap(),
            None
        );
        assert_eq!(
            kbuild_removal_fenced_ambiguous_create_relation(
                &open,
                std::slice::from_ref(&open),
                &causality,
                observation,
                &[b"temporary".to_vec()],
            )
            .unwrap(),
            None
        );
    }

    #[test]
    fn proves_unremoved_ambiguous_create_after_absent_observation() {
        let open = batch(0, 1, vec![member(0, b"generated")]);
        let unrelated_removal = batch(1, 2, vec![member(2, b"unrelated")]);
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &open,
                &[open.clone(), unrelated_removal],
                &[],
            )
            .unwrap(),
            Some(1)
        );

        let same_name_removal = batch(0, 2, vec![member(2, b"generated")]);
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &open,
                &[open.clone(), same_name_removal],
                &[],
            )
            .unwrap(),
            None
        );
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &open,
                std::slice::from_ref(&open),
                &[b"generated".to_vec()],
            )
            .unwrap(),
            None
        );

        let directory_replacement = batch(
            1,
            2,
            vec![KbuildDirectoryEffectDescriptor {
                kind_tag: 4,
                subject: KbuildDirectoryEffectSubject::DirectoryObject,
            }],
        );
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &open,
                &[open.clone(), directory_replacement],
                &[],
            )
            .unwrap(),
            None
        );
    }

    #[test]
    fn proves_atomic_rename_membership_without_inventing_process_order() {
        let rename = batch(0, 20, vec![member(6, b"generated.h")]);
        let creation = batch(
            1,
            10,
            vec![KbuildDirectoryEffectDescriptor {
                kind_tag: 4,
                subject: KbuildDirectoryEffectSubject::DirectoryObject,
            }],
        );
        let observation = KbuildProcessEventKey {
            process: 9,
            syscall_index: 30,
            stream_ordinal: 30,
        };
        let causality = KbuildProcessCausality::default();
        assert_eq!(kbuild_process_event_relation(&causality, rename.event, observation).unwrap(), 2);

        // A fresh directory has no initial generated.h; its only insertion
        // must precede a complete listing which contains that name.
        assert_eq!(
            kbuild_directory_batch_relations(
                &[creation.clone(), rename.clone()],
                &causality,
                observation,
                &[b"generated.h".to_vec()],
                None,
            ).unwrap(),
            vec![0, 0]
        );
        assert_eq!(
            kbuild_projected_directory_batch_relations(
                &[creation.clone(), rename.clone()],
                &causality,
                observation,
                &[],
                &BTreeSet::new(),
            ).unwrap(),
            vec![0, 1]
        );

        // An existing directory may already contain the destination. Its
        // presence cannot order a replacement, but absence with no remover
        // proves that the rename has yet to happen.
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &rename, std::slice::from_ref(&rename), &[]
            ).unwrap(),
            Some(1)
        );
        assert_eq!(
            kbuild_unremoved_absent_ambiguous_create_relation(
                &rename, std::slice::from_ref(&rename), &[b"generated.h".to_vec()]
            ).unwrap(),
            None
        );
        for removal_kind in [2, 5] {
            let removal = batch(1, 25, vec![member(removal_kind, b"generated.h")]);
            assert_eq!(
                kbuild_unremoved_absent_ambiguous_create_relation(
                    &rename, &[rename.clone(), removal.clone()], &[]
                ).unwrap(),
                None
            );
            assert_eq!(
                kbuild_fresh_directory_proved_relation(
                    &rename, &[creation.clone(), rename.clone(), removal], &[]
                ),
                None
            );
        }
        let replacement = batch(2, 25, vec![member(6, b"generated.h")]);
        assert_eq!(
            kbuild_fresh_directory_proved_relation(
                &rename, &[creation, rename.clone(), replacement], &[b"generated.h".to_vec()]
            ),
            None
        );
    }

    #[test]
    fn projects_temporary_rename_source_before_proving_persistent_destination() {
        let creation = batch(1, 10, vec![KbuildDirectoryEffectDescriptor {
            kind_tag: 4,
            subject: KbuildDirectoryEffectSubject::DirectoryObject,
        }]);
        let rename = batch(0, 20, vec![member(5, b"temporary"), member(6, b"generated.h")]);
        let observation = KbuildProcessEventKey {
            process: 9, syscall_index: 30, stream_ordinal: 30,
        };
        let batches = [creation, rename];
        let members = [b"generated.h".to_vec()];
        let causality = KbuildProcessCausality::default();
        assert_eq!(
            kbuild_directory_batch_relations(&batches, &causality, observation, &members, None).unwrap(),
            vec![0, 2]
        );
        assert_eq!(
            kbuild_projected_directory_batch_relations(
                &batches, &causality, observation, &members, &BTreeSet::from([b"temporary".to_vec()])
            ).unwrap(),
            vec![0, 0]
        );
    }
}

#[cfg(unix)]
fn kbuild_membership_proved_directory_relation(
    batch: &KbuildDirectoryEffectBatch,
    members: &[Vec<u8>],
) -> Result<Option<u8>> {
    let mut proved_relation = None;
    for effect in &batch.effects {
        let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
            return Ok(None);
        };
        let (class, proved) = kbuild_directory_membership_effect_class(effect.kind_tag)?;
        if !proved {
            return Ok(None);
        }
        let retained = members.binary_search(member).is_ok();
        let relation = match (class, retained) {
            (1, true) | (2, false) => 0,
            (1, false) | (2, true) => 1,
            _ => return Ok(None),
        };
        match proved_relation {
            Some(previous) if previous != relation => return Ok(None),
            Some(_) => {}
            None => proved_relation = Some(relation),
        }
    }
    Ok(proved_relation)
}

#[cfg(unix)]
fn kbuild_fresh_directory_proved_relation(
    batch: &KbuildDirectoryEffectBatch,
    batches: &[KbuildDirectoryEffectBatch],
    members: &[Vec<u8>],
) -> Option<u8> {
    let directory_object_effects = batches
        .iter()
        .flat_map(|candidate| candidate.effects.iter())
        .filter(|effect| effect.subject == KbuildDirectoryEffectSubject::DirectoryObject)
        .collect::<Vec<_>>();
    if directory_object_effects.len() != 1 || directory_object_effects[0].kind_tag != 4 {
        return None;
    }
    if batch
        .effects
        .iter()
        .any(|effect| effect.subject == KbuildDirectoryEffectSubject::DirectoryObject)
    {
        return (batch.effects.len() == 1 && batch.effects[0].kind_tag == 4).then_some(0);
    }
    if batch.effects.is_empty() {
        return None;
    }
    let mut proved_relation = None;
    for effect in &batch.effects {
        let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
            return None;
        };
        if !matches!(effect.kind_tag, 0 | 6) {
            return None;
        }
        let member_effects = batches
            .iter()
            .flat_map(|candidate| candidate.effects.iter())
            .filter(|candidate| candidate.subject == effect.subject)
            .count();
        if member_effects != 1 {
            return None;
        }
        let relation = if members.binary_search(member).is_ok() {
            0
        } else {
            1
        };
        match proved_relation {
            Some(previous) if previous != relation => return None,
            Some(_) => {}
            None => proved_relation = Some(relation),
        }
    }
    proved_relation
}

#[cfg(unix)]
fn kbuild_removal_fenced_ambiguous_create_relation(
    batch: &KbuildDirectoryEffectBatch,
    batches: &[KbuildDirectoryEffectBatch],
    causality: &KbuildProcessCausality,
    observation: KbuildProcessEventKey,
    members: &[Vec<u8>],
) -> Result<Option<u8>> {
    if batch.effects.is_empty() {
        return Ok(None);
    }
    for effect in &batch.effects {
        let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
            return Ok(None);
        };
        if effect.kind_tag != 0 || members.binary_search(member).is_ok() {
            return Ok(None);
        }
        let mut fenced = false;
        for candidate in batches {
            let removes_subject = candidate.effects.iter().any(|candidate_effect| {
                candidate_effect.subject == effect.subject
                    && matches!(candidate_effect.kind_tag, 2 | 5)
            });
            if removes_subject
                && kbuild_process_event_relation(causality, batch.event, candidate.event)? == 0
                && kbuild_process_event_relation(causality, candidate.event, observation)? == 0
            {
                fenced = true;
                break;
            }
        }
        if !fenced {
            return Ok(None);
        }
    }
    Ok(Some(0))
}

#[cfg(unix)]
fn kbuild_unremoved_absent_ambiguous_create_relation(
    batch: &KbuildDirectoryEffectBatch,
    batches: &[KbuildDirectoryEffectBatch],
    members: &[Vec<u8>],
) -> Result<Option<u8>> {
    if batch.effects.is_empty()
        || batches.iter().flat_map(|candidate| candidate.effects.iter()).any(|effect| {
            effect.subject == KbuildDirectoryEffectSubject::DirectoryObject
        })
    {
        return Ok(None);
    }
    for effect in &batch.effects {
        let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
            return Ok(None);
        };
        // Each successful operation leaves this name present. In a stable
        // directory with no removal of that name, an absent listing proves
        // the operation follows the observation even when sibling processes
        // have no wait/fork ordering edge.
        if !matches!(effect.kind_tag, 0 | 6) || members.binary_search(member).is_ok() {
            return Ok(None);
        }
        if batches
            .iter()
            .flat_map(|candidate| candidate.effects.iter())
            .any(|candidate_effect| {
                candidate_effect.subject == effect.subject
                    && matches!(candidate_effect.kind_tag, 2 | 5)
            })
        {
            return Ok(None);
        }
    }
    Ok(Some(1))
}

#[cfg(unix)]
fn kbuild_resolve_action_directory_relations(
    batches: &[KbuildDirectoryEffectBatch],
    relations: &mut [u8],
    excluded_action: Option<u64>,
) {
    kbuild_resolve_projected_action_directory_relations(
        batches,
        relations,
        excluded_action,
        &BTreeSet::new(),
    );
}

#[cfg(unix)]
fn kbuild_batch_has_projected_directory_effect(
    batch: &KbuildDirectoryEffectBatch,
    ignored_members: &BTreeSet<Vec<u8>>,
) -> bool {
    batch.effects.iter().any(|effect| match &effect.subject {
        KbuildDirectoryEffectSubject::DirectoryObject => true,
        KbuildDirectoryEffectSubject::Member(member) => !ignored_members.contains(member),
    })
}

#[cfg(unix)]
fn kbuild_resolve_projected_action_directory_relations(
    batches: &[KbuildDirectoryEffectBatch],
    relations: &mut [u8],
    excluded_action: Option<u64>,
    ignored_members: &BTreeSet<Vec<u8>>,
) {
    let mut action_directions = BTreeMap::<u64, BTreeSet<u8>>::new();
    for (batch, relation) in batches.iter().zip(relations.iter()) {
        let KbuildProcessOwner::Action(action_index) = batch.owner else {
            continue;
        };
        if Some(action_index) == excluded_action
            || *relation == 2
            || !kbuild_batch_has_projected_directory_effect(batch, ignored_members)
        {
            continue;
        }
        action_directions
            .entry(action_index)
            .or_default()
            .insert(*relation);
    }
    for (batch, relation) in batches.iter().zip(relations.iter_mut()) {
        if *relation != 2 {
            continue;
        }
        let KbuildProcessOwner::Action(action_index) = batch.owner else {
            continue;
        };
        if Some(action_index) == excluded_action {
            continue;
        }
        if !kbuild_batch_has_projected_directory_effect(batch, ignored_members) {
            continue;
        }
        if let Some(directions) = action_directions.get(&action_index) {
            if directions.len() == 1 {
                *relation = *directions
                    .iter()
                    .next()
                    .expect("one exact action direction is present");
            }
        }
    }
}

#[cfg(unix)]
fn kbuild_directory_batch_relations(
    batches: &[KbuildDirectoryEffectBatch],
    causality: &KbuildProcessCausality,
    observation: KbuildProcessEventKey,
    members: &[Vec<u8>],
    excluded_action: Option<u64>,
) -> Result<Vec<u8>> {
    let mut relations = batches
        .iter()
        .map(|batch| {
            let causal = kbuild_process_event_relation(causality, batch.event, observation)?;
            if causal == 2 {
                let membership = kbuild_membership_proved_directory_relation(batch, members)?
                    .or_else(|| kbuild_fresh_directory_proved_relation(batch, batches, members));
                let fenced = if membership.is_none() {
                    kbuild_removal_fenced_ambiguous_create_relation(
                        batch,
                        batches,
                        causality,
                        observation,
                        members,
                    )?
                } else {
                    None
                };
                let unremoved_absent = if membership.is_none() && fenced.is_none() {
                    kbuild_unremoved_absent_ambiguous_create_relation(batch, batches, members)?
                } else {
                    None
                };
                Ok(membership.or(fenced).or(unremoved_absent).unwrap_or(2))
            } else {
                Ok(causal)
            }
        })
        .collect::<Result<Vec<_>>>()?;
    kbuild_resolve_action_directory_relations(batches, &mut relations, excluded_action);
    Ok(relations)
}

#[cfg(unix)]
fn kbuild_projected_directory_batch_relations(
    batches: &[KbuildDirectoryEffectBatch],
    causality: &KbuildProcessCausality,
    observation: KbuildProcessEventKey,
    members: &[Vec<u8>],
    ignored_members: &BTreeSet<Vec<u8>>,
) -> Result<Vec<u8>> {
    // A rename carries source and destination effects in one syscall batch.
    // Apply the already-proved transient-name projection to its effects
    // before testing membership; a discarded temporary source must not hide
    // the persistent destination's exact listing relation.
    let projected_batches = batches.iter().map(|batch| KbuildDirectoryEffectBatch {
        owner: batch.owner,
        event: batch.event,
        effects: batch.effects.iter().filter(|effect| match &effect.subject {
            KbuildDirectoryEffectSubject::DirectoryObject => true,
            KbuildDirectoryEffectSubject::Member(member) => !ignored_members.contains(member),
        }).cloned().collect(),
    }).collect::<Vec<_>>();
    let mut relations = projected_batches
        .iter()
        .map(|batch| {
            let causal = kbuild_process_event_relation(causality, batch.event, observation)?;
            if causal == 2 {
                let membership = kbuild_membership_proved_directory_relation(batch, members)?
                    .or_else(|| kbuild_fresh_directory_proved_relation(batch, &projected_batches, members));
                let fenced = if membership.is_none() {
                    kbuild_removal_fenced_ambiguous_create_relation(
                        batch,
                        &projected_batches,
                        causality,
                        observation,
                        members,
                    )?
                } else {
                    None
                };
                let unremoved_absent = if membership.is_none() && fenced.is_none() {
                    kbuild_unremoved_absent_ambiguous_create_relation(batch, &projected_batches, members)?
                } else {
                    None
                };
                Ok(membership.or(fenced).or(unremoved_absent).unwrap_or(2))
            } else {
                Ok(causal)
            }
        })
        .collect::<Result<Vec<_>>>()?;
    kbuild_resolve_projected_action_directory_relations(
        batches,
        &mut relations,
        None,
        ignored_members,
    );
    Ok(relations)
}

#[cfg(unix)]
fn kbuild_analyzer_internal_directory_transaction(
    provenance: KbuildAnalyzerDirectoryProvenance,
    members: &[Vec<u8>],
    batches: &[KbuildDirectoryEffectBatch],
    causality: &KbuildProcessCausality,
    observation: KbuildProcessEventKey,
) -> Result<bool> {
    if provenance != KbuildAnalyzerDirectoryProvenance::SameOwnerPostCandidate {
        return Ok(false);
    }
    let mut relations = Vec::with_capacity(batches.len());
    for batch in batches {
        if batch.owner != KbuildProcessOwner::Analyzer {
            return Ok(false);
        }
        let relation = kbuild_process_event_relation(causality, batch.event, observation)?;
        if relation == 2 {
            return Ok(false);
        }
        relations.push(relation);
    }

    let mut last_directory_before = None;
    let mut last_directory_after = None;
    for (index, (batch, relation)) in batches.iter().zip(&relations).enumerate() {
        for effect in &batch.effects {
            if effect.subject != KbuildDirectoryEffectSubject::DirectoryObject {
                continue;
            }
            match relation {
                0 => last_directory_before = Some((index, effect.kind_tag)),
                1 => last_directory_after = Some((index, effect.kind_tag)),
                _ => unreachable!("resolved analyzer transaction has a fixed relation set"),
            }
        }
    }
    let Some((creation_index, 4)) = last_directory_before else {
        return Ok(false);
    };
    let Some((removal_index, removal_kind)) = last_directory_after else {
        return Ok(false);
    };
    if kbuild_directory_membership_effect_class(removal_kind)? != (2, true) {
        return Ok(false);
    }

    let mut member_state = BTreeMap::<Vec<u8>, bool>::new();
    for (index, (batch, relation)) in batches.iter().zip(&relations).enumerate() {
        for effect in &batch.effects {
            let KbuildDirectoryEffectSubject::Member(member) = &effect.subject else {
                continue;
            };
            if *relation == 0 && index > creation_index {
                let (class, _) = kbuild_directory_membership_effect_class(effect.kind_tag)?;
                member_state.insert(member.clone(), class != 2);
            } else if *relation == 1 && index > removal_index {
                return Ok(false);
            }
        }
    }
    let retained = members.iter().cloned().collect::<BTreeSet<_>>();
    if retained.len() != members.len() {
        return Ok(false);
    }
    let derived = member_state
        .into_iter()
        .filter_map(|(member, present)| present.then_some(member))
        .collect::<BTreeSet<_>>();
    Ok(derived == retained)
}

#[cfg(unix)]
fn kbuild_retained_directory_path_anchors(
    observations: &[KbuildInputObservation],
    mutation_index: &KbuildInputMutationIndex,
    anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>,
) -> Result<BTreeMap<u64, KbuildDirectoryPathAnchor>> {
    let mut retained = BTreeMap::new();
    for (ordinal, anchor) in anchors {
        let index = usize::try_from(*ordinal)
            .context("Kbuild directory-anchor ordinal does not fit usize")?;
        let observation = observations
            .get(index)
            .context("Kbuild directory anchor has no observation")?;
        if observation.ordinal != *ordinal
            || observation.class != KbuildInputObservationClass::Directory
            || !matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
            || observation.process != anchor.process
            || observation.path != anchor.path
            || observation.object != anchor.object
            || anchor.descriptor < 0
            || anchor.open_stream_ordinal >= observation.stream_ordinal
            || observation
                .syscall_index
                .is_none_or(|syscall_index| anchor.open_syscall_index >= syscall_index)
        {
            anyhow::bail!("Kbuild directory path anchor is malformed");
        }
        if mutation_index
            .directory_epoch_events
            .contains_key(&observation.path)
        {
            retained.insert(*ordinal, anchor.clone());
        }
    }
    Ok(retained)
}

#[cfg(unix)]
fn kbuild_generated_directory_checkpoints(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census_digest: [u8; 32],
    provenance_partition_digest: [u8; 32],
    mutation_attribution_digest: [u8; 32],
    observations: &[KbuildInputObservation],
    mutation_index: &KbuildInputMutationIndex,
    causality: &KbuildProcessCausality,
    output_root: &Path,
    action_count: u64,
    directory_members: &BTreeMap<u64, Vec<Vec<u8>>>,
    directory_anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>,
) -> Result<KbuildGeneratedDirectoryCheckpoints> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-generated-directory-checkpoints.v8\0");
    for digest in [
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census_digest,
        provenance_partition_digest,
        mutation_attribution_digest,
    ] {
        hasher.update(&digest);
    }
    hasher.update(&action_count.to_le_bytes());

    let mut checkpoints = Vec::new();
    let mut directories = BTreeSet::new();
    let mut consumers = BTreeSet::new();
    let mut member_names = 0_u64;
    let mut effect_batches = 0_u64;
    let mut effect_occurrences = 0_u64;
    let mut directory_object_effects = 0_u64;
    let mut member_effects = 0_u64;
    let mut member_effects_on_retained_names = 0_u64;
    let mut member_effects_on_absent_names = 0_u64;
    let mut ambiguous_create_or_truncate_effects = 0_u64;
    let mut proved_add_effects = 0_u64;
    let mut proved_remove_effects = 0_u64;
    let mut ambiguous_rename_destination_effects = 0_u64;
    let mut effects_before_observations = 0_u64;
    let mut observations_before_effects = 0_u64;
    let mut causally_unresolved_effects = 0_u64;
    let mut before_only_external_action_relations = 0_u64;
    let mut after_only_external_action_relations = 0_u64;
    let mut unresolved_external_action_relations = 0_u64;
    let mut straddling_external_action_relations = 0_u64;
    let mut straddling_external_action_relations_with_proved_effects = 0_u64;
    let mut straddling_external_action_relations_with_only_ambiguous_effects = 0_u64;
    let mut straddling_external_action_relations_with_retained_name_effects = 0_u64;
    let mut straddling_external_action_relations_without_retained_name_effects = 0_u64;
    let mut self_effect_batches = 0_u64;
    let mut self_effect_batches_before_observations = 0_u64;
    let mut self_effect_batches_after_observations = 0_u64;
    let mut self_effect_batches_causally_unresolved = 0_u64;
    let mut self_member_effects_on_retained_names = 0_u64;
    let mut self_member_effects_on_retained_names_before_observations = 0_u64;
    let mut self_member_effects_on_retained_names_after_observations = 0_u64;
    let mut self_member_effects_on_retained_names_causally_unresolved = 0_u64;
    let mut self_member_effects_on_absent_names = 0_u64;
    let mut analyzer_effect_batches = 0_u64;
    let mut analyzer_effect_batches_before_observations = 0_u64;
    let mut analyzer_effect_batches_after_observations = 0_u64;
    let mut analyzer_effect_batches_causally_unresolved = 0_u64;
    let mut analyzer_member_effects_on_retained_names = 0_u64;
    let mut analyzer_member_effects_on_absent_names = 0_u64;
    let mut candidate_action_boundary_observations = 0_u64;

    for observation in observations {
        if mutation_index.classify(observation) != KbuildInputProvenanceClass::CrossOwnerMutation
            || observation.owner == KbuildProcessOwner::Analyzer
            || !matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
        {
            continue;
        }
        let KbuildProcessOwner::Action(consumer_action_index) = observation.owner else {
            unreachable!("analyzer directory checkpoint was filtered above");
        };
        if consumer_action_index >= action_count
            || observation.class != KbuildInputObservationClass::Directory
            || observation.object.kind != KbuildInputObjectKind::Directory
            || !matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
        {
            anyhow::bail!("Kbuild generated directory checkpoint is malformed");
        }
        let effects = mutation_index
            .directory_epoch_events
            .get(&observation.path)
            .context("Kbuild generated directory checkpoint has no candidate effects")?;
        let batches = kbuild_directory_effect_batches(effects)?;
        if batches.is_empty() {
            anyhow::bail!("Kbuild generated directory checkpoint has no effect batches");
        }
        let members = directory_members
            .get(&observation.ordinal)
            .context("Kbuild generated directory checkpoint has no retained members")?;
        let anchor = directory_anchors
            .get(&observation.ordinal)
            .context("Kbuild generated directory checkpoint has no proved path anchor")?;
        let relative = observation
            .path
            .strip_prefix(output_root)
            .context("Kbuild generated directory checkpoint is outside the output root")?;
        let relative = os_bytes(relative.as_os_str());
        directories.insert(relative.clone());
        consumers.insert(consumer_action_index);
        member_names = member_names
            .checked_add(
                u64::try_from(members.len())
                    .context("Kbuild generated directory member count does not fit u64")?,
            )
            .context("Kbuild generated directory member count overflowed")?;
        effect_batches = effect_batches
            .checked_add(
                u64::try_from(batches.len())
                    .context("Kbuild generated directory effect count does not fit u64")?,
            )
            .context("Kbuild generated directory effect count overflowed")?;

        update_kbuild_generated_observation(&mut hasher, observation)?;
        hasher.update(&anchor.descriptor.to_le_bytes());
        hasher.update(&anchor.open_syscall_index.to_le_bytes());
        hasher.update(&anchor.open_stream_ordinal.to_le_bytes());
        hasher.update(
            &u64::try_from(members.len())
                .context("Kbuild generated directory member count does not fit u64")?
                .to_le_bytes(),
        );
        for member in members {
            hash_kbuild_bytes(&mut hasher, member)?;
        }
        hasher.update(
            &u64::try_from(batches.len())
                .context("Kbuild generated directory effect count does not fit u64")?
                .to_le_bytes(),
        );

        let observation_key = KbuildProcessEventKey {
            process: observation.process,
            syscall_index: observation
                .syscall_index
                .context("Kbuild generated directory checkpoint has no syscall index")?,
            stream_ordinal: observation.stream_ordinal,
        };
        let mut before_actions = BTreeSet::new();
        let mut after_actions = BTreeSet::new();
        let mut unresolved_actions = BTreeSet::new();
        let mut checkpoint_unresolved = false;
        let mut checkpoint_self_effect = false;
        let mut checkpoint_analyzer_effect = false;
        let mut checkpoint_unresolved_self_effect = false;
        let mut checkpoint_unresolved_analyzer_effect = false;
        let mut checkpoint_self_directory_object_effect = false;
        let mut checkpoint_self_retained_name_effect_before_observation = false;
        let mut checkpoint_self_retained_name_effect_after_observation = false;
        let mut checkpoint_analyzer_directory_object_effect = false;
        let mut checkpoint_analyzer_retained_name_effect = false;
        let mut first_self_directory_object_batch = None;
        let mut first_unresolved_self_batch = None;
        let mut first_unresolved_analyzer_batch = None;
        let mut external_action_proved_effects = BTreeMap::<u64, bool>::new();
        let mut external_action_retained_name_effects = BTreeMap::<u64, bool>::new();
        let relations = kbuild_directory_batch_relations(
            &batches,
            causality,
            observation_key,
            members,
            Some(consumer_action_index),
        )?;
        for (batch, relation) in batches.iter().zip(relations.iter().copied()) {
            match relation {
                0 => {
                    effects_before_observations = effects_before_observations
                        .checked_add(1)
                        .context("Kbuild directory effect-before count overflowed")?;
                }
                1 => {
                    observations_before_effects = observations_before_effects
                        .checked_add(1)
                        .context("Kbuild directory effect-after count overflowed")?;
                }
                2 => {
                    checkpoint_unresolved = true;
                    causally_unresolved_effects = causally_unresolved_effects
                        .checked_add(1)
                        .context("Kbuild unresolved directory effect count overflowed")?;
                }
                _ => unreachable!("process-event relation has a fixed tag set"),
            }
            update_kbuild_process_owner(&mut hasher, batch.owner);
            hasher.update(&batch.event.process.to_le_bytes());
            hasher.update(&batch.event.syscall_index.to_le_bytes());
            hasher.update(&batch.event.stream_ordinal.to_le_bytes());
            hasher.update(&[relation]);
            update_kbuild_directory_effect_descriptors(&mut hasher, &batch.effects)?;
            effect_occurrences = effect_occurrences
                .checked_add(
                    u64::try_from(batch.effects.len())
                        .context("Kbuild directory effect occurrence count does not fit u64")?,
                )
                .context("Kbuild directory effect occurrence count overflowed")?;
            let mut batch_has_proved_effect = false;
            let mut batch_has_retained_name_effect = false;
            for effect in &batch.effects {
                match &effect.subject {
                    KbuildDirectoryEffectSubject::DirectoryObject => {
                        directory_object_effects = directory_object_effects
                            .checked_add(1)
                            .context("Kbuild directory-object effect count overflowed")?;
                        match batch.owner {
                            KbuildProcessOwner::Analyzer => {
                                checkpoint_analyzer_directory_object_effect = true;
                            }
                            KbuildProcessOwner::Action(action_index)
                                if action_index == consumer_action_index =>
                            {
                                checkpoint_self_directory_object_effect = true;
                                if first_self_directory_object_batch.is_none() {
                                    first_self_directory_object_batch = Some(batch.clone());
                                }
                            }
                            KbuildProcessOwner::Action(_) => {}
                        }
                    }
                    KbuildDirectoryEffectSubject::Member(member) => {
                        member_effects = member_effects
                            .checked_add(1)
                            .context("Kbuild directory member-effect count overflowed")?;
                        let retained = members.binary_search(member).is_ok();
                        batch_has_retained_name_effect |= retained;
                        if retained {
                            member_effects_on_retained_names =
                                member_effects_on_retained_names.checked_add(1).context(
                                    "Kbuild retained-name directory effect count overflowed",
                                )?;
                        } else {
                            member_effects_on_absent_names = member_effects_on_absent_names
                                .checked_add(1)
                                .context("Kbuild absent-name directory effect count overflowed")?;
                        }
                        match batch.owner {
                            KbuildProcessOwner::Analyzer if retained => {
                                checkpoint_analyzer_retained_name_effect = true;
                                analyzer_member_effects_on_retained_names =
                                    analyzer_member_effects_on_retained_names
                                        .checked_add(1)
                                        .context(
                                            "Kbuild analyzer retained-name effect count overflowed",
                                        )?;
                            }
                            KbuildProcessOwner::Analyzer => {
                                analyzer_member_effects_on_absent_names =
                                    analyzer_member_effects_on_absent_names
                                        .checked_add(1)
                                        .context(
                                            "Kbuild analyzer absent-name effect count overflowed",
                                        )?;
                            }
                            KbuildProcessOwner::Action(action_index)
                                if action_index == consumer_action_index && retained =>
                            {
                                self_member_effects_on_retained_names =
                                    self_member_effects_on_retained_names
                                        .checked_add(1)
                                        .context(
                                            "Kbuild self retained-name effect count overflowed",
                                        )?;
                                let count = match relation {
                                    0 => {
                                        checkpoint_self_retained_name_effect_before_observation =
                                            true;
                                        &mut self_member_effects_on_retained_names_before_observations
                                    }
                                    1 => {
                                        checkpoint_self_retained_name_effect_after_observation =
                                            true;
                                        &mut self_member_effects_on_retained_names_after_observations
                                    }
                                    2 => {
                                        &mut self_member_effects_on_retained_names_causally_unresolved
                                    }
                                    _ => unreachable!(
                                        "process-event relation has a fixed tag set"
                                    ),
                                };
                                *count = count.checked_add(1).context(
                                    "Kbuild directional self retained-name count overflowed",
                                )?;
                            }
                            KbuildProcessOwner::Action(action_index)
                                if action_index == consumer_action_index =>
                            {
                                self_member_effects_on_absent_names =
                                    self_member_effects_on_absent_names.checked_add(1).context(
                                        "Kbuild self absent-name effect count overflowed",
                                    )?;
                            }
                            KbuildProcessOwner::Action(_) => {}
                        }
                    }
                }
                let (class, proved) = kbuild_directory_membership_effect_class(effect.kind_tag)?;
                batch_has_proved_effect |= proved;
                let count = match class {
                    0 => &mut ambiguous_create_or_truncate_effects,
                    1 => &mut proved_add_effects,
                    2 => &mut proved_remove_effects,
                    3 => &mut ambiguous_rename_destination_effects,
                    _ => unreachable!("directory membership class has a fixed tag set"),
                };
                *count = count
                    .checked_add(1)
                    .context("Kbuild directory membership-effect count overflowed")?;
            }
            match batch.owner {
                KbuildProcessOwner::Analyzer => {
                    checkpoint_analyzer_effect = true;
                    checkpoint_unresolved_analyzer_effect |= relation == 2;
                    if relation == 2 {
                        first_unresolved_analyzer_batch
                            .get_or_insert_with(|| batch.clone());
                    }
                    analyzer_effect_batches = analyzer_effect_batches
                        .checked_add(1)
                        .context("Kbuild analyzer directory effect count overflowed")?;
                    let count = match relation {
                        0 => &mut analyzer_effect_batches_before_observations,
                        1 => &mut analyzer_effect_batches_after_observations,
                        2 => &mut analyzer_effect_batches_causally_unresolved,
                        _ => unreachable!("process-event relation has a fixed tag set"),
                    };
                    *count = count
                        .checked_add(1)
                        .context("Kbuild analyzer effect relation count overflowed")?;
                }
                KbuildProcessOwner::Action(action_index) => {
                    if action_index >= action_count {
                        anyhow::bail!("Kbuild directory effect owner exceeds the graph");
                    }
                    if action_index == consumer_action_index {
                        checkpoint_self_effect = true;
                        checkpoint_unresolved_self_effect |= relation == 2;
                        if relation == 2 {
                            first_unresolved_self_batch.get_or_insert_with(|| batch.clone());
                        }
                        self_effect_batches = self_effect_batches
                            .checked_add(1)
                            .context("Kbuild self directory effect count overflowed")?;
                        let count = match relation {
                            0 => &mut self_effect_batches_before_observations,
                            1 => &mut self_effect_batches_after_observations,
                            2 => &mut self_effect_batches_causally_unresolved,
                            _ => unreachable!("process-event relation has a fixed tag set"),
                        };
                        *count = count
                            .checked_add(1)
                            .context("Kbuild self effect relation count overflowed")?;
                    } else if relation == 0 {
                        before_actions.insert(action_index);
                    } else if relation == 1 {
                        after_actions.insert(action_index);
                    } else {
                        unresolved_actions.insert(action_index);
                    }
                    if action_index != consumer_action_index {
                        let proved = external_action_proved_effects
                            .entry(action_index)
                            .or_insert(false);
                        *proved |= batch_has_proved_effect;
                        let retained = external_action_retained_name_effects
                            .entry(action_index)
                            .or_insert(false);
                        *retained |= batch_has_retained_name_effect;
                    }
                }
            }
        }

        let first_unresolved_self_subjects = first_unresolved_self_batch
            .as_ref()
            .map(|batch| {
                batch
                    .effects
                    .iter()
                    .map(|effect| effect.subject.clone())
                    .collect::<BTreeSet<_>>()
            })
            .unwrap_or_default();
        let first_unresolved_self_subject_batch_count = u64::try_from(
            batches
                .iter()
                .filter(|batch| {
                    batch.effects.iter().any(|effect| {
                        first_unresolved_self_subjects.contains(&effect.subject)
                    })
                })
                .count(),
        )
        .context("Kbuild unresolved self-subject batch count does not fit u64")?;
        let mut first_unresolved_self_subject_timeline = Vec::new();
        let mut previous_subject_event = None;
        let observation_process_chain = causality.process_chain(observation.process)?;
        for (batch, relation) in batches.iter().zip(relations.iter().copied()) {
            if !batch.effects.iter().any(|effect| {
                first_unresolved_self_subjects.contains(&effect.subject)
            }) {
                continue;
            }
            let previous_relation = previous_subject_event
                .map(|previous| {
                    kbuild_process_event_relation(causality, previous, batch.event)
                })
                .transpose()?;
            let direct_observation_relation =
                kbuild_process_event_relation(causality, batch.event, observation_key)?;
            let process_chain = causality.process_chain(batch.event.process)?;
            if first_unresolved_self_subject_timeline.len() < 16 {
                first_unresolved_self_subject_timeline.push((
                    batch.clone(),
                    relation,
                    direct_observation_relation,
                    previous_relation,
                    process_chain,
                ));
            }
            previous_subject_event = Some(batch.event);
        }
        let first_unresolved_self_branch = first_unresolved_self_batch
            .as_ref()
            .map(|batch| {
                causality.branch_diagnostic(batch.event.process, observation.process)
            })
            .transpose()?
            .flatten();

        let raw_straddling = before_actions
            .intersection(&after_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        let membership_neutral_actions =
            kbuild_membership_neutral_actions(&batches, members, action_count)?;
        if membership_neutral_actions.contains(&consumer_action_index) {
            checkpoint_unresolved_self_effect = false;
        }
        let normalizable = unresolved_actions
            .iter()
            .chain(before_actions.intersection(&after_actions))
            .filter(|action_index| membership_neutral_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        for action_index in normalizable {
            unresolved_actions.remove(&action_index);
            after_actions.remove(&action_index);
            before_actions.insert(action_index);
        }
        let straddling = before_actions
            .intersection(&after_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        let before_only = before_actions
            .difference(&after_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        let after_only = after_actions
            .difference(&before_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        before_only_external_action_relations = before_only_external_action_relations
            .checked_add(
                u64::try_from(before_only.len())
                    .context("Kbuild before-only action count does not fit u64")?,
            )
            .context("Kbuild before-only action count overflowed")?;
        after_only_external_action_relations = after_only_external_action_relations
            .checked_add(
                u64::try_from(after_only.len())
                    .context("Kbuild after-only action count does not fit u64")?,
            )
            .context("Kbuild after-only action count overflowed")?;
        unresolved_external_action_relations = unresolved_external_action_relations
            .checked_add(
                u64::try_from(unresolved_actions.len())
                    .context("Kbuild unresolved action count does not fit u64")?,
            )
            .context("Kbuild unresolved action count overflowed")?;
        straddling_external_action_relations = straddling_external_action_relations
            .checked_add(
                u64::try_from(raw_straddling.len())
                    .context("Kbuild straddling action count does not fit u64")?,
            )
            .context("Kbuild straddling action count overflowed")?;
        for action_index in &raw_straddling {
            if external_action_proved_effects
                .get(action_index)
                .copied()
                .unwrap_or(false)
            {
                straddling_external_action_relations_with_proved_effects =
                    straddling_external_action_relations_with_proved_effects
                        .checked_add(1)
                        .context("Kbuild proved straddling action count overflowed")?;
            } else {
                straddling_external_action_relations_with_only_ambiguous_effects =
                    straddling_external_action_relations_with_only_ambiguous_effects
                        .checked_add(1)
                        .context("Kbuild ambiguous straddling action count overflowed")?;
            }
            if external_action_retained_name_effects
                .get(action_index)
                .copied()
                .unwrap_or(false)
            {
                straddling_external_action_relations_with_retained_name_effects =
                    straddling_external_action_relations_with_retained_name_effects
                        .checked_add(1)
                        .context("Kbuild retained-name straddling action count overflowed")?;
            } else {
                straddling_external_action_relations_without_retained_name_effects =
                    straddling_external_action_relations_without_retained_name_effects
                        .checked_add(1)
                        .context("Kbuild other-name straddling action count overflowed")?;
            }
        }
        let candidate_action_boundary = !checkpoint_unresolved
            && !checkpoint_self_effect
            && !checkpoint_analyzer_effect
            && straddling.is_empty();
        if candidate_action_boundary {
            candidate_action_boundary_observations = candidate_action_boundary_observations
                .checked_add(1)
                .context("Kbuild boundary-candidate checkpoint count overflowed")?;
        }
        for actions in [&before_only, &after_only, &unresolved_actions, &straddling] {
            hasher.update(
                &u64::try_from(actions.len())
                    .context("Kbuild directory action relation count does not fit u64")?
                    .to_le_bytes(),
            );
            for action_index in actions {
                hasher.update(&action_index.to_le_bytes());
            }
        }
        hasher.update(&[
            u8::from(checkpoint_unresolved),
            u8::from(checkpoint_self_effect),
            u8::from(checkpoint_analyzer_effect),
            u8::from(checkpoint_unresolved_self_effect),
            u8::from(checkpoint_unresolved_analyzer_effect),
            u8::from(checkpoint_self_directory_object_effect),
            u8::from(checkpoint_self_retained_name_effect_before_observation),
            u8::from(checkpoint_self_retained_name_effect_after_observation),
            u8::from(checkpoint_analyzer_directory_object_effect),
            u8::from(checkpoint_analyzer_retained_name_effect),
            u8::from(straddling.is_empty()),
        ]);
        checkpoints.push(KbuildGeneratedDirectoryCheckpoint {
            consumer_action_index,
            observation_ordinal: observation.ordinal,
            path: ExternalPathKey {
                root: "obj".to_string(),
                path: relative,
            },
            object: observation.object,
            value: observation.value,
            members: members.clone(),
            anchor: anchor.clone(),
            before_actions,
            after_actions,
            unresolved_actions,
            has_self_effect: checkpoint_self_effect,
            has_analyzer_effect: checkpoint_analyzer_effect,
            has_unresolved_self_effect: checkpoint_unresolved_self_effect,
            has_unresolved_analyzer_effect: checkpoint_unresolved_analyzer_effect,
            has_self_directory_object_effect: checkpoint_self_directory_object_effect,
            has_self_retained_name_effect_before_observation:
                checkpoint_self_retained_name_effect_before_observation,
            has_self_retained_name_effect_after_observation:
                checkpoint_self_retained_name_effect_after_observation,
            has_analyzer_directory_object_effect: checkpoint_analyzer_directory_object_effect,
            has_analyzer_retained_name_effect: checkpoint_analyzer_retained_name_effect,
            first_self_directory_object_batch,
            first_unresolved_self_batch,
            first_unresolved_analyzer_batch,
            first_unresolved_self_subject_batch_count,
            first_unresolved_self_subject_timeline,
            observation_process_chain,
            first_unresolved_self_branch,
            candidate_action_boundary,
        });
    }

    let observations = u64::try_from(checkpoints.len())
        .context("Kbuild generated directory checkpoint count does not fit u64")?;
    let distinct_directories = u64::try_from(directories.len())
        .context("Kbuild generated directory path count does not fit u64")?;
    let consumer_actions = u64::try_from(consumers.len())
        .context("Kbuild generated directory consumer count does not fit u64")?;
    let effect_partition = effects_before_observations
        .checked_add(observations_before_effects)
        .and_then(|count| count.checked_add(causally_unresolved_effects))
        .context("Kbuild generated directory effect partition overflowed")?;
    let subject_partition = directory_object_effects
        .checked_add(member_effects)
        .context("Kbuild generated directory effect-subject partition overflowed")?;
    let member_partition = member_effects_on_retained_names
        .checked_add(member_effects_on_absent_names)
        .context("Kbuild generated directory member-effect partition overflowed")?;
    let membership_class_partition = ambiguous_create_or_truncate_effects
        .checked_add(proved_add_effects)
        .and_then(|count| count.checked_add(proved_remove_effects))
        .and_then(|count| count.checked_add(ambiguous_rename_destination_effects))
        .context("Kbuild generated directory membership-class partition overflowed")?;
    let straddling_partition = straddling_external_action_relations_with_proved_effects
        .checked_add(straddling_external_action_relations_with_only_ambiguous_effects)
        .context("Kbuild generated directory straddling partition overflowed")?;
    let straddling_name_partition = straddling_external_action_relations_with_retained_name_effects
        .checked_add(straddling_external_action_relations_without_retained_name_effects)
        .context("Kbuild generated directory straddling-name partition overflowed")?;
    let self_relation_partition = self_effect_batches_before_observations
        .checked_add(self_effect_batches_after_observations)
        .and_then(|count| count.checked_add(self_effect_batches_causally_unresolved))
        .context("Kbuild generated directory self-effect partition overflowed")?;
    let analyzer_relation_partition = analyzer_effect_batches_before_observations
        .checked_add(analyzer_effect_batches_after_observations)
        .and_then(|count| count.checked_add(analyzer_effect_batches_causally_unresolved))
        .context("Kbuild generated directory analyzer-effect partition overflowed")?;
    if effect_partition != effect_batches
        || subject_partition != effect_occurrences
        || member_partition != member_effects
        || membership_class_partition != effect_occurrences
        || straddling_partition != straddling_external_action_relations
        || straddling_name_partition != straddling_external_action_relations
        || self_relation_partition != self_effect_batches
        || analyzer_relation_partition != analyzer_effect_batches
        || candidate_action_boundary_observations > observations
        || checkpoints
            .windows(2)
            .any(|pair| pair[0].observation_ordinal >= pair[1].observation_ordinal)
    {
        anyhow::bail!("Kbuild generated directory checkpoint partition is incomplete");
    }
    for count in [
        observations,
        distinct_directories,
        consumer_actions,
        member_names,
        effect_batches,
        effect_occurrences,
        directory_object_effects,
        member_effects,
        member_effects_on_retained_names,
        member_effects_on_absent_names,
        ambiguous_create_or_truncate_effects,
        proved_add_effects,
        proved_remove_effects,
        ambiguous_rename_destination_effects,
        effects_before_observations,
        observations_before_effects,
        causally_unresolved_effects,
        before_only_external_action_relations,
        after_only_external_action_relations,
        unresolved_external_action_relations,
        straddling_external_action_relations,
        straddling_external_action_relations_with_proved_effects,
        straddling_external_action_relations_with_only_ambiguous_effects,
        straddling_external_action_relations_with_retained_name_effects,
        straddling_external_action_relations_without_retained_name_effects,
        self_effect_batches,
        self_effect_batches_before_observations,
        self_effect_batches_after_observations,
        self_effect_batches_causally_unresolved,
        self_member_effects_on_retained_names,
        self_member_effects_on_retained_names_before_observations,
        self_member_effects_on_retained_names_after_observations,
        self_member_effects_on_retained_names_causally_unresolved,
        self_member_effects_on_absent_names,
        analyzer_effect_batches,
        analyzer_effect_batches_before_observations,
        analyzer_effect_batches_after_observations,
        analyzer_effect_batches_causally_unresolved,
        analyzer_member_effects_on_retained_names,
        analyzer_member_effects_on_absent_names,
        candidate_action_boundary_observations,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    Ok(KbuildGeneratedDirectoryCheckpoints {
        seal: KbuildGeneratedDirectoryCheckpointSeal {
            checkpoint_digest: *hasher.finalize().as_bytes(),
            observations,
            distinct_directories,
            consumer_actions,
            member_names,
            effect_batches,
            effect_occurrences,
            directory_object_effects,
            member_effects,
            member_effects_on_retained_names,
            member_effects_on_absent_names,
            ambiguous_create_or_truncate_effects,
            proved_add_effects,
            proved_remove_effects,
            ambiguous_rename_destination_effects,
            effects_before_observations,
            observations_before_effects,
            causally_unresolved_effects,
            before_only_external_action_relations,
            after_only_external_action_relations,
            unresolved_external_action_relations,
            straddling_external_action_relations,
            straddling_external_action_relations_with_proved_effects,
            straddling_external_action_relations_with_only_ambiguous_effects,
            straddling_external_action_relations_with_retained_name_effects,
            straddling_external_action_relations_without_retained_name_effects,
            self_effect_batches,
            self_effect_batches_before_observations,
            self_effect_batches_after_observations,
            self_effect_batches_causally_unresolved,
            self_member_effects_on_retained_names,
            self_member_effects_on_retained_names_before_observations,
            self_member_effects_on_retained_names_after_observations,
            self_member_effects_on_retained_names_causally_unresolved,
            self_member_effects_on_absent_names,
            analyzer_effect_batches,
            analyzer_effect_batches_before_observations,
            analyzer_effect_batches_after_observations,
            analyzer_effect_batches_causally_unresolved,
            analyzer_member_effects_on_retained_names,
            analyzer_member_effects_on_absent_names,
            candidate_action_boundary_observations,
        },
        checkpoints,
    })
}

#[cfg(unix)]
fn kbuild_directory_causal_census(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census_digest: [u8; 32],
    provenance_partition_digest: [u8; 32],
    mutation_attribution_digest: [u8; 32],
    final_output_value_digest: [u8; 32],
    observations: &[KbuildInputObservation],
    mutation_index: &KbuildInputMutationIndex,
    causality: &KbuildProcessCausality,
    output_root: &Path,
    directory_anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>,
) -> Result<KbuildDirectoryCausalCensusSeal> {
    let mut grouped = BTreeMap::<PathBuf, Vec<&KbuildInputObservation>>::new();
    for observation in observations {
        if !matches!(
            observation.value,
            KbuildObservedInputValue::Directory { .. }
        ) {
            continue;
        }
        if !mutation_index
            .directory_epoch_events
            .contains_key(&observation.path)
        {
            continue;
        }
        if observation.class != KbuildInputObservationClass::Directory
            || observation.object.kind != KbuildInputObjectKind::Directory
            || !matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
            || observation.object.mount_id.is_none()
            || observation.syscall_index.is_none()
        {
            anyhow::bail!("Kbuild causal directory census has a malformed observation");
        }
        grouped
            .entry(observation.path.clone())
            .or_default()
            .push(observation);
    }

    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-generated-directory-causal-checkpoints.v4\0");
    for digest in [
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census_digest,
        provenance_partition_digest,
        mutation_attribution_digest,
        final_output_value_digest,
    ] {
        hasher.update(&digest);
    }
    let creation_count = u64::try_from(causality.creations.len())
        .context("Kbuild process-creation boundary count does not fit u64")?;
    hasher.update(&creation_count.to_le_bytes());
    for (child, boundary) in &causality.creations {
        hasher.update(&child.to_le_bytes());
        hasher.update(&boundary.parent.to_le_bytes());
        hasher.update(&boundary.syscall_index.to_le_bytes());
        hasher.update(&boundary.stream_ordinal.to_le_bytes());
    }
    let finish_count = u64::try_from(causality.finishes.len())
        .context("Kbuild process-finish boundary count does not fit u64")?;
    hasher.update(&finish_count.to_le_bytes());
    for (process, (stream_ordinal, outcome)) in &causality.finishes {
        hasher.update(&process.to_le_bytes());
        hasher.update(&stream_ordinal.to_le_bytes());
        match outcome {
            CapturedProcessOutcome::Exited(status) => {
                hasher.update(&[0]);
                hasher.update(&status.to_le_bytes());
            }
            CapturedProcessOutcome::Signaled(signal) => {
                hasher.update(&[1]);
                hasher.update(&signal.to_le_bytes());
            }
        }
    }
    let reap_count = u64::try_from(causality.reaps.len())
        .context("Kbuild process-reap boundary count does not fit u64")?;
    hasher.update(&reap_count.to_le_bytes());
    for (child, boundary) in &causality.reaps {
        hasher.update(&child.to_le_bytes());
        hasher.update(&boundary.parent.to_le_bytes());
        hasher.update(&boundary.syscall_index.to_le_bytes());
        hasher.update(&boundary.stream_ordinal.to_le_bytes());
        hasher.update(&boundary.status.to_le_bytes());
    }

    let mut observation_count = 0_u64;
    let mut checkpoint_pairs = 0_u64;
    let mut unchanged_checkpoint_pairs = 0_u64;
    let mut changed_checkpoint_pairs = 0_u64;
    let mut causally_ordered_checkpoint_pairs = 0_u64;
    let mut causally_unresolved_checkpoint_pairs = 0_u64;
    let mut effect_events = 0_u64;
    let mut effect_batches = 0_u64;
    let mut coeffect_occurrences = 0_u64;
    let mut adjacent_effect_batch_pairs = 0_u64;
    let mut causally_ordered_adjacent_effect_batch_pairs = 0_u64;
    let mut causally_unresolved_adjacent_effect_batch_pairs = 0_u64;
    let mut effect_relations = 0_u64;
    let mut effects_before_observations = 0_u64;
    let mut observations_before_effects = 0_u64;
    let mut causally_unresolved_effect_relations = 0_u64;
    let mut causally_ordered_observations = 0_u64;
    let mut causally_unresolved_observations = 0_u64;
    let mut single_checkpoint_paths = 0_u64;
    let mut stable_multi_checkpoint_paths = 0_u64;
    let mut changing_multi_checkpoint_paths = 0_u64;
    let mut single_effect_batch_paths = 0_u64;
    let mut causally_ordered_multi_effect_batch_paths = 0_u64;
    let mut causally_unresolved_multi_effect_batch_paths = 0_u64;
    let mut causally_ordered_paths = 0_u64;
    let mut causally_unresolved_paths = 0_u64;
    let mut directory_object_replacement_pairs = 0_u64;
    let mut unchanged_member_checkpoint_pairs_with_between_effects = 0_u64;
    let mut unchanged_member_checkpoint_pairs_without_between_effects = 0_u64;
    let mut unchanged_member_checkpoint_pairs_with_unresolved_effect_windows = 0_u64;
    let mut changed_member_checkpoint_pairs_with_between_effects = 0_u64;
    let mut changed_member_checkpoint_pairs_without_between_effects = 0_u64;
    let mut changed_member_checkpoint_pairs_with_unresolved_effect_windows = 0_u64;
    let mut path_anchor_proved_observations = 0_u64;
    let mut path_anchor_unproved_observations = 0_u64;
    let mut path_anchor_proved_paths = 0_u64;
    let mut path_anchor_unproved_paths = 0_u64;

    let path_count = u64::try_from(grouped.len())
        .context("Kbuild causal directory path count does not fit u64")?;
    hasher.update(&path_count.to_le_bytes());
    for (path, path_observations) in &mut grouped {
        path_observations
            .sort_by_key(|observation| (observation.stream_ordinal, observation.ordinal));
        let effects = mutation_index
            .directory_epoch_events
            .get(path)
            .context("Kbuild causal directory path has no effect events")?;
        if effects.is_empty() {
            anyhow::bail!("Kbuild causal directory path has an empty effect census");
        }
        let batches = kbuild_directory_effect_batches(effects)?;
        if batches.is_empty() {
            anyhow::bail!("Kbuild causal directory path has an empty effect-batch census");
        }
        effect_events = effect_events
            .checked_add(
                u64::try_from(effects.len())
                    .context("Kbuild causal directory effect count does not fit u64")?,
            )
            .context("Kbuild causal directory effect count overflowed")?;
        effect_batches = effect_batches
            .checked_add(
                u64::try_from(batches.len())
                    .context("Kbuild causal directory batch count does not fit u64")?,
            )
            .context("Kbuild causal directory batch count overflowed")?;
        coeffect_occurrences = coeffect_occurrences
            .checked_add(
                u64::try_from(effects.len() - batches.len())
                    .context("Kbuild causal directory co-effect count does not fit u64")?,
            )
            .context("Kbuild causal directory co-effect count overflowed")?;
        let relative = path
            .strip_prefix(output_root)
            .context("Kbuild causal directory path is outside the output root")?;
        let relative = os_bytes(relative.as_os_str());
        let relative_length = u64::try_from(relative.len())
            .context("Kbuild causal directory path length does not fit u64")?;
        hasher.update(&relative_length.to_le_bytes());
        hasher.update(&relative);
        hasher.update(
            &u64::try_from(path_observations.len())
                .context("Kbuild causal directory observation count does not fit u64")?
                .to_le_bytes(),
        );
        hasher.update(
            &u64::try_from(effects.len())
                .context("Kbuild causal directory effect count does not fit u64")?
                .to_le_bytes(),
        );
        hasher.update(
            &u64::try_from(batches.len())
                .context("Kbuild causal directory batch count does not fit u64")?
                .to_le_bytes(),
        );
        for batch in &batches {
            update_kbuild_process_owner(&mut hasher, batch.owner);
            hasher.update(&batch.event.process.to_le_bytes());
            hasher.update(&batch.event.syscall_index.to_le_bytes());
            hasher.update(&batch.event.stream_ordinal.to_le_bytes());
            update_kbuild_directory_effect_descriptors(&mut hasher, &batch.effects)?;
        }

        let mut path_effect_batch_unresolved = false;
        for pair in batches.windows(2) {
            adjacent_effect_batch_pairs = adjacent_effect_batch_pairs
                .checked_add(1)
                .context("Kbuild adjacent directory-effect pair count overflowed")?;
            let relation = kbuild_process_event_relation(causality, pair[0].event, pair[1].event)?;
            hasher.update(&[relation]);
            if relation == 0 {
                causally_ordered_adjacent_effect_batch_pairs =
                    causally_ordered_adjacent_effect_batch_pairs
                        .checked_add(1)
                        .context("Kbuild ordered directory-effect pair count overflowed")?;
            } else if relation == 2 {
                path_effect_batch_unresolved = true;
                causally_unresolved_adjacent_effect_batch_pairs =
                    causally_unresolved_adjacent_effect_batch_pairs
                        .checked_add(1)
                        .context("Kbuild unresolved directory-effect pair count overflowed")?;
            } else {
                anyhow::bail!("Kbuild directory effect order contradicts stream order");
            }
        }

        let mut path_changed = false;
        let mut path_unresolved = path_effect_batch_unresolved;
        let mut path_anchor_unproved = false;
        for observation in path_observations.iter().copied() {
            observation_count = observation_count
                .checked_add(1)
                .context("Kbuild causal directory observation count overflowed")?;
            update_kbuild_process_owner(&mut hasher, observation.owner);
            hasher.update(&observation.process.to_le_bytes());
            let observation_syscall_index = observation
                .syscall_index
                .context("Kbuild causal directory observation has no syscall index")?;
            hasher.update(&observation_syscall_index.to_le_bytes());
            update_kbuild_generated_observation(&mut hasher, observation)?;
            let observation_key = KbuildProcessEventKey {
                process: observation.process,
                syscall_index: observation_syscall_index,
                stream_ordinal: observation.stream_ordinal,
            };
            if let Some(anchor) = directory_anchors.get(&observation.ordinal) {
                if anchor.process != observation.process
                    || anchor.path != observation.path
                    || anchor.object != observation.object
                    || anchor.descriptor < 0
                    || anchor.open_stream_ordinal >= observation.stream_ordinal
                    || anchor.open_syscall_index >= observation_syscall_index
                {
                    anyhow::bail!("Kbuild causal directory census has a malformed path anchor");
                }
                hasher.update(&[1]);
                hasher.update(&anchor.descriptor.to_le_bytes());
                hasher.update(&anchor.open_syscall_index.to_le_bytes());
                hasher.update(&anchor.open_stream_ordinal.to_le_bytes());
                path_anchor_proved_observations = path_anchor_proved_observations
                    .checked_add(1)
                    .context("Kbuild proved directory-anchor count overflowed")?;
            } else {
                hasher.update(&[0]);
                path_anchor_unproved = true;
                path_anchor_unproved_observations = path_anchor_unproved_observations
                    .checked_add(1)
                    .context("Kbuild unproved directory-anchor count overflowed")?;
            }
            let mut observation_unresolved = false;
            for effect in effects {
                effect_relations = effect_relations
                    .checked_add(1)
                    .context("Kbuild causal directory relation count overflowed")?;
                update_kbuild_process_owner(&mut hasher, effect.owner);
                hasher.update(&effect.process.to_le_bytes());
                hasher.update(&effect.syscall_index.to_le_bytes());
                hasher.update(&effect.stream_ordinal.to_le_bytes());
                hasher.update(&[kbuild_mutation_candidate_kind_tag(effect.kind)]);
                let relation = kbuild_process_event_relation(
                    causality,
                    KbuildProcessEventKey {
                        process: effect.process,
                        syscall_index: effect.syscall_index,
                        stream_ordinal: effect.stream_ordinal,
                    },
                    observation_key,
                )?;
                hasher.update(&[relation]);
                match relation {
                    0 => {
                        effects_before_observations = effects_before_observations
                            .checked_add(1)
                            .context("Kbuild effect-before-observation count overflowed")?;
                    }
                    1 => {
                        observations_before_effects = observations_before_effects
                            .checked_add(1)
                            .context("Kbuild observation-before-effect count overflowed")?;
                    }
                    2 => {
                        observation_unresolved = true;
                        path_unresolved = true;
                        causally_unresolved_effect_relations = causally_unresolved_effect_relations
                            .checked_add(1)
                            .context("Kbuild unresolved directory relation count overflowed")?;
                    }
                    _ => unreachable!("process-event relation has a fixed tag set"),
                }
            }
            if observation_unresolved {
                causally_unresolved_observations = causally_unresolved_observations
                    .checked_add(1)
                    .context("Kbuild unresolved directory observation count overflowed")?;
            } else {
                causally_ordered_observations = causally_ordered_observations
                    .checked_add(1)
                    .context("Kbuild ordered directory observation count overflowed")?;
            }
        }
        for pair in path_observations.windows(2) {
            checkpoint_pairs = checkpoint_pairs
                .checked_add(1)
                .context("Kbuild directory checkpoint-pair count overflowed")?;
            let unchanged = pair[0].object == pair[1].object && pair[0].value == pair[1].value;
            if unchanged {
                unchanged_checkpoint_pairs = unchanged_checkpoint_pairs
                    .checked_add(1)
                    .context("Kbuild unchanged checkpoint-pair count overflowed")?;
            } else {
                path_changed = true;
                changed_checkpoint_pairs = changed_checkpoint_pairs
                    .checked_add(1)
                    .context("Kbuild changed checkpoint-pair count overflowed")?;
            }
            let left_key = KbuildProcessEventKey {
                process: pair[0].process,
                syscall_index: pair[0]
                    .syscall_index
                    .context("Kbuild directory checkpoint has no syscall index")?,
                stream_ordinal: pair[0].stream_ordinal,
            };
            let right_key = KbuildProcessEventKey {
                process: pair[1].process,
                syscall_index: pair[1]
                    .syscall_index
                    .context("Kbuild directory checkpoint has no syscall index")?,
                stream_ordinal: pair[1].stream_ordinal,
            };
            let relation = kbuild_process_event_relation(causality, left_key, right_key)?;
            if relation == 0 {
                causally_ordered_checkpoint_pairs = causally_ordered_checkpoint_pairs
                    .checked_add(1)
                    .context("Kbuild ordered checkpoint-pair count overflowed")?;
            } else if relation == 2 {
                path_unresolved = true;
                causally_unresolved_checkpoint_pairs = causally_unresolved_checkpoint_pairs
                    .checked_add(1)
                    .context("Kbuild unresolved checkpoint-pair count overflowed")?;
            } else {
                anyhow::bail!("Kbuild directory checkpoint order contradicts stream order");
            }
            let (left_listing_digest, right_listing_digest) = match (pair[0].value, pair[1].value) {
                (
                    KbuildObservedInputValue::Directory {
                        listing_digest: left,
                        ..
                    },
                    KbuildObservedInputValue::Directory {
                        listing_digest: right,
                        ..
                    },
                ) => (left, right),
                _ => unreachable!("causal directory checkpoints have directory values"),
            };
            let members_unchanged = left_listing_digest == right_listing_digest;
            if pair[0].object != pair[1].object {
                directory_object_replacement_pairs = directory_object_replacement_pairs
                    .checked_add(1)
                    .context("Kbuild directory object-replacement count overflowed")?;
            }
            let mut between_effect = false;
            let mut effect_window_unresolved = relation != 0;
            for batch in &batches {
                let left_relation =
                    kbuild_process_event_relation(causality, left_key, batch.event)?;
                let right_relation =
                    kbuild_process_event_relation(causality, batch.event, right_key)?;
                let window_tag = if relation != 0 {
                    3
                } else {
                    match (left_relation, right_relation) {
                        (1, 0) => 0,
                        (0, 0) => {
                            between_effect = true;
                            1
                        }
                        (0, 1) => 2,
                        (2, _) | (_, 2) => {
                            effect_window_unresolved = true;
                            3
                        }
                        (1, 1) => {
                            anyhow::bail!("Kbuild directory effect contradicts checkpoint order")
                        }
                        _ => unreachable!("process-event relation has a fixed tag set"),
                    }
                };
                hasher.update(&[left_relation, right_relation, window_tag]);
            }
            match (members_unchanged, effect_window_unresolved, between_effect) {
                (true, false, true) => {
                    unchanged_member_checkpoint_pairs_with_between_effects =
                        unchanged_member_checkpoint_pairs_with_between_effects
                            .checked_add(1)
                            .context("Kbuild unchanged between-effect count overflowed")?;
                }
                (true, false, false) => {
                    unchanged_member_checkpoint_pairs_without_between_effects =
                        unchanged_member_checkpoint_pairs_without_between_effects
                            .checked_add(1)
                            .context("Kbuild unchanged no-between-effect count overflowed")?;
                }
                (true, true, _) => {
                    unchanged_member_checkpoint_pairs_with_unresolved_effect_windows =
                        unchanged_member_checkpoint_pairs_with_unresolved_effect_windows
                            .checked_add(1)
                            .context("Kbuild unchanged unresolved-window count overflowed")?;
                    path_unresolved = true;
                }
                (false, false, true) => {
                    changed_member_checkpoint_pairs_with_between_effects =
                        changed_member_checkpoint_pairs_with_between_effects
                            .checked_add(1)
                            .context("Kbuild changed between-effect count overflowed")?;
                }
                (false, false, false) => {
                    changed_member_checkpoint_pairs_without_between_effects =
                        changed_member_checkpoint_pairs_without_between_effects
                            .checked_add(1)
                            .context("Kbuild changed no-between-effect count overflowed")?;
                }
                (false, true, _) => {
                    changed_member_checkpoint_pairs_with_unresolved_effect_windows =
                        changed_member_checkpoint_pairs_with_unresolved_effect_windows
                            .checked_add(1)
                            .context("Kbuild changed unresolved-window count overflowed")?;
                    path_unresolved = true;
                }
            }
            hasher.update(&[
                u8::from(unchanged),
                relation,
                u8::from(members_unchanged),
                u8::from(effect_window_unresolved),
                u8::from(between_effect),
            ]);
        }
        if path_observations.len() == 1 {
            single_checkpoint_paths = single_checkpoint_paths
                .checked_add(1)
                .context("Kbuild single-checkpoint directory-path count overflowed")?;
        } else if path_changed {
            changing_multi_checkpoint_paths = changing_multi_checkpoint_paths
                .checked_add(1)
                .context("Kbuild changing multi-checkpoint path count overflowed")?;
        } else {
            stable_multi_checkpoint_paths = stable_multi_checkpoint_paths
                .checked_add(1)
                .context("Kbuild stable multi-checkpoint path count overflowed")?;
        }
        if batches.len() == 1 {
            single_effect_batch_paths = single_effect_batch_paths
                .checked_add(1)
                .context("Kbuild single-effect-batch path count overflowed")?;
        } else if path_effect_batch_unresolved {
            causally_unresolved_multi_effect_batch_paths =
                causally_unresolved_multi_effect_batch_paths
                    .checked_add(1)
                    .context("Kbuild unresolved multi-effect-batch path count overflowed")?;
        } else {
            causally_ordered_multi_effect_batch_paths = causally_ordered_multi_effect_batch_paths
                .checked_add(1)
                .context("Kbuild ordered multi-effect-batch path count overflowed")?;
        }
        if path_unresolved {
            causally_unresolved_paths = causally_unresolved_paths
                .checked_add(1)
                .context("Kbuild unresolved directory-path count overflowed")?;
        } else {
            causally_ordered_paths = causally_ordered_paths
                .checked_add(1)
                .context("Kbuild ordered directory-path count overflowed")?;
        }
        if path_anchor_unproved {
            path_anchor_unproved_paths = path_anchor_unproved_paths
                .checked_add(1)
                .context("Kbuild unproved directory-anchor path count overflowed")?;
        } else {
            path_anchor_proved_paths = path_anchor_proved_paths
                .checked_add(1)
                .context("Kbuild proved directory-anchor path count overflowed")?;
        }
    }

    let unchanged_total = unchanged_checkpoint_pairs
        .checked_add(changed_checkpoint_pairs)
        .context("Kbuild checkpoint-value partition overflowed")?;
    let checkpoint_order_total = causally_ordered_checkpoint_pairs
        .checked_add(causally_unresolved_checkpoint_pairs)
        .context("Kbuild checkpoint-order partition overflowed")?;
    let effect_occurrence_total = effect_batches
        .checked_add(coeffect_occurrences)
        .context("Kbuild directory effect-occurrence partition overflowed")?;
    let adjacent_effect_order_total = causally_ordered_adjacent_effect_batch_pairs
        .checked_add(causally_unresolved_adjacent_effect_batch_pairs)
        .context("Kbuild adjacent directory-effect partition overflowed")?;
    let effect_order_total = effects_before_observations
        .checked_add(observations_before_effects)
        .and_then(|count| count.checked_add(causally_unresolved_effect_relations))
        .context("Kbuild directory effect-relation partition overflowed")?;
    let observation_order_total = causally_ordered_observations
        .checked_add(causally_unresolved_observations)
        .context("Kbuild directory observation-order partition overflowed")?;
    let stability_total = single_checkpoint_paths
        .checked_add(stable_multi_checkpoint_paths)
        .and_then(|count| count.checked_add(changing_multi_checkpoint_paths))
        .context("Kbuild directory stability partition overflowed")?;
    let effect_batch_path_total = single_effect_batch_paths
        .checked_add(causally_ordered_multi_effect_batch_paths)
        .and_then(|count| count.checked_add(causally_unresolved_multi_effect_batch_paths))
        .context("Kbuild directory effect-batch path partition overflowed")?;
    let path_order_total = causally_ordered_paths
        .checked_add(causally_unresolved_paths)
        .context("Kbuild directory path-order partition overflowed")?;
    let transition_total = unchanged_member_checkpoint_pairs_with_between_effects
        .checked_add(unchanged_member_checkpoint_pairs_without_between_effects)
        .and_then(|count| {
            count.checked_add(unchanged_member_checkpoint_pairs_with_unresolved_effect_windows)
        })
        .and_then(|count| count.checked_add(changed_member_checkpoint_pairs_with_between_effects))
        .and_then(|count| {
            count.checked_add(changed_member_checkpoint_pairs_without_between_effects)
        })
        .and_then(|count| {
            count.checked_add(changed_member_checkpoint_pairs_with_unresolved_effect_windows)
        })
        .context("Kbuild directory transition partition overflowed")?;
    let observation_structure_total = checkpoint_pairs
        .checked_add(path_count)
        .context("Kbuild directory observation structure count overflowed")?;
    let effect_batch_structure_total = adjacent_effect_batch_pairs
        .checked_add(path_count)
        .context("Kbuild directory effect-batch structure count overflowed")?;
    let semantic_changed_total = changed_member_checkpoint_pairs_with_between_effects
        .checked_add(changed_member_checkpoint_pairs_without_between_effects)
        .and_then(|count| {
            count.checked_add(changed_member_checkpoint_pairs_with_unresolved_effect_windows)
        })
        .context("Kbuild semantic directory-change count overflowed")?;
    let path_anchor_observation_total = path_anchor_proved_observations
        .checked_add(path_anchor_unproved_observations)
        .context("Kbuild directory-anchor observation partition overflowed")?;
    let path_anchor_path_total = path_anchor_proved_paths
        .checked_add(path_anchor_unproved_paths)
        .context("Kbuild directory-anchor path partition overflowed")?;
    if unchanged_total != checkpoint_pairs
        || checkpoint_order_total != checkpoint_pairs
        || effect_occurrence_total != effect_events
        || adjacent_effect_order_total != adjacent_effect_batch_pairs
        || effect_order_total != effect_relations
        || observation_order_total != observation_count
        || stability_total != path_count
        || effect_batch_path_total != path_count
        || path_order_total != path_count
        || transition_total != checkpoint_pairs
        || observation_structure_total != observation_count
        || effect_batch_structure_total != effect_batches
        || directory_object_replacement_pairs > changed_checkpoint_pairs
        || semantic_changed_total > changed_checkpoint_pairs
        || path_anchor_observation_total != observation_count
        || path_anchor_path_total != path_count
    {
        anyhow::bail!("Kbuild causal directory census has an incomplete partition");
    }
    for count in [
        observation_count,
        checkpoint_pairs,
        unchanged_checkpoint_pairs,
        changed_checkpoint_pairs,
        causally_ordered_checkpoint_pairs,
        causally_unresolved_checkpoint_pairs,
        effect_events,
        effect_batches,
        coeffect_occurrences,
        adjacent_effect_batch_pairs,
        causally_ordered_adjacent_effect_batch_pairs,
        causally_unresolved_adjacent_effect_batch_pairs,
        effect_relations,
        effects_before_observations,
        observations_before_effects,
        causally_unresolved_effect_relations,
        causally_ordered_observations,
        causally_unresolved_observations,
        single_checkpoint_paths,
        stable_multi_checkpoint_paths,
        changing_multi_checkpoint_paths,
        single_effect_batch_paths,
        causally_ordered_multi_effect_batch_paths,
        causally_unresolved_multi_effect_batch_paths,
        causally_ordered_paths,
        causally_unresolved_paths,
        directory_object_replacement_pairs,
        unchanged_member_checkpoint_pairs_with_between_effects,
        unchanged_member_checkpoint_pairs_without_between_effects,
        unchanged_member_checkpoint_pairs_with_unresolved_effect_windows,
        changed_member_checkpoint_pairs_with_between_effects,
        changed_member_checkpoint_pairs_without_between_effects,
        changed_member_checkpoint_pairs_with_unresolved_effect_windows,
        path_anchor_proved_observations,
        path_anchor_unproved_observations,
        path_anchor_proved_paths,
        path_anchor_unproved_paths,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    Ok(KbuildDirectoryCausalCensusSeal {
        causal_digest: *hasher.finalize().as_bytes(),
        observations: observation_count,
        checkpoint_pairs,
        unchanged_checkpoint_pairs,
        changed_checkpoint_pairs,
        causally_ordered_checkpoint_pairs,
        causally_unresolved_checkpoint_pairs,
        effect_events,
        effect_batches,
        coeffect_occurrences,
        adjacent_effect_batch_pairs,
        causally_ordered_adjacent_effect_batch_pairs,
        causally_unresolved_adjacent_effect_batch_pairs,
        effect_relations,
        effects_before_observations,
        observations_before_effects,
        causally_unresolved_effect_relations,
        causally_ordered_observations,
        causally_unresolved_observations,
        single_checkpoint_paths,
        stable_multi_checkpoint_paths,
        changing_multi_checkpoint_paths,
        single_effect_batch_paths,
        causally_ordered_multi_effect_batch_paths,
        causally_unresolved_multi_effect_batch_paths,
        causally_ordered_paths,
        causally_unresolved_paths,
        directory_object_replacement_pairs,
        unchanged_member_checkpoint_pairs_with_between_effects,
        unchanged_member_checkpoint_pairs_without_between_effects,
        unchanged_member_checkpoint_pairs_with_unresolved_effect_windows,
        changed_member_checkpoint_pairs_with_between_effects,
        changed_member_checkpoint_pairs_without_between_effects,
        changed_member_checkpoint_pairs_with_unresolved_effect_windows,
        path_anchor_proved_observations,
        path_anchor_unproved_observations,
        path_anchor_proved_paths,
        path_anchor_unproved_paths,
    })
}

#[cfg(unix)]
fn kbuild_analyzer_directory_checkpoints(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census_digest: [u8; 32],
    provenance_partition_digest: [u8; 32],
    mutation_attribution_digest: [u8; 32],
    final_output_value_digest: [u8; 32],
    directory_member_retention_digest: [u8; 32],
    directory_causal_census_digest: [u8; 32],
    observations: &[KbuildInputObservation],
    mutation_index: &KbuildInputMutationIndex,
    causality: &KbuildProcessCausality,
    output_root: &Path,
    action_count: u64,
    action_transient_paths: &BTreeSet<(u64, PathBuf)>,
    action_receipt_paths: &BTreeSet<(u64, PathBuf)>,
    directory_members: &BTreeMap<u64, Vec<Vec<u8>>>,
    directory_anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>,
) -> Result<KbuildAnalyzerDirectoryCheckpoints> {
    let mut checkpoints = Vec::new();
    let mut directories = BTreeSet::new();
    let mut exact_directories = BTreeSet::new();
    let mut member_names = 0_u64;
    let mut bootstrap_observations = 0_u64;
    let mut post_candidate_observations = 0_u64;
    let mut exact_cross_owner_observations = 0_u64;
    let mut external_seed_observations = 0_u64;
    let mut same_owner_pre_mutation_observations = 0_u64;
    let mut same_owner_post_candidate_observations = 0_u64;
    let mut effect_batches = 0_u64;
    let mut analyzer_effect_batches = 0_u64;
    let mut action_effect_batches = 0_u64;
    let mut analyzer_effect_batches_before_observations = 0_u64;
    let mut analyzer_effect_batches_after_observations = 0_u64;
    let mut analyzer_effect_batches_causally_unresolved = 0_u64;
    let mut effects_before_observations = 0_u64;
    let mut observations_before_effects = 0_u64;
    let mut causally_unresolved_effects = 0_u64;
    let mut before_only_action_relations = 0_u64;
    let mut after_only_action_relations = 0_u64;
    let mut unresolved_action_relations = 0_u64;
    let mut straddling_action_relations = 0_u64;
    let mut directory_object_effects = 0_u64;
    let mut member_effects = 0_u64;
    let mut analyzer_directory_object_effects = 0_u64;
    let mut action_directory_object_effects = 0_u64;
    let mut analyzer_member_effects_on_retained_names = 0_u64;
    let mut analyzer_member_effects_on_absent_names = 0_u64;
    let mut action_member_effects_on_retained_names = 0_u64;
    let mut action_member_effects_on_absent_names = 0_u64;
    let mut analyzer_only_retained_member_occurrences = 0_u64;
    let mut action_only_retained_member_occurrences = 0_u64;
    let mut mixed_owner_retained_member_occurrences = 0_u64;
    let mut unaffected_retained_member_occurrences = 0_u64;
    let mut checkpoints_with_analyzer_effects = 0_u64;
    let mut checkpoints_with_analyzer_effects_before_observation = 0_u64;
    let mut checkpoints_with_analyzer_effects_after_observation = 0_u64;
    let mut checkpoints_with_only_post_observation_analyzer_effects = 0_u64;
    let mut checkpoints_with_analyzer_directory_object_effects = 0_u64;
    let mut checkpoints_with_analyzer_directory_object_effects_before_observation = 0_u64;
    let mut checkpoints_with_analyzer_directory_object_effects_after_observation = 0_u64;
    let mut checkpoints_with_analyzer_retained_name_effects = 0_u64;
    let mut checkpoints_with_analyzer_retained_name_effects_before_observation = 0_u64;
    let mut checkpoints_with_analyzer_retained_name_effects_after_observation = 0_u64;
    let mut analysis_internal_namespace_transaction_observations = 0_u64;
    let mut checkpoints_with_before_actions = 0_u64;
    let mut checkpoints_with_after_actions = 0_u64;
    let mut checkpoints_with_before_and_after_actions = 0_u64;
    let mut checkpoints_with_no_action_effects = 0_u64;
    let mut checkpoints_with_analyzer_effects_and_before_actions = 0_u64;
    let mut checkpoints_with_analyzer_retained_name_effects_and_before_actions = 0_u64;
    let mut checkpoints_with_unaffected_retained_names = 0_u64;
    let mut checkpoints_with_unaffected_retained_names_and_before_actions = 0_u64;
    let mut candidate_action_boundary_observations = 0_u64;

    for observation in observations {
        if observation.owner != KbuildProcessOwner::Analyzer
            || !matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
            || !mutation_index
                .directory_epoch_events
                .contains_key(&observation.path)
        {
            continue;
        }
        let members = directory_members
            .get(&observation.ordinal)
            .context("Kbuild analyzer directory checkpoint has no retained members")?;
        let anchor = directory_anchors
            .get(&observation.ordinal)
            .context("Kbuild analyzer directory checkpoint has no proved path anchor")?;
        let syscall_index = observation
            .syscall_index
            .context("Kbuild analyzer directory checkpoint has no syscall index")?;
        if anchor.process != observation.process
            || anchor.path != observation.path
            || anchor.object != observation.object
            || anchor.descriptor < 0
            || anchor.open_stream_ordinal >= observation.stream_ordinal
            || anchor.open_syscall_index >= syscall_index
        {
            anyhow::bail!("Kbuild analyzer directory checkpoint has a malformed path anchor");
        }
        let relative = observation
            .path
            .strip_prefix(output_root)
            .context("Kbuild analyzer directory checkpoint is outside the output root")?;
        let relative = os_bytes(relative.as_os_str());
        let provenance = match mutation_index.classify(observation) {
            KbuildInputProvenanceClass::AnalyzerBootstrapDirectory => {
                bootstrap_observations = bootstrap_observations
                    .checked_add(1)
                    .context("Kbuild analyzer directory bootstrap count overflowed")?;
                KbuildAnalyzerDirectoryProvenance::Bootstrap
            }
            KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => {
                post_candidate_observations = post_candidate_observations
                    .checked_add(1)
                    .context("Kbuild analyzer directory post-candidate count overflowed")?;
                KbuildAnalyzerDirectoryProvenance::PostCandidate
            }
            KbuildInputProvenanceClass::CrossOwnerMutation => {
                exact_cross_owner_observations = exact_cross_owner_observations
                    .checked_add(1)
                    .context("Kbuild analyzer exact directory count overflowed")?;
                exact_directories.insert(relative.clone());
                KbuildAnalyzerDirectoryProvenance::ExactCrossOwner
            }
            KbuildInputProvenanceClass::ExternalSeed => {
                external_seed_observations = external_seed_observations
                    .checked_add(1)
                    .context("Kbuild analyzer external directory count overflowed")?;
                KbuildAnalyzerDirectoryProvenance::ExternalSeed
            }
            KbuildInputProvenanceClass::SameOwnerPreMutation => {
                same_owner_pre_mutation_observations = same_owner_pre_mutation_observations
                    .checked_add(1)
                    .context("Kbuild analyzer same-owner pre-mutation count overflowed")?;
                KbuildAnalyzerDirectoryProvenance::SameOwnerPreMutation
            }
            KbuildInputProvenanceClass::SameOwnerPostCandidate => {
                same_owner_post_candidate_observations = same_owner_post_candidate_observations
                    .checked_add(1)
                    .context("Kbuild analyzer same-owner post-candidate count overflowed")?;
                KbuildAnalyzerDirectoryProvenance::SameOwnerPostCandidate
            }
        };
        directories.insert(relative.clone());
        member_names = member_names
            .checked_add(
                u64::try_from(members.len())
                    .context("Kbuild analyzer directory member count does not fit u64")?,
            )
            .context("Kbuild analyzer directory member count overflowed")?;

        let effects = mutation_index
            .directory_epoch_events
            .get(&observation.path)
            .context("Kbuild analyzer directory checkpoint has no candidate effects")?;
        let batches = kbuild_directory_effect_batches(effects)?;
        if batches.is_empty() {
            anyhow::bail!("Kbuild analyzer directory checkpoint has no effect batches");
        }
        effect_batches = effect_batches
            .checked_add(
                u64::try_from(batches.len())
                    .context("Kbuild analyzer directory effect count does not fit u64")?,
            )
            .context("Kbuild analyzer directory effect count overflowed")?;
        let observation_key = KbuildProcessEventKey {
            process: observation.process,
            syscall_index,
            stream_ordinal: observation.stream_ordinal,
        };
        let mut before_actions = BTreeSet::new();
        let mut after_actions = BTreeSet::new();
        let mut unresolved_actions = BTreeSet::new();
        let mut has_analyzer_effect = false;
        let mut has_analyzer_effect_before_observation = false;
        let mut has_analyzer_effect_after_observation = false;
        let mut has_unresolved_analyzer_effect = false;
        let mut has_analyzer_directory_object_effect = false;
        let mut has_analyzer_directory_object_effect_before_observation = false;
        let mut has_analyzer_directory_object_effect_after_observation = false;
        let mut has_analyzer_retained_name_effect = false;
        let mut has_analyzer_retained_name_effect_before_observation = false;
        let mut has_analyzer_retained_name_effect_after_observation = false;
        let mut analyzer_affected_members = BTreeSet::new();
        let mut action_affected_members = BTreeSet::new();
        let relations =
            kbuild_directory_batch_relations(&batches, causality, observation_key, members, None)?;
        for (batch, relation) in batches.iter().zip(relations.iter().copied()) {
            let relation_count = match relation {
                0 => &mut effects_before_observations,
                1 => &mut observations_before_effects,
                2 => &mut causally_unresolved_effects,
                _ => unreachable!("process-event relation has a fixed tag set"),
            };
            *relation_count = relation_count
                .checked_add(1)
                .context("Kbuild analyzer directory effect relation count overflowed")?;
            for effect in &batch.effects {
                match &effect.subject {
                    KbuildDirectoryEffectSubject::DirectoryObject => {
                        directory_object_effects = directory_object_effects
                            .checked_add(1)
                            .context("Kbuild analyzer directory-object effect count overflowed")?;
                        match batch.owner {
                            KbuildProcessOwner::Analyzer => {
                                has_analyzer_directory_object_effect = true;
                                match relation {
                                    0 => {
                                        has_analyzer_directory_object_effect_before_observation =
                                            true;
                                    }
                                    1 => {
                                        has_analyzer_directory_object_effect_after_observation =
                                            true;
                                    }
                                    2 => {}
                                    _ => unreachable!("process-event relation has a fixed tag set"),
                                }
                                analyzer_directory_object_effects =
                                    analyzer_directory_object_effects.checked_add(1).context(
                                        "Kbuild analyzer-owned directory-object effect count \
                                         overflowed",
                                    )?;
                            }
                            KbuildProcessOwner::Action(_) => {
                                action_directory_object_effects =
                                    action_directory_object_effects.checked_add(1).context(
                                        "Kbuild action-owned directory-object effect count \
                                         overflowed",
                                    )?;
                            }
                        }
                    }
                    KbuildDirectoryEffectSubject::Member(member) => {
                        member_effects = member_effects
                            .checked_add(1)
                            .context("Kbuild analyzer directory member-effect count overflowed")?;
                        match batch.owner {
                            KbuildProcessOwner::Analyzer => {
                                analyzer_affected_members.insert(member.clone());
                            }
                            KbuildProcessOwner::Action(_) => {
                                action_affected_members.insert(member.clone());
                            }
                        }
                        let retained = members.binary_search(member).is_ok();
                        let count = match (batch.owner, retained) {
                            (KbuildProcessOwner::Analyzer, true) => {
                                has_analyzer_retained_name_effect = true;
                                match relation {
                                    0 => {
                                        has_analyzer_retained_name_effect_before_observation = true;
                                    }
                                    1 => {
                                        has_analyzer_retained_name_effect_after_observation = true;
                                    }
                                    2 => {}
                                    _ => unreachable!("process-event relation has a fixed tag set"),
                                }
                                &mut analyzer_member_effects_on_retained_names
                            }
                            (KbuildProcessOwner::Analyzer, false) => {
                                &mut analyzer_member_effects_on_absent_names
                            }
                            (KbuildProcessOwner::Action(_), true) => {
                                &mut action_member_effects_on_retained_names
                            }
                            (KbuildProcessOwner::Action(_), false) => {
                                &mut action_member_effects_on_absent_names
                            }
                        };
                        *count = count
                            .checked_add(1)
                            .context("Kbuild analyzer directory member-owner count overflowed")?;
                    }
                }
            }
            match batch.owner {
                KbuildProcessOwner::Analyzer => {
                    has_analyzer_effect = true;
                    let relation_count = match relation {
                        0 => {
                            has_analyzer_effect_before_observation = true;
                            &mut analyzer_effect_batches_before_observations
                        }
                        1 => {
                            has_analyzer_effect_after_observation = true;
                            &mut analyzer_effect_batches_after_observations
                        }
                        2 => {
                            has_unresolved_analyzer_effect = true;
                            &mut analyzer_effect_batches_causally_unresolved
                        }
                        _ => unreachable!("process-event relation has a fixed tag set"),
                    };
                    *relation_count = relation_count.checked_add(1).context(
                        "Kbuild analyzer-owned directory effect relation count overflowed",
                    )?;
                    analyzer_effect_batches = analyzer_effect_batches
                        .checked_add(1)
                        .context("Kbuild analyzer-owned directory effect count overflowed")?;
                }
                KbuildProcessOwner::Action(action_index) => {
                    if action_index >= action_count {
                        anyhow::bail!("Kbuild analyzer directory effect owner exceeds the graph");
                    }
                    action_effect_batches = action_effect_batches
                        .checked_add(1)
                        .context("Kbuild action-owned directory effect count overflowed")?;
                    match relation {
                        0 => {
                            before_actions.insert(action_index);
                        }
                        1 => {
                            after_actions.insert(action_index);
                        }
                        2 => {
                            unresolved_actions.insert(action_index);
                        }
                        _ => unreachable!("process-event relation has a fixed tag set"),
                    }
                }
            }
        }
        let raw_straddling = before_actions
            .intersection(&after_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
          let (analysis_ignored_transient_members, _) =
              kbuild_analyzer_transient_directory_projection(
                  &observation.path,
                  members,
                  &batches,
                  action_count,
                  action_transient_paths,
              )?;
          let analysis_relations = kbuild_projected_directory_batch_relations(
              &batches,
              causality,
              observation_key,
              members,
              &analysis_ignored_transient_members,
          )?;
          before_actions.clear();
          after_actions.clear();
          unresolved_actions.clear();
          for (batch, relation) in batches.iter().zip(analysis_relations.iter().copied()) {
              let KbuildProcessOwner::Action(action_index) = batch.owner else {
                  continue;
              };
              if !kbuild_batch_has_projected_directory_effect(
                  batch,
                  &analysis_ignored_transient_members,
              ) {
                  continue;
              }
              match relation {
                  0 => {
                      before_actions.insert(action_index);
                  }
                  1 => {
                      after_actions.insert(action_index);
                  }
                  2 => {
                      unresolved_actions.insert(action_index);
                  }
                  _ => unreachable!("process-event relation has a fixed tag set"),
              }
          }
          let (receipt_completed_actions, analysis_added_receipt_members) =
              kbuild_analyzer_receipt_completion_projection(
                  &observation.path,
                  members,
                  &batches,
                  &analysis_relations,
                  &analysis_ignored_transient_members,
                  &before_actions,
                  &after_actions,
                  &unresolved_actions,
                  action_receipt_paths,
              )?;
          for action_index in receipt_completed_actions {
              after_actions.remove(&action_index);
              unresolved_actions.remove(&action_index);
              before_actions.insert(action_index);
          }
          let mut analysis_members = members
              .iter()
              .filter(|member| !analysis_ignored_transient_members.contains(*member))
              .cloned()
              .collect::<Vec<_>>();
          analysis_members.extend(analysis_added_receipt_members.iter().cloned());
          analysis_members.sort();
          let analysis_listing_digest = captured_directory_listing_digest(&analysis_members)?;
          let analysis_internal_namespace_transaction =
              kbuild_analyzer_internal_directory_transaction(
                  provenance,
                  members,
                  &batches,
                  causality,
                  observation_key,
              )?;
          let membership_neutral_actions = kbuild_membership_neutral_actions_projected(
              &batches,
              members,
              action_count,
              &analysis_ignored_transient_members,
          )?;
          let normalizable = unresolved_actions
              .iter()
              .chain(before_actions.intersection(&after_actions))
              .filter(|action_index| membership_neutral_actions.contains(action_index))
              .copied()
              .collect::<BTreeSet<_>>();
          for action_index in normalizable {
              unresolved_actions.remove(&action_index);
              after_actions.remove(&action_index);
              before_actions.insert(action_index);
          }
          let straddling = before_actions
              .intersection(&after_actions)
              .filter(|action_index| !unresolved_actions.contains(action_index))
              .copied()
              .collect::<BTreeSet<_>>();
          let before_only = before_actions
            .difference(&after_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        let after_only = after_actions
            .difference(&before_actions)
            .filter(|action_index| !unresolved_actions.contains(action_index))
            .copied()
            .collect::<BTreeSet<_>>();
        before_only_action_relations = before_only_action_relations
            .checked_add(
                u64::try_from(before_only.len())
                    .context("Kbuild analyzer directory before-action count does not fit u64")?,
            )
            .context("Kbuild analyzer directory before-action count overflowed")?;
        after_only_action_relations = after_only_action_relations
            .checked_add(
                u64::try_from(after_only.len())
                    .context("Kbuild analyzer directory after-action count does not fit u64")?,
            )
            .context("Kbuild analyzer directory after-action count overflowed")?;
        unresolved_action_relations =
            unresolved_action_relations
                .checked_add(u64::try_from(unresolved_actions.len()).context(
                    "Kbuild analyzer directory unresolved-action count does not fit u64",
                )?)
                .context("Kbuild analyzer directory unresolved-action count overflowed")?;
        straddling_action_relations =
            straddling_action_relations
                .checked_add(u64::try_from(raw_straddling.len()).context(
                    "Kbuild analyzer directory straddling-action count does not fit u64",
                )?)
                .context("Kbuild analyzer directory straddling-action count overflowed")?;
        let has_before_actions = !before_actions.is_empty();
        let has_after_actions = !after_actions.is_empty();
        let mut has_unaffected_retained_name = false;
        for member in members {
            let analyzer_affected = analyzer_affected_members.contains(member);
            let action_affected = action_affected_members.contains(member);
            let count = match (analyzer_affected, action_affected) {
                (true, false) => &mut analyzer_only_retained_member_occurrences,
                (false, true) => &mut action_only_retained_member_occurrences,
                (true, true) => &mut mixed_owner_retained_member_occurrences,
                (false, false) => {
                    has_unaffected_retained_name = true;
                    &mut unaffected_retained_member_occurrences
                }
            };
            *count = count
                .checked_add(1)
                .context("Kbuild analyzer retained-member partition count overflowed")?;
        }
        checkpoints_with_before_actions = checkpoints_with_before_actions
            .checked_add(u64::from(has_before_actions))
            .context("Kbuild analyzer checkpoint-before count overflowed")?;
        checkpoints_with_after_actions = checkpoints_with_after_actions
            .checked_add(u64::from(has_after_actions))
            .context("Kbuild analyzer checkpoint-after count overflowed")?;
        checkpoints_with_before_and_after_actions = checkpoints_with_before_and_after_actions
            .checked_add(u64::from(has_before_actions && has_after_actions))
            .context("Kbuild analyzer checkpoint-around count overflowed")?;
        checkpoints_with_no_action_effects = checkpoints_with_no_action_effects
            .checked_add(u64::from(!has_before_actions && !has_after_actions))
            .context("Kbuild analyzer checkpoint no-action count overflowed")?;
        checkpoints_with_analyzer_effects = checkpoints_with_analyzer_effects
            .checked_add(u64::from(has_analyzer_effect))
            .context("Kbuild analyzer-effect checkpoint count overflowed")?;
        checkpoints_with_analyzer_effects_before_observation =
            checkpoints_with_analyzer_effects_before_observation
                .checked_add(u64::from(has_analyzer_effect_before_observation))
                .context("Kbuild analyzer pre-observation checkpoint count overflowed")?;
        checkpoints_with_analyzer_effects_after_observation =
            checkpoints_with_analyzer_effects_after_observation
                .checked_add(u64::from(has_analyzer_effect_after_observation))
                .context("Kbuild analyzer post-observation checkpoint count overflowed")?;
        checkpoints_with_only_post_observation_analyzer_effects =
            checkpoints_with_only_post_observation_analyzer_effects
                .checked_add(u64::from(
                    has_analyzer_effect_after_observation
                        && !has_analyzer_effect_before_observation
                        && !has_unresolved_analyzer_effect,
                ))
                .context("Kbuild analyzer post-only checkpoint count overflowed")?;
        checkpoints_with_analyzer_directory_object_effects =
            checkpoints_with_analyzer_directory_object_effects
                .checked_add(u64::from(has_analyzer_directory_object_effect))
                .context("Kbuild analyzer directory-object checkpoint count overflowed")?;
        checkpoints_with_analyzer_directory_object_effects_before_observation =
            checkpoints_with_analyzer_directory_object_effects_before_observation
                .checked_add(u64::from(
                    has_analyzer_directory_object_effect_before_observation,
                ))
                .context("Kbuild analyzer pre-observation object count overflowed")?;
        checkpoints_with_analyzer_directory_object_effects_after_observation =
            checkpoints_with_analyzer_directory_object_effects_after_observation
                .checked_add(u64::from(
                    has_analyzer_directory_object_effect_after_observation,
                ))
                .context("Kbuild analyzer post-observation object count overflowed")?;
        checkpoints_with_analyzer_retained_name_effects =
            checkpoints_with_analyzer_retained_name_effects
                .checked_add(u64::from(has_analyzer_retained_name_effect))
                .context("Kbuild analyzer retained-name checkpoint count overflowed")?;
        checkpoints_with_analyzer_retained_name_effects_before_observation =
            checkpoints_with_analyzer_retained_name_effects_before_observation
                .checked_add(u64::from(
                    has_analyzer_retained_name_effect_before_observation,
                ))
                .context("Kbuild analyzer pre-observation retained-name count overflowed")?;
        checkpoints_with_analyzer_retained_name_effects_after_observation =
            checkpoints_with_analyzer_retained_name_effects_after_observation
                .checked_add(u64::from(
                    has_analyzer_retained_name_effect_after_observation,
                ))
                .context("Kbuild analyzer post-observation retained-name count overflowed")?;
        analysis_internal_namespace_transaction_observations =
            analysis_internal_namespace_transaction_observations
                .checked_add(u64::from(analysis_internal_namespace_transaction))
                .context("Kbuild analysis-internal transaction count overflowed")?;
        checkpoints_with_analyzer_effects_and_before_actions =
            checkpoints_with_analyzer_effects_and_before_actions
                .checked_add(u64::from(has_analyzer_effect && has_before_actions))
                .context("Kbuild analyzer-effect checkpoint-before count overflowed")?;
        checkpoints_with_analyzer_retained_name_effects_and_before_actions =
            checkpoints_with_analyzer_retained_name_effects_and_before_actions
                .checked_add(u64::from(
                    has_analyzer_retained_name_effect && has_before_actions,
                ))
                .context("Kbuild analyzer retained-name checkpoint-before count overflowed")?;
        checkpoints_with_unaffected_retained_names = checkpoints_with_unaffected_retained_names
            .checked_add(u64::from(has_unaffected_retained_name))
            .context("Kbuild analyzer unaffected-name checkpoint count overflowed")?;
        checkpoints_with_unaffected_retained_names_and_before_actions =
            checkpoints_with_unaffected_retained_names_and_before_actions
                .checked_add(u64::from(
                    has_unaffected_retained_name && has_before_actions,
                ))
                .context("Kbuild analyzer unaffected-name checkpoint-before count overflowed")?;
        let candidate_action_boundary =
            unresolved_actions.is_empty() && !has_analyzer_effect && straddling.is_empty();
        candidate_action_boundary_observations = candidate_action_boundary_observations
            .checked_add(u64::from(candidate_action_boundary))
            .context("Kbuild analyzer boundary-candidate count overflowed")?;
        checkpoints.push(KbuildAnalyzerDirectoryCheckpoint {
            observation_ordinal: observation.ordinal,
            process: observation.process,
            stream_ordinal: observation.stream_ordinal,
            syscall_index,
            path: ExternalPathKey {
                root: "obj".to_string(),
                path: relative,
            },
            object: observation.object,
            value: observation.value,
            members: members.clone(),
            anchor: anchor.clone(),
            provenance,
            before_actions,
            after_actions,
            unresolved_actions,
            analyzer_affected_members,
            action_affected_members,
            analysis_ignored_transient_members,
            analysis_added_receipt_members,
            analysis_listing_digest,
            has_analyzer_effect,
            has_analyzer_effect_before_observation,
            has_analyzer_effect_after_observation,
            has_unresolved_analyzer_effect,
            has_analyzer_directory_object_effect,
            has_analyzer_directory_object_effect_before_observation,
            has_analyzer_directory_object_effect_after_observation,
            has_analyzer_retained_name_effect,
            has_analyzer_retained_name_effect_before_observation,
            has_analyzer_retained_name_effect_after_observation,
            analysis_internal_namespace_transaction,
            candidate_action_boundary,
        });
    }

    let observations = u64::try_from(checkpoints.len())
        .context("Kbuild analyzer directory checkpoint count does not fit u64")?;
    let provenance_total = bootstrap_observations
        .checked_add(post_candidate_observations)
        .and_then(|count| count.checked_add(exact_cross_owner_observations))
        .and_then(|count| count.checked_add(external_seed_observations))
        .and_then(|count| count.checked_add(same_owner_pre_mutation_observations))
        .and_then(|count| count.checked_add(same_owner_post_candidate_observations))
        .context("Kbuild analyzer directory provenance count overflowed")?;
    if provenance_total != observations {
        anyhow::bail!("Kbuild analyzer directory provenance partition is incomplete");
    }
    if analyzer_effect_batches
        .checked_add(action_effect_batches)
        .context("Kbuild analyzer directory effect-owner partition overflowed")?
        != effect_batches
        || effects_before_observations
            .checked_add(observations_before_effects)
            .and_then(|count| count.checked_add(causally_unresolved_effects))
            .context("Kbuild analyzer directory effect-time partition overflowed")?
            != effect_batches
        || analyzer_effect_batches_before_observations
            .checked_add(analyzer_effect_batches_after_observations)
            .and_then(|count| count.checked_add(analyzer_effect_batches_causally_unresolved))
            .context("Kbuild analyzer effect-time partition overflowed")?
            != analyzer_effect_batches
        || directory_object_effects
            .checked_add(member_effects)
            .context("Kbuild analyzer directory effect-subject partition overflowed")?
            < effect_batches
        || analyzer_directory_object_effects
            .checked_add(action_directory_object_effects)
            .context("Kbuild analyzer directory object-owner partition overflowed")?
            != directory_object_effects
        || analyzer_member_effects_on_retained_names
            .checked_add(analyzer_member_effects_on_absent_names)
            .and_then(|count| count.checked_add(action_member_effects_on_retained_names))
            .and_then(|count| count.checked_add(action_member_effects_on_absent_names))
            .context("Kbuild analyzer directory member-owner partition overflowed")?
            != member_effects
        || analyzer_only_retained_member_occurrences
            .checked_add(action_only_retained_member_occurrences)
            .and_then(|count| count.checked_add(mixed_owner_retained_member_occurrences))
            .and_then(|count| count.checked_add(unaffected_retained_member_occurrences))
            .context("Kbuild analyzer retained-member partition overflowed")?
            != member_names
        || candidate_action_boundary_observations > observations
        || checkpoints_with_before_actions > observations
        || checkpoints_with_after_actions > observations
        || checkpoints_with_before_and_after_actions > observations
        || checkpoints_with_no_action_effects > observations
        || checkpoints_with_analyzer_effects_and_before_actions > checkpoints_with_analyzer_effects
        || checkpoints_with_analyzer_retained_name_effects_and_before_actions
            > checkpoints_with_analyzer_retained_name_effects
        || checkpoints_with_unaffected_retained_names > observations
        || checkpoints_with_unaffected_retained_names_and_before_actions
            > checkpoints_with_unaffected_retained_names
        || checkpoints_with_analyzer_effects_before_observation > checkpoints_with_analyzer_effects
        || checkpoints_with_analyzer_effects_after_observation > checkpoints_with_analyzer_effects
        || checkpoints_with_only_post_observation_analyzer_effects
            > checkpoints_with_analyzer_effects_after_observation
        || checkpoints_with_analyzer_directory_object_effects_before_observation
            > checkpoints_with_analyzer_directory_object_effects
        || checkpoints_with_analyzer_directory_object_effects_after_observation
            > checkpoints_with_analyzer_directory_object_effects
        || checkpoints_with_analyzer_retained_name_effects_before_observation
            > checkpoints_with_analyzer_retained_name_effects
        || checkpoints_with_analyzer_retained_name_effects_after_observation
            > checkpoints_with_analyzer_retained_name_effects
        || analysis_internal_namespace_transaction_observations > observations
    {
        anyhow::bail!("Kbuild analyzer directory causal partition is incomplete");
    }
    let checkpoint_digest = kbuild_analyzer_directory_checkpoint_digest(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census_digest,
        provenance_partition_digest,
        mutation_attribution_digest,
        final_output_value_digest,
        directory_member_retention_digest,
        directory_causal_census_digest,
        &checkpoints,
    )?;
    Ok(KbuildAnalyzerDirectoryCheckpoints {
        seal: KbuildAnalyzerDirectoryCheckpointSeal {
            checkpoint_digest,
            observations,
            distinct_directories: u64::try_from(directories.len())
                .context("Kbuild analyzer directory path count does not fit u64")?,
            member_names,
            bootstrap_observations,
            post_candidate_observations,
            exact_cross_owner_observations,
            distinct_exact_cross_owner_directories: u64::try_from(exact_directories.len())
                .context("Kbuild analyzer exact directory path count does not fit u64")?,
            external_seed_observations,
            same_owner_pre_mutation_observations,
            same_owner_post_candidate_observations,
            effect_batches,
            analyzer_effect_batches,
            action_effect_batches,
            analyzer_effect_batches_before_observations,
            analyzer_effect_batches_after_observations,
            analyzer_effect_batches_causally_unresolved,
            effects_before_observations,
            observations_before_effects,
            causally_unresolved_effects,
            before_only_action_relations,
            after_only_action_relations,
            unresolved_action_relations,
            straddling_action_relations,
            directory_object_effects,
            member_effects,
            analyzer_directory_object_effects,
            action_directory_object_effects,
            analyzer_member_effects_on_retained_names,
            analyzer_member_effects_on_absent_names,
            action_member_effects_on_retained_names,
            action_member_effects_on_absent_names,
            analyzer_only_retained_member_occurrences,
            action_only_retained_member_occurrences,
            mixed_owner_retained_member_occurrences,
            unaffected_retained_member_occurrences,
            checkpoints_with_analyzer_effects,
            checkpoints_with_analyzer_effects_before_observation,
            checkpoints_with_analyzer_effects_after_observation,
            checkpoints_with_only_post_observation_analyzer_effects,
            checkpoints_with_analyzer_directory_object_effects,
            checkpoints_with_analyzer_directory_object_effects_before_observation,
            checkpoints_with_analyzer_directory_object_effects_after_observation,
            checkpoints_with_analyzer_retained_name_effects,
            checkpoints_with_analyzer_retained_name_effects_before_observation,
            checkpoints_with_analyzer_retained_name_effects_after_observation,
            analysis_internal_namespace_transaction_observations,
            checkpoints_with_before_actions,
            checkpoints_with_after_actions,
            checkpoints_with_before_and_after_actions,
            checkpoints_with_no_action_effects,
            checkpoints_with_analyzer_effects_and_before_actions,
            checkpoints_with_analyzer_retained_name_effects_and_before_actions,
            checkpoints_with_unaffected_retained_names,
            checkpoints_with_unaffected_retained_names_and_before_actions,
            candidate_action_boundary_observations,
        },
        checkpoints,
    })
}

#[cfg(unix)]
fn kbuild_generated_input_provenance(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census: &KbuildInputValueCensusSeal,
    provenance: &KbuildInputProvenancePartitionSeal,
    mutation_attribution_digest: [u8; 32],
    directory_members: KbuildDirectoryMemberRetention,
    directory_anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>,
    observations: &[KbuildInputObservation],
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    process_causality: &KbuildProcessCausality,
    declared_output_order: &BTreeMap<u64, Vec<PathBuf>>,
    final_outputs: &KbuildFinalOutputValueSeal,
    output_root: &Path,
) -> Result<KbuildGeneratedInputProvenance> {
    if input_census.graph_digest != graph_digest
        || input_census.stream_digest != stream_digest
        || input_census.assignment_digest != assignment_digest
        || provenance.graph_digest != graph_digest
        || provenance.stream_digest != stream_digest
        || provenance.assignment_digest != assignment_digest
        || provenance.input_census_digest != input_census.census_digest
        || provenance.mutation_attribution_digest != mutation_attribution_digest
        || directory_members.seal.graph_digest != graph_digest
        || directory_members.seal.stream_digest != stream_digest
        || directory_members.seal.assignment_digest != assignment_digest
        || directory_members.seal.input_census_digest != input_census.census_digest
        || directory_members.seal.directory_observations != input_census.directory_observations
        || final_outputs.graph_digest != graph_digest
        || final_outputs.stream_digest != stream_digest
        || final_outputs.assignment_digest != assignment_digest
        || final_outputs.mutation_attribution_digest != mutation_attribution_digest
    {
        anyhow::bail!("Kbuild generated-input provenance has inconsistent identity");
    }
    let validated_directory_members = kbuild_directory_member_retention(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census,
        observations,
        &directory_members.members,
    )?;
    if validated_directory_members != directory_members {
        anyhow::bail!("Kbuild generated-input directory-member retention changed");
    }

    let mutation_index = KbuildInputMutationIndex::from_events(mutation_events)?;
    let retained_directory_anchors =
        kbuild_retained_directory_path_anchors(observations, &mutation_index, directory_anchors)?;
    let action_count = u64::try_from(declared_output_order.len())
        .context("Kbuild generated-input action count does not fit u64")?;
    for (position, action_index) in declared_output_order.keys().copied().enumerate() {
        if action_index
            != u64::try_from(position)
                .context("Kbuild generated-input action position does not fit u64")?
        {
            anyhow::bail!("Kbuild generated-input actions are not contiguous");
        }
    }
    let mut last_mutations = BTreeMap::new();
    for (event_index, (owner, mutation)) in mutation_events.iter().enumerate() {
        last_mutations.insert(mutation.path.clone(), (*owner, event_index));
    }

    let mut outputs_by_path = BTreeMap::new();
    for output in final_outputs.outputs() {
        let action_outputs = declared_output_order
            .get(&output.action_index)
            .context("Kbuild generated input has no producer output list")?;
        let output_index = usize::try_from(output.output_index)
            .context("Kbuild generated input output index does not fit usize")?;
        let path = action_outputs
            .get(output_index)
            .context("Kbuild generated input output index exceeds its action")?;
        if outputs_by_path.insert(path.clone(), *output).is_some() {
            anyhow::bail!("Kbuild generated input repeats a declared producer output");
        }
    }
    let action_transient_paths = mutation_events
        .iter()
        .filter_map(|(owner, mutation)| match owner {
            KbuildProcessOwner::Action(action_index)
                if !outputs_by_path.contains_key(&mutation.path) =>
            {
                Some((*action_index, mutation.path.clone()))
            }
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    let action_receipt_paths = declared_output_order
        .iter()
        .flat_map(|(action_index, paths)| {
            paths.iter().filter_map(move |path| {
                native_adapter::is_command_receipt(path)
                    .then_some((*action_index, path.clone()))
            })
        })
        .collect::<BTreeSet<_>>();

    let mut directory_hasher = blake3::Hasher::new();
    directory_hasher.update(b"rush.kbuild-generated-directory-epochs.v1\0");
    directory_hasher.update(&graph_digest);
    directory_hasher.update(&stream_digest);
    directory_hasher.update(&assignment_digest);
    directory_hasher.update(&input_census.census_digest);
    directory_hasher.update(&provenance.partition_digest);
    directory_hasher.update(&mutation_attribution_digest);
    directory_hasher.update(&final_outputs.value_digest);
    directory_hasher.update(&directory_members.seal.retention_digest);
    let mut directory_epoch_observations = 0_u64;
    let mut analyzer_directory_epoch_observations = 0_u64;
    let mut action_directory_epoch_observations = 0_u64;
    let mut pre_effect_directory_epoch_observations = 0_u64;
    let mut intermediate_directory_epoch_observations = 0_u64;
    let mut post_effect_directory_epoch_observations = 0_u64;
    let mut self_effect_directory_epoch_observations = 0_u64;
    let mut cross_owner_directory_epoch_observations = 0_u64;
    let mut directory_epoch_paths = BTreeSet::new();
    for observation in observations {
        let Some((first_effect, last_effect, effect_owners)) =
            kbuild_directory_epoch_boundary(observation, &mutation_index)?
        else {
            continue;
        };
        directory_epoch_observations = directory_epoch_observations
            .checked_add(1)
            .context("Kbuild directory-epoch observation count overflowed")?;
        match observation.owner {
            KbuildProcessOwner::Analyzer => {
                analyzer_directory_epoch_observations = analyzer_directory_epoch_observations
                    .checked_add(1)
                    .context("Kbuild analyzer directory-epoch count overflowed")?;
            }
            KbuildProcessOwner::Action(action_index) => {
                action_directory_epoch_observations = action_directory_epoch_observations
                    .checked_add(1)
                    .context("Kbuild action directory-epoch count overflowed")?;
                if effect_owners.contains(&KbuildProcessOwner::Action(action_index)) {
                    self_effect_directory_epoch_observations =
                        self_effect_directory_epoch_observations
                            .checked_add(1)
                            .context("Kbuild self-effect directory-epoch count overflowed")?;
                }
            }
        }
        let epoch_tag = if observation.stream_ordinal < first_effect {
            pre_effect_directory_epoch_observations = pre_effect_directory_epoch_observations
                .checked_add(1)
                .context("Kbuild pre-effect directory-epoch count overflowed")?;
            0_u8
        } else if observation.stream_ordinal > last_effect {
            post_effect_directory_epoch_observations = post_effect_directory_epoch_observations
                .checked_add(1)
                .context("Kbuild post-effect directory-epoch count overflowed")?;
            2_u8
        } else {
            intermediate_directory_epoch_observations = intermediate_directory_epoch_observations
                .checked_add(1)
                .context("Kbuild intermediate directory-epoch count overflowed")?;
            1_u8
        };
        if mutation_index.classify(observation) == KbuildInputProvenanceClass::CrossOwnerMutation {
            cross_owner_directory_epoch_observations = cross_owner_directory_epoch_observations
                .checked_add(1)
                .context("Kbuild cross-owner directory-epoch count overflowed")?;
        }
        let relative = observation
            .path
            .strip_prefix(output_root)
            .context("Kbuild directory epoch is outside the output root")?;
        let relative = os_bytes(relative.as_os_str());
        let relative_length = u64::try_from(relative.len())
            .context("Kbuild directory-epoch path length does not fit u64")?;
        directory_epoch_paths.insert(relative.clone());
        update_kbuild_process_owner(&mut directory_hasher, observation.owner);
        directory_hasher.update(&observation.ordinal.to_le_bytes());
        directory_hasher.update(&observation.stream_ordinal.to_le_bytes());
        directory_hasher.update(&first_effect.to_le_bytes());
        directory_hasher.update(&last_effect.to_le_bytes());
        directory_hasher.update(&[epoch_tag]);
        directory_hasher.update(&relative_length.to_le_bytes());
        directory_hasher.update(&relative);
        directory_hasher.update(&observation.object.device.to_le_bytes());
        directory_hasher.update(&observation.object.inode.to_le_bytes());
        directory_hasher.update(
            &observation
                .object
                .mount_id
                .context("Kbuild generated directory has no mount identity")?
                .to_le_bytes(),
        );
        let KbuildObservedInputValue::Directory {
            entries,
            digest,
            listing_digest,
        } = observation.value
        else {
            unreachable!("directory epoch census contains only directory observations");
        };
        directory_hasher.update(&entries.to_le_bytes());
        directory_hasher.update(&digest);
        directory_hasher.update(&listing_digest);
        let owner_count = u64::try_from(effect_owners.len())
            .context("Kbuild directory-epoch owner count does not fit u64")?;
        directory_hasher.update(&owner_count.to_le_bytes());
        for owner in effect_owners {
            update_kbuild_process_owner(&mut directory_hasher, owner);
        }
    }
    let directory_owner_total = analyzer_directory_epoch_observations
        .checked_add(action_directory_epoch_observations)
        .context("Kbuild directory-epoch owner partition overflowed")?;
    let directory_timing_total = pre_effect_directory_epoch_observations
        .checked_add(intermediate_directory_epoch_observations)
        .and_then(|count| count.checked_add(post_effect_directory_epoch_observations))
        .context("Kbuild directory-epoch timing partition overflowed")?;
    let expected_cross_owner_directories = observations
        .iter()
        .filter(|observation| {
            matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            ) && mutation_index
                .directory_epoch_effects
                .contains_key(&observation.path)
                && mutation_index.classify(observation)
                    == KbuildInputProvenanceClass::CrossOwnerMutation
        })
        .count();
    let expected_directory_epoch_observations = u64::try_from(
        observations
            .iter()
            .filter(|observation| {
                matches!(
                    observation.value,
                    KbuildObservedInputValue::Directory { .. }
                ) && mutation_index
                    .directory_epoch_effects
                    .contains_key(&observation.path)
            })
            .count(),
    )
    .context("Kbuild expected directory-epoch count does not fit u64")?;
    if directory_owner_total != directory_epoch_observations
        || directory_timing_total != directory_epoch_observations
        || expected_directory_epoch_observations != directory_epoch_observations
        || cross_owner_directory_epoch_observations
            != u64::try_from(expected_cross_owner_directories)
                .context("Kbuild cross-owner directory count does not fit u64")?
    {
        anyhow::bail!("Kbuild directory-epoch census is incomplete");
    }
    let distinct_directory_epoch_paths = u64::try_from(directory_epoch_paths.len())
        .context("Kbuild directory-epoch path count does not fit u64")?;
    for count in [
        directory_epoch_observations,
        analyzer_directory_epoch_observations,
        action_directory_epoch_observations,
        pre_effect_directory_epoch_observations,
        intermediate_directory_epoch_observations,
        post_effect_directory_epoch_observations,
        self_effect_directory_epoch_observations,
        cross_owner_directory_epoch_observations,
        distinct_directory_epoch_paths,
    ] {
        directory_hasher.update(&count.to_le_bytes());
    }
    let directory_epoch_digest = *directory_hasher.finalize().as_bytes();
    let directory_causal_census = kbuild_directory_causal_census(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census.census_digest,
        provenance.partition_digest,
        mutation_attribution_digest,
        final_outputs.value_digest,
        observations,
        &mutation_index,
        process_causality,
        output_root,
        &retained_directory_anchors,
    )?;
    if directory_causal_census.observations != directory_epoch_observations
        || directory_causal_census
            .path_anchor_proved_paths
            .checked_add(directory_causal_census.path_anchor_unproved_paths)
            != Some(distinct_directory_epoch_paths)
    {
        anyhow::bail!("Kbuild causal directory census differs from the epoch census");
    }
    let analyzer_directory_checkpoints = kbuild_analyzer_directory_checkpoints(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census.census_digest,
        provenance.partition_digest,
        mutation_attribution_digest,
        final_outputs.value_digest,
        directory_members.seal.retention_digest,
        directory_causal_census.causal_digest,
        observations,
        &mutation_index,
        process_causality,
        output_root,
        action_count,
        &action_transient_paths,
        &action_receipt_paths,
        &directory_members.members,
        &retained_directory_anchors,
    )?;
    if analyzer_directory_checkpoints.seal.observations != analyzer_directory_epoch_observations {
        anyhow::bail!("Kbuild analyzer directory checkpoints do not cover the epoch census");
    }
    let generated_directory_checkpoints = kbuild_generated_directory_checkpoints(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census.census_digest,
        provenance.partition_digest,
        mutation_attribution_digest,
        observations,
        &mutation_index,
        process_causality,
        output_root,
        action_count,
        &directory_members.members,
        &retained_directory_anchors,
    )?;

    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-generated-input-provenance.v14\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&input_census.census_digest);
    hasher.update(&provenance.partition_digest);
    hasher.update(&mutation_attribution_digest);
    hasher.update(&final_outputs.value_digest);
    hasher.update(&directory_members.seal.retention_digest);
    hasher.update(&directory_epoch_digest);
    hasher.update(&directory_causal_census.causal_digest);
    hasher.update(&analyzer_directory_checkpoints.seal.checkpoint_digest);
    hasher.update(&generated_directory_checkpoints.seal.checkpoint_digest);
    let mut observations_count = 0_u64;
    let mut distinct_inputs = BTreeSet::new();
    let mut cross_owner_directory_observations = 0_u64;
    let mut exact_cross_owner_directory_path_observations = 0_u64;
    let mut pre_mutation_directory_observations = 0_u64;
    let mut post_mutation_directory_observations = 0_u64;
    let mut cross_owner_directories = BTreeSet::new();
    let mut analyzer_cross_owner_observations = 0_u64;
    let mut analyzer_exact_path_observations = 0_u64;
    let mut analyzer_pre_mutation_observations = 0_u64;
    let mut analyzer_post_mutation_observations = 0_u64;
    let mut analyzer_cross_owner_paths = BTreeSet::new();
    let mut analyzer_generated_file_observations = 0_u64;
    let mut analyzer_pre_final_value_match_observations = 0_u64;
    let mut analyzer_post_final_generated_file_observations = 0_u64;
    let mut analyzer_generated_files = BTreeSet::new();
    let mut analyzer_pre_producer_mutation_observations = 0_u64;
    let mut analyzer_directory_observations = 0_u64;
    let mut analyzer_directories = BTreeSet::new();
    let mut analyzer_undeclared_output_observations = 0_u64;
    let mut analyzer_final_value_mismatch_observations = 0_u64;
    let mut unresolved_exact_observations = 0_u64;
    let mut analyzer_produced_observations = 0_u64;
    let mut undeclared_output_observations = 0_u64;
    let mut pre_final_mutation_observations = 0_u64;
    let mut final_value_mismatch_observations = 0_u64;
    let mut unresolved_exact_inputs = BTreeSet::new();
    let mut grouped = BTreeMap::<(u64, u64), (u64, BTreeSet<Vec<u8>>)>::new();
    let mut generated_action_inputs = BTreeMap::<(u64, Vec<u8>), KbuildGeneratedActionInput>::new();
    let mut analyzer_generated_inputs = BTreeMap::<Vec<u8>, KbuildAnalyzerGeneratedInput>::new();
    for observation in observations {
        if mutation_index.classify(observation) != KbuildInputProvenanceClass::CrossOwnerMutation {
            continue;
        }
        let relative = observation
            .path
            .strip_prefix(output_root)
            .context("Kbuild generated input is outside the output root")?;
        let relative = os_bytes(relative.as_os_str());
        let relative_length = u64::try_from(relative.len())
            .context("Kbuild generated input path length does not fit u64")?;
        if observation.owner == KbuildProcessOwner::Analyzer {
            hasher.update(&[2]);
            let (owner, first_mutation) = mutation_index
                .exact_paths
                .get(&observation.path)
                .context("Kbuild analyzer cross-owner input has no exact mutation")?;
            update_kbuild_process_owner(&mut hasher, *owner);
            analyzer_cross_owner_observations = analyzer_cross_owner_observations
                .checked_add(1)
                .context("Kbuild analyzer cross-owner count overflowed")?;
            analyzer_exact_path_observations = analyzer_exact_path_observations
                .checked_add(1)
                .context("Kbuild analyzer exact-path count overflowed")?;
            if observation.stream_ordinal < *first_mutation {
                analyzer_pre_mutation_observations = analyzer_pre_mutation_observations
                    .checked_add(1)
                    .context("Kbuild analyzer pre-mutation count overflowed")?;
            } else {
                analyzer_post_mutation_observations = analyzer_post_mutation_observations
                    .checked_add(1)
                    .context("Kbuild analyzer post-mutation count overflowed")?;
            }
            analyzer_cross_owner_paths.insert(relative.clone());
            let KbuildProcessOwner::Action(producer_action_index) = *owner else {
                anyhow::bail!("Kbuild analyzer generated input has an analyzer producer");
            };
            let (last_owner, last_event_index) = last_mutations
                .get(&observation.path)
                .copied()
                .context("Kbuild analyzer generated input has no final mutation")?;
            if last_owner != *owner {
                anyhow::bail!("Kbuild analyzer generated input changed mutation owner");
            }
            let last_mutation = &mutation_events[last_event_index].1;
            let analyzer_class = if observation.stream_ordinal < *first_mutation {
                analyzer_pre_producer_mutation_observations =
                    analyzer_pre_producer_mutation_observations
                        .checked_add(1)
                        .context("Kbuild analyzer pre-producer-mutation count overflowed")?;
                4_u8
            } else {
                match observation.value {
                    KbuildObservedInputValue::Directory { .. } => {
                        analyzer_directory_observations = analyzer_directory_observations
                            .checked_add(1)
                            .context("Kbuild analyzer directory count overflowed")?;
                        analyzer_directories.insert(relative.clone());
                        1_u8
                    }
                    KbuildObservedInputValue::WholeFile { .. } => {
                        match outputs_by_path
                            .get(&observation.path)
                            .filter(|output| output.action_index == producer_action_index)
                        {
                            None => {
                                analyzer_undeclared_output_observations =
                                    analyzer_undeclared_output_observations
                                        .checked_add(1)
                                        .context(
                                            "Kbuild analyzer undeclared-input count overflowed",
                                        )?;
                                2_u8
                            }
                            Some(final_output)
                                if !kbuild_generated_regular_file_matches(
                                    observation,
                                    final_output,
                                ) =>
                            {
                                analyzer_final_value_mismatch_observations =
                                    analyzer_final_value_mismatch_observations
                                        .checked_add(1)
                                        .context(
                                            "Kbuild analyzer value-mismatch count overflowed",
                                        )?;
                                3_u8
                            }
                            Some(final_output) => {
                                let retained = KbuildAnalyzerGeneratedInput {
                                    producer_action_index,
                                    producer_output_index: final_output.output_index,
                                    path: ExternalPathKey {
                                        root: "obj".to_string(),
                                        path: relative.clone(),
                                    },
                                    value: kbuild_external_input_value(observation.value),
                                    object: final_output.object,
                                };
                                match analyzer_generated_inputs.entry(relative.clone()) {
                                    std::collections::btree_map::Entry::Vacant(entry) => {
                                        entry.insert(retained);
                                    }
                                    std::collections::btree_map::Entry::Occupied(entry)
                                        if entry.get() != &retained =>
                                    {
                                        anyhow::bail!(
                                            "Kbuild analyzer generated input has inconsistent \
                                             proof values"
                                        );
                                    }
                                    std::collections::btree_map::Entry::Occupied(_) => {}
                                }
                                if last_mutation.stream_ordinal < observation.stream_ordinal {
                                    analyzer_generated_file_observations =
                                        analyzer_generated_file_observations
                                            .checked_add(1)
                                            .context(
                                                "Kbuild analyzer generated-file count overflowed",
                                            )?;
                                    analyzer_post_final_generated_file_observations =
                                        analyzer_post_final_generated_file_observations
                                            .checked_add(1)
                                            .context(
                                                "Kbuild analyzer post-final count overflowed",
                                            )?;
                                    analyzer_generated_files.insert(relative.clone());
                                    0_u8
                                } else {
                                    analyzer_pre_final_value_match_observations =
                                        analyzer_pre_final_value_match_observations
                                            .checked_add(1)
                                            .context(
                                                "Kbuild analyzer pre-final value-match count \
                                                 overflowed",
                                            )?;
                                    5_u8
                                }
                            }
                        }
                    }
                }
            };
            hasher.update(&[analyzer_class]);
            hasher.update(&observation.ordinal.to_le_bytes());
            hasher.update(&observation.stream_ordinal.to_le_bytes());
            hasher.update(&first_mutation.to_le_bytes());
            hasher.update(&last_mutation.stream_ordinal.to_le_bytes());
            hasher.update(&relative_length.to_le_bytes());
            hasher.update(&relative);
            hasher.update(&observation.object.device.to_le_bytes());
            hasher.update(&observation.object.inode.to_le_bytes());
            hasher.update(
                &observation
                    .object
                    .mount_id
                    .context("Kbuild analyzer cross-owner input has no mount identity")?
                    .to_le_bytes(),
            );
            match observation.value {
                KbuildObservedInputValue::WholeFile {
                    bytes,
                    digest,
                    mode,
                } => {
                    hasher.update(&[0]);
                    hasher.update(&bytes.to_le_bytes());
                    hasher.update(&digest);
                    hasher.update(&mode.to_le_bytes());
                }
                KbuildObservedInputValue::Directory {
                    entries,
                    digest,
                    listing_digest,
                } => {
                    hasher.update(&[1]);
                    hasher.update(&entries.to_le_bytes());
                    hasher.update(&digest);
                    hasher.update(&listing_digest);
                }
            }
            continue;
        }
        let KbuildProcessOwner::Action(consumer_action_index) = observation.owner else {
            unreachable!("analyzer owner was handled above");
        };
        if matches!(
            observation.value,
            KbuildObservedInputValue::Directory { .. }
        ) {
            let exact_producer = mutation_index.exact_paths.get(&observation.path);
            let effect = mutation_index
                .directory_epoch_effects
                .get(&observation.path)
                .context("Kbuild cross-owner directory has no mutation epoch")?;
            let KbuildObservedInputValue::Directory {
                entries,
                digest,
                listing_digest,
            } = observation.value
            else {
                anyhow::bail!("Kbuild cross-owner directory has no complete listing value");
            };
            if observation.class != KbuildInputObservationClass::Directory
                || observation.object.kind != KbuildInputObjectKind::Directory
                || effect.owners.is_empty()
                || effect
                    .owners
                    .iter()
                    .all(|owner| *owner == observation.owner)
            {
                anyhow::bail!("Kbuild cross-owner directory partition is malformed");
            }
            let exact_output = if let Some((producer, _)) = exact_producer {
                let KbuildProcessOwner::Action(producer_action_index) = *producer else {
                    anyhow::bail!("Kbuild exact generated directory has an analyzer producer");
                };
                if producer_action_index == consumer_action_index {
                    anyhow::bail!(
                        "Kbuild exact generated directory has the same producer and consumer"
                    );
                }
                exact_cross_owner_directory_path_observations =
                    exact_cross_owner_directory_path_observations
                        .checked_add(1)
                        .context("Kbuild exact cross-owner directory count overflowed")?;
                let output = outputs_by_path
                    .get(&observation.path)
                    .filter(|output| output.action_index == producer_action_index)
                    .context(
                        "Kbuild exact generated directory is not a declared producer output",
                    )?;
                let (last_owner, last_event_index) = last_mutations
                    .get(&observation.path)
                    .copied()
                    .context("Kbuild exact generated directory has no final mutation")?;
                let last_mutation = &mutation_events[last_event_index].1;
                if last_owner != *producer
                    || last_mutation.stream_ordinal >= observation.stream_ordinal
                    || !kbuild_generated_directory_matches(observation, output)
                {
                    anyhow::bail!("Kbuild exact generated directory has no stable producer value");
                }
                Some((producer_action_index, output.output_index))
            } else {
                None
            };
            cross_owner_directory_observations = cross_owner_directory_observations
                .checked_add(1)
                .context("Kbuild cross-owner directory count overflowed")?;
            if observation.stream_ordinal < effect.first_stream_ordinal {
                pre_mutation_directory_observations = pre_mutation_directory_observations
                    .checked_add(1)
                    .context("Kbuild pre-mutation directory count overflowed")?;
            } else {
                post_mutation_directory_observations = post_mutation_directory_observations
                    .checked_add(1)
                    .context("Kbuild post-mutation directory count overflowed")?;
            }
            cross_owner_directories.insert(relative.clone());
            hasher.update(&[1, u8::from(exact_output.is_some())]);
            hasher.update(&consumer_action_index.to_le_bytes());
            hasher.update(&observation.ordinal.to_le_bytes());
            hasher.update(&observation.stream_ordinal.to_le_bytes());
            hasher.update(&effect.first_stream_ordinal.to_le_bytes());
            if let Some((producer_action_index, producer_output_index)) = exact_output {
                hasher.update(&producer_action_index.to_le_bytes());
                hasher.update(&producer_output_index.to_le_bytes());
            }
            hasher.update(&relative_length.to_le_bytes());
            hasher.update(&relative);
            let owner_count = u64::try_from(effect.owners.len())
                .context("Kbuild directory-effect owner count does not fit u64")?;
            hasher.update(&owner_count.to_le_bytes());
            for owner in &effect.owners {
                update_kbuild_process_owner(&mut hasher, *owner);
            }
            hasher.update(&observation.object.device.to_le_bytes());
            hasher.update(&observation.object.inode.to_le_bytes());
            hasher.update(
                &observation
                    .object
                    .mount_id
                    .context("Kbuild cross-owner directory has no mount identity")?
                    .to_le_bytes(),
            );
            hasher.update(&entries.to_le_bytes());
            hasher.update(&digest);
            hasher.update(&listing_digest);
            continue;
        }
        let (producer, _) = mutation_index
            .exact_paths
            .get(&observation.path)
            .context("Kbuild cross-owner file has no exact mutation")?;
        if relative.is_empty() {
            anyhow::bail!("Kbuild generated file names the output root");
        }
        let mut record_unresolved =
            |tag: u8, producer: KbuildProcessOwner, last_mutation: Option<u64>| -> Result<()> {
                unresolved_exact_observations = unresolved_exact_observations
                    .checked_add(1)
                    .context("Kbuild unresolved exact-input count overflowed")?;
                unresolved_exact_inputs.insert(relative.clone());
                hasher.update(&[3, tag]);
                update_kbuild_process_owner(&mut hasher, producer);
                hasher.update(&consumer_action_index.to_le_bytes());
                match last_mutation {
                    Some(ordinal) => {
                        hasher.update(&[1]);
                        hasher.update(&ordinal.to_le_bytes());
                    }
                    None => {
                        hasher.update(&[0]);
                    }
                }
                hasher.update(&relative_length.to_le_bytes());
                hasher.update(&relative);
                update_kbuild_generated_observation(&mut hasher, observation)
            };
        let KbuildProcessOwner::Action(producer_action_index) = *producer else {
            analyzer_produced_observations = analyzer_produced_observations
                .checked_add(1)
                .context("Kbuild analyzer-produced input count overflowed")?;
            record_unresolved(0, *producer, None)?;
            continue;
        };
        if producer_action_index == consumer_action_index {
            anyhow::bail!("Kbuild generated input has the same producer and consumer");
        }
        let Some(final_output) = outputs_by_path
            .get(&observation.path)
            .filter(|output| output.action_index == producer_action_index)
        else {
            undeclared_output_observations = undeclared_output_observations
                .checked_add(1)
                .context("Kbuild undeclared generated-input count overflowed")?;
            record_unresolved(1, *producer, None)?;
            continue;
        };
        let (last_owner, last_event_index) = last_mutations
            .get(&observation.path)
            .copied()
            .context("Kbuild generated input has no final mutation")?;
        let last_mutation = &mutation_events[last_event_index].1;
        if last_owner != *producer {
            anyhow::bail!("Kbuild generated input changed mutation owner");
        }
        if last_mutation.stream_ordinal >= observation.stream_ordinal {
            pre_final_mutation_observations = pre_final_mutation_observations
                .checked_add(1)
                .context("Kbuild pre-final generated-input count overflowed")?;
            record_unresolved(2, *producer, Some(last_mutation.stream_ordinal))?;
            continue;
        }
        let (bytes, digest, mode) = match observation.value {
            KbuildObservedInputValue::WholeFile {
                bytes,
                digest,
                mode,
            } => (bytes, digest, mode),
            KbuildObservedInputValue::Directory { .. } => {
                final_value_mismatch_observations = final_value_mismatch_observations
                    .checked_add(1)
                    .context("Kbuild generated-input mismatch count overflowed")?;
                record_unresolved(3, *producer, Some(last_mutation.stream_ordinal))?;
                continue;
            }
        };
        if !kbuild_generated_regular_file_matches(observation, final_output) {
            final_value_mismatch_observations = final_value_mismatch_observations
                .checked_add(1)
                .context("Kbuild generated-input mismatch count overflowed")?;
            record_unresolved(3, *producer, Some(last_mutation.stream_ordinal))?;
            continue;
        }
        observations_count = observations_count
            .checked_add(1)
            .context("Kbuild generated input observation count overflowed")?;
        distinct_inputs.insert(relative.clone());
        let edge = grouped
            .entry((producer_action_index, consumer_action_index))
            .or_default();
        edge.0 = edge
            .0
            .checked_add(1)
            .context("Kbuild generated input edge count overflowed")?;
        edge.1.insert(relative.clone());

        let retained = KbuildGeneratedActionInput {
            producer_action_index,
            consumer_action_index,
            producer_output_index: final_output.output_index,
            path: ExternalPathKey {
                root: "obj".to_string(),
                path: relative.clone(),
            },
            value: kbuild_external_input_value(observation.value),
            object: final_output.object,
        };
        match generated_action_inputs.entry((consumer_action_index, relative.clone())) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(retained);
            }
            std::collections::btree_map::Entry::Occupied(entry) if entry.get() != &retained => {
                anyhow::bail!("Kbuild generated action input has inconsistent proof values");
            }
            std::collections::btree_map::Entry::Occupied(_) => {}
        }

        hasher.update(&[0]);
        hasher.update(&producer_action_index.to_le_bytes());
        hasher.update(&consumer_action_index.to_le_bytes());
        hasher.update(&observation.ordinal.to_le_bytes());
        hasher.update(&observation.stream_ordinal.to_le_bytes());
        hasher.update(&last_mutation.stream_ordinal.to_le_bytes());
        hasher.update(&relative_length.to_le_bytes());
        hasher.update(&relative);
        hasher.update(&[match observation.class {
            KbuildInputObservationClass::Executable => 0,
            KbuildInputObservationClass::ExecMapping => 1,
            KbuildInputObservationClass::Open => 2,
            KbuildInputObservationClass::Mmap => 3,
            KbuildInputObservationClass::Read => 4,
            KbuildInputObservationClass::Directory => 5,
        }]);
        hasher.update(&observation.object.device.to_le_bytes());
        hasher.update(&observation.object.inode.to_le_bytes());
        hasher.update(&final_output.object.mount_id.to_le_bytes());
        hasher.update(&bytes.to_le_bytes());
        hasher.update(&digest);
        hasher.update(&mode.to_le_bytes());
    }
    let partitioned_observations = observations_count
        .checked_add(unresolved_exact_observations)
        .and_then(|count| count.checked_add(cross_owner_directory_observations))
        .and_then(|count| count.checked_add(analyzer_cross_owner_observations))
        .context("Kbuild cross-owner partition count overflowed")?;
    let exact_path_observations = observations_count
        .checked_add(unresolved_exact_observations)
        .and_then(|count| count.checked_add(analyzer_exact_path_observations))
        .context("Kbuild exact cross-owner count overflowed")?;
    let unresolved_reason_observations = analyzer_produced_observations
        .checked_add(undeclared_output_observations)
        .and_then(|count| count.checked_add(pre_final_mutation_observations))
        .and_then(|count| count.checked_add(final_value_mismatch_observations))
        .context("Kbuild unresolved exact-input partition overflowed")?;
    let analyzer_timing_observations = analyzer_pre_mutation_observations
        .checked_add(analyzer_post_mutation_observations)
        .context("Kbuild analyzer timing count overflowed")?;
    let analyzer_reason_observations = analyzer_generated_file_observations
        .checked_add(analyzer_pre_final_value_match_observations)
        .and_then(|count| count.checked_add(analyzer_pre_producer_mutation_observations))
        .and_then(|count| count.checked_add(analyzer_directory_observations))
        .and_then(|count| count.checked_add(analyzer_undeclared_output_observations))
        .and_then(|count| count.checked_add(analyzer_final_value_mismatch_observations))
        .context("Kbuild analyzer generated-input partition overflowed")?;
    if partitioned_observations != provenance.cross_owner_mutation_observations {
        anyhow::bail!(
            "Kbuild generated-input provenance partition mismatch: retained={} census={}",
            partitioned_observations,
            provenance.cross_owner_mutation_observations,
        );
    }
    let path_census_observations = exact_path_observations
        .checked_add(exact_cross_owner_directory_path_observations)
        .context("Kbuild generated-input path census overflowed")?;
    if path_census_observations != input_census.cross_owner_mutation_path_observations {
        anyhow::bail!(
            "Kbuild generated-input path census mismatch: files={} exact_directories={} retained={} census={}",
            exact_path_observations,
            exact_cross_owner_directory_path_observations,
            path_census_observations,
            input_census.cross_owner_mutation_path_observations,
        );
    }
    if unresolved_reason_observations != unresolved_exact_observations {
        anyhow::bail!(
            "Kbuild generated-input unresolved-reason mismatch: reasons={} unresolved={}",
            unresolved_reason_observations,
            unresolved_exact_observations,
        );
    }
    if analyzer_exact_path_observations != analyzer_cross_owner_observations
        || analyzer_timing_observations != analyzer_cross_owner_observations
        || analyzer_reason_observations != analyzer_cross_owner_observations
    {
        anyhow::bail!(
            "Kbuild analyzer generated-input partition mismatch: exact={} timing={} reasons={} total={}",
            analyzer_exact_path_observations,
            analyzer_timing_observations,
            analyzer_reason_observations,
            analyzer_cross_owner_observations,
        );
    }
    if analyzer_post_final_generated_file_observations != analyzer_generated_file_observations {
        anyhow::bail!(
            "Kbuild analyzer generated-input final-value mismatch: post-final={} generated={}",
            analyzer_post_final_generated_file_observations,
            analyzer_generated_file_observations,
        );
    }
    if generated_directory_checkpoints.seal.observations != cross_owner_directory_observations {
        anyhow::bail!(
            "Kbuild generated-directory checkpoint mismatch: retained={} census={}",
            generated_directory_checkpoints.seal.observations,
            cross_owner_directory_observations,
        );
    }

    let distinct_inputs_count = u64::try_from(distinct_inputs.len())
        .context("Kbuild generated input count does not fit u64")?;
    let distinct_cross_owner_directories = u64::try_from(cross_owner_directories.len())
        .context("Kbuild cross-owner directory count does not fit u64")?;
    if generated_directory_checkpoints.seal.distinct_directories != distinct_cross_owner_directories
    {
        anyhow::bail!("Kbuild generated directory checkpoint paths changed");
    }
    let distinct_analyzer_cross_owner_paths = u64::try_from(analyzer_cross_owner_paths.len())
        .context("Kbuild analyzer cross-owner path count does not fit u64")?;
    let distinct_analyzer_generated_files = u64::try_from(analyzer_generated_files.len())
        .context("Kbuild analyzer generated-file count does not fit u64")?;
    let distinct_analyzer_directories = u64::try_from(analyzer_directories.len())
        .context("Kbuild analyzer directory count does not fit u64")?;
    let distinct_unresolved_exact_inputs = u64::try_from(unresolved_exact_inputs.len())
        .context("Kbuild unresolved exact-input count does not fit u64")?;
    let edge_count =
        u64::try_from(grouped.len()).context("Kbuild generated edge count does not fit u64")?;
    let generated_action_input_references = u64::try_from(generated_action_inputs.len())
        .context("Kbuild generated action input count does not fit u64")?;
    if generated_action_input_references > observations_count {
        anyhow::bail!("Kbuild generated action input count exceeds its observations");
    }
    let grouped_action_input_references =
        grouped
            .values()
            .try_fold(0_u64, |count, (_, paths)| -> Result<u64> {
                count
                    .checked_add(
                        u64::try_from(paths.len())
                            .context("Kbuild generated edge input count does not fit u64")?,
                    )
                    .context("Kbuild generated edge input count overflowed")
            })?;
    if grouped_action_input_references != generated_action_input_references {
        anyhow::bail!("Kbuild generated action input ledger differs from edge summaries");
    }
    for ((producer_action_index, consumer_action_index), (_, paths)) in &grouped {
        for path in paths {
            let input = generated_action_inputs
                .get(&(*consumer_action_index, path.clone()))
                .context("Kbuild generated edge has no retained action input")?;
            if input.producer_action_index != *producer_action_index {
                anyhow::bail!("Kbuild generated edge has a different retained producer");
            }
        }
    }
    for ((consumer_action_index, path), input) in &generated_action_inputs {
        if input.consumer_action_index != *consumer_action_index
            || input.path.root != "obj"
            || input.path.path != *path
            || !grouped
                .get(&(input.producer_action_index, *consumer_action_index))
                .is_some_and(|(_, paths)| paths.contains(path))
        {
            anyhow::bail!("Kbuild retained action input has no matching edge");
        }
        let producer_outputs = declared_output_order
            .get(&input.producer_action_index)
            .context("Kbuild retained action input has no producer")?;
        let output_index = usize::try_from(input.producer_output_index)
            .context("Kbuild retained producer output index does not fit usize")?;
        let producer_path = producer_outputs
            .get(output_index)
            .context("Kbuild retained producer output index exceeds its action")?;
        let producer_relative = producer_path
            .strip_prefix(output_root)
            .context("Kbuild retained producer output is outside the output root")?;
        if os_bytes(producer_relative.as_os_str()) != input.path.path {
            anyhow::bail!("Kbuild retained action input differs from its producer output");
        }
        let final_output = final_outputs
            .outputs()
            .iter()
            .find(|output| {
                output.action_index == input.producer_action_index
                    && output.output_index == input.producer_output_index
            })
            .context("Kbuild retained action input has no selected final output")?;
        let final_value = ExternalInputValue::File {
            digest: final_output.digest,
            executable: final_output.mode & 0o111 != 0,
        };
        if final_output.kind != KbuildFinalOutputKind::RegularFile
            || final_output.object != input.object
            || final_value != input.value
        {
            anyhow::bail!("Kbuild retained action input differs from its final output value");
        }
    }
    let action_count_usize = usize::try_from(action_count)
        .context("Kbuild generated-input action count does not fit usize")?;
    let mut action_inputs = vec![Vec::new(); action_count_usize];
    for ((consumer_action_index, _), input) in generated_action_inputs {
        let consumer_index = usize::try_from(consumer_action_index)
            .context("Kbuild generated-input consumer index does not fit usize")?;
        action_inputs
            .get_mut(consumer_index)
            .context("Kbuild generated-input consumer index exceeds the graph")?
            .push(input);
    }
    let actions_with_generated_inputs = u64::try_from(
        action_inputs
            .iter()
            .filter(|inputs| !inputs.is_empty())
            .count(),
    )
    .context("Kbuild generated-input consumer count does not fit u64")?;
    let generated_action_input_digest = kbuild_generated_action_input_digest(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census.census_digest,
        provenance.partition_digest,
        mutation_attribution_digest,
        final_outputs.value_digest,
        &action_inputs,
    )?;
    let analyzer_inputs = analyzer_generated_inputs.into_values().collect::<Vec<_>>();
    let analyzer_generated_input_references = u64::try_from(analyzer_inputs.len())
        .context("Kbuild analyzer generated-input count does not fit u64")?;
    let analyzer_generated_observations = analyzer_generated_file_observations
        .checked_add(analyzer_pre_final_value_match_observations)
        .context("Kbuild analyzer generated-file count overflowed")?;
    if analyzer_generated_input_references > analyzer_generated_observations {
        anyhow::bail!("Kbuild analyzer generated-input count exceeds its observations");
    }
    for input in &analyzer_inputs {
        let producer_outputs = declared_output_order
            .get(&input.producer_action_index)
            .context("Kbuild analyzer generated input has no producer")?;
        let output_index = usize::try_from(input.producer_output_index)
            .context("Kbuild analyzer producer output index does not fit usize")?;
        let producer_path = producer_outputs
            .get(output_index)
            .context("Kbuild analyzer producer output index exceeds its action")?;
        let producer_relative = producer_path
            .strip_prefix(output_root)
            .context("Kbuild analyzer producer output is outside the output root")?;
        if input.path.root != "obj" || os_bytes(producer_relative.as_os_str()) != input.path.path {
            anyhow::bail!("Kbuild analyzer generated input differs from its producer output");
        }
        let final_output = final_outputs
            .outputs()
            .iter()
            .find(|output| {
                output.action_index == input.producer_action_index
                    && output.output_index == input.producer_output_index
            })
            .context("Kbuild analyzer generated input has no selected final output")?;
        let final_value = ExternalInputValue::File {
            digest: final_output.digest,
            executable: final_output.mode & 0o111 != 0,
        };
        if final_output.kind != KbuildFinalOutputKind::RegularFile
            || final_output.object != input.object
            || final_value != input.value
        {
            anyhow::bail!("Kbuild analyzer generated input differs from its final output value");
        }
    }
    let analyzer_generated_input_digest = kbuild_analyzer_generated_input_digest(
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census.census_digest,
        provenance.partition_digest,
        mutation_attribution_digest,
        final_outputs.value_digest,
        action_count,
        &analyzer_inputs,
    )?;
    hasher.update(&observations_count.to_le_bytes());
    hasher.update(&distinct_inputs_count.to_le_bytes());
    hasher.update(&generated_action_input_digest);
    hasher.update(&generated_action_input_references.to_le_bytes());
    hasher.update(&actions_with_generated_inputs.to_le_bytes());
    hasher.update(&analyzer_generated_input_digest);
    hasher.update(&analyzer_generated_input_references.to_le_bytes());
    hasher.update(&cross_owner_directory_observations.to_le_bytes());
    hasher.update(&pre_mutation_directory_observations.to_le_bytes());
    hasher.update(&post_mutation_directory_observations.to_le_bytes());
    hasher.update(&distinct_cross_owner_directories.to_le_bytes());
    hasher.update(&analyzer_cross_owner_observations.to_le_bytes());
    hasher.update(&analyzer_exact_path_observations.to_le_bytes());
    hasher.update(&analyzer_pre_mutation_observations.to_le_bytes());
    hasher.update(&analyzer_post_mutation_observations.to_le_bytes());
    hasher.update(&distinct_analyzer_cross_owner_paths.to_le_bytes());
    hasher.update(&analyzer_generated_file_observations.to_le_bytes());
    hasher.update(&analyzer_pre_final_value_match_observations.to_le_bytes());
    hasher.update(&analyzer_post_final_generated_file_observations.to_le_bytes());
    hasher.update(&distinct_analyzer_generated_files.to_le_bytes());
    hasher.update(&analyzer_pre_producer_mutation_observations.to_le_bytes());
    hasher.update(&analyzer_directory_observations.to_le_bytes());
    hasher.update(&distinct_analyzer_directories.to_le_bytes());
    hasher.update(&analyzer_undeclared_output_observations.to_le_bytes());
    hasher.update(&analyzer_final_value_mismatch_observations.to_le_bytes());
    hasher.update(&directory_epoch_observations.to_le_bytes());
    hasher.update(&analyzer_directory_epoch_observations.to_le_bytes());
    hasher.update(&action_directory_epoch_observations.to_le_bytes());
    hasher.update(&pre_effect_directory_epoch_observations.to_le_bytes());
    hasher.update(&intermediate_directory_epoch_observations.to_le_bytes());
    hasher.update(&post_effect_directory_epoch_observations.to_le_bytes());
    hasher.update(&self_effect_directory_epoch_observations.to_le_bytes());
    hasher.update(&distinct_directory_epoch_paths.to_le_bytes());
    hasher.update(&unresolved_exact_observations.to_le_bytes());
    hasher.update(&analyzer_produced_observations.to_le_bytes());
    hasher.update(&undeclared_output_observations.to_le_bytes());
    hasher.update(&pre_final_mutation_observations.to_le_bytes());
    hasher.update(&final_value_mismatch_observations.to_le_bytes());
    hasher.update(&distinct_unresolved_exact_inputs.to_le_bytes());
    hasher.update(&edge_count.to_le_bytes());
    let mut edges = Vec::with_capacity(grouped.len());
    for ((producer_action_index, consumer_action_index), (observations, inputs)) in grouped {
        let distinct_inputs = u64::try_from(inputs.len())
            .context("Kbuild generated edge input count does not fit u64")?;
        hasher.update(&producer_action_index.to_le_bytes());
        hasher.update(&consumer_action_index.to_le_bytes());
        hasher.update(&observations.to_le_bytes());
        hasher.update(&distinct_inputs.to_le_bytes());
        edges.push(KbuildGeneratedInputEdgeSeal {
            producer_action_index,
            consumer_action_index,
            observations,
            distinct_inputs,
        });
    }
    Ok(KbuildGeneratedInputProvenance {
        seal: KbuildGeneratedInputProvenanceSeal {
            graph_digest,
            stream_digest,
            assignment_digest,
            input_census_digest: input_census.census_digest,
            provenance_partition_digest: provenance.partition_digest,
            mutation_attribution_digest,
            final_output_value_digest: final_outputs.value_digest,
            directory_member_retention: directory_members.seal,
            generated_directory_checkpoints: generated_directory_checkpoints.seal,
            generated_action_input_digest,
            analyzer_generated_input_digest,
            analyzer_directory_checkpoints: analyzer_directory_checkpoints.seal,
            provenance_digest: *hasher.finalize().as_bytes(),
            directory_causal_census,
            observations: observations_count,
            distinct_inputs: distinct_inputs_count,
            generated_action_input_references,
            actions_with_generated_inputs,
            analyzer_generated_input_references,
            cross_owner_directory_observations,
            pre_mutation_directory_observations,
            post_mutation_directory_observations,
            distinct_cross_owner_directories,
            analyzer_cross_owner_observations,
            analyzer_exact_path_observations,
            analyzer_pre_mutation_observations,
            analyzer_post_mutation_observations,
            distinct_analyzer_cross_owner_paths,
            analyzer_generated_file_observations,
            analyzer_pre_final_value_match_observations,
            analyzer_post_final_generated_file_observations,
            distinct_analyzer_generated_files,
            analyzer_pre_producer_mutation_observations,
            analyzer_directory_observations,
            distinct_analyzer_directories,
            analyzer_undeclared_output_observations,
            analyzer_final_value_mismatch_observations,
            directory_epoch_observations,
            analyzer_directory_epoch_observations,
            action_directory_epoch_observations,
            pre_effect_directory_epoch_observations,
            intermediate_directory_epoch_observations,
            post_effect_directory_epoch_observations,
            self_effect_directory_epoch_observations,
            distinct_directory_epoch_paths,
            unresolved_exact_observations,
            analyzer_produced_observations,
            undeclared_output_observations,
            pre_final_mutation_observations,
            final_value_mismatch_observations,
            distinct_unresolved_exact_inputs,
            edges,
        },
        action_inputs,
        analyzer_inputs,
        analyzer_directory_checkpoints: analyzer_directory_checkpoints.checkpoints,
        directory_members: directory_members.members,
        directory_anchors: retained_directory_anchors,
        directory_checkpoints: generated_directory_checkpoints.checkpoints,
    })
}

#[cfg(unix)]
fn kbuild_validate_mandatory_directory_checkpoint(
    checkpoint: &KbuildGeneratedDirectoryCheckpoint,
    observation: &KbuildInputObservation,
    members: &[Vec<u8>],
    anchor: &KbuildDirectoryPathAnchor,
    output_root: &Path,
    action_count: u64,
) -> Result<()> {
    let KbuildProcessOwner::Action(action_index) = observation.owner else {
        anyhow::bail!("Kbuild mandatory directory checkpoint has no action owner");
    };
    let relative = observation
        .path
        .strip_prefix(output_root)
        .context("Kbuild mandatory directory checkpoint escaped its output root")?;
    let rooted_path = ExternalPathKey {
        root: "obj".to_string(),
        path: os_bytes(relative.as_os_str()),
    };
    if checkpoint.consumer_action_index != action_index
        || checkpoint.observation_ordinal != observation.ordinal
        || checkpoint.path != rooted_path
        || checkpoint.object != observation.object
        || checkpoint.value != observation.value
        || checkpoint.members != members
        || checkpoint.anchor != *anchor
        || checkpoint.object.kind != KbuildInputObjectKind::Directory
        || !matches!(checkpoint.value, KbuildObservedInputValue::Directory { .. })
        || checkpoint.members.windows(2).any(|pair| pair[0] >= pair[1])
    {
        anyhow::bail!("Kbuild mandatory directory checkpoint changed its exact value");
    }
    if !checkpoint.unresolved_actions.is_empty()
        || !checkpoint
            .before_actions
            .is_disjoint(&checkpoint.after_actions)
        || checkpoint.has_unresolved_self_effect
        || checkpoint.has_unresolved_analyzer_effect
        || checkpoint.has_self_directory_object_effect
        || checkpoint.has_analyzer_directory_object_effect
        || checkpoint.has_analyzer_retained_name_effect
    {
        let first_unresolved_self_member_presence = checkpoint
            .first_unresolved_self_batch
            .as_ref()
            .map(|batch| {
                batch
                    .effects
                    .iter()
                    .map(|effect| match &effect.subject {
                        KbuildDirectoryEffectSubject::DirectoryObject => None,
                        KbuildDirectoryEffectSubject::Member(member) => {
                            Some((member.clone(), members.binary_search(member).is_ok()))
                        }
                    })
                    .collect::<Vec<_>>()
            });
        anyhow::bail!(
            "Kbuild mandatory directory checkpoint {:?} for action {} is not causally \
             enforceable: before={:?}, after={:?}, unresolved={:?}, self_effect={}, \
             analyzer_effect={}, unresolved_self={}, unresolved_analyzer={}, \
             self_object={}, analyzer_object={}, analyzer_retained_name={}, \
             observation=(process {}, syscall {:?}, stream {}), \
             first_unresolved_self={:?}, first_unresolved_self_member_presence={:?}, \
             first_unresolved_self_subject_batches={}/{:?}, \
             observation_process_chain={:?}, \
             first_self_directory_object={:?}, \
             first_unresolved_self_branch={:?}, \
             first_unresolved_analyzer={:?}",
            checkpoint.path.path,
            checkpoint.consumer_action_index,
            checkpoint.before_actions,
            checkpoint.after_actions,
            checkpoint.unresolved_actions,
            checkpoint.has_self_effect,
            checkpoint.has_analyzer_effect,
            checkpoint.has_unresolved_self_effect,
            checkpoint.has_unresolved_analyzer_effect,
            checkpoint.has_self_directory_object_effect,
            checkpoint.has_analyzer_directory_object_effect,
            checkpoint.has_analyzer_retained_name_effect,
            observation.process,
            observation.syscall_index,
            observation.stream_ordinal,
            checkpoint.first_unresolved_self_batch,
            first_unresolved_self_member_presence,
            checkpoint.first_unresolved_self_subject_batch_count,
            checkpoint.first_unresolved_self_subject_timeline,
            checkpoint.observation_process_chain,
            checkpoint.first_self_directory_object_batch,
            checkpoint.first_unresolved_self_branch,
            checkpoint.first_unresolved_analyzer_batch,
        );
    }
    if checkpoint
        .before_actions
        .iter()
        .chain(&checkpoint.after_actions)
        .any(|owner| *owner >= action_count || *owner == action_index)
    {
        anyhow::bail!("Kbuild mandatory directory checkpoint has an invalid action relation");
    }
    let expected_candidate = !checkpoint.has_self_effect
        && !checkpoint.has_analyzer_effect
        && checkpoint.unresolved_actions.is_empty()
        && checkpoint
            .before_actions
            .is_disjoint(&checkpoint.after_actions);
    if checkpoint.candidate_action_boundary != expected_candidate {
        anyhow::bail!("Kbuild mandatory directory checkpoint changed its classification");
    }
    Ok(())
}

#[cfg(unix)]
fn update_kbuild_mandatory_directory_checkpoint(
    hasher: &mut blake3::Hasher,
    checkpoint: &KbuildGeneratedDirectoryCheckpoint,
) -> Result<()> {
    hasher.update(&checkpoint.observation_ordinal.to_le_bytes());
    update_kbuild_external_input_path(hasher, &checkpoint.path)?;
    hasher.update(&checkpoint.object.device.to_le_bytes());
    hasher.update(&checkpoint.object.inode.to_le_bytes());
    hasher.update(
        &checkpoint
            .object
            .mount_id
            .context("Kbuild mandatory directory checkpoint has no mount identity")?
            .to_le_bytes(),
    );
    let KbuildObservedInputValue::Directory {
        entries,
        digest,
        listing_digest,
    } = checkpoint.value
    else {
        anyhow::bail!("Kbuild mandatory directory checkpoint is not a directory");
    };
    hasher.update(&entries.to_le_bytes());
    hasher.update(&digest);
    hasher.update(&listing_digest);
    hasher.update(
        &u64::try_from(checkpoint.members.len())
            .context("Kbuild mandatory directory member count does not fit u64")?
            .to_le_bytes(),
    );
    for member in &checkpoint.members {
        hash_kbuild_bytes(hasher, member)?;
    }
    hasher.update(&checkpoint.anchor.process.to_le_bytes());
    hasher.update(&checkpoint.anchor.descriptor.to_le_bytes());
    hash_kbuild_bytes(hasher, &os_bytes(checkpoint.anchor.path.as_os_str()))?;
    hasher.update(&checkpoint.anchor.object.device.to_le_bytes());
    hasher.update(&checkpoint.anchor.object.inode.to_le_bytes());
    hasher.update(
        &checkpoint
            .anchor
            .object
            .mount_id
            .context("Kbuild mandatory directory anchor has no mount identity")?
            .to_le_bytes(),
    );
    hasher.update(&checkpoint.anchor.open_syscall_index.to_le_bytes());
    hasher.update(&checkpoint.anchor.open_stream_ordinal.to_le_bytes());
    for actions in [&checkpoint.before_actions, &checkpoint.after_actions] {
        hasher.update(
            &u64::try_from(actions.len())
                .context("Kbuild mandatory directory relation count does not fit u64")?
                .to_le_bytes(),
        );
        for action_index in actions {
            hasher.update(&action_index.to_le_bytes());
        }
    }
    hasher.update(&[
        u8::from(checkpoint.has_self_effect),
        u8::from(checkpoint.has_analyzer_effect),
        u8::from(checkpoint.has_self_retained_name_effect_before_observation),
        u8::from(checkpoint.has_self_retained_name_effect_after_observation),
        u8::from(checkpoint.candidate_action_boundary),
    ]);
    Ok(())
}

#[cfg(unix)]
fn kbuild_mandatory_action_eligibility(
    procfs: &KbuildProcfsMandatoryExecutionSeal,
    ownership_actions: &[KbuildActionOwnershipCensus],
    input_census: &KbuildInputValueCensusSeal,
    provenance: &KbuildInputProvenancePartitionSeal,
    generated: &KbuildGeneratedInputProvenance,
    procfs_directories: &KbuildProcfsDirectoryCensus,
    final_outputs: &KbuildFinalOutputValueSeal,
    observations: &[KbuildInputObservation],
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    declared_output_order: &BTreeMap<u64, Vec<PathBuf>>,
    source_root: &Path,
    output_root: &Path,
    managed_seed: Option<&KbuildManagedCaptureSeed>,
) -> Result<KbuildMandatoryActionEligibilityContracts> {
    if procfs.graph_digest != input_census.graph_digest
        || procfs.stream_digest != input_census.stream_digest
        || procfs.assignment_digest != input_census.assignment_digest
        || provenance.graph_digest != input_census.graph_digest
        || provenance.stream_digest != input_census.stream_digest
        || provenance.assignment_digest != input_census.assignment_digest
        || provenance.input_census_digest != input_census.census_digest
        || generated.graph_digest != input_census.graph_digest
        || generated.stream_digest != input_census.stream_digest
        || generated.assignment_digest != input_census.assignment_digest
        || generated.input_census_digest != input_census.census_digest
        || generated.provenance_partition_digest != provenance.partition_digest
        || generated.mutation_attribution_digest != provenance.mutation_attribution_digest
        || procfs_directories.seal.graph_digest != input_census.graph_digest
        || procfs_directories.seal.stream_digest != input_census.stream_digest
        || procfs_directories.seal.assignment_digest != input_census.assignment_digest
        || procfs_directories.seal.input_census_digest != input_census.census_digest
        || procfs.directory_census_digest != procfs_directories.seal.census_digest
        || final_outputs.graph_digest != input_census.graph_digest
        || final_outputs.stream_digest != input_census.stream_digest
        || final_outputs.assignment_digest != input_census.assignment_digest
        || final_outputs.mutation_attribution_digest != provenance.mutation_attribution_digest
        || generated.final_output_value_digest != final_outputs.value_digest
    {
        anyhow::bail!("Kbuild mandatory-action eligibility has inconsistent identity");
    }
    require_kbuild_procfs_directory_census(procfs_directories)?;
    let action_count = u64::try_from(generated.action_inputs.len())
        .context("Kbuild mandatory-action count does not fit u64")?;
    if declared_output_order.len() != generated.action_inputs.len() {
        anyhow::bail!("Kbuild mandatory-action eligibility has incomplete action declarations");
    }
    if ownership_actions.len() != generated.action_inputs.len()
        || ownership_actions
            .iter()
            .enumerate()
            .any(|(position, action)| {
                action.action_index != u64::try_from(position).unwrap_or(u64::MAX)
            })
    {
        anyhow::bail!("Kbuild mandatory-action eligibility has incomplete ownership context");
    }
    if u64::try_from(observations.len())
        .context("Kbuild mandatory-action observation count does not fit u64")?
        != input_census.observations
    {
        anyhow::bail!("Kbuild mandatory-action eligibility changed the input denominator");
    }
    for (position, action_index) in declared_output_order.keys().copied().enumerate() {
        if action_index
            != u64::try_from(position)
                .context("Kbuild mandatory-action position does not fit u64")?
        {
            anyhow::bail!("Kbuild mandatory-action declarations are not contiguous");
        }
    }
    if !output_root.is_absolute() || output_root == Path::new("/") {
        anyhow::bail!("Kbuild mandatory-action writable root is not confined");
    }

    let mutation_index = KbuildInputMutationIndex::from_events(mutation_events)?;
    let mut policy_actions = BTreeSet::new();
    let mut previous_policy_action = None;
    let mut policy_read_observations = 0_u64;
    let mut policy_directory_observations = 0_u64;
    let mut policy_directory_openings = 0_u64;
    let mut contracts = Vec::with_capacity(procfs.actions.len());
    let mut action_seals = Vec::with_capacity(procfs.actions.len());
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-mandatory-action-eligibility.v4\0");
    hasher.update(&procfs.graph_digest);
    hasher.update(&procfs.stream_digest);
    hasher.update(&procfs.assignment_digest);
    hasher.update(&procfs.policy_digest);
    hasher.update(&input_census.census_digest);
    hasher.update(&provenance.partition_digest);
    hasher.update(&provenance.mutation_attribution_digest);
    hasher.update(&generated.generated_action_input_digest);
    hasher.update(&procfs_directories.seal.census_digest);
    hasher.update(&generated.directory_member_retention.retention_digest);
    hasher.update(&generated.generated_directory_checkpoints.checkpoint_digest);
    update_kbuild_external_input_path(
        &mut hasher,
        &ExternalPathKey {
            root: "obj".to_string(),
            path: Vec::new(),
        },
    )?;
    let mandatory_actions = u64::try_from(procfs.actions.len())
        .context("Kbuild mandatory-action policy count does not fit u64")?;
    hasher.update(&action_count.to_le_bytes());
    hasher.update(&mandatory_actions.to_le_bytes());

    for policy in &procfs.actions {
        let action_index = policy.action_index;
        if action_index >= action_count
            || previous_policy_action.is_some_and(|previous| previous >= action_index)
            || !policy_actions.insert(action_index)
        {
            anyhow::bail!("Kbuild mandatory-action policy repeats an invalid action");
        }
        previous_policy_action = Some(action_index);
        let total_observations = policy
            .read_observations
            .checked_add(policy.directory_observations)
            .context("Kbuild mandatory-action evidence count overflowed")?;
        let expected_directory_observations = policy
            .directory_openings
            .checked_mul(2)
            .context("Kbuild mandatory-action directory evidence count overflowed")?;
        if total_observations == 0
            || policy.executable_identities == 0
            || (policy.read_observations == 0) != policy.classes.is_empty()
            || (policy.directory_observations == 0) != policy.directory_classes.is_empty()
            || policy.directory_observations != expected_directory_observations
        {
            anyhow::bail!("Kbuild mandatory-action policy has empty evidence");
        }
        policy_read_observations = policy_read_observations
            .checked_add(policy.read_observations)
            .context("Kbuild mandatory-action procfs count overflowed")?;
        policy_directory_observations = policy_directory_observations
            .checked_add(policy.directory_observations)
            .context("Kbuild mandatory-action procfs directory count overflowed")?;
        policy_directory_openings = policy_directory_openings
            .checked_add(policy.directory_openings)
            .context("Kbuild mandatory-action procfs directory opening count overflowed")?;
        let action_position = usize::try_from(action_index)
            .context("Kbuild mandatory-action index does not fit usize")?;
        let owned = ownership_actions
            .get(action_position)
            .context("Kbuild mandatory action has no execution context")?;
        let generated_inputs = generated
            .action_inputs
            .get(action_position)
            .context("Kbuild mandatory action has no generated-input partition")?
            .clone();
        let mut external_inputs = BTreeMap::new();
        let mut procfs_directory_checkpoints = Vec::new();
        let mut procfs_directory_ordinals = BTreeSet::new();
        let mut procfs_directory_openings = BTreeSet::new();
        let mut external_input_observations = 0_u64;
        let mut generated_input_observations = 0_u64;
        let mut observed_generated_inputs = BTreeSet::new();
        let mut directory_checkpoints = Vec::new();
        let mut observed_directory_ordinals = BTreeSet::new();
        let mut directory_checkpoint_paths = BTreeSet::new();
        let mut same_owner_post_candidate_observations = 0_u64;
        for observation in observations
            .iter()
            .filter(|observation| observation.owner == KbuildProcessOwner::Action(action_index))
        {
            if let Some(checkpoint) = procfs_directories.checkpoints.get(&observation.ordinal) {
                if checkpoint.observation != *observation
                    || !procfs_directory_ordinals.insert(observation.ordinal)
                {
                    anyhow::bail!("Kbuild mandatory procfs directory checkpoint changed");
                }
                procfs_directory_openings
                    .insert((observation.process, checkpoint.anchor.open_stream_ordinal));
                procfs_directory_checkpoints.push(checkpoint.clone());
                continue;
            }
            let provenance_class = mutation_index.classify(observation);
            match provenance_class {
                KbuildInputProvenanceClass::ExternalSeed => {
                    external_input_observations = external_input_observations
                        .checked_add(1)
                        .context("Kbuild mandatory external-input count overflowed")?;
                    let path = root_path(&observation.path, source_root, output_root)?;
                    let retained = KbuildExternalInputReference {
                        absolute_path: observation.path.clone(),
                        value: observation.value,
                    };
                    match external_inputs.entry(path) {
                        std::collections::btree_map::Entry::Vacant(entry) => {
                            entry.insert(retained);
                        }
                        std::collections::btree_map::Entry::Occupied(entry)
                            if entry.get() != &retained =>
                        {
                            anyhow::bail!(
                                "Kbuild mandatory action observed inconsistent external inputs"
                            );
                        }
                        std::collections::btree_map::Entry::Occupied(_) => {}
                    }
                }
                KbuildInputProvenanceClass::CrossOwnerMutation => {
                    if matches!(
                        observation.value,
                        KbuildObservedInputValue::Directory { .. }
                    ) {
                        let members = generated.directory_members.get(&observation.ordinal);
                        let anchor = generated.directory_anchors.get(&observation.ordinal);
                        let checkpoint =
                            generated.directory_checkpoints.iter().find(|checkpoint| {
                                checkpoint.consumer_action_index == action_index
                                    && checkpoint.observation_ordinal == observation.ordinal
                            });
                        let (Some(members), Some(anchor), Some(checkpoint)) =
                            (members, anchor, checkpoint)
                        else {
                            anyhow::bail!(
                                "Kbuild mandatory directory input lost its retained contract"
                            );
                        };
                        kbuild_validate_mandatory_directory_checkpoint(
                            checkpoint,
                            observation,
                            members,
                            anchor,
                            output_root,
                            action_count,
                        )?;
                        if !observed_directory_ordinals.insert(observation.ordinal) {
                            anyhow::bail!(
                                "Kbuild mandatory directory input repeats an observation"
                            );
                        }
                        directory_checkpoint_paths.insert(checkpoint.path.clone());
                        directory_checkpoints.push(checkpoint.clone());
                        continue;
                    }
                    let mount_id = observation
                        .object
                        .mount_id
                        .context("Kbuild mandatory generated input has no mount identity")?;
                    let path = root_path(&observation.path, source_root, output_root)?;
                    let value = kbuild_external_input_value(observation.value);
                    let object = KbuildOutputObjectIdentity {
                        device: observation.object.device,
                        inode: observation.object.inode,
                        mount_id,
                    };
                    if !generated_inputs.iter().any(|input| {
                        input.consumer_action_index == action_index
                            && input.path == path
                            && input.value == value
                            && input.object == object
                    }) {
                        anyhow::bail!("Kbuild mandatory action has an unproved cross-owner input");
                    }
                    observed_generated_inputs.insert(path);
                    generated_input_observations = generated_input_observations
                        .checked_add(1)
                        .context("Kbuild mandatory generated-input count overflowed")?;
                }
                KbuildInputProvenanceClass::SameOwnerPostCandidate => {
                    same_owner_post_candidate_observations = same_owner_post_candidate_observations
                        .checked_add(1)
                        .context("Kbuild mandatory self-input count overflowed")?;
                }
                KbuildInputProvenanceClass::SameOwnerPreMutation => {
                    let (path, retained) = managed_seed
                        .map(|seed| seed.input_reference(observation, source_root, output_root))
                        .transpose()?
                        .flatten()
                        .context("Kbuild mandatory action has an unseeded pre-mutation input")?;
                    match external_inputs.entry(path) {
                        std::collections::btree_map::Entry::Vacant(entry) => {
                            entry.insert(retained);
                        }
                        std::collections::btree_map::Entry::Occupied(entry)
                            if entry.get() != &retained =>
                        {
                            anyhow::bail!("Kbuild mandatory action has inconsistent seed input");
                        }
                        std::collections::btree_map::Entry::Occupied(_) => {}
                    }
                }
                KbuildInputProvenanceClass::AnalyzerBootstrapDirectory
                | KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => {
                    anyhow::bail!(
                        "Kbuild mandatory action has an unsupported captured input: action={} class={:?} path={}",
                        action_index,
                        provenance_class,
                        observation.path.display(),
                    );
                }
            }
        }
        let retained_procfs_directory_observations = procfs_directories
            .checkpoints
            .values()
            .filter(|checkpoint| {
                checkpoint.observation.owner == KbuildProcessOwner::Action(action_index)
            })
            .count();
        if procfs_directory_ordinals.len() != retained_procfs_directory_observations
            || u64::try_from(procfs_directory_ordinals.len()).ok()
                != Some(policy.directory_observations)
            || u64::try_from(procfs_directory_openings.len()).ok()
                != Some(policy.directory_openings)
        {
            anyhow::bail!("Kbuild mandatory procfs directory ledger changed its observations");
        }
        for input in &generated_inputs {
            if input.consumer_action_index != action_index {
                anyhow::bail!("Kbuild mandatory action retained another consumer's input");
            }
        }
        if observed_generated_inputs.len() != generated_inputs.len() {
            anyhow::bail!("Kbuild mandatory generated-input ledger changed its references");
        }
        let retained_directory_observations = generated
            .directory_checkpoints
            .iter()
            .filter(|checkpoint| checkpoint.consumer_action_index == action_index)
            .count();
        if observed_directory_ordinals.len() != retained_directory_observations {
            anyhow::bail!("Kbuild mandatory directory checkpoint ledger changed its observations");
        }

        let declared = declared_output_order
            .get(&action_index)
            .context("Kbuild mandatory action has no output declaration")?;
        if declared.is_empty() {
            anyhow::bail!("Kbuild mandatory action has no declared persistent output");
        }
        let declared = declared.iter().collect::<BTreeSet<_>>();
        if declared.len()
            != declared_output_order
                .get(&action_index)
                .expect("checked above")
                .len()
        {
            anyhow::bail!("Kbuild mandatory action repeats a declared output");
        }
        let selected_outputs = final_outputs
            .outputs
            .iter()
            .filter(|output| output.action_index == action_index)
            .collect::<Vec<_>>();
        if selected_outputs.len() != declared.len()
            || selected_outputs
                .iter()
                .enumerate()
                .any(|(position, output)| {
                    output.output_index != u64::try_from(position).unwrap_or(u64::MAX)
                })
        {
            anyhow::bail!("Kbuild mandatory action has incomplete final output values");
        }
        let mut mutation_candidate_events = 0_u64;
        let mut mutation_paths = BTreeSet::new();
        for (_, mutation) in mutation_events
            .iter()
            .filter(|(owner, _)| *owner == KbuildProcessOwner::Action(action_index))
        {
            let relative = mutation
                .path
                .strip_prefix(output_root)
                .context("Kbuild mandatory action mutation is outside the writable root")?;
            if relative.as_os_str().is_empty()
                || os_bytes(relative.as_os_str()) != mutation.relative
            {
                anyhow::bail!("Kbuild mandatory action mutation has an invalid rooted path");
            }
            mutation_candidate_events = mutation_candidate_events
                .checked_add(1)
                .context("Kbuild mandatory mutation-event count overflowed")?;
            mutation_paths.insert(&mutation.path);
        }
        if !declared.iter().all(|path| mutation_paths.contains(*path)) {
            anyhow::bail!("Kbuild mandatory action has an unmutated declared output");
        }
        let mutation_candidate_paths = u64::try_from(mutation_paths.len())
            .context("Kbuild mandatory mutation-path count does not fit u64")?;
        let persistent_paths = u64::try_from(declared.len())
            .context("Kbuild mandatory persistent-path count does not fit u64")?;
        let transient_paths = mutation_candidate_paths
            .checked_sub(persistent_paths)
            .context("Kbuild mandatory mutation paths omit declared outputs")?;
        let procfs_directory_observations = u64::try_from(procfs_directory_checkpoints.len())
            .context("Kbuild mandatory procfs directory count does not fit u64")?;
        let procfs_directory_opening_count = u64::try_from(procfs_directory_openings.len())
            .context("Kbuild mandatory procfs directory opening count does not fit u64")?;
        let external_input_references = u64::try_from(external_inputs.len())
            .context("Kbuild mandatory external-input reference count does not fit u64")?;
        let generated_input_references = u64::try_from(generated_inputs.len())
            .context("Kbuild mandatory generated-input reference count does not fit u64")?;
        let directory_checkpoint_observations = u64::try_from(directory_checkpoints.len())
            .context("Kbuild mandatory directory checkpoint count does not fit u64")?;
        let directory_checkpoint_references = u64::try_from(directory_checkpoint_paths.len())
            .context("Kbuild mandatory directory reference count does not fit u64")?;
        let isolation = rush_exec::local_isolation::LocalExecutionIsolation::new(vec![
            output_root.to_path_buf(),
        ])?;
        isolation
            .validate_credentials(owned.credentials())
            .context("Kbuild mandatory action credentials are not isolatable")?;
        let procfs_filesystems_reads = policy.filesystems_reads.clone();
        let cache_policy = if kbuild_procfs_policy_cacheable(policy, procfs.stream_digest)? {
            crate::action_manager::ActionCachePolicy::CACHEABLE
        } else {
            crate::action_manager::ActionCachePolicy::ALWAYS_RUN
        };
        if !cache_policy.store
            || cache_policy.durable
            || isolation.writable_roots() != [output_root]
            || isolation.descriptor_topology()
                != rush_exec::local_isolation::LocalDescriptorTopology::StandardOnlyV1
        {
            anyhow::bail!("Kbuild mandatory action has an invalid execution policy");
        }

        for count in [
            action_index,
            procfs_directory_observations,
            procfs_directory_opening_count,
            external_input_observations,
            external_input_references,
            generated_input_observations,
            generated_input_references,
            directory_checkpoint_observations,
            directory_checkpoint_references,
            same_owner_post_candidate_observations,
            mutation_candidate_events,
            mutation_candidate_paths,
            persistent_paths,
            transient_paths,
        ] {
            hasher.update(&count.to_le_bytes());
        }
        hasher.update(&owned.signal_state.blocked.to_le_bytes());
        hasher.update(&owned.signal_state.ignored.to_le_bytes());
        hasher.update(&owned.file_creation_mask.to_le_bytes());
        let credential_bytes = bincode::serialize(owned.credentials())
            .context("serialize Kbuild mandatory-action credentials")?;
        hash_kbuild_bytes(&mut hasher, &credential_bytes)?;
        for checkpoint in &procfs_directory_checkpoints {
            update_kbuild_procfs_directory_checkpoint(&mut hasher, checkpoint)?;
        }
        for (path, input) in &external_inputs {
            update_kbuild_external_input_path(&mut hasher, path)?;
            update_kbuild_external_input_value(&mut hasher, input.value);
        }
        for input in &generated_inputs {
            hasher.update(&input.producer_action_index.to_le_bytes());
            hasher.update(&input.producer_output_index.to_le_bytes());
            update_kbuild_external_input_path(&mut hasher, &input.path)?;
            let ExternalInputValue::File { digest, executable } = &input.value else {
                anyhow::bail!("Kbuild mandatory generated input is not a regular file");
            };
            hasher.update(&[0, u8::from(*executable)]);
            hasher.update(digest);
            hasher.update(&input.object.device.to_le_bytes());
            hasher.update(&input.object.inode.to_le_bytes());
            hasher.update(&input.object.mount_id.to_le_bytes());
        }
        for checkpoint in &directory_checkpoints {
            update_kbuild_mandatory_directory_checkpoint(&mut hasher, checkpoint)?;
        }
        for path in &mutation_paths {
            let relative = path
                .strip_prefix(output_root)
                .context("Kbuild mandatory mutation digest path escaped its root")?;
            hash_kbuild_bytes(&mut hasher, &os_bytes(relative.as_os_str()))?;
            hasher.update(&[u8::from(declared.contains(path))]);
        }
        action_seals.push(KbuildMandatoryActionEligibility {
            action_index,
            procfs_directory_observations,
            procfs_directory_openings: procfs_directory_opening_count,
            external_input_observations,
            external_input_references,
            generated_input_observations,
            generated_input_references,
            directory_checkpoint_observations,
            directory_checkpoint_references,
            same_owner_post_candidate_observations,
            mutation_candidate_events,
            mutation_candidate_paths,
            persistent_paths,
            transient_paths,
        });
        contracts.push(KbuildMandatoryActionExecutionContract {
            action_index,
            procfs_filesystems_reads,
            procfs_directory_checkpoints,
            external_inputs,
            generated_inputs,
            directory_checkpoints,
            cache_policy,
            isolation,
        });
    }
    if policy_read_observations != procfs.read_observations {
        anyhow::bail!("Kbuild mandatory-action policy changed its read denominator");
    }
    if policy_directory_observations != procfs.directory_observations
        || policy_directory_openings != procfs.directory_openings
    {
        anyhow::bail!("Kbuild mandatory-action policy changed its directory denominator");
    }

    Ok(KbuildMandatoryActionEligibilityContracts {
        seal: KbuildMandatoryActionEligibilitySeal {
            graph_digest: procfs.graph_digest,
            stream_digest: procfs.stream_digest,
            assignment_digest: procfs.assignment_digest,
            procfs_policy_digest: procfs.policy_digest,
            input_census_digest: input_census.census_digest,
            provenance_partition_digest: provenance.partition_digest,
            mutation_attribution_digest: provenance.mutation_attribution_digest,
            generated_action_input_digest: generated.generated_action_input_digest,
            directory_member_retention_digest: generated
                .directory_member_retention
                .retention_digest,
            generated_directory_checkpoint_digest: generated
                .generated_directory_checkpoints
                .checkpoint_digest,
            eligibility_digest: *hasher.finalize().as_bytes(),
            actions: action_seals,
        },
        actions: contracts,
    })
}

#[cfg(unix)]
fn update_kbuild_external_input_value(
    hasher: &mut blake3::Hasher,
    value: KbuildObservedInputValue,
) {
    match value {
        KbuildObservedInputValue::WholeFile { digest, mode, .. } => {
            hasher.update(&[0, u8::from(mode & 0o111 != 0)]);
            hasher.update(&digest);
        }
        KbuildObservedInputValue::Directory { listing_digest, .. } => {
            hasher.update(&[1]);
            hasher.update(&listing_digest);
        }
    }
}

#[cfg(unix)]
fn update_kbuild_external_input_path(
    hasher: &mut blake3::Hasher,
    path: &ExternalPathKey,
) -> Result<()> {
    let root_bytes = u64::try_from(path.root.len())
        .context("Kbuild external-input root length does not fit u64")?;
    let path_bytes = u64::try_from(path.path.len())
        .context("Kbuild external-input path length does not fit u64")?;
    hasher.update(&root_bytes.to_le_bytes());
    hasher.update(path.root.as_bytes());
    hasher.update(&path_bytes.to_le_bytes());
    hasher.update(&path.path);
    Ok(())
}

#[cfg(unix)]
fn kbuild_external_input_manifest_seal(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    input_census: &KbuildInputValueCensusSeal,
    provenance: &KbuildInputProvenancePartitionSeal,
    generated: Option<&KbuildGeneratedInputProvenance>,
    procfs_directories: &KbuildProcfsDirectoryCensus,
    observations: &[KbuildInputObservation],
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    source_root: &Path,
    output_root: &Path,
    action_count: u64,
    managed_seed: Option<&KbuildManagedCaptureSeed>,
) -> Result<(
    KbuildExternalInputManifestSeal,
    KbuildExternalInputReferences,
)> {
    if input_census.graph_digest != graph_digest
        || input_census.stream_digest != stream_digest
        || input_census.assignment_digest != assignment_digest
        || provenance.graph_digest != graph_digest
        || provenance.stream_digest != stream_digest
        || provenance.assignment_digest != assignment_digest
        || provenance.input_census_digest != input_census.census_digest
        || procfs_directories.seal.graph_digest != graph_digest
        || procfs_directories.seal.stream_digest != stream_digest
        || procfs_directories.seal.assignment_digest != assignment_digest
        || procfs_directories.seal.input_census_digest != input_census.census_digest
        || generated.is_some_and(|generated| {
            generated.seal.graph_digest != graph_digest
                || generated.seal.stream_digest != stream_digest
                || generated.seal.assignment_digest != assignment_digest
                || generated.seal.input_census_digest != input_census.census_digest
                || generated.seal.provenance_partition_digest != provenance.partition_digest
        })
    {
        anyhow::bail!("Kbuild external-input manifests have inconsistent identity");
    }
    require_kbuild_procfs_directory_census(procfs_directories)?;
    if let Some(generated) = generated {
        let action_digest = kbuild_generated_action_input_digest(
            graph_digest,
            stream_digest,
            assignment_digest,
            generated.seal.input_census_digest,
            generated.seal.provenance_partition_digest,
            generated.seal.mutation_attribution_digest,
            generated.seal.final_output_value_digest,
            &generated.action_inputs,
        )?;
        let analyzer_digest = kbuild_analyzer_generated_input_digest(
            graph_digest,
            stream_digest,
            assignment_digest,
            generated.seal.input_census_digest,
            generated.seal.provenance_partition_digest,
            generated.seal.mutation_attribution_digest,
            generated.seal.final_output_value_digest,
            action_count,
            &generated.analyzer_inputs,
        )?;
        let analyzer_directory_digest = kbuild_analyzer_directory_checkpoint_digest(
            graph_digest,
            stream_digest,
            assignment_digest,
            generated.seal.input_census_digest,
            generated.seal.provenance_partition_digest,
            generated.seal.mutation_attribution_digest,
            generated.seal.final_output_value_digest,
            generated.seal.directory_member_retention.retention_digest,
            generated.seal.directory_causal_census.causal_digest,
            &generated.analyzer_directory_checkpoints,
        )?;
        if action_digest != generated.seal.generated_action_input_digest
            || analyzer_digest != generated.seal.analyzer_generated_input_digest
            || analyzer_directory_digest
                != generated
                    .seal
                    .analyzer_directory_checkpoints
                    .checkpoint_digest
        {
            anyhow::bail!("Kbuild external-input generated ledgers changed after proof");
        }
    }
    if (provenance.same_owner_pre_mutation_observations != 0 && managed_seed.is_none())
        || provenance.unclassified_observations != 0
        || generated.is_some_and(|generated| generated.seal.unresolved_exact_observations != 0)
    {
        anyhow::bail!(
            "Kbuild external-input manifests have unsupported provenance: \
             same-owner pre-mutation {}, unresolved generated inputs {}, unclassified {}",
            provenance.same_owner_pre_mutation_observations,
            generated.map_or(0, |generated| generated.seal.unresolved_exact_observations),
            provenance.unclassified_observations,
        );
    }
    if let Some(generated) = generated {
        if generated.seal.analyzer_pre_producer_mutation_observations != 0
            || generated.seal.analyzer_undeclared_output_observations != 0
            || generated.seal.analyzer_final_value_mismatch_observations != 0
        {
            anyhow::bail!(
                "Kbuild external-input manifests have unsupported analyzer provenance: \
                 pre-producer {}, undeclared {}, final-value mismatch {}",
                generated.seal.analyzer_pre_producer_mutation_observations,
                generated.seal.analyzer_undeclared_output_observations,
                generated.seal.analyzer_final_value_mismatch_observations,
            );
        }
    }

    let mutation_index = KbuildInputMutationIndex::from_events(mutation_events)?;
    let mut manifests = KbuildExternalInputReferences::new();
    manifests.insert(KbuildProcessOwner::Analyzer, BTreeMap::new());
    for action_index in 0..action_count {
        manifests.insert(KbuildProcessOwner::Action(action_index), BTreeMap::new());
    }
    let mut external_observations = 0_u64;
    let mut analyzer_external_observations = 0_u64;
    let mut action_external_observations = 0_u64;
    let mut withheld_observations = 0_u64;
    let mut withheld_analyzer_bootstrap_directories = 0_u64;
    let mut withheld_analyzer_post_candidate_directories = 0_u64;
    let mut generated_action_observations = 0_u64;
    let mut generated_directory_observations = 0_u64;
    let mut analyzer_generated_file_observations = 0_u64;
    let mut analyzer_generated_directory_observations = 0_u64;
    let mut analyzer_directory_checkpoint_observations = 0_u64;
    let mut analyzer_directory_bootstrap_observations = 0_u64;
    let mut analyzer_directory_post_candidate_observations = 0_u64;
    let mut analyzer_exact_directory_observations = 0_u64;
    let mut analyzer_directory_external_seed_observations = 0_u64;
    let mut analyzer_directory_same_owner_pre_mutation_observations = 0_u64;
    let mut analyzer_directory_same_owner_post_candidate_observations = 0_u64;
    let mut managed_seed_observations = 0_u64;
    let mut procfs_directory_observations = 0_u64;
    let mut procfs_directory_analyzer_observations = 0_u64;
    let mut procfs_directory_action_observations = 0_u64;
    let mut withheld_procfs_paths = BTreeSet::new();
    let mut withheld_analyzer_external_seed_paths = BTreeSet::new();
    for observation in observations {
        if let Some(checkpoint) = procfs_directories.checkpoints.get(&observation.ordinal) {
            if checkpoint.observation != *observation
                || checkpoint.anchor.process != observation.process
                || checkpoint.anchor.path != observation.path
                || checkpoint.anchor.object != observation.object
                || checkpoint.attempt.syscall_index != observation.syscall_index.unwrap_or(u64::MAX)
                || !matches!(
                    mutation_index.classify(observation),
                    KbuildInputProvenanceClass::ExternalSeed
                )
            {
                anyhow::bail!("Kbuild procfs directory checkpoint changed after proof");
            }
            if !manifests.contains_key(&observation.owner) {
                anyhow::bail!("Kbuild procfs directory checkpoint has an unknown owner");
            }
            let rooted = root_path(&observation.path, source_root, output_root)?;
            if rooted.root != "host" {
                anyhow::bail!("Kbuild procfs directory checkpoint is not host-rooted");
            }
            withheld_procfs_paths.insert(rooted);
            procfs_directory_observations = procfs_directory_observations
                .checked_add(1)
                .context("Kbuild procfs directory observation count overflowed")?;
            match observation.owner {
                KbuildProcessOwner::Analyzer => {
                    procfs_directory_analyzer_observations = procfs_directory_analyzer_observations
                        .checked_add(1)
                        .context("Kbuild analyzer procfs directory count overflowed")?;
                }
                KbuildProcessOwner::Action(_) => {
                    procfs_directory_action_observations = procfs_directory_action_observations
                        .checked_add(1)
                        .context("Kbuild action procfs directory count overflowed")?;
                }
            }
            continue;
        }
        if generated.is_some()
            && observation.owner == KbuildProcessOwner::Analyzer
            && matches!(
                observation.value,
                KbuildObservedInputValue::Directory { .. }
            )
            && mutation_index
                .directory_epoch_events
                .contains_key(&observation.path)
        {
            let generated =
                generated.context("Kbuild analyzer directory has no retained checkpoint proof")?;
            let checkpoint = generated
                .analyzer_directory_checkpoints
                .iter()
                .find(|checkpoint| checkpoint.observation_ordinal == observation.ordinal)
                .context("Kbuild analyzer directory observation has no retained checkpoint")?;
            let relative = observation
                .path
                .strip_prefix(output_root)
                .context("Kbuild analyzer directory checkpoint is outside the output root")?;
            let rooted = ExternalPathKey {
                root: "obj".to_string(),
                path: os_bytes(relative.as_os_str()),
            };
            let expected_provenance = match mutation_index.classify(observation) {
                KbuildInputProvenanceClass::AnalyzerBootstrapDirectory => {
                    analyzer_directory_bootstrap_observations =
                        analyzer_directory_bootstrap_observations
                            .checked_add(1)
                            .context("Kbuild analyzer directory bootstrap count overflowed")?;
                    KbuildAnalyzerDirectoryProvenance::Bootstrap
                }
                KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => {
                    analyzer_directory_post_candidate_observations =
                        analyzer_directory_post_candidate_observations
                            .checked_add(1)
                            .context("Kbuild analyzer directory post-candidate count overflowed")?;
                    KbuildAnalyzerDirectoryProvenance::PostCandidate
                }
                KbuildInputProvenanceClass::CrossOwnerMutation => {
                    analyzer_exact_directory_observations = analyzer_exact_directory_observations
                        .checked_add(1)
                        .context("Kbuild analyzer exact directory count overflowed")?;
                    KbuildAnalyzerDirectoryProvenance::ExactCrossOwner
                }
                KbuildInputProvenanceClass::ExternalSeed => {
                    analyzer_directory_external_seed_observations =
                        analyzer_directory_external_seed_observations
                            .checked_add(1)
                            .context("Kbuild analyzer external directory count overflowed")?;
                    withheld_analyzer_external_seed_paths.insert(rooted.clone());
                    KbuildAnalyzerDirectoryProvenance::ExternalSeed
                }
                KbuildInputProvenanceClass::SameOwnerPreMutation => {
                    analyzer_directory_same_owner_pre_mutation_observations =
                        analyzer_directory_same_owner_pre_mutation_observations
                            .checked_add(1)
                            .context("Kbuild analyzer same-owner pre-mutation count overflowed")?;
                    KbuildAnalyzerDirectoryProvenance::SameOwnerPreMutation
                }
                KbuildInputProvenanceClass::SameOwnerPostCandidate => {
                    analyzer_directory_same_owner_post_candidate_observations =
                        analyzer_directory_same_owner_post_candidate_observations
                            .checked_add(1)
                            .context(
                                "Kbuild analyzer same-owner post-candidate count overflowed",
                            )?;
                    KbuildAnalyzerDirectoryProvenance::SameOwnerPostCandidate
                }
            };
            if checkpoint.process != observation.process {
                anyhow::bail!("Kbuild analyzer directory process changed after proof");
            }
            if checkpoint.stream_ordinal != observation.stream_ordinal
                || checkpoint.syscall_index != observation.syscall_index.unwrap_or(u64::MAX)
            {
                anyhow::bail!("Kbuild analyzer directory event changed after proof");
            }
            if checkpoint.path != rooted {
                anyhow::bail!("Kbuild analyzer directory path changed after proof");
            }
            if checkpoint.object != observation.object {
                anyhow::bail!("Kbuild analyzer directory object changed after proof");
            }
            if checkpoint.value != observation.value {
                anyhow::bail!("Kbuild analyzer directory value changed after proof");
            }
            if checkpoint.anchor.process != observation.process
                || checkpoint.anchor.path != observation.path
                || checkpoint.anchor.object != observation.object
                || generated.directory_anchors.get(&observation.ordinal) != Some(&checkpoint.anchor)
            {
                anyhow::bail!("Kbuild analyzer directory anchor changed after proof");
            }
            if generated.directory_members.get(&observation.ordinal) != Some(&checkpoint.members) {
                anyhow::bail!("Kbuild analyzer directory members changed after proof");
            }
            if checkpoint.provenance != expected_provenance {
                anyhow::bail!("Kbuild analyzer directory provenance changed after proof");
            }
            analyzer_directory_checkpoint_observations = analyzer_directory_checkpoint_observations
                .checked_add(1)
                .context("Kbuild analyzer directory checkpoint count overflowed")?;
            continue;
        }
        match mutation_index.classify(observation) {
            KbuildInputProvenanceClass::ExternalSeed => {}
            KbuildInputProvenanceClass::AnalyzerBootstrapDirectory => {
                withheld_analyzer_bootstrap_directories = withheld_analyzer_bootstrap_directories
                    .checked_add(1)
                    .context("Kbuild analyzer-bootstrap count overflowed")?;
                continue;
            }
            KbuildInputProvenanceClass::AnalyzerPostCandidateDirectory => {
                withheld_analyzer_post_candidate_directories =
                    withheld_analyzer_post_candidate_directories
                        .checked_add(1)
                        .context("Kbuild analyzer post-candidate count overflowed")?;
                continue;
            }
            KbuildInputProvenanceClass::SameOwnerPostCandidate => {
                withheld_observations = withheld_observations
                    .checked_add(1)
                    .context("Kbuild withheld input observation count overflowed")?;
                continue;
            }
            KbuildInputProvenanceClass::SameOwnerPreMutation => {
                let (path, retained) = managed_seed
                    .map(|seed| seed.input_reference(observation, source_root, output_root))
                    .transpose()?
                    .flatten()
                    .context(
                        "Kbuild external-input manifests have an unseeded pre-mutation input",
                    )?;
                let owner_manifest = manifests
                    .get_mut(&observation.owner)
                    .context("Kbuild managed seed has an unknown action owner")?;
                match owner_manifest.entry(path) {
                    std::collections::btree_map::Entry::Vacant(entry) => {
                        entry.insert(retained);
                    }
                    std::collections::btree_map::Entry::Occupied(entry)
                        if entry.get() != &retained =>
                    {
                        anyhow::bail!("Kbuild managed seed has inconsistent action input");
                    }
                    std::collections::btree_map::Entry::Occupied(_) => {}
                }
                managed_seed_observations = managed_seed_observations
                    .checked_add(1)
                    .context("Kbuild managed seed observation count overflowed")?;
                continue;
            }
            KbuildInputProvenanceClass::CrossOwnerMutation => {
                let generated =
                    generated.context("Kbuild cross-owner input has no generated-input proof")?;
                let KbuildProcessOwner::Action(action_index) = observation.owner else {
                    match observation.value {
                        KbuildObservedInputValue::WholeFile { .. } => {
                            let rooted = root_path(&observation.path, source_root, output_root)?;
                            let retained = generated
                                .analyzer_inputs
                                .iter()
                                .find(|input| input.path == rooted)
                                .context(
                                    "Kbuild analyzer generated-file observation has no retained \
                                     proof",
                                )?;
                            if retained.value != kbuild_external_input_value(observation.value)
                                || retained.object.device != observation.object.device
                                || retained.object.inode != observation.object.inode
                                || Some(retained.object.mount_id) != observation.object.mount_id
                            {
                                anyhow::bail!(
                                    "Kbuild analyzer generated-file observation changed after \
                                     proof"
                                );
                            }
                            analyzer_generated_file_observations =
                                analyzer_generated_file_observations
                                    .checked_add(1)
                                    .context("Kbuild analyzer generated-file count overflowed")?;
                        }
                        KbuildObservedInputValue::Directory { .. } => {
                            analyzer_generated_directory_observations =
                                analyzer_generated_directory_observations
                                    .checked_add(1)
                                    .context(
                                        "Kbuild analyzer generated-directory count overflowed",
                                    )?;
                        }
                    }
                    continue;
                };
                match observation.value {
                    KbuildObservedInputValue::WholeFile { .. } => {
                        let rooted = root_path(&observation.path, source_root, output_root)?;
                        let consumer_action_index = action_index;
                        let action_index = usize::try_from(consumer_action_index)
                            .context("Kbuild generated-input action index does not fit usize")?;
                        let retained = generated
                            .action_inputs
                            .get(action_index)
                            .into_iter()
                            .flatten()
                            .find(|input| input.path == rooted)
                            .context(
                                "Kbuild action generated-file observation has no retained edge",
                            )?;
                        if retained.consumer_action_index != consumer_action_index
                            || retained.value != kbuild_external_input_value(observation.value)
                            || retained.object.device != observation.object.device
                            || retained.object.inode != observation.object.inode
                            || Some(retained.object.mount_id) != observation.object.mount_id
                        {
                            anyhow::bail!(
                                "Kbuild action generated-file observation changed after proof"
                            );
                        }
                        generated_action_observations = generated_action_observations
                            .checked_add(1)
                            .context("Kbuild generated-action observation count overflowed")?;
                    }
                    KbuildObservedInputValue::Directory { .. } => {
                        let relative = observation
                            .path
                            .strip_prefix(output_root)
                            .context("Kbuild generated directory is outside the output root")?;
                        let checkpoint = generated
                            .directory_checkpoints
                            .iter()
                            .find(|checkpoint| {
                                checkpoint.consumer_action_index == action_index
                                    && checkpoint.observation_ordinal == observation.ordinal
                            })
                            .context(
                                "Kbuild action generated-directory observation has no checkpoint",
                            )?;
                        if checkpoint.path.root != "obj"
                            || checkpoint.path.path != os_bytes(relative.as_os_str())
                            || checkpoint.object != observation.object
                            || checkpoint.value != observation.value
                        {
                            anyhow::bail!(
                                "Kbuild action generated-directory observation changed after proof"
                            );
                        }
                        generated_directory_observations = generated_directory_observations
                            .checked_add(1)
                            .context("Kbuild generated-directory observation count overflowed")?;
                    }
                }
                continue;
            }
        }
        external_observations = external_observations
            .checked_add(1)
            .context("Kbuild external-input observation count overflowed")?;
        match observation.owner {
            KbuildProcessOwner::Analyzer => {
                analyzer_external_observations = analyzer_external_observations
                    .checked_add(1)
                    .context("Kbuild analyzer external-input count overflowed")?;
            }
            KbuildProcessOwner::Action(_) => {
                action_external_observations = action_external_observations
                    .checked_add(1)
                    .context("Kbuild action external-input count overflowed")?;
            }
        }
        let owner_manifest = manifests
            .get_mut(&observation.owner)
            .context("Kbuild external-input observation has an unknown action owner")?;
        let rooted = root_path(&observation.path, source_root, output_root)?;
        match owner_manifest.entry(rooted) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(KbuildExternalInputReference {
                    absolute_path: observation.path.clone(),
                    value: observation.value,
                });
            }
            std::collections::btree_map::Entry::Occupied(entry)
                if entry.get().absolute_path != observation.path
                    || entry.get().value != observation.value =>
            {
                anyhow::bail!("Kbuild owner observed inconsistent external-input values");
            }
            std::collections::btree_map::Entry::Occupied(_) => {}
        }
    }
    let expected_analyzer_generated_file_observations = match generated {
        Some(generated) => generated
            .seal
            .analyzer_generated_file_observations
            .checked_add(generated.seal.analyzer_pre_final_value_match_observations)
            .context("Kbuild analyzer generated-file proof count overflowed")?,
        None => 0,
    };
    if external_observations
        .checked_add(analyzer_directory_external_seed_observations)
        .and_then(|count| count.checked_add(procfs_directory_observations))
        != Some(provenance.external_seed_observations)
        || analyzer_external_observations
            .checked_add(analyzer_directory_external_seed_observations)
            .and_then(|count| count.checked_add(procfs_directory_analyzer_observations))
            != Some(provenance.analyzer_external_seed_observations)
        || action_external_observations.checked_add(procfs_directory_action_observations)
            != Some(provenance.action_external_seed_observations)
        || withheld_analyzer_bootstrap_directories
            .checked_add(analyzer_directory_bootstrap_observations)
            != Some(provenance.analyzer_bootstrap_directory_observations)
        || withheld_analyzer_post_candidate_directories
            .checked_add(analyzer_directory_post_candidate_observations)
            != Some(provenance.analyzer_post_candidate_directory_observations)
        || analyzer_directory_same_owner_pre_mutation_observations
            .checked_add(managed_seed_observations)
            != Some(provenance.same_owner_pre_mutation_observations)
        || withheld_observations
            .checked_add(analyzer_directory_same_owner_post_candidate_observations)
            != Some(provenance.same_owner_post_candidate_observations)
        || generated_action_observations
            != generated.map_or(0, |generated| generated.seal.observations)
        || generated_directory_observations
            != generated.map_or(0, |generated| {
                generated.seal.cross_owner_directory_observations
            })
        || analyzer_generated_file_observations != expected_analyzer_generated_file_observations
        || analyzer_generated_directory_observations != 0
        || analyzer_directory_checkpoint_observations
            != generated.map_or(0, |generated| {
                generated.seal.analyzer_directory_checkpoints.observations
            })
        || analyzer_directory_bootstrap_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .bootstrap_observations
            })
        || analyzer_directory_post_candidate_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .post_candidate_observations
            })
        || analyzer_exact_directory_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .exact_cross_owner_observations
            })
        || analyzer_directory_external_seed_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .external_seed_observations
            })
        || analyzer_directory_same_owner_pre_mutation_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .same_owner_pre_mutation_observations
            })
        || analyzer_directory_same_owner_post_candidate_observations
            != generated.map_or(0, |generated| {
                generated
                    .seal
                    .analyzer_directory_checkpoints
                    .same_owner_post_candidate_observations
            })
        || procfs_directory_observations != procfs_directories.seal.observations
        || procfs_directory_analyzer_observations != procfs_directories.seal.analyzer_observations
        || procfs_directory_action_observations != procfs_directories.seal.action_observations
        || provenance.cross_owner_mutation_observations
            != generated_action_observations
                .checked_add(generated_directory_observations)
                .and_then(|count| count.checked_add(analyzer_generated_file_observations))
                .and_then(|count| count.checked_add(analyzer_exact_directory_observations))
                .context("Kbuild generated-input partition count overflowed")?
    {
        anyhow::bail!("Kbuild external-input manifests do not cover the seed partition");
    }
    let analyzer_generated_input_references = generated.map_or(0, |generated| {
        generated.seal.analyzer_generated_input_references
    });
    let generated_input_provenance_digest =
        generated.map_or([0; 32], |generated| generated.seal.provenance_digest);
    let analyzer_generated_input_digest = generated.map_or([0; 32], |generated| {
        generated.seal.analyzer_generated_input_digest
    });
    let generated_action_input_references = generated.map_or(0, |generated| {
        generated.seal.generated_action_input_references
    });

    let analyzer_directory_checkpoint_digest = generated.map_or([0; 32], |generated| {
        generated
            .seal
            .analyzer_directory_checkpoints
            .checkpoint_digest
    });
    let analyzer_directory_checkpoint_paths = generated.map_or(0, |generated| {
        generated
            .seal
            .analyzer_directory_checkpoints
            .distinct_directories
    });
    let analyzer_exact_directory_paths = generated.map_or(0, |generated| {
        generated
            .seal
            .analyzer_directory_checkpoints
            .distinct_exact_cross_owner_directories
    });
    let procfs_directory_paths = u64::try_from(withheld_procfs_paths.len())
        .context("Kbuild procfs directory path count does not fit u64")?;
    if procfs_directory_paths != procfs_directories.seal.distinct_directories {
        anyhow::bail!("Kbuild procfs directory path set changed after proof");
    }

    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-external-input-manifests.v6\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&input_census.census_digest);
    hasher.update(&provenance.partition_digest);
    hasher.update(&generated_input_provenance_digest);
    hasher.update(&analyzer_generated_input_digest);
    hasher.update(&analyzer_directory_checkpoint_digest);
    hasher.update(&procfs_directories.seal.census_digest);
    hasher.update(&external_observations.to_le_bytes());
    hasher.update(&generated_action_observations.to_le_bytes());
    hasher.update(&generated_action_input_references.to_le_bytes());
    hasher.update(&analyzer_generated_file_observations.to_le_bytes());
    hasher.update(&analyzer_generated_input_references.to_le_bytes());
    hasher.update(&analyzer_directory_checkpoint_observations.to_le_bytes());
    hasher.update(&analyzer_directory_checkpoint_paths.to_le_bytes());
    hasher.update(&analyzer_exact_directory_observations.to_le_bytes());
    hasher.update(&analyzer_exact_directory_paths.to_le_bytes());
    hasher.update(&procfs_directory_observations.to_le_bytes());
    hasher.update(&procfs_directory_paths.to_le_bytes());
    hasher.update(&procfs_directory_analyzer_observations.to_le_bytes());
    hasher.update(&procfs_directory_action_observations.to_le_bytes());
    hasher.update(&managed_seed_observations.to_le_bytes());
    let owner_count = u64::try_from(manifests.len())
        .context("Kbuild external-input owner count does not fit u64")?;
    hasher.update(&owner_count.to_le_bytes());

    let mut input_references = 0_u64;
    let mut analyzer_inputs = 0_u64;
    let mut analyzer_manifest_digest = [0_u8; 32];
    let mut action_input_references = 0_u64;
    let mut whole_file_inputs = 0_u64;
    let mut referenced_file_bytes = 0_u64;
    let mut directory_listing_inputs = 0_u64;
    let mut path_owners: BTreeMap<ExternalPathKey, u64> = BTreeMap::new();
    let mut action_seals = Vec::new();
    for (owner, inputs) in &manifests {
        update_kbuild_process_owner(&mut hasher, *owner);
        let inputs_count = u64::try_from(inputs.len())
            .context("Kbuild external-input reference count does not fit u64")?;
        hasher.update(&inputs_count.to_le_bytes());
        input_references = input_references
            .checked_add(inputs_count)
            .context("Kbuild external-input reference count overflowed")?;
        let mut owner_hasher = blake3::Hasher::new();
        owner_hasher.update(b"rush.kbuild-owner-external-input-manifest.v1\0");
        owner_hasher.update(&graph_digest);
        owner_hasher.update(&stream_digest);
        owner_hasher.update(&assignment_digest);
        update_kbuild_process_owner(&mut owner_hasher, *owner);
        owner_hasher.update(&inputs_count.to_le_bytes());
        let mut owner_whole_files = 0_u64;
        let mut owner_file_bytes = 0_u64;
        let mut owner_directories = 0_u64;
        for (path, input) in inputs {
            let value = input.value;
            update_kbuild_external_input_path(&mut hasher, path)?;
            update_kbuild_external_input_value(&mut hasher, value);
            update_kbuild_external_input_path(&mut owner_hasher, path)?;
            update_kbuild_external_input_value(&mut owner_hasher, value);
            let owners = path_owners.entry(path.clone()).or_insert(0);
            *owners = owners
                .checked_add(1)
                .context("Kbuild external-input path-owner count overflowed")?;
            match value {
                KbuildObservedInputValue::WholeFile { bytes, .. } => {
                    owner_whole_files = owner_whole_files
                        .checked_add(1)
                        .context("Kbuild owner whole-file input count overflowed")?;
                    owner_file_bytes = owner_file_bytes
                        .checked_add(bytes)
                        .context("Kbuild owner referenced-file byte count overflowed")?;
                }
                KbuildObservedInputValue::Directory { .. } => {
                    owner_directories = owner_directories
                        .checked_add(1)
                        .context("Kbuild owner directory input count overflowed")?;
                }
            }
        }
        let owner_digest = *owner_hasher.finalize().as_bytes();
        whole_file_inputs = whole_file_inputs
            .checked_add(owner_whole_files)
            .context("Kbuild whole-file input count overflowed")?;
        referenced_file_bytes = referenced_file_bytes
            .checked_add(owner_file_bytes)
            .context("Kbuild referenced-file byte count overflowed")?;
        directory_listing_inputs = directory_listing_inputs
            .checked_add(owner_directories)
            .context("Kbuild directory input count overflowed")?;
        match owner {
            KbuildProcessOwner::Analyzer => {
                analyzer_inputs = inputs_count;
                analyzer_manifest_digest = owner_digest;
            }
            KbuildProcessOwner::Action(action_index) => {
                action_input_references = action_input_references
                    .checked_add(inputs_count)
                    .context("Kbuild action input-reference count overflowed")?;
                action_seals.push(KbuildActionExternalInputManifestSeal {
                    action_index: *action_index,
                    inputs: inputs_count,
                    whole_file_inputs: owner_whole_files,
                    directory_listing_inputs: owner_directories,
                    referenced_file_bytes: owner_file_bytes,
                    manifest_digest: owner_digest,
                });
            }
        }
    }
    let owner_total = analyzer_inputs
        .checked_add(action_input_references)
        .context("Kbuild external-input owner total overflowed")?;
    let kind_total = whole_file_inputs
        .checked_add(directory_listing_inputs)
        .context("Kbuild external-input kind total overflowed")?;
    if owner_total != input_references || kind_total != input_references {
        anyhow::bail!("Kbuild external-input manifests are internally inconsistent");
    }
    let distinct_inputs = u64::try_from(path_owners.len())
        .context("Kbuild distinct external-input count does not fit u64")?;
    let materialized_paths = path_owners.keys().cloned().collect::<BTreeSet<_>>();
    if !materialized_paths.is_disjoint(&withheld_procfs_paths)
        || !materialized_paths.is_disjoint(&withheld_analyzer_external_seed_paths)
        || !withheld_procfs_paths.is_disjoint(&withheld_analyzer_external_seed_paths)
    {
        anyhow::bail!("Kbuild external-input seed path classes overlap");
    }
    let mut retained_seed_paths = materialized_paths.clone();
    retained_seed_paths.extend(withheld_procfs_paths.iter().cloned());
    retained_seed_paths.extend(withheld_analyzer_external_seed_paths.iter().cloned());
    let mut expected_seed_paths = observations
        .iter()
        .filter(|observation| {
            matches!(
                mutation_index.classify(observation),
                KbuildInputProvenanceClass::ExternalSeed
            )
        })
        .map(|observation| root_path(&observation.path, source_root, output_root))
        .collect::<Result<BTreeSet<_>>>()?;
      if let Some(seed) = managed_seed {
          let source_path = root_path(&seed.source_path, source_root, output_root)?;
          retained_seed_paths.insert(source_path.clone());
          expected_seed_paths.insert(source_path);
          let scratch_path = root_path(
              &output_root.join(KBUILD_MANAGED_SCRATCH_DIRECTORY),
              source_root,
              output_root,
          )?;
          retained_seed_paths.insert(scratch_path.clone());
          expected_seed_paths.insert(scratch_path);
      }
      if retained_seed_paths != expected_seed_paths {
          let missing = expected_seed_paths
              .difference(&retained_seed_paths)
              .take(8)
              .cloned()
              .collect::<Vec<_>>();
          let unexpected = retained_seed_paths
              .difference(&expected_seed_paths)
              .take(8)
              .cloned()
              .collect::<Vec<_>>();
          anyhow::bail!(
              "Kbuild external-input manifests changed the distinct seed set: \
               missing {missing:?}; unexpected {unexpected:?}"
          );
      }
    let shared_inputs = u64::try_from(path_owners.values().filter(|owners| **owners > 1).count())
        .context("Kbuild shared external-input count does not fit u64")?;
    for count in [
        input_references,
        distinct_inputs,
        shared_inputs,
        analyzer_inputs,
        action_input_references,
        whole_file_inputs,
        referenced_file_bytes,
        directory_listing_inputs,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    hasher.update(&analyzer_manifest_digest);
    let action_seal_count = u64::try_from(action_seals.len())
        .context("Kbuild action input-manifest count does not fit u64")?;
    if action_seal_count != action_count {
        anyhow::bail!("Kbuild external-input manifests do not cover every action");
    }
    hasher.update(&action_seal_count.to_le_bytes());
    for action in &action_seals {
        hasher.update(&action.action_index.to_le_bytes());
        hasher.update(&action.inputs.to_le_bytes());
        hasher.update(&action.whole_file_inputs.to_le_bytes());
        hasher.update(&action.directory_listing_inputs.to_le_bytes());
        hasher.update(&action.referenced_file_bytes.to_le_bytes());
        hasher.update(&action.manifest_digest);
    }
    let seal = KbuildExternalInputManifestSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        input_census_digest: input_census.census_digest,
        provenance_partition_digest: provenance.partition_digest,
        generated_input_provenance_digest,
        analyzer_generated_input_digest,
        analyzer_directory_checkpoint_digest,
        procfs_directory_census_digest: procfs_directories.seal.census_digest,
        manifest_digest: *hasher.finalize().as_bytes(),
        observations: external_observations,
        generated_action_observations,
        generated_action_input_references,
        analyzer_generated_observations: analyzer_generated_file_observations,
        analyzer_generated_input_references,
        analyzer_directory_checkpoint_observations,
        analyzer_directory_checkpoint_paths,
        analyzer_exact_directory_observations,
        analyzer_exact_directory_paths,
        procfs_directory_observations,
        procfs_directory_paths,
        procfs_directory_analyzer_observations,
        procfs_directory_action_observations,
        input_references,
        distinct_inputs,
        shared_inputs,
        analyzer_inputs,
        analyzer_manifest_digest,
        action_input_references,
        whole_file_inputs,
        referenced_file_bytes,
        directory_listing_inputs,
        actions: action_seals,
    };
    Ok((seal, manifests))
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KbuildStablePathMetadata {
    device: u64,
    inode: u64,
    bytes: u64,
    mode: u32,
    modified_seconds: i64,
    modified_nanoseconds: i64,
    changed_seconds: i64,
    changed_nanoseconds: i64,
}

#[cfg(unix)]
impl KbuildStablePathMetadata {
    fn from_metadata(metadata: &std::fs::Metadata) -> Self {
        use std::os::unix::fs::MetadataExt as _;

        Self {
            device: metadata.dev(),
            inode: metadata.ino(),
            bytes: metadata.size(),
            mode: metadata.mode(),
            modified_seconds: metadata.mtime(),
            modified_nanoseconds: metadata.mtime_nsec(),
            changed_seconds: metadata.ctime(),
            changed_nanoseconds: metadata.ctime_nsec(),
        }
    }
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum KbuildCurrentInputValue {
    WholeFile {
        bytes: u64,
        digest: [u8; 32],
        mode: u32,
        dependency_digest: [u8; 32],
        metadata: KbuildStablePathMetadata,
    },
    Directory {
        listing_digest: [u8; 32],
        dependency_digest: [u8; 32],
    },
}

#[cfg(unix)]
fn open_kbuild_input_no_follow(path: &Path) -> Result<File> {
    use std::os::unix::fs::OpenOptionsExt as _;

    let mut options = OpenOptions::new();
    options
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK);
    options
        .open(path)
        .with_context(|| format!("open captured Kbuild input {}", path.display()))
}

#[cfg(target_os = "linux")]
fn kbuild_file_mount_id(file: &File) -> Result<u64> {
    use std::os::unix::io::AsRawFd as _;

    let path = PathBuf::from(format!("/proc/self/fdinfo/{}", file.as_raw_fd()));
    let contents =
        std::fs::read_to_string(path).context("read Kbuild descriptor mount identity")?;
    let mount_id = contents
        .lines()
        .find_map(|line| line.strip_prefix("mnt_id:"))
        .context("Kbuild descriptor has no mount identity")?
        .trim()
        .parse::<u64>()
        .context("parse Kbuild descriptor mount identity")?;
    if mount_id == 0 {
        anyhow::bail!("Kbuild descriptor has an invalid mount identity");
    }
    Ok(mount_id)
}

#[cfg(all(unix, not(target_os = "linux")))]
fn kbuild_file_mount_id(_file: &File) -> Result<u64> {
    anyhow::bail!("Kbuild descriptor mount identity requires Linux")
}

#[cfg(unix)]
fn require_stable_kbuild_input_path(path: &Path, expected: KbuildStablePathMetadata) -> Result<()> {
    let reopened = open_kbuild_input_no_follow(path)?;
    let current = KbuildStablePathMetadata::from_metadata(
        &reopened
            .metadata()
            .with_context(|| format!("restat captured Kbuild input {}", path.display()))?,
    );
    if current != expected {
        anyhow::bail!("captured Kbuild input path changed while it was witnessed");
    }
    Ok(())
}

#[cfg(unix)]
fn witness_current_kbuild_input(
    path: &Path,
    expected: KbuildObservedInputValue,
    retain_bytes: bool,
) -> Result<(KbuildCurrentInputValue, Option<Vec<u8>>)> {
    use std::os::unix::io::AsRawFd as _;

    let file = open_kbuild_input_no_follow(path)?;
    let before_metadata = file
        .metadata()
        .with_context(|| format!("stat captured Kbuild input {}", path.display()))?;
    let before = KbuildStablePathMetadata::from_metadata(&before_metadata);
    if before.inode == 0 {
        anyhow::bail!("captured Kbuild input has no stable inode identity");
    }

    match expected {
        KbuildObservedInputValue::WholeFile {
            bytes,
            digest,
            mode,
        } => {
            if !before_metadata.file_type().is_file() || before.mode != mode {
                anyhow::bail!("captured Kbuild file input has the wrong current shape");
            }
            let limit = bytes
                .checked_add(1)
                .context("captured Kbuild file input byte limit overflowed")?;
            let mut limited = file.take(limit);
            let mut contents = Vec::new();
            limited
                .read_to_end(&mut contents)
                .with_context(|| format!("read captured Kbuild input {}", path.display()))?;
            let after = KbuildStablePathMetadata::from_metadata(
                &limited
                    .get_ref()
                    .metadata()
                    .with_context(|| format!("restat captured Kbuild input {}", path.display()))?,
            );
            let current_bytes = u64::try_from(contents.len())
                .context("current Kbuild input length does not fit u64")?;
            let current_digest = *blake3::hash(&contents).as_bytes();
            if after != before
                || current_bytes != bytes
                || current_digest != digest
                || (!regular_file_value_has_synthetic_size(std::os::unix::ffi::OsStrExt::as_bytes(
                    path.as_os_str(),
                )) && before.bytes != bytes)
            {
                anyhow::bail!("captured Kbuild file input changed before materialization");
            }
            require_stable_kbuild_input_path(path, before)?;
            let retained = retain_bytes.then(|| contents.clone());
            Ok((
                KbuildCurrentInputValue::WholeFile {
                    bytes,
                    digest,
                    mode,
                    dependency_digest: content_digest(&contents),
                    metadata: before,
                },
                retained,
            ))
        }
        KbuildObservedInputValue::Directory {
            entries,
            listing_digest,
            ..
        } => {
            if !before_metadata.file_type().is_dir() {
                anyhow::bail!("captured Kbuild directory input has the wrong current shape");
            }
            // The capture-only ordered digest also binds inode numbers, d_type,
            // and opaque directory positions. Those prove that observation was
            // complete, but the replay dependency is the canonical member-name
            // set, so current-state validation compares that semantic digest.
            let descriptor_path = PathBuf::from(format!("/proc/self/fd/{}", file.as_raw_fd()));
            let mut members = Vec::new();
            for entry in std::fs::read_dir(&descriptor_path)
                .with_context(|| format!("enumerate captured Kbuild input {}", path.display()))?
            {
                let entry = entry.with_context(|| {
                    format!("enumerate captured Kbuild input {}", path.display())
                })?;
                members.push(os_bytes(entry.file_name().as_os_str()));
                if u64::try_from(members.len()).unwrap_or(u64::MAX) > entries {
                    anyhow::bail!("captured Kbuild directory input gained members");
                }
            }
            members.sort();
            if members.windows(2).any(|pair| pair[0] == pair[1]) {
                anyhow::bail!("captured Kbuild directory input has duplicate members");
            }
            let current_listing_digest = captured_directory_listing_digest(&members)?;
            let after = KbuildStablePathMetadata::from_metadata(
                &file
                    .metadata()
                    .with_context(|| format!("restat captured Kbuild input {}", path.display()))?,
            );
            if after != before || current_listing_digest != listing_digest {
                anyhow::bail!("captured Kbuild directory input changed before materialization");
            }
            require_stable_kbuild_input_path(path, before)?;
            Ok((
                KbuildCurrentInputValue::Directory {
                    listing_digest,
                    dependency_digest: dir_listing_digest(members),
                },
                None,
            ))
        }
    }
}

#[cfg(unix)]
fn materialize_kbuild_external_input_manifests(
    captured: KbuildExternalInputManifestSeal,
    references: KbuildExternalInputReferences,
    managed_seed: Option<&KbuildManagedCaptureSeed>,
) -> Result<KbuildMaterializedExternalInputManifests> {
    let mut distinct = BTreeMap::<ExternalPathKey, KbuildExternalInputReference>::new();
    for inputs in references.values() {
        for (path, input) in inputs {
            match distinct.entry(path.clone()) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(input.clone());
                }
                std::collections::btree_map::Entry::Occupied(entry) if entry.get() != input => {
                    anyhow::bail!("Kbuild owners disagree about one external-input path or value");
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
            }
        }
    }
    let distinct_validated_inputs = u64::try_from(distinct.len())
        .context("Kbuild validated external-input count does not fit u64")?;
    if distinct_validated_inputs != captured.distinct_inputs {
        anyhow::bail!("Kbuild current-state validation changed the distinct input set");
    }

    let mut current_values = BTreeMap::new();
    let mut retained_files = BTreeMap::new();
    let mut current_hasher = blake3::Hasher::new();
    current_hasher.update(b"rush.kbuild-current-external-input-values.v1\0");
    current_hasher.update(&captured.manifest_digest);
    current_hasher.update(&distinct_validated_inputs.to_le_bytes());
    for (path, input) in &distinct {
        let retain_bytes = path.root == "obj"
            && (path.path == b".config" || path.path == b"include/config/auto.conf");
        let (current, retained) =
            witness_current_kbuild_input(&input.absolute_path, input.value, retain_bytes)
                .with_context(|| "validate captured Kbuild external input against current state")?;
        if let Some(bytes) = retained {
            retained_files.insert(path.clone(), bytes);
        }
        update_kbuild_external_input_path(&mut current_hasher, path)?;
        match current {
            KbuildCurrentInputValue::WholeFile {
                bytes,
                digest,
                mode,
                dependency_digest,
                ..
            } => {
                current_hasher.update(&[0]);
                current_hasher.update(&bytes.to_le_bytes());
                current_hasher.update(&digest);
                current_hasher.update(&mode.to_le_bytes());
                current_hasher.update(&dependency_digest);
            }
            KbuildCurrentInputValue::Directory {
                listing_digest,
                dependency_digest,
            } => {
                current_hasher.update(&[1]);
                current_hasher.update(&listing_digest);
                current_hasher.update(&dependency_digest);
            }
        }
        current_values.insert(path.clone(), current);
    }
    let current_value_digest = *current_hasher.finalize().as_bytes();

    let analysis_inputs = references
        .get(&KbuildProcessOwner::Analyzer)
        .context("Kbuild external-input manifests omit the analyzer owner")?;
    let mut dependencies = Vec::new();
    if let Some(seed) = managed_seed {
        dependencies.push(Dependency::FileContent {
            path: seed.source_path.clone(),
            digest: content_digest(&seed.bytes),
        });
    }
    let mut analysis_file_metadata_dependencies = 0_u64;
    for (path, input) in analysis_inputs {
        let current = current_values
            .get(path)
            .context("Kbuild analyzer input has no current-state witness")?;
        match current {
            KbuildCurrentInputValue::WholeFile {
                dependency_digest,
                metadata,
                ..
            } => {
                analysis_file_metadata_dependencies = analysis_file_metadata_dependencies
                    .checked_add(1)
                    .context("Kbuild analysis file metadata count overflowed")?;
                dependencies.push(Dependency::FileMetadata {
                    path: input.absolute_path.clone(),
                    present: true,
                    len: metadata.bytes,
                    mode: metadata.mode,
                    mtime_ns: i128::from(metadata.modified_seconds) * 1_000_000_000
                        + i128::from(metadata.modified_nanoseconds),
                    ctime_ns: i128::from(metadata.changed_seconds) * 1_000_000_000
                        + i128::from(metadata.changed_nanoseconds),
                    dev: metadata.device,
                    ino: metadata.inode,
                });
                dependencies.push(Dependency::FileContent {
                    path: input.absolute_path.clone(),
                    digest: *dependency_digest,
                });
            }
            KbuildCurrentInputValue::Directory {
                dependency_digest, ..
            } => dependencies.push(Dependency::DirListing {
                path: input.absolute_path.clone(),
                entries_digest: *dependency_digest,
            }),
        }
    }
    let analysis_manifest = DependencyManifest::from_deps(dependencies);
    let analysis_dependencies = u64::try_from(analysis_manifest.len())
        .context("Kbuild analysis dependency count does not fit u64")?;
    let expected_analysis_dependencies = captured
        .analyzer_inputs
        .checked_add(analysis_file_metadata_dependencies)
        .and_then(|count| count.checked_add(u64::from(managed_seed.is_some())))
        .context("Kbuild expected analysis dependency count overflowed")?;
    if analysis_dependencies != expected_analysis_dependencies {
        anyhow::bail!("Kbuild materialized analysis manifest is incomplete");
    }
    let analysis_manifest_digest = analysis_manifest.fingerprint();
    let analyzer_values = analysis_inputs
        .iter()
        .map(|(path, input)| ExternalInputKey {
            path: path.clone(),
            value: kbuild_external_input_value(input.value),
        })
        .collect();

    let action_count = captured.actions.len();
    let mut action_inputs = Vec::with_capacity(action_count);
    let mut action_values = Vec::with_capacity(action_count);
    let mut action_hasher = blake3::Hasher::new();
    action_hasher.update(b"rush.kbuild-action-input-materialization.v1\0");
    action_hasher.update(&captured.manifest_digest);
    let action_count_u64 =
        u64::try_from(action_count).context("Kbuild materialized action count does not fit u64")?;
    action_hasher.update(&action_count_u64.to_le_bytes());
    let mut action_input_references = 0_u64;
    for action_index in 0..action_count {
        let action_index_u64 = u64::try_from(action_index)
            .context("Kbuild materialized action index does not fit u64")?;
        let owner = KbuildProcessOwner::Action(action_index_u64);
        let inputs = references
            .get(&owner)
            .context("Kbuild external-input manifests omit an action owner")?;
        action_hasher.update(&action_index_u64.to_le_bytes());
        action_hasher.update(
            &u64::try_from(inputs.len())
                .context("Kbuild materialized action input count does not fit u64")?
                .to_le_bytes(),
        );
        let mut declarations = Vec::with_capacity(inputs.len());
        let mut values = Vec::with_capacity(inputs.len());
        for (path, input) in inputs {
            let kind = kbuild_external_input_kind(input.value);
            let value = kbuild_external_input_value(input.value);
            update_kbuild_external_input_path(&mut action_hasher, path)?;
            action_hasher.update(&[match kind {
                ExternalInputKind::File => 0,
                ExternalInputKind::DirectoryListing => 1,
                _ => unreachable!("captured Kbuild inputs have only two admitted shapes"),
            }]);
            update_kbuild_external_input_value(&mut action_hasher, input.value);
            declarations.push(ExternalInput {
                path: path.clone(),
                kind,
            });
            values.push(ExternalInputKey {
                path: path.clone(),
                value,
            });
        }
        action_input_references = action_input_references
            .checked_add(
                u64::try_from(inputs.len())
                    .context("Kbuild materialized action input count does not fit u64")?,
            )
            .context("Kbuild materialized action input count overflowed")?;
        action_inputs.push(declarations);
        action_values.push(values);
    }
    if action_input_references != captured.action_input_references {
        anyhow::bail!("Kbuild materialized action input manifests are incomplete");
    }
    let action_materialization_digest = *action_hasher.finalize().as_bytes();

    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-external-input-materialization.v1\0");
    hasher.update(&captured.graph_digest);
    hasher.update(&captured.stream_digest);
    hasher.update(&captured.assignment_digest);
    hasher.update(&captured.manifest_digest);
    hasher.update(&distinct_validated_inputs.to_le_bytes());
    hasher.update(&analysis_dependencies.to_le_bytes());
    hasher.update(&action_input_references.to_le_bytes());
    hasher.update(&current_value_digest);
    hasher.update(&analysis_manifest_digest);
    hasher.update(&action_materialization_digest);
    let seal = KbuildExternalInputMaterializationSeal {
        graph_digest: captured.graph_digest,
        stream_digest: captured.stream_digest,
        assignment_digest: captured.assignment_digest,
        captured_manifest_digest: captured.manifest_digest,
        distinct_validated_inputs,
        analysis_dependencies,
        action_input_references,
        analysis_manifest_digest,
        action_materialization_digest,
        materialization_digest: *hasher.finalize().as_bytes(),
    };
    Ok(KbuildMaterializedExternalInputManifests {
        captured,
        seal,
        analysis_manifest,
        analyzer_values,
        action_inputs,
        action_values,
        retained_files: {
            if let Some(seed) = managed_seed {
                retained_files.insert(
                    ExternalPathKey {
                        root: "obj".to_string(),
                        path: b".config".to_vec(),
                    },
                    seed.bytes.clone(),
                );
            }
            retained_files
        },
    })
}

#[cfg(unix)]
fn kbuild_external_input_kind(value: KbuildObservedInputValue) -> ExternalInputKind {
    match value {
        KbuildObservedInputValue::WholeFile { .. } => ExternalInputKind::File,
        KbuildObservedInputValue::Directory { .. } => ExternalInputKind::DirectoryListing,
    }
}

#[cfg(unix)]
fn kbuild_external_input_value(value: KbuildObservedInputValue) -> ExternalInputValue {
    match value {
        KbuildObservedInputValue::WholeFile { digest, mode, .. } => ExternalInputValue::File {
            digest,
            executable: mode & 0o111 != 0,
        },
        KbuildObservedInputValue::Directory { listing_digest, .. } => {
            ExternalInputValue::DirectoryListing {
                digest: listing_digest,
            }
        }
    }
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct KbuildFinalOutputObservation {
    owner: KbuildProcessOwner,
    process: CapturedProcessId,
    stream_ordinal: u64,
    descriptor: i32,
    action_index: u64,
    output_index: u64,
    object: KbuildOutputObjectIdentity,
    bytes: u64,
    digest: [u8; 32],
    mode: u32,
    boundary: KbuildFinalOutputBoundary,
}

#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct KbuildSymlinkCreationValue {
    owner: KbuildProcessOwner,
    process: CapturedProcessId,
    stream_ordinal: u64,
    syscall_index: u64,
    path: PathBuf,
    target: Vec<u8>,
}

#[cfg(unix)]
fn require_kbuild_final_rename_pair(
    owner: KbuildProcessOwner,
    destination: &KbuildMutationCandidate,
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
) -> Result<()> {
    if destination.kind != KbuildMutationCandidateKind::PathRenameDestination
        || destination.object.is_some()
    {
        anyhow::bail!("Kbuild final output rename destination is malformed");
    }
    let paired = mutation_events
        .iter()
        .filter(|(candidate_owner, candidate)| {
            *candidate_owner == owner
                && candidate.process == destination.process
                && candidate.stream_ordinal == destination.stream_ordinal
                && candidate.syscall_index == destination.syscall_index
        })
        .map(|(_, candidate)| candidate)
        .collect::<Vec<_>>();
    let sources = paired
        .iter()
        .filter(|candidate| {
            candidate.kind == KbuildMutationCandidateKind::PathRenameSource
                && candidate.object.is_none()
                && candidate.path != destination.path
        })
        .count();
    let destinations = paired
        .iter()
        .filter(|candidate| std::ptr::eq(**candidate, destination))
        .count();
    if paired.len() != 2 || sources != 1 || destinations != 1 {
        anyhow::bail!("Kbuild final output rename has no exact source pair");
    }
    Ok(())
}

#[cfg(unix)]
fn kbuild_final_output_value_seal_with_symlink_creations(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    mutation_attribution_digest: [u8; 32],
    declared_outputs: &BTreeMap<u64, Vec<PathBuf>>,
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    observations: &[KbuildFinalOutputObservation],
    symlink_creations: &[KbuildSymlinkCreationValue],
) -> Result<KbuildFinalOutputValueSeal> {
    if observations.windows(2).any(|pair| {
        (pair[0].stream_ordinal, pair[0].descriptor) > (pair[1].stream_ordinal, pair[1].descriptor)
    }) {
        anyhow::bail!("Kbuild final-output observations are not in stream order");
    }

    let declared_output_observations = u64::try_from(observations.len())
        .context("Kbuild final-output observation count does not fit u64")?;
    let mut close_observations = 0_u64;
    let mut descriptor_replacement_observations = 0_u64;
    let mut exit_observations = 0_u64;
    let mut post_capture_rename_observations = 0_u64;
    let mut post_capture_directory_observations = 0_u64;
    let mut post_capture_mode_change_observations = 0_u64;
    let mut post_capture_shared_mapping_observations = 0_u64;
    let mut post_capture_symlink_creation_observations = 0_u64;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-final-output-values.v8\0");
    hasher.update(&graph_digest);
    hasher.update(&stream_digest);
    hasher.update(&assignment_digest);
    hasher.update(&mutation_attribution_digest);
    hasher.update(&declared_output_observations.to_le_bytes());
    for observation in observations {
        if observation.mode & libc::S_IFMT != libc::S_IFREG {
            anyhow::bail!("Kbuild final output value is not a regular file");
        }
        update_kbuild_process_owner(&mut hasher, observation.owner);
        hasher.update(&observation.process.to_le_bytes());
        hasher.update(&observation.stream_ordinal.to_le_bytes());
        hasher.update(&observation.descriptor.to_le_bytes());
        hasher.update(&observation.action_index.to_le_bytes());
        hasher.update(&observation.output_index.to_le_bytes());
        hasher.update(&observation.object.device.to_le_bytes());
        hasher.update(&observation.object.inode.to_le_bytes());
        hasher.update(&observation.object.mount_id.to_le_bytes());
        hasher.update(&observation.bytes.to_le_bytes());
        hasher.update(&observation.digest);
        hasher.update(&observation.mode.to_le_bytes());
        match observation.boundary {
            KbuildFinalOutputBoundary::Close => {
                hasher.update(&[0]);
                close_observations = close_observations
                    .checked_add(1)
                    .context("Kbuild final close-observation count overflowed")?;
            }
            KbuildFinalOutputBoundary::DescriptorReplacement => {
                hasher.update(&[1]);
                descriptor_replacement_observations = descriptor_replacement_observations
                    .checked_add(1)
                    .context("Kbuild final descriptor-replacement observation count overflowed")?;
            }
            KbuildFinalOutputBoundary::Exit => {
                hasher.update(&[2]);
                exit_observations = exit_observations
                    .checked_add(1)
                    .context("Kbuild final exit-observation count overflowed")?;
            }
            KbuildFinalOutputBoundary::PostCaptureRename => {
                anyhow::bail!("Kbuild raw output observation has a post-capture boundary")
            }
            KbuildFinalOutputBoundary::PostCaptureDirectory => {
                anyhow::bail!("Kbuild raw output observation has a post-capture boundary")
            }
            KbuildFinalOutputBoundary::PostCaptureModeChange => {
                anyhow::bail!("Kbuild raw output observation has a post-capture boundary")
            }
            KbuildFinalOutputBoundary::PostCaptureSharedMapping => {
                anyhow::bail!("Kbuild raw output observation has a post-capture boundary")
            }
            KbuildFinalOutputBoundary::PostCaptureSymlinkCreation => {
                anyhow::bail!("Kbuild raw output observation has a post-capture boundary")
            }
        }
    }

    let mut outputs = Vec::new();
    for (action_index, paths) in declared_outputs {
        let owner = KbuildProcessOwner::Action(*action_index);
        for (output_index, path) in paths.iter().enumerate() {
            let output_index =
                u64::try_from(output_index).context("Kbuild output index does not fit u64")?;
            let last_mutation = mutation_events
                .iter()
                .filter(|(candidate_owner, candidate)| {
                    *candidate_owner == owner && candidate.path == *path
                })
                .map(|(_, candidate)| candidate)
                .max_by_key(|candidate| candidate.stream_ordinal)
                .with_context(|| {
                    format!(
                        "Kbuild action {action_index} output {output_index} has no owned mutation"
                    )
                })?;
            let boundary_observations = observations
                .iter()
                .filter(|observation| {
                    observation.owner == owner
                        && observation.action_index == *action_index
                        && observation.output_index == output_index
                })
                .count();
            let selected = observations
                .iter()
                .filter(|observation| {
                    observation.owner == owner
                        && observation.action_index == *action_index
                        && observation.output_index == output_index
                        && observation.stream_ordinal > last_mutation.stream_ordinal
                })
                .max_by_key(|observation| (observation.stream_ordinal, observation.descriptor));
            let prior = observations
                .iter()
                .filter(|observation| {
                    observation.owner == owner
                        && observation.action_index == *action_index
                        && observation.output_index == output_index
                        && observation.stream_ordinal < last_mutation.stream_ordinal
                })
                .max_by_key(|observation| (observation.stream_ordinal, observation.descriptor));
            let output = if last_mutation.kind == KbuildMutationCandidateKind::SharedWritableMapping
            {
                post_capture_shared_mapping_observations = post_capture_shared_mapping_observations
                    .checked_add(1)
                    .context("Kbuild post-capture shared-mapping count overflowed")?;
                witness_current_kbuild_output_after_shared_mapping(
                    path,
                    *action_index,
                    output_index,
                    last_mutation,
                )?
            } else if selected.is_none()
                && last_mutation.kind == KbuildMutationCandidateKind::DirectoryCreation
            {
                if boundary_observations != 0 {
                    anyhow::bail!("Kbuild directory output has a file-value observation");
                }
                let (object, metadata) = witness_current_kbuild_directory_output(path)?;
                post_capture_directory_observations = post_capture_directory_observations
                    .checked_add(1)
                    .context("Kbuild post-capture directory count overflowed")?;
                KbuildFinalOutputValue {
                    action_index: *action_index,
                    output_index,
                    object,
                    kind: KbuildFinalOutputKind::Directory,
                    bytes: 0,
                    digest: *blake3::hash(b"rush.kbuild-directory-output.v1\0").as_bytes(),
                    mode: metadata.mode,
                    boundary: KbuildFinalOutputBoundary::PostCaptureDirectory,
                }
            } else if let Some(selected) = selected {
                if observations.iter().any(|observation| {
                    observation.owner == owner
                        && observation.action_index == *action_index
                        && observation.output_index == output_index
                        && observation.stream_ordinal == selected.stream_ordinal
                        && (
                            observation.object,
                            observation.bytes,
                            observation.digest,
                            observation.mode,
                        ) != (
                            selected.object,
                            selected.bytes,
                            selected.digest,
                            selected.mode,
                        )
                }) {
                    anyhow::bail!(
                        "Kbuild action {action_index} output {output_index} has inconsistent final \
                         values at one stream boundary"
                    );
                }
                let last_removal = mutation_events
                    .iter()
                    .filter(|(candidate_owner, candidate)| {
                        *candidate_owner == owner
                            && candidate.path == *path
                            && candidate.kind == KbuildMutationCandidateKind::PathRemoval
                    })
                    .map(|(_, candidate)| candidate.stream_ordinal)
                    .max();
                let current_objects = mutation_events
                    .iter()
                    .filter(|(candidate_owner, candidate)| {
                        *candidate_owner == owner
                            && candidate.path == *path
                            && last_removal.is_none_or(|ordinal| candidate.stream_ordinal > ordinal)
                    })
                    .filter_map(|(_, candidate)| candidate.object)
                    .collect::<BTreeSet<_>>();
                if current_objects.len() != 1 || !current_objects.contains(&selected.object) {
                    if last_mutation.kind != KbuildMutationCandidateKind::PathRenameDestination {
                        anyhow::bail!(
                            "Kbuild action {action_index} output {output_index} mutations and final \
                             value do not identify one VFS object"
                        );
                    }
                    // A later command in one compound action can read an output
                    // published by the final rename. Rename events have no object
                    // identity, so bind the exact rename pair, captured read value,
                    // and stable current path instead of borrowing an older object.
                    require_kbuild_final_rename_pair(owner, last_mutation, mutation_events)?;
                    let current = witness_current_kbuild_output_after_rename(
                        path,
                        *action_index,
                        output_index,
                    )?;
                    if current.object != selected.object
                        || current.kind != KbuildFinalOutputKind::RegularFile
                        || current.bytes != selected.bytes
                        || current.digest != selected.digest
                        || current.mode != selected.mode
                    {
                        anyhow::bail!(
                            "Kbuild action {action_index} output {output_index} final rename and \
                             later value do not identify one stable VFS object"
                        );
                    }
                }
                KbuildFinalOutputValue {
                    action_index: *action_index,
                    output_index,
                    object: selected.object,
                    kind: KbuildFinalOutputKind::RegularFile,
                    bytes: selected.bytes,
                    digest: selected.digest,
                    mode: selected.mode,
                    boundary: selected.boundary,
                }
            } else if last_mutation.kind == KbuildMutationCandidateKind::PathRenameDestination {
                require_kbuild_final_rename_pair(owner, last_mutation, mutation_events)?;
                post_capture_rename_observations = post_capture_rename_observations
                    .checked_add(1)
                    .context("Kbuild post-rename output count overflowed")?;
                witness_current_kbuild_output_after_rename(path, *action_index, output_index)?
            } else if last_mutation.kind == KbuildMutationCandidateKind::SymbolicLinkCreation {
                if boundary_observations != 0 {
                    anyhow::bail!("Kbuild symbolic-link output has a file-value observation");
                }
                post_capture_symlink_creation_observations =
                    post_capture_symlink_creation_observations
                        .checked_add(1)
                        .context("Kbuild post-capture symlink-creation count overflowed")?;
                witness_current_kbuild_output_after_symlink_creation(
                    path,
                    *action_index,
                    output_index,
                    owner,
                    last_mutation,
                    symlink_creations,
                )?
            } else if matches!(
                last_mutation.kind,
                KbuildMutationCandidateKind::PathModeChange
                    | KbuildMutationCandidateKind::DescriptorModeChange
            ) {
                let prior =
                    prior.context("Kbuild final mode change has no prior complete-file value")?;
                post_capture_mode_change_observations = post_capture_mode_change_observations
                    .checked_add(1)
                    .context("Kbuild post-capture mode-change count overflowed")?;
                witness_current_kbuild_output_after_mode_change(
                    path,
                    *action_index,
                    output_index,
                    prior,
                    last_mutation,
                )?
            } else {
                anyhow::bail!(
                    "Kbuild action {action_index} output {output_index} has no final value after \
                     its last mutation; last kind {}, captured {boundary_observations} matching \
                     value boundaries",
                    last_mutation.kind.label(),
                );
            };
            outputs.push(output);
        }
    }
    let persistent_outputs =
        u64::try_from(outputs.len()).context("Kbuild final-output value count does not fit u64")?;
    hasher.update(&persistent_outputs.to_le_bytes());
    for output in &outputs {
        hasher.update(&output.action_index.to_le_bytes());
        hasher.update(&output.output_index.to_le_bytes());
        hasher.update(&output.object.device.to_le_bytes());
        hasher.update(&output.object.inode.to_le_bytes());
        hasher.update(&output.object.mount_id.to_le_bytes());
        hasher.update(&[match output.kind {
            KbuildFinalOutputKind::RegularFile => 0,
            KbuildFinalOutputKind::Symlink => 1,
            KbuildFinalOutputKind::Directory => 2,
        }]);
        hasher.update(&output.bytes.to_le_bytes());
        hasher.update(&output.digest);
        hasher.update(&output.mode.to_le_bytes());
        hasher.update(&[match output.boundary {
            KbuildFinalOutputBoundary::Close => 0,
            KbuildFinalOutputBoundary::DescriptorReplacement => 1,
            KbuildFinalOutputBoundary::Exit => 2,
            KbuildFinalOutputBoundary::PostCaptureRename => 3,
            KbuildFinalOutputBoundary::PostCaptureDirectory => 4,
            KbuildFinalOutputBoundary::PostCaptureModeChange => 5,
            KbuildFinalOutputBoundary::PostCaptureSharedMapping => 6,
            KbuildFinalOutputBoundary::PostCaptureSymlinkCreation => 7,
        }]);
    }
    Ok(KbuildFinalOutputValueSeal {
        graph_digest,
        stream_digest,
        assignment_digest,
        mutation_attribution_digest,
        value_digest: *hasher.finalize().as_bytes(),
        declared_output_observations,
        close_observations,
        descriptor_replacement_observations,
        exit_observations,
        post_capture_rename_observations,
        post_capture_directory_observations,
        post_capture_mode_change_observations,
        post_capture_shared_mapping_observations,
        post_capture_symlink_creation_observations,
        persistent_outputs,
        outputs,
    })
}

#[cfg(all(unix, test))]
fn kbuild_final_output_value_seal(
    graph_digest: [u8; 32],
    stream_digest: [u8; 32],
    assignment_digest: [u8; 32],
    mutation_attribution_digest: [u8; 32],
    declared_outputs: &BTreeMap<u64, Vec<PathBuf>>,
    mutation_events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
    observations: &[KbuildFinalOutputObservation],
) -> Result<KbuildFinalOutputValueSeal> {
    kbuild_final_output_value_seal_with_symlink_creations(
        graph_digest,
        stream_digest,
        assignment_digest,
        mutation_attribution_digest,
        declared_outputs,
        mutation_events,
        observations,
        &[],
    )
}

#[cfg(target_os = "linux")]
fn open_kbuild_path_identity_no_follow(path: &Path) -> Result<File> {
    use std::os::unix::fs::OpenOptionsExt as _;

    let mut options = OpenOptions::new();
    options
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_PATH);
    options
        .open(path)
        .with_context(|| format!("open captured Kbuild output identity {}", path.display()))
}

#[cfg(all(unix, not(target_os = "linux")))]
fn open_kbuild_path_identity_no_follow(_path: &Path) -> Result<File> {
    anyhow::bail!("Kbuild no-follow path identity requires Linux")
}

#[cfg(unix)]
fn witness_current_kbuild_symlink_output(
    path: &Path,
) -> Result<(
    KbuildOutputObjectIdentity,
    KbuildStablePathMetadata,
    Vec<u8>,
)> {
    use std::os::unix::fs::MetadataExt as _;

    let file = open_kbuild_path_identity_no_follow(path)?;
    let before_metadata = file
        .metadata()
        .with_context(|| format!("stat captured Kbuild output link {}", path.display()))?;
    let before = KbuildStablePathMetadata::from_metadata(&before_metadata);
    let mount_id = kbuild_file_mount_id(&file)?;
    if before.inode == 0
        || !before_metadata.file_type().is_symlink()
        || before_metadata.nlink() != 1
    {
        anyhow::bail!("captured Kbuild output link has the wrong current shape");
    }
    let target = std::fs::read_link(path)
        .with_context(|| format!("read captured Kbuild output link {}", path.display()))?;
    let target = os_bytes(target.as_os_str());
    if before.bytes
        != u64::try_from(target.len())
            .context("Kbuild output link target length does not fit u64")?
    {
        anyhow::bail!("captured Kbuild output link has an inconsistent target length");
    }
    let after_metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("restat captured Kbuild output link {}", path.display()))?;
    let after = KbuildStablePathMetadata::from_metadata(&after_metadata);
    let after_target = std::fs::read_link(path)
        .with_context(|| format!("reread captured Kbuild output link {}", path.display()))?;
    if after != before
        || !after_metadata.file_type().is_symlink()
        || after_metadata.nlink() != 1
        || os_bytes(after_target.as_os_str()) != target
    {
        anyhow::bail!("captured Kbuild output link changed while it was witnessed");
    }
    let parent = path
        .parent()
        .context("captured Kbuild output link has no parent")?;
    let canonical_parent = parent
        .canonicalize()
        .with_context(|| format!("canonicalize Kbuild output parent {}", parent.display()))?;
    if canonical_parent != parent {
        anyhow::bail!("captured Kbuild output link parent is an alias");
    }
    let reopened = open_kbuild_path_identity_no_follow(path)?;
    let reopened_metadata = reopened
        .metadata()
        .with_context(|| format!("reopen captured Kbuild output link {}", path.display()))?;
    if KbuildStablePathMetadata::from_metadata(&reopened_metadata) != before
        || !reopened_metadata.file_type().is_symlink()
        || reopened_metadata.nlink() != 1
        || kbuild_file_mount_id(&reopened)? != mount_id
    {
        anyhow::bail!("captured Kbuild output link path changed while it was witnessed");
    }
    Ok((
        KbuildOutputObjectIdentity {
            device: before.device,
            inode: before.inode,
            mount_id,
        },
        before,
        target,
    ))
}

#[cfg(unix)]
fn witness_current_kbuild_directory_output(
    path: &Path,
) -> Result<(KbuildOutputObjectIdentity, KbuildStablePathMetadata)> {
    let directory = open_kbuild_path_identity_no_follow(path)?;
    let before_metadata = directory
        .metadata()
        .with_context(|| format!("stat captured Kbuild output directory {}", path.display()))?;
    let before = KbuildStablePathMetadata::from_metadata(&before_metadata);
    let mount_id = kbuild_file_mount_id(&directory)?;
    if before.inode == 0 || !before_metadata.file_type().is_dir() {
        anyhow::bail!("captured Kbuild output directory has the wrong shape");
    }
    let canonical = path.canonicalize().with_context(|| {
        format!(
            "canonicalize captured Kbuild output directory {}",
            path.display()
        )
    })?;
    if canonical != path {
        anyhow::bail!("captured Kbuild output directory path is an alias");
    }
    let reopened = open_kbuild_path_identity_no_follow(path)?;
    let reopened_metadata = reopened
        .metadata()
        .with_context(|| format!("reopen Kbuild output directory {}", path.display()))?;
    if KbuildStablePathMetadata::from_metadata(&reopened_metadata) != before
        || !reopened_metadata.file_type().is_dir()
        || kbuild_file_mount_id(&reopened)? != mount_id
    {
        anyhow::bail!("captured Kbuild output directory changed while it was witnessed");
    }
    Ok((
        KbuildOutputObjectIdentity {
            device: before.device,
            inode: before.inode,
            mount_id,
        },
        before,
    ))
}

#[cfg(unix)]
fn witness_current_kbuild_output(
    path: &Path,
    captured: KbuildFinalOutputValue,
) -> Result<KbuildMaterializedFinalOutput> {
    use std::os::unix::fs::MetadataExt as _;

    if captured.kind == KbuildFinalOutputKind::Directory {
        let (object, metadata) = witness_current_kbuild_directory_output(path)?;
        if object != captured.object || metadata.mode != captured.mode {
            anyhow::bail!("captured Kbuild output directory changed before materialization");
        }
        return Ok(KbuildMaterializedFinalOutput {
            path: path.to_path_buf(),
            kind: KbuildFinalOutputKind::Directory,
            bytes: Vec::new(),
            mode: captured.mode,
        });
    }

    if captured.kind == KbuildFinalOutputKind::Symlink {
        let (object, metadata, target) = witness_current_kbuild_symlink_output(path)?;
        let bytes = u64::try_from(target.len())
            .context("current Kbuild output link target length does not fit u64")?;
        if object != captured.object
            || metadata.mode != captured.mode
            || bytes != captured.bytes
            || *blake3::hash(&target).as_bytes() != captured.digest
        {
            anyhow::bail!("captured Kbuild output link changed before materialization");
        }
        return Ok(KbuildMaterializedFinalOutput {
            path: path.to_path_buf(),
            kind: KbuildFinalOutputKind::Symlink,
            bytes: target,
            mode: captured.mode,
        });
    }
    if captured.kind != KbuildFinalOutputKind::RegularFile {
        anyhow::bail!("captured Kbuild output has an unsupported value kind");
    }
    let file = open_kbuild_input_no_follow(path)?;
    let before_metadata = file
        .metadata()
        .with_context(|| format!("stat captured Kbuild output {}", path.display()))?;
    let before = KbuildStablePathMetadata::from_metadata(&before_metadata);
    let before_mount_id = kbuild_file_mount_id(&file)?;
    if before.inode == 0
        || !before_metadata.file_type().is_file()
        || before.mode != captured.mode
        || before.device != captured.object.device
        || before.inode != captured.object.inode
        || before_mount_id != captured.object.mount_id
        || before_metadata.nlink() != 1
    {
        anyhow::bail!("captured Kbuild output has the wrong current shape");
    }
    let limit = captured
        .bytes
        .checked_add(1)
        .context("captured Kbuild output byte limit overflowed")?;
    let mut limited = file.take(limit);
    let mut contents = Vec::new();
    limited
        .read_to_end(&mut contents)
        .with_context(|| format!("read captured Kbuild output {}", path.display()))?;
    let after_metadata = limited
        .get_ref()
        .metadata()
        .with_context(|| format!("restat captured Kbuild output {}", path.display()))?;
    let after = KbuildStablePathMetadata::from_metadata(&after_metadata);
    let current_bytes =
        u64::try_from(contents.len()).context("current Kbuild output length does not fit u64")?;
    if after != before
        || current_bytes != captured.bytes
        || *blake3::hash(&contents).as_bytes() != captured.digest
        || before.bytes != captured.bytes
        || after_metadata.nlink() != 1
    {
        anyhow::bail!("captured Kbuild output changed before materialization");
    }
    let canonical = path
        .canonicalize()
        .with_context(|| format!("canonicalize captured Kbuild output {}", path.display()))?;
    if canonical != path {
        anyhow::bail!("captured Kbuild output path is an alias");
    }
    let reopened = open_kbuild_input_no_follow(path)?;
    let reopened_metadata = reopened
        .metadata()
        .with_context(|| format!("reopen captured Kbuild output {}", path.display()))?;
    if KbuildStablePathMetadata::from_metadata(&reopened_metadata) != before
        || reopened_metadata.nlink() != 1
        || kbuild_file_mount_id(&reopened)? != captured.object.mount_id
    {
        anyhow::bail!("captured Kbuild output path changed while it was witnessed");
    }
    Ok(KbuildMaterializedFinalOutput {
        path: path.to_path_buf(),
        kind: KbuildFinalOutputKind::RegularFile,
        bytes: contents,
        mode: captured.mode,
    })
}

#[cfg(unix)]
fn witness_current_kbuild_output_after_rename(
    path: &Path,
    action_index: u64,
    output_index: u64,
) -> Result<KbuildFinalOutputValue> {
    use std::os::unix::fs::MetadataExt as _;

    let path_metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("stat renamed Kbuild output {}", path.display()))?;
    if path_metadata.file_type().is_symlink() {
        let (object, metadata, target) = witness_current_kbuild_symlink_output(path)?;
        let bytes = u64::try_from(target.len())
            .context("renamed Kbuild output link target length does not fit u64")?;
        return Ok(KbuildFinalOutputValue {
            action_index,
            output_index,
            object,
            kind: KbuildFinalOutputKind::Symlink,
            bytes,
            digest: *blake3::hash(&target).as_bytes(),
            mode: metadata.mode,
            boundary: KbuildFinalOutputBoundary::PostCaptureRename,
        });
    }
    let file = open_kbuild_input_no_follow(path)?;
    let before_metadata = file
        .metadata()
        .with_context(|| format!("stat renamed Kbuild output {}", path.display()))?;
    let before = KbuildStablePathMetadata::from_metadata(&before_metadata);
    let mount_id = kbuild_file_mount_id(&file)?;
    if before.inode == 0 || !before_metadata.file_type().is_file() || before_metadata.nlink() != 1 {
        anyhow::bail!("renamed Kbuild output has the wrong current shape");
    }
    let limit = before
        .bytes
        .checked_add(1)
        .context("renamed Kbuild output byte limit overflowed")?;
    let mut limited = file.take(limit);
    let mut contents = Vec::new();
    limited
        .read_to_end(&mut contents)
        .with_context(|| format!("read renamed Kbuild output {}", path.display()))?;
    let after_metadata = limited
        .get_ref()
        .metadata()
        .with_context(|| format!("restat renamed Kbuild output {}", path.display()))?;
    let after = KbuildStablePathMetadata::from_metadata(&after_metadata);
    let bytes =
        u64::try_from(contents.len()).context("renamed Kbuild output length does not fit u64")?;
    if after != before || bytes != before.bytes || after_metadata.nlink() != 1 {
        anyhow::bail!("renamed Kbuild output changed while it was read");
    }
    let canonical = path
        .canonicalize()
        .with_context(|| format!("canonicalize renamed Kbuild output {}", path.display()))?;
    if canonical != path {
        anyhow::bail!("renamed Kbuild output path is an alias");
    }
    let reopened = open_kbuild_input_no_follow(path)?;
    let reopened_metadata = reopened
        .metadata()
        .with_context(|| format!("reopen renamed Kbuild output {}", path.display()))?;
    if KbuildStablePathMetadata::from_metadata(&reopened_metadata) != before
        || reopened_metadata.nlink() != 1
        || kbuild_file_mount_id(&reopened)? != mount_id
    {
        anyhow::bail!("renamed Kbuild output changed while it was witnessed");
    }
    Ok(KbuildFinalOutputValue {
        action_index,
        output_index,
        object: KbuildOutputObjectIdentity {
            device: before.device,
            inode: before.inode,
            mount_id,
        },
        kind: KbuildFinalOutputKind::RegularFile,
        bytes,
        digest: *blake3::hash(&contents).as_bytes(),
        mode: before.mode,
        boundary: KbuildFinalOutputBoundary::PostCaptureRename,
    })
}

#[cfg(unix)]
fn witness_current_kbuild_output_after_mode_change(
    path: &Path,
    action_index: u64,
    output_index: u64,
    prior: &KbuildFinalOutputObservation,
    mutation: &KbuildMutationCandidate,
) -> Result<KbuildFinalOutputValue> {
    let mut current = witness_current_kbuild_output_after_rename(path, action_index, output_index)?;
    if current.kind != KbuildFinalOutputKind::RegularFile
        || current.object != prior.object
        || current.bytes != prior.bytes
        || current.digest != prior.digest
        || mutation
            .object
            .is_some_and(|object| object != current.object)
    {
        anyhow::bail!("Kbuild final mode change and prior value do not identify one stable file");
    }
    current.boundary = KbuildFinalOutputBoundary::PostCaptureModeChange;
    Ok(current)
}

#[cfg(unix)]
fn witness_current_kbuild_output_after_shared_mapping(
    path: &Path,
    action_index: u64,
    output_index: u64,
    mutation: &KbuildMutationCandidate,
) -> Result<KbuildFinalOutputValue> {
    let mut current = witness_current_kbuild_output_after_rename(path, action_index, output_index)?;
    if current.kind != KbuildFinalOutputKind::RegularFile || mutation.object != Some(current.object)
    {
        anyhow::bail!(
            "Kbuild final writable shared mapping and current path do not identify one stable file"
        );
    }
    current.boundary = KbuildFinalOutputBoundary::PostCaptureSharedMapping;
    Ok(current)
}

#[cfg(unix)]
fn witness_current_kbuild_output_after_symlink_creation(
    path: &Path,
    action_index: u64,
    output_index: u64,
    owner: KbuildProcessOwner,
    mutation: &KbuildMutationCandidate,
    creations: &[KbuildSymlinkCreationValue],
) -> Result<KbuildFinalOutputValue> {
    if mutation.kind != KbuildMutationCandidateKind::SymbolicLinkCreation
        || mutation.object.is_some()
        || mutation.path != path
    {
        anyhow::bail!("Kbuild final symbolic-link creation is malformed");
    }
    let mut matching = creations.iter().filter(|creation| {
        creation.owner == owner
            && creation.process == mutation.process
            && creation.stream_ordinal == mutation.stream_ordinal
            && creation.syscall_index == mutation.syscall_index
            && creation.path == mutation.path
    });
    let creation = matching
        .next()
        .context("Kbuild final symbolic link has no exact creation value")?;
    if matching.next().is_some() {
        anyhow::bail!("Kbuild final symbolic link repeats its creation value");
    }
    let (object, metadata, target) = witness_current_kbuild_symlink_output(path)?;
    if target != creation.target {
        anyhow::bail!("Kbuild final symbolic link does not match its creation target");
    }
    let bytes = u64::try_from(target.len())
        .context("Kbuild final symbolic-link target length does not fit u64")?;
    Ok(KbuildFinalOutputValue {
        action_index,
        output_index,
        object,
        kind: KbuildFinalOutputKind::Symlink,
        bytes,
        digest: *blake3::hash(&target).as_bytes(),
        mode: metadata.mode,
        boundary: KbuildFinalOutputBoundary::PostCaptureSymlinkCreation,
    })
}

#[cfg(unix)]
fn materialize_kbuild_final_outputs(
    captured: &KbuildFinalOutputValueSeal,
    declared_outputs: &BTreeMap<u64, Vec<PathBuf>>,
) -> Result<KbuildMaterializedFinalOutputs> {
    let action_count = u64::try_from(declared_outputs.len())
        .context("Kbuild final-output action count does not fit u64")?;
    let mut values = BTreeMap::new();
    for value in &captured.outputs {
        if values
            .insert((value.action_index, value.output_index), *value)
            .is_some()
        {
            anyhow::bail!("Kbuild final-output materialization repeats an output position");
        }
    }
    if u64::try_from(values.len()).context("Kbuild final-output count does not fit u64")?
        != captured.persistent_outputs
    {
        anyhow::bail!("Kbuild final-output materialization has incomplete captured values");
    }

    let mut output_files = 0_u64;
    let mut output_symlinks = 0_u64;
    let mut output_directories = 0_u64;
    let mut output_bytes = 0_u64;
    let mut actions = Vec::with_capacity(declared_outputs.len());
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-final-output-materialization.v3\0");
    hasher.update(&captured.graph_digest);
    hasher.update(&captured.stream_digest);
    hasher.update(&captured.assignment_digest);
    hasher.update(&captured.value_digest);
    hasher.update(&action_count.to_le_bytes());
    for action_index in 0..action_count {
        let paths = declared_outputs
            .get(&action_index)
            .context("Kbuild final-output declarations omit an action")?;
        let path_count =
            u64::try_from(paths.len()).context("Kbuild action output count does not fit u64")?;
        hasher.update(&action_index.to_le_bytes());
        hasher.update(&path_count.to_le_bytes());
        let mut action_outputs = Vec::with_capacity(paths.len());
        for (output_index, path) in paths.iter().enumerate() {
            let output_index =
                u64::try_from(output_index).context("Kbuild output index does not fit u64")?;
            let value = values
                .remove(&(action_index, output_index))
                .context("Kbuild declared output has no captured final value")?;
            let output = witness_current_kbuild_output(path, value).with_context(|| {
                format!("validate current Kbuild action {action_index} output {output_index}")
            })?;
            match value.kind {
                KbuildFinalOutputKind::RegularFile => {
                    output_files = output_files
                        .checked_add(1)
                        .context("Kbuild materialized file-output count overflowed")?;
                }
                KbuildFinalOutputKind::Symlink => {
                    output_symlinks = output_symlinks
                        .checked_add(1)
                        .context("Kbuild materialized link-output count overflowed")?;
                }
                KbuildFinalOutputKind::Directory => {
                    output_directories = output_directories
                        .checked_add(1)
                        .context("Kbuild materialized directory-output count overflowed")?;
                }
            }
            output_bytes = output_bytes
                .checked_add(value.bytes)
                .context("Kbuild materialized output bytes overflowed")?;
            hasher.update(&output_index.to_le_bytes());
            hasher.update(&[match value.kind {
                KbuildFinalOutputKind::RegularFile => 0,
                KbuildFinalOutputKind::Symlink => 1,
                KbuildFinalOutputKind::Directory => 2,
            }]);
            hasher.update(&value.bytes.to_le_bytes());
            hasher.update(&value.digest);
            hasher.update(&value.mode.to_le_bytes());
            action_outputs.push(output);
        }
        actions.push(action_outputs);
    }
    let output_count = output_files
        .checked_add(output_symlinks)
        .and_then(|count| count.checked_add(output_directories))
        .context("Kbuild materialized output count overflowed")?;
    if !values.is_empty() || output_count != captured.persistent_outputs {
        anyhow::bail!("Kbuild final-output materialization changed the declared output set");
    }
    hasher.update(&output_files.to_le_bytes());
    hasher.update(&output_symlinks.to_le_bytes());
    hasher.update(&output_directories.to_le_bytes());
    hasher.update(&output_bytes.to_le_bytes());
    let seal = KbuildFinalOutputMaterializationSeal {
        graph_digest: captured.graph_digest,
        stream_digest: captured.stream_digest,
        assignment_digest: captured.assignment_digest,
        captured_value_digest: captured.value_digest,
        output_files,
        output_symlinks,
        output_directories,
        output_bytes,
        materialization_digest: *hasher.finalize().as_bytes(),
    };
    Ok(KbuildMaterializedFinalOutputs { seal, actions })
}

#[cfg(unix)]
fn hash_kbuild_bytes(hasher: &mut blake3::Hasher, bytes: &[u8]) -> Result<()> {
    let length = u64::try_from(bytes.len()).context("Kbuild byte length does not fit u64")?;
    hasher.update(&length.to_le_bytes());
    hasher.update(bytes);
    Ok(())
}

#[cfg(unix)]
const RECEIPTLESS_KBUILD_LOGICAL_ID_PREFIX: &str = "rush-kbuild-native-output-v1:";

#[cfg(unix)]
fn kbuild_action_logical_id(
    receipt_target: Option<&[u8]>,
    output_paths: &BTreeSet<ExternalPathKey>,
) -> Result<String> {
    if let Some(target) = receipt_target {
        let logical_id =
            String::from_utf8(target.to_vec()).context("Kbuild receipt target is not UTF-8")?;
        if logical_id.starts_with(RECEIPTLESS_KBUILD_LOGICAL_ID_PREFIX) {
            anyhow::bail!("Kbuild receipt target uses the reserved receiptless-action prefix");
        }
        return Ok(logical_id);
    }
    if output_paths.is_empty() {
        anyhow::bail!("receiptless Kbuild action has no output identity");
    }
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-receiptless-action-output-set.v1\0");
    let output_count =
        u64::try_from(output_paths.len()).context("Kbuild output count does not fit u64")?;
    hasher.update(&output_count.to_le_bytes());
    for output in output_paths {
        hash_kbuild_bytes(&mut hasher, output.root.as_bytes())?;
        hash_kbuild_bytes(&mut hasher, &output.path)?;
    }
    Ok(format!(
        "{RECEIPTLESS_KBUILD_LOGICAL_ID_PREFIX}{}",
        hasher.finalize().to_hex()
    ))
}

#[cfg(unix)]
fn census_kbuild_final_namespace(
    output_root: &Path,
    outputs: &KbuildMaterializedFinalOutputs,
) -> Result<KbuildFinalNamespaceCensusSeal> {
    use std::os::unix::ffi::OsStrExt as _;
    use std::os::unix::fs::MetadataExt as _;

    let root_metadata = std::fs::symlink_metadata(output_root)
        .with_context(|| format!("stat Kbuild output root {}", output_root.display()))?;
    if !root_metadata.file_type().is_dir() {
        anyhow::bail!("Kbuild output root is not a directory");
    }

    let mut declared = BTreeMap::new();
    let mut required_directories = BTreeSet::new();
    for output in outputs.actions.iter().flatten() {
        let relative = output.path.strip_prefix(output_root).with_context(|| {
            format!(
                "captured Kbuild output {} is outside its root",
                output.path.display()
            )
        })?;
        let relative = relative.as_os_str().as_bytes().to_vec();
        if relative.is_empty() || declared.insert(relative, output.kind).is_some() {
            anyhow::bail!("Kbuild final namespace repeats an invalid declared output");
        }
        let mut parent = output.path.parent();
        while let Some(path) = parent {
            if path == output_root {
                break;
            }
            let relative = path
                .strip_prefix(output_root)
                .context("Kbuild output ancestor is outside its root")?
                .as_os_str()
                .as_bytes()
                .to_vec();
            if relative.is_empty() {
                anyhow::bail!("Kbuild output has an invalid ancestor");
            }
            required_directories.insert(relative);
            parent = path.parent();
        }
        if parent.is_none() {
            anyhow::bail!("Kbuild output root is not an ancestor of its output");
        }
    }
    for relative in declared.keys() {
        required_directories.remove(relative);
    }

    let mut entries = walkdir::WalkDir::new(output_root)
        .follow_links(false)
        .into_iter()
        .skip(1)
        .map(|entry| {
            let entry = entry.context("walk Kbuild final namespace")?;
            let relative = entry
                .path()
                .strip_prefix(output_root)
                .context("Kbuild namespace entry is outside its root")?
                .as_os_str()
                .as_bytes()
                .to_vec();
            Ok((relative, entry.into_path()))
        })
        .collect::<Result<Vec<_>>>()?;
    entries.sort_by(|left, right| left.0.cmp(&right.0));

    let mut seen_declared = BTreeSet::new();
    let mut seen_required_directories = BTreeSet::new();
    let mut declared_output_files = 0_u64;
    let mut declared_output_symlinks = 0_u64;
    let mut declared_output_directories = 0_u64;
    let mut required_output_directories = 0_u64;
    let mut unattributed_regular_files = 0_u64;
    let mut unattributed_directories = 0_u64;
    let mut unattributed_symlinks = 0_u64;
    let mut unattributed_special_entries = 0_u64;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-final-namespace-census.v3\0");
    hasher.update(&outputs.seal.graph_digest);
    hasher.update(&outputs.seal.stream_digest);
    hasher.update(&outputs.seal.assignment_digest);
    hasher.update(&outputs.seal.materialization_digest);
    for (relative, path) in &entries {
        let metadata = std::fs::symlink_metadata(path)
            .with_context(|| format!("stat Kbuild namespace entry {}", path.display()))?;
        let file_type = metadata.file_type();
        let class = if let Some(kind) = declared.get(relative) {
            if !seen_declared.insert(relative.clone()) {
                anyhow::bail!("declared Kbuild namespace output is repeated");
            }
            match kind {
                KbuildFinalOutputKind::RegularFile if file_type.is_file() => {
                    declared_output_files = declared_output_files
                        .checked_add(1)
                        .context("Kbuild declared file-output count overflowed")?;
                    0_u8
                }
                KbuildFinalOutputKind::Symlink if file_type.is_symlink() => {
                    declared_output_symlinks = declared_output_symlinks
                        .checked_add(1)
                        .context("Kbuild declared link-output count overflowed")?;
                    1
                }
                KbuildFinalOutputKind::Directory if file_type.is_dir() => {
                    declared_output_directories = declared_output_directories
                        .checked_add(1)
                        .context("Kbuild declared directory-output count overflowed")?;
                    2
                }
                _ => anyhow::bail!("declared Kbuild namespace output has the wrong shape"),
            }
        } else if required_directories.contains(relative) {
            if !file_type.is_dir() || !seen_required_directories.insert(relative.clone()) {
                anyhow::bail!("required Kbuild output ancestor is not one directory");
            }
            required_output_directories = required_output_directories
                .checked_add(1)
                .context("Kbuild required output-directory count overflowed")?;
            3
        } else if file_type.is_file() {
            unattributed_regular_files = unattributed_regular_files
                .checked_add(1)
                .context("Kbuild unattributed regular-file count overflowed")?;
            4
        } else if file_type.is_dir() {
            unattributed_directories = unattributed_directories
                .checked_add(1)
                .context("Kbuild unattributed directory count overflowed")?;
            5
        } else if file_type.is_symlink() {
            unattributed_symlinks = unattributed_symlinks
                .checked_add(1)
                .context("Kbuild unattributed symlink count overflowed")?;
            6
        } else {
            unattributed_special_entries = unattributed_special_entries
                .checked_add(1)
                .context("Kbuild unattributed special-entry count overflowed")?;
            7
        };
        hasher.update(&[class]);
        hash_kbuild_bytes(&mut hasher, relative)?;
        hasher.update(&metadata.dev().to_le_bytes());
        hasher.update(&metadata.ino().to_le_bytes());
        hasher.update(&metadata.mode().to_le_bytes());
        hasher.update(&metadata.nlink().to_le_bytes());
        hasher.update(&metadata.len().to_le_bytes());
        if file_type.is_symlink() {
            let target = std::fs::read_link(path)
                .with_context(|| format!("read Kbuild namespace link {}", path.display()))?;
            hash_kbuild_bytes(&mut hasher, target.as_os_str().as_bytes())?;
        } else {
            hasher.update(&0_u64.to_le_bytes());
        }
    }
    if seen_declared.len() != declared.len() {
        anyhow::bail!("Kbuild final namespace omits a declared output");
    }
    if seen_required_directories != required_directories {
        anyhow::bail!("Kbuild final namespace omits a required output directory");
    }

    let entries = u64::try_from(entries.len())
        .context("Kbuild final namespace entry count does not fit u64")?;
    for count in [
        entries,
        declared_output_files,
        declared_output_symlinks,
        declared_output_directories,
        required_output_directories,
        unattributed_regular_files,
        unattributed_directories,
        unattributed_symlinks,
        unattributed_special_entries,
    ] {
        hasher.update(&count.to_le_bytes());
    }
    let classified = declared_output_files
        .checked_add(declared_output_symlinks)
        .and_then(|count| count.checked_add(declared_output_directories))
        .and_then(|count| count.checked_add(required_output_directories))
        .and_then(|count| count.checked_add(unattributed_regular_files))
        .and_then(|count| count.checked_add(unattributed_directories))
        .and_then(|count| count.checked_add(unattributed_symlinks))
        .and_then(|count| count.checked_add(unattributed_special_entries))
        .context("Kbuild final namespace classified count overflowed")?;
    if classified != entries {
        anyhow::bail!("Kbuild final namespace partition is incomplete");
    }
    Ok(KbuildFinalNamespaceCensusSeal {
        graph_digest: outputs.seal.graph_digest,
        stream_digest: outputs.seal.stream_digest,
        assignment_digest: outputs.seal.assignment_digest,
        final_output_materialization_digest: outputs.seal.materialization_digest,
        census_digest: *hasher.finalize().as_bytes(),
        entries,
        declared_output_files,
        declared_output_symlinks,
        declared_output_directories,
        required_output_directories,
        unattributed_regular_files,
        unattributed_directories,
        unattributed_symlinks,
        unattributed_special_entries,
    })
}

#[cfg(unix)]
fn parse_kbuild_config_values(bytes: &[u8]) -> Result<BTreeMap<String, Vec<u8>>> {
    let mut values = BTreeMap::new();
    for line in bytes.split(|byte| *byte == b'\n') {
        let parsed = if let Some(rest) = line.strip_prefix(b"CONFIG_") {
            if let Some(equal) = rest.iter().position(|byte| *byte == b'=') {
                Some((
                    format!(
                        "CONFIG_{}",
                        std::str::from_utf8(&rest[..equal])
                            .context("captured Kconfig symbol is not UTF-8")?
                    ),
                    rest[equal + 1..].to_vec(),
                ))
            } else {
                None
            }
        } else {
            let symbol = line
                .strip_prefix(b"# ")
                .and_then(|line| line.strip_suffix(b" is not set"))
                .filter(|symbol| symbol.starts_with(b"CONFIG_"));
            match symbol {
                Some(symbol) => Some((
                    std::str::from_utf8(symbol)
                        .context("captured Kconfig symbol is not UTF-8")?
                        .to_string(),
                    b"n".to_vec(),
                )),
                None => None,
            }
        };
        if let Some((name, value)) = parsed {
            if name.as_bytes().contains(&0) || values.insert(name, value).is_some() {
                anyhow::bail!("captured Kconfig value source repeats an invalid symbol");
            }
        }
    }
    Ok(values)
}

#[cfg(unix)]
fn require_fine_grained_kconfig_inputs(
    selected_kconfig: Option<&ExternalPathKey>,
    config_dependencies: &[String],
    inputs: &[ExternalInput],
) -> Result<()> {
    if config_dependencies.is_empty() {
        return Ok(());
    }
    if selected_kconfig.is_some_and(|selected| inputs.iter().any(|input| &input.path == selected)) {
        anyhow::bail!("Kbuild action directly observes the selected configuration source");
    }
    Ok(())
}

#[cfg(unix)]
fn kbuild_replay_action_inputs(
    action_index: u64,
    external_declarations: &[ExternalInput],
    external_values: &[ExternalInputKey],
    generated_inputs: &[KbuildGeneratedActionInput],
) -> Result<(Vec<ExternalInput>, Vec<ExternalInputKey>)> {
    if external_declarations.len() != external_values.len() {
        anyhow::bail!("Kbuild action input declarations and values have different lengths");
    }
    let mut declarations = Vec::with_capacity(
        external_declarations
            .len()
            .checked_add(generated_inputs.len())
            .context("Kbuild replay input count overflowed")?,
    );
    let mut values = Vec::with_capacity(declarations.capacity());
    let mut paths = BTreeSet::new();
    for (declaration, value) in external_declarations.iter().zip(external_values) {
        if declaration.path != value.path || !paths.insert(declaration.path.clone()) {
            anyhow::bail!("Kbuild external action inputs are not one-to-one");
        }
        declarations.push(declaration.clone());
        values.push(value.clone());
    }
    for input in generated_inputs {
        if input.consumer_action_index != action_index
            || input.path.root != "obj"
            || !matches!(input.value, ExternalInputValue::File { .. })
            || !paths.insert(input.path.clone())
        {
            anyhow::bail!("Kbuild generated action inputs are not one-to-one");
        }
        declarations.push(ExternalInput {
            path: input.path.clone(),
            kind: ExternalInputKind::File,
        });
        values.push(ExternalInputKey {
            path: input.path.clone(),
            value: input.value.clone(),
        });
    }
    Ok((declarations, values))
}

#[cfg(unix)]
fn kbuild_mandatory_action_contracts_by_index<'a>(
    mandatory: &'a KbuildMandatoryActionEligibilityContracts,
    procfs_directories: &KbuildProcfsDirectoryCensus,
) -> Result<BTreeMap<u64, &'a KbuildMandatoryActionExecutionContract>> {
    if mandatory.seal.actions.len() != mandatory.actions.len() {
        anyhow::bail!("Kbuild mandatory-action eligibility is incomplete");
    }
    let mut by_index = BTreeMap::new();
    let mut procfs_directory_ordinals = BTreeSet::new();
    for (sealed, contract) in mandatory.seal.actions.iter().zip(&mandatory.actions) {
        let contract_openings = contract
            .procfs_directory_checkpoints
            .iter()
            .map(|checkpoint| {
                (
                    checkpoint.observation.process,
                    checkpoint.anchor.open_stream_ordinal,
                )
            })
            .collect::<BTreeSet<_>>();
        if sealed.action_index != contract.action_index
            || usize::try_from(sealed.procfs_directory_observations).ok()
                != Some(contract.procfs_directory_checkpoints.len())
            || usize::try_from(sealed.procfs_directory_openings).ok()
                != Some(contract_openings.len())
            || by_index.insert(contract.action_index, contract).is_some()
        {
            anyhow::bail!("Kbuild mandatory-action contracts are not one-to-one");
        }
        for checkpoint in &contract.procfs_directory_checkpoints {
            if checkpoint.observation.owner != KbuildProcessOwner::Action(contract.action_index)
                || procfs_directories
                    .checkpoints
                    .get(&checkpoint.observation.ordinal)
                    != Some(checkpoint)
                || !procfs_directory_ordinals.insert(checkpoint.observation.ordinal)
            {
                anyhow::bail!("Kbuild mandatory procfs directory contract changed during assembly");
            }
        }
    }
    if procfs_directory_ordinals.len() != procfs_directories.checkpoints.len() {
        anyhow::bail!("Kbuild mandatory procfs directory contract is incomplete");
    }
    Ok(by_index)
}

#[cfg(unix)]
#[derive(Debug)]
struct KbuildAnalysisStage {
    expected_inputs: BTreeMap<ExternalPathKey, ExternalInputValue>,
    required_blocked_actions: BTreeSet<usize>,
}

#[cfg(unix)]
fn kbuild_action_dependency_closure(
    actions: &[ExternalAction],
    action_index: &BTreeMap<&str, usize>,
    seeds: BTreeSet<usize>,
) -> Result<BTreeSet<usize>> {
    let mut closure = BTreeSet::new();
    let mut pending = seeds.into_iter().collect::<Vec<_>>();
    while let Some(index) = pending.pop() {
        let action = actions
            .get(index)
            .context("Kbuild analysis stage references an unknown replay action")?;
        if !closure.insert(index) {
            continue;
        }
        for dependency in &action.dependencies {
            pending.push(
                *action_index
                    .get(dependency.as_str())
                    .context("Kbuild analysis stage has an unknown action dependency")?,
            );
        }
    }
    Ok(closure)
}

#[cfg(unix)]
fn kbuild_captured_replay_action_id(
    captured_action_ids: &[Option<String>],
    index: u64,
) -> Result<&str> {
    let index =
        usize::try_from(index).context("Kbuild captured action index does not fit usize")?;
    captured_action_ids
        .get(index)
        .and_then(Option::as_deref)
        .context("Kbuild captured action has no replay action")
}

#[cfg(unix)]
fn kbuild_analysis_barriers(
    actions: &[ExternalAction],
    captured_action_ids: &[Option<String>],
    analyzer_inputs: &[KbuildAnalyzerGeneratedInput],
    analyzer_directory_checkpoints: &[KbuildAnalyzerDirectoryCheckpoint],
) -> Result<Vec<ExternalAnalysisBarrier>> {
    let mut action_index = BTreeMap::new();
    for (index, action) in actions.iter().enumerate() {
        if action_index
            .insert(action.logical_id.as_str(), index)
            .is_some()
        {
            anyhow::bail!("Kbuild analysis stages have repeated replay action identities");
        }
    }
    let captured_index = |index: u64| -> Result<usize> {
        let logical_id = kbuild_captured_replay_action_id(captured_action_ids, index)
            .context("resolve Kbuild analysis stage action")?;
        action_index
            .get(logical_id)
            .copied()
            .context("Kbuild analysis stage action identity disappeared")
    };

    let mut stages = BTreeMap::<BTreeSet<usize>, KbuildAnalysisStage>::new();
    let mut insert_stage = |producers: BTreeSet<usize>,
                            path: ExternalPathKey,
                            value: ExternalInputValue,
                            required_blocked_actions: BTreeSet<usize>|
     -> Result<()> {
        if producers.is_empty() {
            anyhow::bail!("Kbuild analysis checkpoint has no producer closure");
        }
        let stage = stages
            .entry(producers)
            .or_insert_with(|| KbuildAnalysisStage {
                expected_inputs: BTreeMap::new(),
                required_blocked_actions: BTreeSet::new(),
            });
        match stage.expected_inputs.entry(path) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(value);
            }
            std::collections::btree_map::Entry::Occupied(entry) if entry.get() != &value => {
                anyhow::bail!("Kbuild analysis stage has conflicting checkpoint values");
            }
            std::collections::btree_map::Entry::Occupied(_) => {}
        }
        stage
            .required_blocked_actions
            .extend(required_blocked_actions);
        Ok(())
    };

    for input in analyzer_inputs {
        if input.path.root != "obj" || !matches!(input.value, ExternalInputValue::File { .. }) {
            anyhow::bail!("Kbuild analyzer generated-file checkpoint has the wrong shape");
        }
        let producer = captured_index(input.producer_action_index)?;
        if !actions[producer]
            .outputs
            .iter()
            .any(|output| output.path == input.path && output.kind == ExternalOutputKind::File)
        {
            anyhow::bail!("Kbuild analyzer generated-file checkpoint lost its producer");
        }
        let producers =
            kbuild_action_dependency_closure(actions, &action_index, BTreeSet::from([producer]))?;
        insert_stage(
            producers,
            input.path.clone(),
            input.value.clone(),
            BTreeSet::new(),
        )?;
    }

    for checkpoint in analyzer_directory_checkpoints {
        if checkpoint.path.root != "obj"
            || checkpoint.object.kind != KbuildInputObjectKind::Directory
            || !matches!(checkpoint.value, KbuildObservedInputValue::Directory { .. })
        {
            anyhow::bail!("Kbuild analyzer directory checkpoint has the wrong shape");
        }
        if checkpoint.analysis_internal_namespace_transaction {
            if checkpoint.provenance != KbuildAnalyzerDirectoryProvenance::SameOwnerPostCandidate
                || !checkpoint.before_actions.is_empty()
                || !checkpoint.after_actions.is_empty()
                || !checkpoint.unresolved_actions.is_empty()
                || !checkpoint.has_analyzer_effect
                || !checkpoint.has_analyzer_effect_before_observation
                || !checkpoint.has_analyzer_effect_after_observation
                || checkpoint.has_unresolved_analyzer_effect
                || !checkpoint.has_analyzer_directory_object_effect
                || !checkpoint.has_analyzer_directory_object_effect_before_observation
                || !checkpoint.has_analyzer_directory_object_effect_after_observation
                || checkpoint.candidate_action_boundary
            {
                anyhow::bail!("Kbuild analysis-internal directory proof changed");
            }
            continue;
        }
        let expected_candidate = !checkpoint.has_analyzer_effect
            && !checkpoint.has_unresolved_analyzer_effect
            && checkpoint.unresolved_actions.is_empty()
            && checkpoint
                .before_actions
                .is_disjoint(&checkpoint.after_actions);
        let analyzer_effects_are_listing_irrelevant = checkpoint.has_analyzer_effect
            && !checkpoint.has_analyzer_directory_object_effect
            && !checkpoint.has_analyzer_retained_name_effect;
        if checkpoint.candidate_action_boundary != expected_candidate
            || (!checkpoint.candidate_action_boundary && !analyzer_effects_are_listing_irrelevant)
            || !checkpoint.unresolved_actions.is_empty()
            || !checkpoint
                .before_actions
                .is_disjoint(&checkpoint.after_actions)
            || (checkpoint.has_unresolved_analyzer_effect
                && !analyzer_effects_are_listing_irrelevant)
            || checkpoint.has_analyzer_directory_object_effect
            || checkpoint.has_analyzer_retained_name_effect
        {
            anyhow::bail!(
                "Kbuild analyzer directory checkpoint {:?} is not causally enforceable: \
                 provenance={:?}, before={:?}, after={:?}, unresolved={:?}, \
                 analyzer_effect={}, unresolved_analyzer={}, analyzer_object={}, \
                 analyzer_retained_name={}, ignored_transient_members={:?}, \
                 added_receipt_members={:?}, \
                 observation=(ordinal {}, process {}, syscall {}, stream {}), \
                 internal_transaction={}, candidate={}",
                checkpoint.path.path,
                checkpoint.provenance,
                checkpoint.before_actions,
                checkpoint.after_actions,
                checkpoint.unresolved_actions,
                checkpoint.has_analyzer_effect,
                checkpoint.has_unresolved_analyzer_effect,
                checkpoint.has_analyzer_directory_object_effect,
                checkpoint.has_analyzer_retained_name_effect,
                checkpoint.analysis_ignored_transient_members,
                checkpoint.analysis_added_receipt_members,
                checkpoint.observation_ordinal,
                checkpoint.process,
                checkpoint.syscall_index,
                checkpoint.stream_ordinal,
                checkpoint.analysis_internal_namespace_transaction,
                checkpoint.candidate_action_boundary,
            );
        }
        let before = checkpoint
            .before_actions
            .iter()
            .map(|index| captured_index(*index))
            .collect::<Result<BTreeSet<_>>>()?;
        let after = checkpoint
            .after_actions
            .iter()
            .map(|index| captured_index(*index))
            .collect::<Result<BTreeSet<_>>>()?;
        let producers = kbuild_action_dependency_closure(actions, &action_index, before)?;
        if !producers.is_disjoint(&after) {
            anyhow::bail!("Kbuild analyzer directory checkpoint crosses its producer closure");
        }
        insert_stage(
            producers,
            obj_path(checkpoint.path.path.clone()),
            ExternalInputValue::DirectoryListing {
                digest: checkpoint.analysis_listing_digest,
            },
            after,
        )?;
    }

    let mut remaining = stages.into_iter().collect::<Vec<_>>();
    remaining.sort_by(|(left, _), (right, _)| {
        left.len().cmp(&right.len()).then_with(|| left.cmp(right))
    });
    let mut causal_order = Vec::with_capacity(remaining.len());
    while !remaining.is_empty() {
        let Some(next) = remaining.iter().position(|(producers, _)| {
            remaining
                .iter()
                .all(|(_, stage)| stage.required_blocked_actions.is_disjoint(producers))
        }) else {
            anyhow::bail!("Kbuild analysis stages have a causal ordering cycle");
        };
        causal_order.push(remaining.remove(next));
    }

    let mut ordered = Vec::<(BTreeSet<usize>, KbuildAnalysisStage)>::new();
    let mut previous = BTreeSet::new();
    for (producers, mut stage) in causal_order {
        let cumulative = previous.union(&producers).copied().collect::<BTreeSet<_>>();
        if !stage.required_blocked_actions.is_disjoint(&cumulative) {
            anyhow::bail!("Kbuild analysis stage crossed a required blocked action");
        }
        if cumulative == previous {
            let (_, prior) = ordered
                .last_mut()
                .context("Kbuild analysis stage has no cumulative producer closure")?;
            for (path, value) in stage.expected_inputs {
                match prior.expected_inputs.entry(path) {
                    std::collections::btree_map::Entry::Vacant(entry) => {
                        entry.insert(value);
                    }
                    std::collections::btree_map::Entry::Occupied(entry)
                        if entry.get() != &value =>
                    {
                        anyhow::bail!(
                            "Kbuild cumulative analysis stage has conflicting checkpoint values"
                        );
                    }
                    std::collections::btree_map::Entry::Occupied(_) => {}
                }
            }
            prior
                .required_blocked_actions
                .append(&mut stage.required_blocked_actions);
        } else {
            previous = cumulative.clone();
            ordered.push((cumulative, stage));
        }
    }

    let mut previous = BTreeSet::new();
    let all_actions = (0..actions.len()).collect::<BTreeSet<_>>();
    let mut barriers = Vec::with_capacity(ordered.len());
    for (producers, stage) in ordered {
        if !previous.is_subset(&producers) || previous == producers {
            anyhow::bail!("Kbuild analysis producer closures are not strictly nested");
        }
        let blocked = all_actions
            .difference(&producers)
            .copied()
            .collect::<BTreeSet<_>>();
        if blocked.is_empty() || !stage.required_blocked_actions.is_subset(&blocked) {
            anyhow::bail!("Kbuild analysis stage has no complete blocked action segment");
        }
        barriers.push(ExternalAnalysisBarrier {
            producer_closure: producers
                .iter()
                .map(|index| actions[*index].logical_id.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect(),
            expected_inputs: stage
                .expected_inputs
                .into_iter()
                .map(|(path, value)| ExternalInputKey { path, value })
                .collect(),
            blocked_actions: blocked
                .iter()
                .map(|index| actions[*index].logical_id.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect(),
        });
        previous = producers;
    }
    Ok(barriers)
}

#[cfg(unix)]
fn kbuild_requested_materialization_roots(
    requested_goals: &[Vec<u8>],
    requested_outputs: Vec<ExternalPathKey>,
    action_outputs: &[Vec<ExternalPathKey>],
    producers: &BTreeMap<ExternalPathKey, usize>,
) -> Result<Vec<ExternalPathKey>> {
    if requested_outputs.is_empty() {
        anyhow::bail!("Kbuild snapshot has no requested outputs");
    }
    let produced = requested_outputs
        .iter()
        .map(|output| producers.contains_key(output))
        .collect::<Vec<_>>();
    if produced.iter().all(|present| *present) {
        return Ok(requested_outputs);
    }
    let exact_phony_goals = produced.iter().all(|present| !*present)
        && requested_outputs.len() == requested_goals.len()
        && requested_outputs
            .iter()
            .zip(requested_goals)
            .all(|(output, goal)| output.root == "obj" && output.path == *goal);
    if !exact_phony_goals {
        anyhow::bail!("Kbuild snapshot has an invalid requested output");
    }

    let mut roots = Vec::with_capacity(action_outputs.len());
    let mut seen = BTreeSet::new();
    for (action_index, outputs) in action_outputs.iter().enumerate() {
        let output = outputs
            .first()
            .context("Kbuild captured action has no materialization root")?;
        if producers.get(output) != Some(&action_index) || !seen.insert(output.clone()) {
            anyhow::bail!("Kbuild captured action has an invalid materialization root");
        }
        roots.push(output.clone());
    }
    Ok(roots)
}

#[cfg(unix)]
fn kbuild_clean_entry_execution_shape(
    replay_directory_only_action: bool,
    mandatory_must_execute: bool,
) -> (bool, bool, &'static str) {
    let mandatory = replay_directory_only_action || mandatory_must_execute;
    (
        false,
        !mandatory,
        if mandatory {
            PROCFS_CLEAN_ENTRY_MANDATORY_EXECUTION
        } else {
            PROCFS_CLEAN_ENTRY_CACHEABLE_EXECUTION
        },
    )
}

#[cfg(unix)]
fn kbuild_record_first_directory_checkpoint(
    checkpoints: &mut BTreeMap<(u64, PathBuf), (u64, BTreeSet<Vec<u8>>)>,
    action_index: u64,
    observation_ordinal: u64,
    directory: PathBuf,
    members: &[Vec<u8>],
) -> Result<()> {
    let value = (observation_ordinal, members.iter().cloned().collect());
    match checkpoints.entry((action_index, directory)) {
        std::collections::btree_map::Entry::Vacant(entry) => {
            entry.insert(value);
        }
        std::collections::btree_map::Entry::Occupied(mut entry)
            if observation_ordinal < entry.get().0 =>
        {
            entry.insert(value);
        }
        std::collections::btree_map::Entry::Occupied(entry)
            if observation_ordinal == entry.get().0 && value.1 != entry.get().1 =>
        {
            anyhow::bail!("Kbuild directory checkpoints disagree at one observation ordinal");
        }
        std::collections::btree_map::Entry::Occupied(_) => {}
    }
    Ok(())
}

#[cfg(unix)]
fn kbuild_deferred_initial_roots(
    output_root: &Path,
    first_checkpoints: &BTreeMap<(u64, PathBuf), (u64, BTreeSet<Vec<u8>>)>,
    action_output_paths: &BTreeMap<u64, BTreeSet<PathBuf>>,
) -> Result<BTreeSet<PathBuf>> {
    let mut deferred = BTreeSet::new();
    for ((action_index, directory), (_, members)) in first_checkpoints {
        if !directory.starts_with(output_root) {
            anyhow::bail!("Kbuild directory checkpoint escaped its output root");
        }
        let outputs = action_output_paths
            .get(action_index)
            .context("Kbuild directory checkpoint action has no declared outputs")?;
        for output in outputs {
            if !output.starts_with(output_root) {
                anyhow::bail!("Kbuild declared output escaped its output root");
            }
            let Ok(relative) = output.strip_prefix(directory) else {
                continue;
            };
            let Some(std::path::Component::Normal(member)) = relative.components().next() else {
                continue;
            };
            if !members.contains(&os_bytes(member)) {
                deferred.insert(directory.join(member));
            }
        }
    }
    Ok(deferred)
}

#[cfg(unix)]
fn kbuild_close_bootstrap_directories(
    output_root: &Path,
    directories: &mut BTreeMap<PathBuf, u32>,
    declared_outputs: &BTreeSet<PathBuf>,
) -> Result<()> {
    use std::os::unix::fs::MetadataExt as _;

    let descendants = directories.keys().cloned().collect::<Vec<_>>();
    for descendant in descendants {
        let mut parent = descendant.parent();
        while let Some(path) = parent {
            if path == output_root {
                break;
            }
            if !path.starts_with(output_root) {
                anyhow::bail!("Kbuild bootstrap directory ancestor escaped its output root");
            }
            if declared_outputs.contains(path) {
                anyhow::bail!("Kbuild bootstrap directory has a declared-output ancestor");
            }
            if !directories.contains_key(path) {
                let metadata = std::fs::symlink_metadata(path).with_context(|| {
                    format!(
                        "stat Kbuild bootstrap directory ancestor {}",
                        path.display()
                    )
                })?;
                if !metadata.file_type().is_dir() {
                    anyhow::bail!("Kbuild bootstrap directory ancestor is not a directory");
                }
                directories.insert(path.to_path_buf(), metadata.mode() & 0o7777);
            }
            parent = path.parent();
        }
    }
      Ok(())
}

#[cfg(unix)]
fn kbuild_close_initial_value_directories(
    output_root: &Path,
    initial_values: &BTreeMap<PathBuf, ExternalInitialInputValue>,
    directories: &mut BTreeMap<PathBuf, u32>,
    declared_outputs: &BTreeSet<PathBuf>,
) -> Result<()> {
    use std::os::unix::fs::MetadataExt as _;

    for initial_path in initial_values.keys() {
        let Some(parent) = initial_path.parent() else {
            anyhow::bail!("Kbuild initial value has no parent directory");
        };
        if parent == output_root {
            continue;
        }
        if let Some(value) = initial_values.get(parent) {
            if !matches!(value, ExternalInitialInputValue::Directory { .. }) {
                anyhow::bail!("Kbuild initial value ancestor is not a directory");
            }
            continue;
        }
        if !parent.starts_with(output_root) {
            anyhow::bail!("Kbuild initial value ancestor escaped its output root");
        }
        if declared_outputs.contains(parent) {
            anyhow::bail!("Kbuild initial value has a declared-output ancestor");
        }
        let metadata = std::fs::symlink_metadata(parent)
            .with_context(|| format!("stat Kbuild initial value ancestor {}", parent.display()))?;
        if !metadata.file_type().is_dir() {
            anyhow::bail!("Kbuild initial value ancestor is not a directory");
        }
        let mode = metadata.mode() & 0o7777;
        match directories.entry(parent.to_path_buf()) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(mode);
            }
            std::collections::btree_map::Entry::Occupied(entry) if *entry.get() == mode => {}
            std::collections::btree_map::Entry::Occupied(_) => {
                anyhow::bail!("Kbuild initial value ancestor changed mode");
            }
        }
    }
    kbuild_close_bootstrap_directories(output_root, directories, declared_outputs)
}

#[cfg(unix)]
fn stable_kbuild_namespace_metadata(before: &std::fs::Metadata, after: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::MetadataExt as _;

    before.file_type() == after.file_type()
        && before.dev() == after.dev()
        && before.ino() == after.ino()
        && before.len() == after.len()
        && before.mode() == after.mode()
        && before.uid() == after.uid()
        && before.gid() == after.gid()
        && before.nlink() == after.nlink()
        && before.mtime() == after.mtime()
        && before.mtime_nsec() == after.mtime_nsec()
        && before.ctime() == after.ctime()
        && before.ctime_nsec() == after.ctime_nsec()
}

#[cfg(unix)]
fn kbuild_unowned_initial_namespace(
    output_root: &Path,
    captured_outputs: &BTreeSet<PathBuf>,
    captured_output_directories: &BTreeSet<PathBuf>,
) -> Result<BTreeMap<PathBuf, ExternalInitialInputValue>> {
    use std::os::unix::fs::MetadataExt as _;

    let mut values = BTreeMap::new();
    for entry in walkdir::WalkDir::new(output_root).follow_links(false) {
        let entry = entry.context("walk Kbuild initial namespace")?;
        let path = entry.path();
        if path == output_root
            || captured_outputs.contains(path)
            || path
                .ancestors()
                .skip(1)
                .any(|ancestor| captured_output_directories.contains(ancestor))
        {
            continue;
        }
        if !path.starts_with(output_root) {
            anyhow::bail!("Kbuild initial namespace entry escaped its output root");
        }
        let before = std::fs::symlink_metadata(path)
            .with_context(|| format!("stat Kbuild initial namespace entry {}", path.display()))?;
        let value = if before.file_type().is_file() {
            ExternalInitialInputValue::File {
                bytes: std::fs::read(path).with_context(|| {
                    format!("read Kbuild initial namespace file {}", path.display())
                })?,
                mode: before.mode() & 0o7777,
            }
        } else if before.file_type().is_dir() {
            ExternalInitialInputValue::Directory {
                mode: before.mode() & 0o7777,
            }
        } else if before.file_type().is_symlink() {
            ExternalInitialInputValue::Symlink {
                target: os_bytes(
                    std::fs::read_link(path)
                        .with_context(|| {
                            format!("read Kbuild initial namespace link {}", path.display())
                        })?
                        .as_os_str(),
                ),
            }
        } else {
            anyhow::bail!("Kbuild initial namespace contains a special entry");
        };
        let after = std::fs::symlink_metadata(path)
            .with_context(|| format!("restat Kbuild initial namespace entry {}", path.display()))?;
        if !stable_kbuild_namespace_metadata(&before, &after)
            || values.insert(path.to_path_buf(), value).is_some()
        {
            anyhow::bail!("Kbuild initial namespace changed during materialization");
        }
    }
    Ok(values)
}

#[cfg(unix)]
fn kbuild_has_declared_output_ancestor(
    path: &Path,
    output_root: &Path,
    declared_outputs: &BTreeSet<PathBuf>,
) -> bool {
    path.ancestors()
        .skip(1)
        .take_while(|ancestor| *ancestor != output_root)
        .any(|ancestor| declared_outputs.contains(ancestor))
}

#[cfg(unix)]
fn kbuild_staged_symlink_initial_values(
    final_outputs: &KbuildMaterializedFinalOutputs,
    output_root: &Path,
    declared_outputs: &BTreeSet<PathBuf>,
) -> Result<BTreeMap<PathBuf, ExternalInitialInputValue>> {
    let mut values = BTreeMap::new();
    for output in final_outputs.actions.iter().flatten() {
        if output.kind != KbuildFinalOutputKind::Symlink {
            continue;
        }
        if !output.path.starts_with(output_root) {
            anyhow::bail!("Kbuild staged initial symlink escaped its output root");
        }
        if kbuild_has_declared_output_ancestor(&output.path, output_root, declared_outputs) {
            continue;
        }
        let before = std::fs::symlink_metadata(&output.path)
            .context("stat Kbuild staged initial symlink")?;
        if !before.file_type().is_symlink() {
            anyhow::bail!("Kbuild staged initial symlink has the wrong shape");
        }
        let target = os_bytes(
            std::fs::read_link(&output.path)
                .context("read Kbuild staged initial symlink")?
                .as_os_str(),
        );
        let after = std::fs::symlink_metadata(&output.path)
            .context("restat Kbuild staged initial symlink")?;
        if !stable_kbuild_namespace_metadata(&before, &after) || target != output.bytes {
            anyhow::bail!("Kbuild staged initial symlink changed during materialization");
        }
        if values
            .insert(
                output.path.clone(),
                ExternalInitialInputValue::Symlink { target },
            )
            .is_some()
        {
            anyhow::bail!("Kbuild staged initial symlink is repeated");
        }
    }
    Ok(values)
}

#[cfg(unix)]
fn assemble_kbuild_snapshot(
    capture: &KbuildActionGraphCapture,
    source_root: &Path,
    output_root: &Path,
    ownership: &KbuildProcessOwnershipSeal,
    external_inputs: &KbuildMaterializedExternalInputManifests,
    final_outputs: &KbuildMaterializedFinalOutputs,
    final_namespace: &KbuildFinalNamespaceCensusSeal,
    procfs: &KbuildProcfsAnalysisWitnessSeal,
    procfs_directories: &KbuildProcfsDirectoryCensus,
    generated: &KbuildGeneratedInputProvenance,
    mandatory: &KbuildMandatoryActionEligibilityContracts,
    managed_seed: Option<&KbuildManagedCaptureSeed>,
) -> Result<KbuildAssembledSnapshot> {
    if !capture.initial_inputs.is_empty() || !capture.empty_output_directory_listings.is_empty() {
        anyhow::bail!(
            "Kbuild snapshot assembly does not admit legacy initial or empty-output inputs"
        );
    }
    if capture.actions.is_empty()
        || capture.actions.len() != ownership.actions.len()
        || capture.actions.len() != external_inputs.action_inputs.len()
        || capture.actions.len() != external_inputs.action_values.len()
        || capture.actions.len() != generated.action_inputs.len()
        || capture.actions.len() != final_outputs.actions.len()
    {
        anyhow::bail!("Kbuild snapshot assembly has incomplete action materials");
    }
    if final_namespace.graph_digest != ownership.graph_digest
        || final_namespace.stream_digest != ownership.stream_digest
        || final_namespace.assignment_digest != ownership.assignment_digest
        || final_namespace.final_output_materialization_digest
            != final_outputs.seal.materialization_digest
    {
        anyhow::bail!("Kbuild snapshot assembly has a mismatched final namespace");
    }
    if generated.seal.graph_digest != ownership.graph_digest
        || generated.seal.stream_digest != ownership.stream_digest
        || generated.seal.assignment_digest != ownership.assignment_digest
        || generated.seal.provenance_digest
            != external_inputs.captured.generated_input_provenance_digest
        || generated.seal.analyzer_generated_input_digest
            != external_inputs.captured.analyzer_generated_input_digest
        || generated
            .seal
            .analyzer_directory_checkpoints
            .checkpoint_digest
            != external_inputs
                .captured
                .analyzer_directory_checkpoint_digest
    {
        anyhow::bail!("Kbuild snapshot assembly has mismatched generated inputs");
    }
    if procfs_directories.seal.graph_digest != ownership.graph_digest
        || procfs_directories.seal.stream_digest != ownership.stream_digest
        || procfs_directories.seal.assignment_digest != ownership.assignment_digest
        || procfs_directories.seal.census_digest
            != external_inputs.captured.procfs_directory_census_digest
        || procfs_directories.seal.observations
            != external_inputs.captured.procfs_directory_observations
    {
        anyhow::bail!("Kbuild snapshot assembly has mismatched procfs directories");
    }
    require_kbuild_procfs_directory_census(procfs_directories)?;
    if mandatory.seal.graph_digest != ownership.graph_digest
        || mandatory.seal.stream_digest != ownership.stream_digest
        || mandatory.seal.assignment_digest != ownership.assignment_digest
        || mandatory.seal.actions.len() != mandatory.actions.len()
    {
        anyhow::bail!("Kbuild snapshot assembly has mismatched mandatory-action eligibility");
    }
    let mandatory_by_index =
        kbuild_mandatory_action_contracts_by_index(mandatory, procfs_directories)?;
    let mandatory_actions = u64::try_from(mandatory_by_index.len())
        .context("Kbuild mandatory-action count does not fit u64")?;
    let first = capture
        .actions
        .first()
        .context("Kbuild snapshot assembly has no first action")?;
    validate_invocation(&first.analyzer, "analyzer")?;
    if capture.actions.iter().any(|action| {
        action.analyzer != first.analyzer || action.requested_goals != first.requested_goals
    }) {
        anyhow::bail!("Kbuild snapshot actions do not share one analyzer request");
    }

    let analyzer_executable =
        canonical_existing(&first.analyzer.executable, "captured analyzer executable")?;
    let analyzer_executable_key = root_path(&analyzer_executable, source_root, output_root)?;
    let analyzer_executable_digest = external_inputs
        .analyzer_values
        .iter()
        .find(|value| value.path == analyzer_executable_key)
        .and_then(|value| match value.value {
            ExternalInputValue::File { digest, .. } => Some(digest),
            _ => None,
        })
        .context("Kbuild analyzer executable has no materialized captured value")?;
    let analyzer = ExternalAnalyzerIdentity {
        kind: "gnu-make-kbuild".to_string(),
        executable_digest: analyzer_executable_digest,
        argv: first.analyzer.argv.clone(),
        working_directory: canonical_existing(
            &first.analyzer.working_directory,
            "captured analyzer working directory",
        )?,
        environment: captured_environment(&first.analyzer, "analyzer")?,
        build_options: BTreeMap::new(),
        platform: BTreeMap::from([("os".to_string(), std::env::consts::OS.to_string())]),
    };
    let key = ExternalAnalysisKey::new(
        source_root.to_path_buf(),
        output_root.to_path_buf(),
        &analyzer,
        first.requested_goals.clone(),
    );

    let receipts = capture
        .actions
        .iter()
        .zip(&final_outputs.actions)
        .enumerate()
        .map(|(action_index, (action, outputs))| {
            let Some(receipt_path) = &action.receipt_path else {
                return Ok(None);
            };
            let receipt = outputs
                .iter()
                .find(|output| output.path == *receipt_path)
                .with_context(|| {
                    format!("Kbuild action {action_index} has no materialized receipt output")
                })?;
            if receipt.kind != KbuildFinalOutputKind::RegularFile {
                anyhow::bail!("Kbuild action {action_index} receipt output is not a regular file");
            }
            parse_kbuild_receipt(&receipt.bytes)
                .with_context(|| format!("parse materialized Kbuild action {action_index} receipt"))
                .map(Some)
        })
        .collect::<Result<Vec<_>>>()?;
    let config_input_references = receipts
        .iter()
        .flatten()
        .try_fold(0_u64, |count, receipt| {
            count
                .checked_add(
                    u64::try_from(receipt.config_deps.len())
                        .context("Kbuild config input count does not fit u64")?,
                )
                .context("Kbuild config input count overflowed")
        })?;
    let dot_config_key = ExternalPathKey {
        root: "obj".to_string(),
        path: b".config".to_vec(),
    };
    let auto_config_key = ExternalPathKey {
        root: "obj".to_string(),
        path: b"include/config/auto.conf".to_vec(),
    };
    let (kconfig, kconfig_values) = if config_input_references == 0 {
        (None, BTreeMap::new())
    } else {
        let (path, bytes) = [auto_config_key, dot_config_key]
            .into_iter()
            .find_map(|path| {
                external_inputs
                    .retained_files
                    .get(&path)
                    .map(|bytes| (path, bytes))
            })
            .context("Kbuild config dependencies have no captured configuration value")?;
        (
            Some(ExternalKconfigSource {
                path,
                captured_bytes: bytes.clone(),
            }),
            parse_kbuild_config_values(bytes)?,
        )
    };

    let mut analysis_boundary_actions = generated
        .analyzer_directory_checkpoints
        .iter()
        .flat_map(|checkpoint| {
            checkpoint
                .before_actions
                .iter()
                .chain(&checkpoint.after_actions)
        })
        .copied()
        .collect::<BTreeSet<_>>();
    let replay_directory_roots = final_outputs
        .actions
        .iter()
        .enumerate()
        .filter(|(action_index, outputs)| {
            u64::try_from(*action_index)
                .is_ok_and(|action_index| analysis_boundary_actions.contains(&action_index))
                && !outputs.is_empty()
                && outputs
                    .iter()
                    .all(|output| output.kind == KbuildFinalOutputKind::Directory)
        })
        .flat_map(|(_, outputs)| outputs.iter().map(|output| output.path.clone()))
        .collect::<BTreeSet<_>>();
    for (action_index, outputs) in final_outputs.actions.iter().enumerate() {
        if outputs.is_empty()
            || outputs
                .iter()
                .any(|output| output.kind != KbuildFinalOutputKind::Directory)
            || !outputs.iter().any(|output| {
                replay_directory_roots
                    .iter()
                    .any(|root| output.path != *root && output.path.starts_with(root))
            })
        {
            continue;
        }
        analysis_boundary_actions.insert(
            u64::try_from(action_index)
                .context("Kbuild descendant directory action index does not fit u64")?,
        );
    }
    let mandatory_directory_checkpoints = mandatory
        .actions
        .iter()
        .flat_map(|contract| &contract.directory_checkpoints)
        .collect::<Vec<_>>();
    if mandatory_directory_checkpoints.len() != generated.directory_checkpoints.len()
        || generated
            .directory_checkpoints
            .iter()
            .any(|checkpoint| !mandatory_directory_checkpoints.contains(&checkpoint))
    {
        anyhow::bail!("Kbuild generated directory checkpoints are not all mandatory");
    }
    let mut first_directory_checkpoints = BTreeMap::new();
    for checkpoint in &mandatory_directory_checkpoints {
        if checkpoint.path.root != "obj" {
            anyhow::bail!("Kbuild mandatory directory checkpoint has a non-output root");
        }
        kbuild_record_first_directory_checkpoint(
            &mut first_directory_checkpoints,
            checkpoint.consumer_action_index,
            checkpoint.observation_ordinal,
            output_root.join(bytes_path(&checkpoint.path.path)),
            &checkpoint.members,
        )?;
    }
    let action_output_paths = final_outputs
        .actions
        .iter()
        .enumerate()
        .map(|(action_index, outputs)| {
            Ok((
                u64::try_from(action_index)
                    .context("Kbuild output action index does not fit u64")?,
                outputs
                    .iter()
                    .map(|output| output.path.clone())
                    .collect::<BTreeSet<_>>(),
            ))
        })
        .collect::<Result<BTreeMap<_, _>>>()?;
    let deferred_initial_roots = kbuild_deferred_initial_roots(
        output_root,
        &first_directory_checkpoints,
        &action_output_paths,
    )?;
    let mut bootstrap_directories = BTreeMap::new();
    for (action_index, outputs) in final_outputs.actions.iter().enumerate() {
        let action_index = u64::try_from(action_index)
            .context("Kbuild directory-output action index does not fit u64")?;
        let replay_directory_only_action = analysis_boundary_actions.contains(&action_index)
            && !outputs.is_empty()
            && outputs
                .iter()
                .all(|output| output.kind == KbuildFinalOutputKind::Directory);
        for output in outputs {
            if output.kind != KbuildFinalOutputKind::Directory || replay_directory_only_action {
                continue;
            }
            if !output.path.starts_with(output_root)
                || bootstrap_directories
                    .insert(output.path.clone(), output.mode & 0o7777)
                    .is_some()
            {
                anyhow::bail!("Kbuild bootstrap directory is repeated or outside its output root");
            }
        }
    }
    let declared_output_paths = final_outputs
        .actions
        .iter()
        .enumerate()
        .flat_map(|(action_index, outputs)| {
            let replay_directory_only_action = u64::try_from(action_index).is_ok_and(|index| {
                analysis_boundary_actions.contains(&index)
                    && !outputs.is_empty()
                    && outputs
                        .iter()
                        .all(|output| output.kind == KbuildFinalOutputKind::Directory)
            });
            outputs.iter().filter_map(move |output| {
                (output.kind != KbuildFinalOutputKind::Directory || replay_directory_only_action)
                    .then(|| output.path.clone())
            })
        })
        .collect::<BTreeSet<_>>();
    kbuild_close_bootstrap_directories(
        output_root,
        &mut bootstrap_directories,
        &declared_output_paths,
    )?;
      let captured_output_paths = final_outputs
        .actions
        .iter()
          .flat_map(|outputs| outputs.iter().map(|output| output.path.clone()))
          .collect::<BTreeSet<_>>();
      let captured_output_directories = final_outputs
          .actions
          .iter()
          .flat_map(|outputs| outputs.iter())
          .filter(|output| output.kind == KbuildFinalOutputKind::Directory)
          .map(|output| output.path.clone())
          .collect::<BTreeSet<_>>();
      let mut initial_values = kbuild_unowned_initial_namespace(
          output_root,
          &captured_output_paths,
          &captured_output_directories,
      )?;
      if let Some(seed) = managed_seed {
          let seed_value = ExternalInitialInputValue::File {
              bytes: seed.bytes.clone(),
              mode: seed.output_mode & 0o7777,
          };
          match initial_values.entry(seed.output_path.clone()) {
              std::collections::btree_map::Entry::Vacant(entry) => {
                  entry.insert(seed_value);
              }
            std::collections::btree_map::Entry::Occupied(entry) if entry.get() == &seed_value => {}
              std::collections::btree_map::Entry::Occupied(_) => {
                anyhow::bail!("Kbuild managed configuration seed changed in the initial namespace");
              }
          }
          if initial_values
              .insert(
                  output_root.join(KBUILD_MANAGED_SCRATCH_DIRECTORY),
                  ExternalInitialInputValue::Directory {
                      mode: KBUILD_MANAGED_SCRATCH_MODE,
                  },
              )
              .is_some()
          {
              anyhow::bail!("Kbuild managed scratch overlaps the initial namespace");
          }
      }
    for (path, value) in
        kbuild_staged_symlink_initial_values(final_outputs, output_root, &declared_output_paths)?
    {
          if initial_values.insert(path, value).is_some() {
              anyhow::bail!("Kbuild staged initial symlink overlaps the seed namespace");
          }
      }
      initial_values.retain(|path, _| {
          !deferred_initial_roots
              .iter()
              .any(|deferred| path.starts_with(deferred))
      });
      bootstrap_directories.retain(|path, _| {
          !deferred_initial_roots
              .iter()
              .any(|deferred| path.starts_with(deferred))
      });
      kbuild_close_initial_value_directories(
          output_root,
          &initial_values,
          &mut bootstrap_directories,
          &declared_output_paths,
      )?;
      bootstrap_directories.retain(|path, _| {
          !deferred_initial_roots
              .iter()
              .any(|deferred| path.starts_with(deferred))
      });
      for (path, mode) in bootstrap_directories {
        match initial_values.entry(path) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(ExternalInitialInputValue::Directory { mode });
            }
            std::collections::btree_map::Entry::Occupied(entry)
                if entry.get() == &ExternalInitialInputValue::Directory { mode } => {}
            std::collections::btree_map::Entry::Occupied(_) => {
                anyhow::bail!("Kbuild bootstrap directory changed during initial materialization");
            }
        }
    }
    let mut bootstrap_directory_paths = BTreeSet::new();
    let initial_inputs = initial_values
        .into_iter()
        .map(|(path, value)| {
            let path = root_path(&path, source_root, output_root)?;
            if path.root != "obj" || !bootstrap_directory_paths.insert(path.clone()) {
                anyhow::bail!("Kbuild bootstrap directory closure has an invalid rooted path");
            }
            Ok(ExternalInitialInput { path, value })
        })
        .collect::<Result<Vec<_>>>()?;

    let mut actions = Vec::with_capacity(capture.actions.len());
    let mut witnesses = Vec::with_capacity(capture.actions.len());
    let mut captured_action_ids = vec![None; capture.actions.len()];
    let mut normal_input_references = 0_u64;
    for (action_index, action) in capture.actions.iter().enumerate() {
        validate_compound_invocations(&action.commands, "action")?;
        let first_command = &action.commands[0];
        let action_index_u64 =
            u64::try_from(action_index).context("Kbuild snapshot action index does not fit u64")?;
        let owned = ownership
            .actions
            .get(action_index)
            .filter(|owned| owned.action_index() == action_index_u64)
            .context("Kbuild snapshot ownership is not in action order")?;
        let receipt = receipts[action_index].as_ref();
        let mandatory_contract = mandatory_by_index.get(&action_index_u64).copied();
        if let Some(contract) = mandatory_contract {
            if !matches!(
                contract.cache_policy,
                crate::action_manager::ActionCachePolicy::CACHEABLE
                    | crate::action_manager::ActionCachePolicy::ALWAYS_RUN
            ) || !contract.cache_policy.store
                || contract.cache_policy.durable
                || contract.isolation.writable_roots() != [output_root]
                || contract.isolation.descriptor_topology()
                    != rush_exec::local_isolation::LocalDescriptorTopology::StandardOnlyV1
            {
                anyhow::bail!("Kbuild mandatory action lost its no-reuse isolation policy");
            }
            contract
                .isolation
                .validate_credentials(owned.credentials())
                .context("Kbuild mandatory action credentials are not isolatable")?;
        }
          if let Some(receipt) = receipt {
              if !receipt.wildcard_dependencies.is_empty() {
                  anyhow::bail!("unresolved non-Kconfig wildcard remains in Kbuild receipt");
              }
              if !action.commands.iter().any(|command| {
                  command_arguments_contain_saved_evidence(&command.argv, &receipt.command)
              }) {
                  anyhow::bail!("captured action does not contain its saved command evidence");
              }
        }
        let output_values = &final_outputs.actions[action_index];
        let directory_only_action = !output_values.is_empty()
            && output_values
                .iter()
                .all(|output| output.kind == KbuildFinalOutputKind::Directory);
        let replay_directory_only_action =
            directory_only_action && analysis_boundary_actions.contains(&action_index_u64);
        if directory_only_action {
            if receipt.is_some() {
                anyhow::bail!("directory-only Kbuild action has a command receipt");
            }
            if !replay_directory_only_action {
                continue;
            }
        }

        let action_working_directory = canonical_existing(
            &first_command.working_directory,
            "captured action working directory",
        )?;
          let receipt_command = match receipt {
              Some(receipt) => action
                  .commands
                  .iter()
                  .find(|command| {
                      command_arguments_contain_saved_evidence(&command.argv, &receipt.command)
                  })
                  .context("captured action has no command matching its saved command evidence")?,
              None => action
                  .commands
                  .last()
                  .context("captured action has no final command")?,
          };
          let receipt_working_directory = canonical_existing(
              &receipt_command.working_directory,
              "captured receipt-command working directory",
          )?;
        let executable_keys = action
            .commands
            .iter()
            .map(|command| {
                let executable =
                    canonical_existing(&command.executable, "captured action executable")?;
                root_path(&executable, source_root, output_root)
            })
            .collect::<Result<Vec<_>>>()?;
        let executable_paths = executable_keys.iter().cloned().collect::<BTreeSet<_>>();
        let (mut declarations, mut values) = kbuild_replay_action_inputs(
            action_index_u64,
            &external_inputs.action_inputs[action_index],
            &external_inputs.action_values[action_index],
            &generated.action_inputs[action_index],
        )?;
        if let Some(contract) = mandatory_contract {
            let actual_inputs = declarations
                .iter()
                .zip(&values)
                .map(|(declaration, value)| {
                    (
                        declaration.path.clone(),
                        (declaration.kind, value.value.clone()),
                    )
                })
                .collect::<BTreeMap<_, _>>();
            let mut expected_inputs = contract
                .external_inputs
                .iter()
                .map(|(path, input)| {
                    (
                        path.clone(),
                        (
                            kbuild_external_input_kind(input.value),
                            kbuild_external_input_value(input.value),
                        ),
                    )
                })
                .collect::<BTreeMap<_, _>>();
            for input in &contract.generated_inputs {
                if input.consumer_action_index != action_index_u64
                    || expected_inputs
                        .insert(
                            input.path.clone(),
                            (ExternalInputKind::File, input.value.clone()),
                        )
                        .is_some()
                {
                    anyhow::bail!("Kbuild mandatory action has conflicting generated inputs");
                }
            }
            if actual_inputs != expected_inputs {
                anyhow::bail!("Kbuild mandatory action input contract changed during assembly");
            }
            if !contract.procfs_filesystems_reads.is_empty() {
                let contents = std::fs::read("/proc/filesystems")
                    .context("read current /proc/filesystems action input")?;
                for observation in &contract.procfs_filesystems_reads {
                    let offset = observation
                        .offset
                        .filter(|_| observation.uses_descriptor_offset)
                        .context("captured /proc/filesystems read has no descriptor offset")?;
                    let offset = usize::try_from(offset)
                        .context("captured /proc/filesystems offset does not fit usize")?;
                    let bytes = usize::try_from(observation.value.bytes)
                        .context("captured /proc/filesystems byte count does not fit usize")?;
                    let end = offset
                        .checked_add(bytes)
                        .context("captured /proc/filesystems range overflowed")?;
                    let captured = contents
                        .get(offset..end)
                        .context("captured /proc/filesystems range exceeds current value")?;
                    if observation.requested_bytes == 0
                        || (observation.value.bytes == 0 && offset != contents.len())
                        || observation.requested_bytes < observation.value.bytes
                        || *blake3::hash(captured).as_bytes() != observation.value.digest
                    {
                        anyhow::bail!("captured /proc/filesystems read changed before assembly");
                    }
                }
                let path = ExternalPathKey {
                    root: "host".to_string(),
                    path: b"proc/filesystems".to_vec(),
                };
                if declarations.iter().any(|input| input.path == path) {
                    anyhow::bail!("Kbuild action repeats its /proc/filesystems input");
                }
                declarations.push(ExternalInput {
                    path: path.clone(),
                    kind: ExternalInputKind::File,
                });
                values.push(ExternalInputKey {
                    path,
                    value: ExternalInputValue::File {
                        digest: *blake3::hash(&contents).as_bytes(),
                        executable: false,
                    },
                });
            }
        }
        require_fine_grained_kconfig_inputs(
            kconfig.as_ref().map(|source| &source.path),
            receipt.map_or(&[], |receipt| receipt.config_deps.as_slice()),
            &declarations,
        )?;
        let mut executable_values = BTreeMap::new();
        let mut normal_inputs = Vec::new();
        let mut witness_inputs = Vec::new();
        let mut input_paths = BTreeSet::new();
        for (declaration, value) in declarations.iter().zip(&values) {
            if declaration.path != value.path || !input_paths.insert(declaration.path.clone()) {
                anyhow::bail!("Kbuild action input materialization is not one-to-one");
            }
            if executable_paths.contains(&declaration.path) {
                if executable_values
                    .insert(declaration.path.clone(), value.value.clone())
                    .is_some()
                {
                    anyhow::bail!("Kbuild action repeats its executable value");
                }
            } else {
                normal_inputs.push(declaration.clone());
                witness_inputs.push(value.clone());
            }
        }
        let executable_witnesses = executable_keys
            .iter()
            .map(|path| {
                let value = executable_values
                    .get(path)
                    .filter(|value| {
                        matches!(
                            value,
                            ExternalInputValue::File {
                                executable: true,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .context("Kbuild action executable has no executable captured value")?;
                Ok(ExternalExecutableWitness {
                    path: path.clone(),
                    value,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        normal_input_references = normal_input_references
            .checked_add(
                u64::try_from(normal_inputs.len())
                    .context("Kbuild normal input count does not fit u64")?,
            )
            .context("Kbuild normal input count overflowed")?;

        for symbol in receipt.into_iter().flat_map(|receipt| &receipt.config_deps) {
            let value = kconfig_values
                .get(symbol)
                .cloned()
                .unwrap_or_else(|| b"<absent>".to_vec());
            witness_inputs.push(ExternalInputKey {
                path: ExternalPathKey {
                    root: "kconfig".to_string(),
                    path: symbol.as_bytes().to_vec(),
                },
                value: ExternalInputValue::Virtual {
                    name: symbol.as_bytes().to_vec(),
                    value,
                },
            });
        }

        let mut output_paths = BTreeSet::new();
        let outputs = output_values
            .iter()
            .filter(|output| {
                output.kind != KbuildFinalOutputKind::Directory || replay_directory_only_action
            })
            .map(|output| {
                let path = root_path(&output.path, source_root, output_root)?;
                if path.root != "obj" || !output_paths.insert(path.clone()) {
                    anyhow::bail!("Kbuild action has a repeated or non-output-root output");
                }
                Ok(ExternalOutput {
                    path,
                    kind: match output.kind {
                        KbuildFinalOutputKind::RegularFile => ExternalOutputKind::File,
                        KbuildFinalOutputKind::Symlink => ExternalOutputKind::Symlink,
                        KbuildFinalOutputKind::Directory => ExternalOutputKind::Tree,
                    },
                    mode: output.mode & 0o7777,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        if let Some(receipt) = receipt {
            let receipt_path = root_path(
                action
                    .receipt_path
                    .as_ref()
                    .context("receipt-backed action has no receipt path")?,
                source_root,
                output_root,
            )?;
            let target_path = normalized_output_target(output_root, &receipt.target)?;
            let target_path = root_path(&target_path, source_root, output_root)?;
            if !output_paths.contains(&receipt_path) || !output_paths.contains(&target_path) {
                anyhow::bail!("captured outputs omit the Kbuild target or its receipt");
            }
            for dependency in receipt.source.iter().chain(&receipt.dependencies) {
                let dependency = bytes_path(dependency);
                let absolute = if dependency.is_absolute() {
                    dependency
                } else {
                    receipt_working_directory.join(dependency)
                };
                let absolute = canonical_existing(&absolute, "Kbuild receipt dependency")?;
                let rooted = root_path(&absolute, source_root, output_root)?;
                if !input_paths.contains(&rooted) || executable_paths.contains(&rooted) {
                    anyhow::bail!("Kbuild receipt dependency was not observed as an action input");
                }
            }
        }

        let logical_id = kbuild_action_logical_id(
            receipt.map(|receipt| receipt.target.as_slice()),
            &output_paths,
        )?;
        captured_action_ids[action_index] = Some(logical_id.clone());
        let action_environment =
            canonical_environment(first_command, "action", source_root, output_root)?;
        let mandatory_execution = mandatory_contract.is_some();
        let (always_run, cacheable, clean_entry_policy) = kbuild_clean_entry_execution_shape(
            replay_directory_only_action,
            mandatory_contract.is_some_and(|contract| contract.cache_policy.must_execute()),
        );
        let mut execution_properties = BTreeMap::from([(
            "rush.capture.observer".to_string(),
            "native-process-stream".to_string(),
        )]);
        if mandatory_execution {
            execution_properties.insert(
                MANDATORY_EXECUTION_PROPERTY.to_string(),
                clean_entry_policy.to_string(),
            );
            for (index, checkpoint) in mandatory_contract
                .expect("mandatory execution has a contract")
                .directory_checkpoints
                .iter()
                .enumerate()
            {
                let path = obj_path(checkpoint.path.path.clone());
                let (name, value) =
                    encode_runtime_directory_checkpoint(index, &path, &checkpoint.members)?;
                if execution_properties.insert(name, value).is_some() {
                    anyhow::bail!("Kbuild mandatory action repeats a runtime checkpoint");
                }
            }
        }
        let mut external = ExternalAction {
            logical_id: logical_id.clone(),
            mnemonic: "KbuildCapturedAction".to_string(),
            commands: action
                .commands
                .iter()
                .zip(&executable_keys)
                .map(|(command, executable)| {
                    let environment =
                        canonical_environment(command, "action", source_root, output_root)?;
                    Ok(ExternalCommand {
                        executable: executable.clone(),
                        argv0: canonical_argument(&command.argv[0], source_root, output_root),
                        argv: command
                            .argv
                            .iter()
                            .skip(1)
                            .map(|argument| canonical_argument(argument, source_root, output_root))
                            .collect(),
                        environment: (environment != action_environment).then_some(environment),
                        working_directory: (command.working_directory
                            != first_command.working_directory)
                            .then(|| {
                                root_path(&command.working_directory, source_root, output_root)
                            })
                            .transpose()?,
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            working_directory: root_path(&action_working_directory, source_root, output_root)?,
            environment: action_environment,
            signal_state: owned.signal_state(),
            file_creation_mask: owned.file_creation_mask(),
            credentials: owned.credentials().clone(),
            normal_inputs,
            order_only_inputs: Vec::new(),
            outputs,
            dependencies: Vec::new(),
            config_deps: receipt
                .map(|receipt| receipt.config_deps.clone())
                .unwrap_or_default(),
            depfile: None,
            restat: true,
            always_run,
            cacheable,
            local_only: true,
            sandbox: mandatory_execution,
            resource: ManifestResourceClass::KernelCodegen,
            execution_properties,
        };
        let directory_materialization_contract_safe = mandatory_contract.is_none_or(|contract| {
            !contract.cache_policy.must_execute() && contract.directory_checkpoints.is_empty()
        });
        let declared_mkdir_targets_safe = first_command.argv.len() >= 3
            && first_command.argv[0] == b"mkdir"
            && first_command.argv[1] == b"-p"
            && first_command.argv.iter().skip(2).all(|argument| {
                let path = bytes_path(argument);
                !path.as_os_str().is_empty()
                    && path.is_relative()
                    && !argument.starts_with(b"-")
                    && path
                        .components()
                        .all(|component| matches!(component, std::path::Component::Normal(_)))
            });
        let declared_mkdir_outputs_safe = declared_mkdir_targets_safe
            && first_command.argv.iter().skip(2).all(|argument| {
                let target = bytes_path(argument);
                external.outputs.iter().any(|output| {
                    output.kind == ExternalOutputKind::Tree
                        && output.path.root == "obj"
                        && bytes_path(&output.path.path) == target
                })
            })
            && external.outputs.iter().all(|output| {
                output.path.root == "obj"
                    && first_command.argv.iter().skip(2).any(|argument| {
                        bytes_path(argument).starts_with(bytes_path(&output.path.path))
                    })
            });
        if replay_directory_only_action
            && receipt.is_none()
            && directory_materialization_contract_safe
            && action.commands.len() == 1
            && first_command.executable == Path::new("/usr/bin/mkdir")
            && first_command.working_directory == action_working_directory
            && declared_mkdir_outputs_safe
            && !external.outputs.is_empty()
            && external
                .outputs
                .iter()
                .all(|output| output.kind == ExternalOutputKind::Tree)
        {
            external.execution_properties.insert(
                "rush.kbuild.directory-materialization".to_string(),
                "declared-mkdir-p-v1".to_string(),
            );
        }
        witnesses.push(ExternalActionCaptureWitness {
            logical_id,
            executables: executable_witnesses,
            inputs: witness_inputs,
        });
        actions.push(external);
    }

    let mut empty_output_input_values = BTreeMap::new();
    for (action, witness) in actions.iter().zip(&witnesses) {
        for input in &action.normal_inputs {
            if input.kind != ExternalInputKind::DirectoryListing
                || !bootstrap_directory_paths.contains(&input.path)
            {
                continue;
            }
            let value = witness
                .inputs
                .iter()
                .find(|value| value.path == input.path)
                .map(|value| value.value.clone())
                .context("Kbuild bootstrap directory input has no captured value")?;
            if !matches!(value, ExternalInputValue::DirectoryListing { .. }) {
                anyhow::bail!("Kbuild bootstrap directory input has the wrong value kind");
            }
            match empty_output_input_values.entry(input.path.clone()) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(value);
                }
                std::collections::btree_map::Entry::Occupied(entry) if entry.get() != &value => {
                    anyhow::bail!(
                        "Kbuild bootstrap directory has inconsistent empty-output values"
                    );
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
            }
        }
    }
    let empty_output_inputs = empty_output_input_values
        .into_iter()
        .map(|(path, value)| ExternalEmptyOutputInput {
            path,
            kind: ExternalInputKind::DirectoryListing,
            value,
        })
        .collect();

    let mut producers = BTreeMap::new();
    let mut directory_producers = Vec::new();
    for (index, action) in actions.iter().enumerate() {
        for output in &action.outputs {
            if producers.insert(output.path.clone(), index).is_some() {
                anyhow::bail!("Kbuild snapshot captures the same output more than once");
            }
            if output.kind == ExternalOutputKind::Tree {
                directory_producers.push((output.path.clone(), index));
            }
        }
    }
    let logical_ids = actions
        .iter()
        .map(|action| action.logical_id.clone())
        .collect::<Vec<_>>();
    for (index, action) in actions.iter_mut().enumerate() {
        let mut dependencies = BTreeSet::new();
        for input in action
            .normal_inputs
            .iter()
            .map(|input| &input.path)
            .chain(witnesses[index].executables.iter().map(|input| &input.path))
        {
            if let Some(&producer) = producers.get(input) {
                if producer == index {
                    anyhow::bail!("Kbuild action consumes its own declared output");
                }
                dependencies.insert(logical_ids[producer].clone());
            }
        }
        for output in &action.outputs {
            for (directory, producer) in &directory_producers {
                if *producer != index && external_path_is_below(&output.path, directory) {
                    dependencies.insert(logical_ids[*producer].clone());
                }
            }
        }
        action.dependencies = dependencies.into_iter().collect();
    }
    for action in &mut actions {
        if action.logical_id != "vmlinux.unstripped"
            || action.cacheable
            || !action.local_only
            || !action.sandbox
            || !action
                .dependencies
                .iter()
                .any(|dependency| dependency == "init/version-timestamp.o")
            || !action.outputs.iter().any(|output| {
                output.path.root == "obj"
                    && output.path.path == b"vmlinux.unstripped"
                    && output.kind == ExternalOutputKind::File
            })
        {
            continue;
        }
        let [command] = action.commands.as_slice() else {
            continue;
        };
        let invokes_link_vmlinux = command.argv.len() == 2
            && match &command.argv[1] {
                ExternalArgumentKey::Literal(value) => {
                    contains_subslice(value, b"/scripts/link-vmlinux.sh")
                }
                ExternalArgumentKey::Joined(parts) => parts.iter().any(|part| {
                    matches!(
                        part,
                        ExternalArgumentPart::Literal(value)
                            if contains_subslice(value, b"/scripts/link-vmlinux.sh")
                    )
                }),
                ExternalArgumentKey::Path(_) => false,
            };
        if command.executable.root != "host"
            || command.executable.path != b"usr/bin/dash"
            || !matches!(
                &command.argv0,
                ExternalArgumentKey::Literal(value) if value == b"/bin/sh"
            )
            || command.argv.len() != 2
            || !matches!(
                &command.argv[0],
                ExternalArgumentKey::Literal(value) if value == b"-c"
            )
            || !invokes_link_vmlinux
            || command.environment.is_some()
            || !matches!(
                action.environment.get(b"MAKE".as_slice()),
                Some(ExternalArgumentKey::Literal(value)) if value == b"/usr/bin/make"
            )
        {
            continue;
        }
        action.environment.insert(
            b"MAKE".to_vec(),
            ExternalArgumentKey::Literal(b":".to_vec()),
        );
        if action
            .execution_properties
            .insert(
                "rush.kbuild.suppress-represented-recursive-make".to_string(),
                "link-vmlinux-version-timestamp-v1".to_string(),
            )
            .is_some()
        {
            anyhow::bail!("Kbuild link action repeats recursive Make suppression");
        }
    }
    // Collect every checkpoint edge that requires a producer to run before its
    // observer before considering the opposite, post-checkpoint direction.
    // Compound Kbuild actions can observe one nested producer on both sides of
    // different directory checkpoints. Deciding post-checkpoint edges in
    // traversal order would otherwise miss a not-yet-inserted predecessor and
    // manufacture a two-action dependency cycle.
    let mut directory_checkpoint_predecessor_edges = BTreeSet::new();
    for (&observer_index, contract) in &mandatory_by_index {
        let observer_id =
            kbuild_captured_replay_action_id(&captured_action_ids, observer_index)
                .context("resolve Kbuild mandatory checkpoint observer predecessor")?;
        let observer_action_index = logical_ids
            .iter()
            .position(|logical_id| logical_id == observer_id)
            .context("Kbuild mandatory checkpoint predecessor observer disappeared")?;
        for checkpoint in &contract.directory_checkpoints {
            let directory = obj_path(checkpoint.path.path.clone());
            for producer_capture_index in &checkpoint.before_actions {
                let Some(producer_id) = usize::try_from(*producer_capture_index)
                    .ok()
                    .and_then(|index| captured_action_ids.get(index))
                    .and_then(Option::as_deref)
                else {
                    continue;
                };
                let producer = actions
                    .iter()
                    .find(|action| action.logical_id == producer_id)
                    .context("Kbuild checkpoint predecessor lost its replay action")?;
                if producer.outputs.iter().any(|output| {
                    external_direct_child(&output.path, &directory)
                        .is_some_and(|member| {
                            checkpoint
                                .members
                                .binary_search_by(|candidate| candidate.as_slice().cmp(member))
                                .is_ok()
                        })
                }) {
                    directory_checkpoint_predecessor_edges
                        .insert((observer_action_index, producer_id.to_string()));
                }
            }
        }
    }
    let mut directory_checkpoint_edges = BTreeSet::new();
    let mut runtime_directory_checkpoint_updates = BTreeMap::new();
    for (&observer_index, contract) in &mandatory_by_index {
        let observer_id = kbuild_captured_replay_action_id(&captured_action_ids, observer_index)
        .context("resolve Kbuild mandatory checkpoint observer")?;
        let observer_action_index = logical_ids
            .iter()
            .position(|logical_id| logical_id == observer_id)
            .context("Kbuild mandatory checkpoint observer disappeared")?;
        for (checkpoint_index, checkpoint) in contract.directory_checkpoints.iter().enumerate() {
            let directory = obj_path(checkpoint.path.path.clone());
            let update = runtime_directory_checkpoint_updates
                .entry((observer_index, observer_action_index, checkpoint_index))
                .or_insert_with(|| {
                    (
                        checkpoint.members.iter().cloned().collect::<BTreeSet<_>>(),
                        BTreeSet::<String>::new(),
                        BTreeSet::<String>::new(),
                    )
                });
            for (producer_index, producer) in actions.iter().enumerate() {
                if producer_index == observer_action_index {
                    continue;
                }
                let direct_members = producer
                    .outputs
                    .iter()
                    .filter_map(|output| external_direct_child(&output.path, &directory))
                    .collect::<Vec<_>>();
                let produces_retained_member = direct_members
                    .iter()
                    .any(|member| checkpoint.members.iter().any(|seen| seen == *member));
                let introduces_absent_member = direct_members
                    .iter()
                    .any(|member| !checkpoint.members.iter().any(|seen| seen == *member));
                if !produces_retained_member && !introduces_absent_member {
                    continue;
                }
                    let producer_id = &logical_ids[producer_index];
                    let producer_capture_index = captured_action_ids
                        .iter()
                        .position(|logical_id| logical_id.as_ref() == Some(producer_id))
                        .context("Kbuild checkpoint producer lost its capture index")?;
                let producer_capture_index = u64::try_from(producer_capture_index)
                        .context("Kbuild checkpoint producer index does not fit u64")?;

                if checkpoint.after_actions.contains(&producer_capture_index)
                    && kbuild_promote_checkpoint_dependency(
                        &actions[observer_action_index],
                        &mut directory_checkpoint_predecessor_edges,
                        observer_action_index,
                        producer_id,
                        &directory,
                        &producer.outputs,
                        &mut update.0,
                        &mut update.1,
                    )
                {
                    continue;
                }

                if produces_retained_member
                    && checkpoint.before_actions.contains(&producer_capture_index)
                {
                    update.1.insert(producer_id.clone());
                    directory_checkpoint_predecessor_edges
                        .insert((observer_action_index, producer_id.clone()));
                }

                if introduces_absent_member
                    && checkpoint.after_actions.contains(&producer_capture_index)
                {
                    update.2.insert(producer_id.clone());

                    let reverse_checkpoint_edge = directory_checkpoint_edges
                        .contains(&(observer_action_index, producer_id.clone()));
                    if reverse_checkpoint_edge {
                        anyhow::bail!(
                            "Kbuild directory checkpoint ordering conflicts with an existing \
                             dependency: path={:?}, observer={:?}, producer={:?}, \
                             producer_capture_index={}, relation=after, existing_edge=checkpoint",
                            checkpoint.path.path,
                            observer_id,
                            producer_id,
                            producer_capture_index,
                        );
                    }
                    directory_checkpoint_edges.insert((producer_index, observer_id.to_string()));
                }
            }
        }
    }
    for (
        (observer_index, observer_action_index, checkpoint_index),
        (members, before_actions, after_actions),
    ) in runtime_directory_checkpoint_updates
    {
        let checkpoint = mandatory_by_index
            .get(&observer_index)
            .and_then(|contract| contract.directory_checkpoints.get(checkpoint_index))
            .context("Kbuild promoted directory checkpoint disappeared")?;
        let path = obj_path(checkpoint.path.path.clone());
        let (name, captured_value) =
            encode_runtime_directory_checkpoint(checkpoint_index, &path, &checkpoint.members)?;
        let promoted_members = members.into_iter().collect::<Vec<_>>();
        let (promoted_name, promoted_value) = encode_ordered_runtime_directory_checkpoint(
            checkpoint_index,
            &path,
            &promoted_members,
            checkpoint.observation_ordinal,
            &before_actions.into_iter().collect::<Vec<_>>(),
            &after_actions.into_iter().collect::<Vec<_>>(),
        )?;
        if promoted_name != name {
            anyhow::bail!("Kbuild promoted directory checkpoint changed its identity");
        }
        let value = actions
            .get_mut(observer_action_index)
            .and_then(|action| action.execution_properties.get_mut(&name))
            .context("Kbuild promoted directory checkpoint has no runtime contract")?;
        if *value != captured_value {
            anyhow::bail!("Kbuild promoted directory checkpoint changed before assembly");
        }
        *value = promoted_value;
    }
    for (observer_action_index, producer_id) in directory_checkpoint_predecessor_edges {
        let dependencies = &mut actions[observer_action_index].dependencies;
        dependencies.push(producer_id);
        dependencies.sort();
        dependencies.dedup();
    }
    for (producer_index, observer_id) in directory_checkpoint_edges {
        let dependencies = &mut actions[producer_index].dependencies;
        dependencies.push(observer_id);
        dependencies.sort();
        dependencies.dedup();
    }
    let analysis_barriers = kbuild_analysis_barriers(
        &actions,
        &captured_action_ids,
        &generated.analyzer_inputs,
        &generated.analyzer_directory_checkpoints,
    )?;

    let mut requested_outputs = Vec::new();
    let mut requested_seen = BTreeSet::new();
    for output in &capture.requested_outputs {
        let output = root_path(output, source_root, output_root)?;
        if output.root != "obj" || !requested_seen.insert(output.clone()) {
            anyhow::bail!("Kbuild snapshot has an invalid requested output");
        }
        requested_outputs.push(output);
    }
    let action_outputs = actions
        .iter()
        .map(|action| {
            action
                .outputs
                .iter()
                .map(|output| output.path.clone())
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let requested_outputs = kbuild_requested_materialization_roots(
        &first.requested_goals,
        requested_outputs,
        &action_outputs,
        &producers,
    )?;

    let mut dependencies = external_inputs.analysis_manifest.deps().to_vec();
    dependencies.extend_from_slice(procfs.analysis_manifest().deps());
    let analysis_manifest = DependencyManifest::from_deps(dependencies);
    let analysis_manifest_digest = analysis_manifest.fingerprint();
    let analysis_dependencies = u64::try_from(analysis_manifest.len())
        .context("Kbuild snapshot analysis dependency count does not fit u64")?;
    let snapshot = ExternalAnalysisSnapshot::new(
        key,
        analyzer,
        analysis_manifest,
        ExternalActionGraph {
            roots: BTreeMap::from([
                ("src".to_string(), source_root.to_path_buf()),
                ("obj".to_string(), output_root.to_path_buf()),
                ("host".to_string(), PathBuf::from("/")),
                ("kconfig".to_string(), output_root.to_path_buf()),
            ]),
            kconfig,
            initial_inputs,
            empty_output_inputs,
            actions,
            analysis_barriers,
            requested_outputs,
        },
    )?;
    let witnesses = ExternalCaptureWitnessReceipt::new(&snapshot, witnesses)?;
    let snapshot_digest = *blake3::hash(&bincode::serialize(&snapshot)?).as_bytes();
    let witness_receipt_digest = *blake3::hash(&bincode::serialize(&witnesses)?).as_bytes();
    let actions = u64::try_from(snapshot.graph.actions.len())
        .context("Kbuild snapshot action count does not fit u64")?;
    let output_files = final_outputs.seal.output_files;
    let output_symlinks = final_outputs.seal.output_symlinks;
    let output_directories = final_outputs.seal.output_directories;
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rush.kbuild-snapshot-assembly.v6\0");
    hasher.update(&ownership.graph_digest);
    hasher.update(&ownership.stream_digest);
    hasher.update(&ownership.assignment_digest);
    hasher.update(&external_inputs.seal.materialization_digest);
    hasher.update(&generated.seal.provenance_digest);
    hasher.update(&procfs_directories.seal.census_digest);
    hasher.update(&final_outputs.seal.materialization_digest);
    hasher.update(&final_namespace.census_digest);
    hasher.update(&analysis_manifest_digest);
    hasher.update(&mandatory.seal.eligibility_digest);
    hasher.update(&actions.to_le_bytes());
    hasher.update(&mandatory_actions.to_le_bytes());
    hasher.update(&analysis_dependencies.to_le_bytes());
    hasher.update(&normal_input_references.to_le_bytes());
    hasher.update(&config_input_references.to_le_bytes());
    hasher.update(&output_files.to_le_bytes());
    hasher.update(&output_symlinks.to_le_bytes());
    hasher.update(&output_directories.to_le_bytes());
    hasher.update(&snapshot_digest);
    hasher.update(&witness_receipt_digest);
    let seal = KbuildSnapshotAssemblySeal {
        graph_digest: ownership.graph_digest,
        stream_digest: ownership.stream_digest,
        assignment_digest: ownership.assignment_digest,
        external_input_materialization_digest: external_inputs.seal.materialization_digest,
        generated_input_provenance_digest: generated.seal.provenance_digest,
        procfs_directory_census_digest: procfs_directories.seal.census_digest,
        final_output_materialization_digest: final_outputs.seal.materialization_digest,
        final_namespace_census_digest: final_namespace.census_digest,
        analysis_manifest_digest,
        mandatory_action_eligibility_digest: mandatory.seal.eligibility_digest,
        actions,
        mandatory_actions,
        analysis_dependencies,
        normal_input_references,
        config_input_references,
        output_files,
        output_symlinks,
        output_directories,
        snapshot_digest,
        witness_receipt_digest,
        assembly_digest: *hasher.finalize().as_bytes(),
    };
    Ok(KbuildAssembledSnapshot {
        seal,
        snapshot,
        witnesses,
        outputs: final_outputs.actions.clone(),
    })
}

#[cfg(unix)]
fn normalized_absolute_path(path: &Path, description: &str) -> Result<PathBuf> {
    if !path.is_absolute() {
        anyhow::bail!("Kbuild {description} is not absolute");
    }
    let mut normalized = PathBuf::from("/");
    for component in path.components() {
        match component {
            Component::RootDir | Component::CurDir => {}
            Component::Normal(value) => normalized.push(value),
            Component::ParentDir => {
                anyhow::bail!("Kbuild {description} contains an unresolved parent component");
            }
            Component::Prefix(_) => {
                anyhow::bail!("Kbuild {description} has an unsupported root");
            }
        }
    }
    Ok(normalized)
}

#[cfg(unix)]
fn output_root_candidate(
    raw: &[u8],
    output_root: &Path,
    description: &str,
) -> Result<(PathBuf, Vec<u8>)> {
    if raw.is_empty() || raw.contains(&0) || raw.ends_with(b" (deleted)") {
        anyhow::bail!("Kbuild {description} has an ambiguous descriptor target");
    }
    let path = normalized_absolute_path(&bytes_path(raw), description)?;
    let relative = path.strip_prefix(output_root).with_context(|| {
        format!(
            "Kbuild {description} {} is outside the output root",
            path.display()
        )
    })?;
    if relative.as_os_str().is_empty() {
        anyhow::bail!("Kbuild {description} names the output root itself");
    }
    let relative = os_bytes(relative.as_os_str());
    Ok((path, relative))
}

#[cfg(unix)]
fn resolved_mutation_path(
    path: &[u8],
    path_is_null: bool,
    base: Option<&[u8]>,
    description: &str,
) -> Result<Vec<u8>> {
    if path_is_null || path.is_empty() || path.contains(&0) {
        anyhow::bail!("Kbuild {description} has an ambiguous pathname");
    }
    let path = bytes_path(path);
    let absolute = if path.is_absolute() {
        path
    } else {
        let base = base.context("Kbuild relative mutation pathname has no observed base")?;
        let base = normalized_absolute_path(&bytes_path(base), "mutation pathname base")?;
        base.join(path)
    };
    let normalized = normalized_absolute_path(&absolute, description)?;
    Ok(os_bytes(normalized.as_os_str()))
}

#[cfg(unix)]
fn declared_kbuild_outputs(
    capture: &KbuildActionGraphCapture,
    output_root: &Path,
) -> Result<(
    BTreeMap<u64, BTreeSet<PathBuf>>,
    BTreeMap<u64, Vec<PathBuf>>,
)> {
    let mut by_action = BTreeMap::new();
    let mut ordered_by_action = BTreeMap::new();
    let mut owners = BTreeMap::new();
    for (index, action) in capture.actions.iter().enumerate() {
        let action_index = u64::try_from(index).context("Kbuild action index does not fit u64")?;
        let mut outputs = BTreeSet::new();
        let mut ordered_outputs = Vec::new();
        for path in &action.persistent_outputs {
            let path = normalized_absolute_path(path, "declared persistent output")?;
            let relative = path
                .strip_prefix(output_root)
                .context("Kbuild declared persistent output is outside the output root")?;
            if relative.as_os_str().is_empty() {
                anyhow::bail!("Kbuild declared persistent output names the output root itself");
            }
            if !outputs.insert(path.clone()) {
                anyhow::bail!("Kbuild action repeats a declared persistent output");
            }
            ordered_outputs.push(path.clone());
            if owners.insert(path, action_index).is_some() {
                anyhow::bail!("Kbuild graph assigns one persistent output to multiple actions");
            }
        }
        by_action.insert(action_index, outputs);
        ordered_by_action.insert(action_index, ordered_outputs);
    }
    Ok((by_action, ordered_by_action))
}

#[cfg(unix)]
fn kbuild_mutation_candidates_at(
    event: &ProcessCaptureStreamEvent<'_>,
    output_root: &Path,
    stream_ordinal: u64,
) -> Result<Vec<KbuildMutationCandidate>> {
    const LINUX_RENAME_NOREPLACE: u32 = 1;

    let ProcessCaptureStreamEvent::PathRenameAttempt { process, attempt } = event else {
        return Ok(
            kbuild_mutation_candidate_at(event, output_root, stream_ordinal)?
                .into_iter()
                .collect(),
        );
    };
    if attempt.outcome != CapturedPathRenameOutcome::Completed {
        return Ok(Vec::new());
    }
    if attempt.request.flags & !LINUX_RENAME_NOREPLACE != 0 {
        anyhow::bail!("Kbuild mutation attribution does not support exchange or whiteout renames");
    }
    if !attempt.request.old_path_terminated || !attempt.request.new_path_terminated {
        anyhow::bail!("Kbuild completed rename has an unterminated pathname");
    }
    let old_target = resolved_mutation_path(
        &attempt.request.old_path,
        attempt.request.old_path_is_null,
        attempt.request.old_base.as_deref(),
        "pathname-rename source",
    )?;
    let new_target = resolved_mutation_path(
        &attempt.request.new_path,
        attempt.request.new_path_is_null,
        attempt.request.new_base.as_deref(),
        "pathname-rename destination",
    )?;
    let (old_path, old_relative) =
        output_root_candidate(&old_target, output_root, "pathname-rename source")?;
    let (new_path, new_relative) =
        output_root_candidate(&new_target, output_root, "pathname-rename destination")?;
    if old_path == new_path {
        anyhow::bail!("Kbuild completed rename has the same source and destination");
    }
    Ok(vec![
        KbuildMutationCandidate {
            process: *process,
            stream_ordinal,
            syscall_index: attempt.syscall_index,
            kind: KbuildMutationCandidateKind::PathRenameSource,
            object: None,
            path: old_path,
            relative: old_relative,
        },
        KbuildMutationCandidate {
            process: *process,
            stream_ordinal,
            syscall_index: attempt.syscall_index,
            kind: KbuildMutationCandidateKind::PathRenameDestination,
            object: None,
            path: new_path,
            relative: new_relative,
        },
    ])
}

#[cfg(unix)]
fn kbuild_mutation_candidate_at(
    event: &ProcessCaptureStreamEvent<'_>,
    output_root: &Path,
    stream_ordinal: u64,
) -> Result<Option<KbuildMutationCandidate>> {
    const LINUX_O_CREAT: u64 = 0o100;
    const LINUX_O_TRUNC: u64 = 0o1000;
    const LINUX_O_TMPFILE: u64 = 0o20200000;
    const LINUX_PROT_WRITE: u64 = 0x2;
    const LINUX_MAP_TYPE: u64 = 0x0f;
    const LINUX_MAP_SHARED: u64 = 0x01;
    const LINUX_MAP_SHARED_VALIDATE: u64 = 0x03;
    const LINUX_UTIME_OMIT: i64 = (1 << 30) - 2;

    let make_candidate = |process, syscall_index, kind, object, target: &[u8], description| {
        let (path, relative) = output_root_candidate(target, output_root, description)?;
        Ok(Some(KbuildMutationCandidate {
            process,
            stream_ordinal,
            syscall_index,
            kind,
            object,
            path,
            relative,
        }))
    };

    match event {
        ProcessCaptureStreamEvent::OpenAttempt { process, attempt } => {
            let CapturedOpenOutcome::Opened {
                identity, mount_id, ..
            } = &attempt.outcome
            else {
                return Ok(None);
            };
            if attempt.request.flags & LINUX_O_TMPFILE == LINUX_O_TMPFILE {
                anyhow::bail!("Kbuild mutation attribution does not support O_TMPFILE");
            }
            if attempt.request.flags & (LINUX_O_CREAT | LINUX_O_TRUNC) == 0 {
                return Ok(None);
            }
            if identity.kind != CapturedDescriptorKind::RegularFile {
                if identity.kind == CapturedDescriptorKind::CharacterDevice
                    && identity.target == b"/dev/null"
                {
                    return Ok(None);
                }
                anyhow::bail!(
                    "Kbuild create-or-truncate open resolved to an unsupported non-regular file"
                );
            }
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::CreateOrTruncateOpen,
                Some(kbuild_output_object(identity, *mount_id)?),
                &identity.target,
                "create-or-truncate target",
            )
        }
        ProcessCaptureStreamEvent::WriteAttempt { process, attempt } => {
            let CapturedWriteOutcome::Wrote { bytes, .. } = attempt.outcome else {
                return Ok(None);
            };
            if bytes == 0 {
                return Ok(None);
            }
            let identity = attempt
                .request
                .identity
                .as_ref()
                .context("Kbuild successful write has no descriptor identity")?;
            if identity.kind != CapturedDescriptorKind::RegularFile {
                return Ok(None);
            }
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::DescriptorWrite,
                Some(kbuild_output_object(
                    identity,
                    attempt
                        .request
                        .mount_id
                        .context("Kbuild successful write has no mount identity")?,
                )?),
                &identity.target,
                "regular-file write target",
            )
        }
        ProcessCaptureStreamEvent::XattrAttempt { process, attempt }
            if attempt.request.system_call == CapturedXattrSystemCall::Fsetxattr
                && attempt.outcome == CapturedXattrOutcome::Changed =>
        {
            let identity = attempt
                .request
                .descriptor_identity
                .as_ref()
                .context("Kbuild successful fsetxattr has no descriptor identity")?;
            let mount_id = attempt
                .request
                .descriptor_mount_id
                .context("Kbuild successful fsetxattr has no mount identity")?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::DescriptorXattrChange,
                Some(kbuild_output_object(identity, mount_id)?),
                &identity.target,
                "descriptor extended-attribute target",
            )
        }
        ProcessCaptureStreamEvent::MmapAttempt { process, attempt } => {
            let CapturedMmapOutcome::Mapped { .. } = attempt.outcome else {
                return Ok(None);
            };
            let mapping_type = attempt.request.flags & LINUX_MAP_TYPE;
            let shared =
                mapping_type == LINUX_MAP_SHARED || mapping_type == LINUX_MAP_SHARED_VALIDATE;
            let Some(identity) = attempt
                .request
                .identity
                .as_ref()
                .filter(|identity| identity.kind == CapturedDescriptorKind::RegularFile)
            else {
                return Ok(None);
            };
            if shared && attempt.request.protection & LINUX_PROT_WRITE != 0 {
                return make_candidate(
                    *process,
                    attempt.syscall_index,
                    KbuildMutationCandidateKind::SharedWritableMapping,
                    Some(kbuild_output_object(
                        identity,
                        attempt
                            .request
                            .mount_id
                            .context("Kbuild writable shared mapping has no mount identity")?,
                    )?),
                    &identity.target,
                    "writable shared mapping target",
                );
            }
            Ok(None)
        }
        ProcessCaptureStreamEvent::PathRemovalAttempt { process, attempt }
            if attempt.outcome == CapturedPathRemovalOutcome::Removed =>
        {
            let target = resolved_mutation_path(
                &attempt.request.path,
                attempt.request.path_is_null,
                attempt.request.base.as_deref(),
                "pathname removal target",
            )?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::PathRemoval,
                None,
                &target,
                "pathname removal target",
            )
        }
        ProcessCaptureStreamEvent::DirectoryCreationAttempt { process, attempt }
            if attempt.outcome == CapturedDirectoryCreationOutcome::Created =>
        {
            let target = resolved_mutation_path(
                &attempt.request.path,
                attempt.request.path_is_null,
                attempt.request.base.as_deref(),
                "directory-creation target",
            )?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::DirectoryCreation,
                None,
                &target,
                "directory-creation target",
            )
        }
        ProcessCaptureStreamEvent::PathRenameAttempt { attempt, .. }
            if attempt.outcome == CapturedPathRenameOutcome::Completed =>
        {
            anyhow::bail!("Kbuild pathname rename requires dual-path attribution")
        }
        ProcessCaptureStreamEvent::PathModeChangeAttempt { process, attempt }
            if attempt.outcome == CapturedPathModeChangeOutcome::Changed =>
        {
            if attempt.request.system_call == CapturedPathModeChangeSystemCall::Fchmod {
                let identity = attempt
                    .request
                    .descriptor_identity
                    .as_ref()
                    .context("Kbuild successful fchmod has no descriptor identity")?;
                let mount_id = attempt
                    .request
                    .descriptor_mount_id
                    .context("Kbuild successful fchmod has no mount identity")?;
                return make_candidate(
                    *process,
                    attempt.syscall_index,
                    KbuildMutationCandidateKind::DescriptorModeChange,
                    Some(kbuild_output_object(identity, mount_id)?),
                    &identity.target,
                    "descriptor mode-change target",
                );
            }
            if !attempt.request.path_terminated {
                anyhow::bail!("Kbuild successful pathname chmod has an unterminated pathname");
            }
            let target = resolved_mutation_path(
                &attempt.request.path,
                attempt.request.path_is_null,
                attempt.request.base.as_deref(),
                "pathname mode-change target",
            )?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::PathModeChange,
                None,
                &target,
                "pathname mode-change target",
            )
        }
        ProcessCaptureStreamEvent::DescriptorTimestampChangeAttempt { process, attempt }
            if attempt.outcome == CapturedDescriptorTimestampChangeOutcome::Changed =>
        {
            if attempt.request.times.is_some_and(|times| {
                times
                    .iter()
                    .all(|timestamp| timestamp.nanoseconds == LINUX_UTIME_OMIT)
            }) {
                return Ok(None);
            }
            let identity = attempt
                .request
                .identity
                .as_ref()
                .context("Kbuild successful timestamp change has no descriptor identity")?;
            let mount_id = attempt
                .request
                .mount_id
                .context("Kbuild successful timestamp change has no mount identity")?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::DescriptorTimestampChange,
                Some(kbuild_output_object(identity, mount_id)?),
                &identity.target,
                "descriptor timestamp-change target",
            )
        }
        ProcessCaptureStreamEvent::SymbolicLinkCreationAttempt { process, attempt }
            if attempt.outcome == CapturedSymbolicLinkCreationOutcome::Created =>
        {
            if attempt.request.target_is_null || !attempt.request.target_terminated {
                anyhow::bail!("Kbuild created symbolic link has an ambiguous target");
            }
            if !attempt.request.link_path_terminated {
                anyhow::bail!("Kbuild created symbolic link has an unterminated link pathname");
            }
            let link_path = resolved_mutation_path(
                &attempt.request.link_path,
                attempt.request.link_path_is_null,
                attempt.request.base.as_deref(),
                "symbolic-link creation link pathname",
            )?;
            make_candidate(
                *process,
                attempt.syscall_index,
                KbuildMutationCandidateKind::SymbolicLinkCreation,
                None,
                &link_path,
                "symbolic-link creation link pathname",
            )
        }
        _ => Ok(None),
    }
}

#[cfg(all(unix, test))]
fn kbuild_mutation_candidate(
    event: &ProcessCaptureStreamEvent<'_>,
    output_root: &Path,
) -> Result<Option<KbuildMutationCandidate>> {
    kbuild_mutation_candidate_at(event, output_root, 0)
}

#[cfg(unix)]
fn require_unique_mutation_candidate_owners(
    candidates: &BTreeMap<KbuildProcessOwner, BTreeSet<PathBuf>>,
) -> Result<()> {
    let mut owners = BTreeMap::new();
    for (owner, paths) in candidates {
        for path in paths {
            if owners.insert(path, *owner).is_some() {
                anyhow::bail!("Kbuild mutation candidate has multiple process owners");
            }
        }
    }
    Ok(())
}

#[cfg(unix)]
fn classify_kbuild_owner_mutation_paths(
    expected_owner: KbuildProcessOwner,
    owner_description: &str,
    actual: &BTreeSet<PathBuf>,
    declared: &BTreeSet<PathBuf>,
    certified_precreated_transients: &BTreeSet<PathBuf>,
    events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
) -> Result<(u64, u64)> {
    let missing = declared.difference(actual).count();
    let undeclared = actual.difference(declared).collect::<Vec<_>>();
    if missing != 0 {
        anyhow::bail!(
            "Kbuild {owner_description} mutation candidates have {missing} missing and {} \
             undeclared paths",
            undeclared.len()
        );
    }
    if !certified_precreated_transients.is_disjoint(declared) {
        anyhow::bail!(
            "Kbuild {owner_description} certified precreated transient is also declared"
        );
    }
    let missing_certified_precreated = certified_precreated_transients.difference(actual).count();
    if missing_certified_precreated != 0 {
        anyhow::bail!(
            "Kbuild {owner_description} has {missing_certified_precreated} certified precreated \
             transients without mutation candidates"
        );
    }

    for path in declared {
        std::fs::symlink_metadata(path).with_context(|| {
            format!(
                "stat retained Kbuild {owner_description} output {}",
                path.display()
            )
        })?;
    }

    let mut invalid_paths = 0_u64;
    let mut missing_creation = 0_u64;
    let mut missing_final_removal = 0_u64;
    let mut missing_final_absence = 0_u64;
    let mut first_invalid = None;
    for path in &undeclared {
        let path_candidates = events
            .iter()
            .filter(|(event_owner, candidate)| {
                *event_owner == expected_owner && candidate.path.as_path() == path.as_path()
            })
            .collect::<Vec<_>>();
        let path_events = path_candidates
            .iter()
            .map(|(_, candidate)| candidate.kind)
            .collect::<Vec<_>>();
        let opened_for_create_or_truncate = path_events
            .iter()
            .any(|kind| *kind == KbuildMutationCandidateKind::CreateOrTruncateOpen);
        let created_directory = path_events
            .iter()
            .any(|kind| *kind == KbuildMutationCandidateKind::DirectoryCreation);
        let created_symbolic_link = path_events
            .iter()
            .any(|kind| *kind == KbuildMutationCandidateKind::SymbolicLinkCreation);
        let published_by_rename = path_events
            .iter()
            .any(|kind| *kind == KbuildMutationCandidateKind::PathRenameDestination);
        let removed_last = matches!(
            path_events.last(),
            Some(
                KbuildMutationCandidateKind::PathRemoval
                    | KbuildMutationCandidateKind::PathRenameSource
            )
        );
        let absent = match std::fs::symlink_metadata(path) {
            Ok(_) => false,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => true,
            Err(error) => {
                return Err(error).with_context(|| {
                    format!(
                        "stat transient Kbuild {owner_description} path {}",
                        path.display()
                    )
                });
            }
        };
        let has_creation = opened_for_create_or_truncate
            || created_directory
            || created_symbolic_link
            || published_by_rename
            || certified_precreated_transients.contains(path.as_path());
        if !has_creation || !removed_last || !absent {
            invalid_paths = invalid_paths
                .checked_add(1)
                .context("Kbuild invalid undeclared mutation-path count overflowed")?;
            missing_creation = missing_creation
                .checked_add(u64::from(!has_creation))
                .context("Kbuild missing-creation mutation-path count overflowed")?;
            missing_final_removal = missing_final_removal
                .checked_add(u64::from(!removed_last))
                .context("Kbuild missing-removal mutation-path count overflowed")?;
            missing_final_absence = missing_final_absence
                .checked_add(u64::from(!absent))
                .context("Kbuild retained-undeclared mutation-path count overflowed")?;
            first_invalid.get_or_insert_with(|| {
                (
                    path_candidates
                        .first()
                        .map(|(_, candidate)| candidate.relative.clone())
                        .unwrap_or_default(),
                    path_events,
                    has_creation,
                    removed_last,
                    absent,
                )
            });
        }
    }
    if let Some((relative, event_kinds, has_creation, removed_last, absent)) = first_invalid {
        anyhow::bail!(
            "Kbuild {owner_description} mutation candidates have 0 missing and {} undeclared \
             paths: {invalid_paths} invalid; an undeclared path lacks a same-owner creation, \
             final removal, or final absence; missing_creation={missing_creation} \
             missing_final_removal={missing_final_removal} \
             missing_final_absence={missing_final_absence} first_relative={} \
             first_events={event_kinds:?} first_has_creation={has_creation} \
             first_removed_last={removed_last} first_absent={absent}",
            undeclared.len(),
            String::from_utf8_lossy(&relative)
        );
    }

    Ok((
        u64::try_from(declared.len())
            .context("Kbuild persistent mutation-path count does not fit u64")?,
        u64::try_from(undeclared.len())
            .context("Kbuild transient mutation-path count does not fit u64")?,
    ))
}

#[cfg(unix)]
fn classify_kbuild_action_mutation_paths(
    action_index: u64,
    actual: &BTreeSet<PathBuf>,
    declared: &BTreeSet<PathBuf>,
    events: &[(KbuildProcessOwner, KbuildMutationCandidate)],
) -> Result<(u64, u64)> {
    classify_kbuild_owner_mutation_paths(
        KbuildProcessOwner::Action(action_index),
        &format!("action {action_index}"),
        actual,
        declared,
        &BTreeSet::new(),
        events,
    )
}

#[cfg(unix)]
fn kbuild_owner_record_lock_count(
    owner: KbuildProcessOwner,
    actual: &BTreeSet<PathBuf>,
    persistent: &BTreeSet<PathBuf>,
    record_locks: &[(KbuildProcessOwner, PathBuf)],
) -> Result<u64> {
    let paths = record_locks
        .iter()
        .filter(|(record_owner, _)| *record_owner == owner)
        .map(|(_, path)| path)
        .collect::<Vec<_>>();
    if paths
        .iter()
        .any(|path| persistent.contains(*path) || !actual.contains(*path))
    {
        anyhow::bail!("Kbuild owner record lock is not bound to a transient mutation path");
    }
    u64::try_from(paths.len()).context("Kbuild owner record-lock count does not fit u64")
}

#[cfg(unix)]
fn validate_kbuild_signal_deliveries(
    process_parents: &BTreeMap<CapturedProcessId, Option<CapturedProcessId>>,
    process_outcomes: &BTreeMap<CapturedProcessId, CapturedProcessOutcome>,
    deliveries: &[(CapturedProcessId, CapturedSignalDelivery)],
) -> Result<()> {
    let mut notified_children = BTreeSet::new();
    for (target, delivery) in deliveries {
        let CapturedSignalSource::TracedProcess { process: child } = delivery.source else {
            anyhow::bail!("Kbuild signal delivery does not come from a traced child process");
        };
        let expected_parent = process_parents.get(&child).copied().flatten();
        let duplicate = notified_children.contains(&child);
        if delivery.signal != nix::libc::SIGCHLD as u32
            || delivery.code != nix::libc::CLD_EXITED
            || delivery.errno != 0
            || delivery.active_syscall.is_some()
            || expected_parent != Some(*target)
            || duplicate
        {
            anyhow::bail!(
                "Kbuild signal delivery is not a unique completed-child notification: \
                 target={target:?} child={child:?} signal={} expected_signal={} code={} \
                 expected_code={} errno={} active_syscall={:?} expected_parent={expected_parent:?} \
                 duplicate={duplicate}",
                delivery.signal,
                nix::libc::SIGCHLD,
                delivery.code,
                nix::libc::CLD_EXITED,
                delivery.errno,
                delivery.active_syscall,
            );
        }
        notified_children.insert(child);
        let status = delivery
            .child_status
            .context("Kbuild child-exit signal delivery has no exit status")?;
        if process_outcomes.get(&child) != Some(&CapturedProcessOutcome::Exited(status)) {
            anyhow::bail!("Kbuild child-exit signal delivery does not match the child outcome");
        }
    }
    Ok(())
}

#[cfg(unix)]
fn validate_kbuild_ignored_openssl_sigpipes(
    process_outcomes: &BTreeMap<CapturedProcessId, CapturedProcessOutcome>,
    invocation_counts: &BTreeMap<CapturedProcessId, u64>,
    openssl_key_manager_processes: &BTreeSet<CapturedProcessId>,
    writes: &[(CapturedProcessId, u64, rush_observe::CapturedWriteAttempt)],
    deliveries: &[(CapturedProcessId, CapturedSignalDelivery)],
    delivery_ordinals: &[u64],
) -> Result<(
    Vec<(CapturedProcessId, CapturedSignalDelivery)>,
    Vec<u64>,
)> {
    if deliveries.len() != delivery_ordinals.len() {
        anyhow::bail!("Kbuild signal delivery ordinals do not match the deliveries");
    }
    let mut retained = Vec::new();
    let mut retained_ordinals = Vec::new();
    let mut matched_writes = BTreeSet::new();
    for ((target, delivery), delivery_ordinal) in deliveries.iter().zip(delivery_ordinals) {
        if delivery.signal != nix::libc::SIGPIPE as u32 {
            retained.push((*target, *delivery));
            retained_ordinals.push(*delivery_ordinal);
            continue;
        }
        let CapturedSignalSource::TracedProcess { process: source } = delivery.source else {
            anyhow::bail!("Kbuild ignored OpenSSL SIGPIPE has no traced self source");
        };
        if source != *target
            || delivery.code != nix::libc::SI_USER
            || delivery.errno != 0
            || delivery.child_status.is_some()
            || delivery.active_syscall.is_some()
            || delivery.disposition != CapturedSignalDisposition::Ignored
            || invocation_counts.get(target) != Some(&1)
            || !openssl_key_manager_processes.contains(target)
            || process_outcomes.get(target) != Some(&CapturedProcessOutcome::Exited(0))
        {
            anyhow::bail!("Kbuild ignored OpenSSL SIGPIPE has no exact process binding");
        }
        let Some((write_index, _)) = writes.iter().enumerate().find(
            |(write_index, (process, write_ordinal, attempt))| {
                !matched_writes.contains(write_index)
                    && process == target
                    && write_ordinal < delivery_ordinal
                    && attempt.syscall_index.checked_add(1) == Some(delivery.syscall_entries)
                    && kbuild_openssl_sigpipe_write(attempt)
            },
        ) else {
            anyhow::bail!("Kbuild ignored OpenSSL SIGPIPE has no exact EPIPE write witness");
        };
        matched_writes.insert(write_index);
    }
    if matched_writes.len() != writes.len() {
        anyhow::bail!("Kbuild OpenSSL EPIPE write has no exact ignored SIGPIPE delivery");
    }
    Ok((retained, retained_ordinals))
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
const KBUILD_SI_TKILL: i32 = nix::libc::SI_TKILL;

#[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
const KBUILD_SI_TKILL: i32 = i32::MIN;

#[cfg(unix)]
fn kbuild_process_within_lineage(
    process_parents: &BTreeMap<CapturedProcessId, Option<CapturedProcessId>>,
    process: CapturedProcessId,
    ancestor: CapturedProcessId,
) -> bool {
    let mut current = Some(process);
    let mut visited = BTreeSet::new();
    while let Some(candidate) = current {
        if candidate == ancestor {
            return true;
        }
        if !visited.insert(candidate) {
            return false;
        }
        current = process_parents.get(&candidate).copied().flatten();
    }
    false
}

#[cfg(unix)]
fn validate_kbuild_signal_deliveries_with_rustc(
    process_parents: &BTreeMap<CapturedProcessId, Option<CapturedProcessId>>,
    process_outcomes: &BTreeMap<CapturedProcessId, CapturedProcessOutcome>,
    rustc_processes: &BTreeSet<CapturedProcessId>,
    rustc_sigusr1_requests: &[(CapturedProcessId, u64)],
    deliveries: &[(CapturedProcessId, CapturedSignalDelivery)],
    delivery_ordinals: &[u64],
) -> Result<()> {
    if deliveries.len() != delivery_ordinals.len() {
        anyhow::bail!("Kbuild signal delivery ordinals do not match the deliveries");
    }
    let mut child_deliveries = Vec::new();
    let mut matched_requests = BTreeSet::new();
    for ((target, delivery), delivery_ordinal) in deliveries.iter().zip(delivery_ordinals) {
        if delivery.signal != nix::libc::SIGUSR1 as u32 {
            child_deliveries.push((*target, *delivery));
            continue;
        }
        let CapturedSignalSource::TracedProcess { process: source } = delivery.source else {
            anyhow::bail!("Kbuild rustc SIGUSR1 delivery has no traced source");
        };
        if delivery.code != KBUILD_SI_TKILL
            || delivery.errno != 0
            || delivery.active_syscall.is_some()
            || delivery.child_status.is_some()
            || delivery.syscall_entries == 0
            || delivery.disposition != CapturedSignalDisposition::Caught
            || source == *target
            || !rustc_processes.contains(&source)
            || !rustc_processes.contains(target)
            || !kbuild_process_within_lineage(process_parents, *target, source)
        {
            anyhow::bail!("Kbuild rustc SIGUSR1 delivery has no exact thread-group binding");
        }
        let Some((request_index, _)) = rustc_sigusr1_requests.iter().enumerate().find(
            |(request_index, (sender, request_ordinal))| {
                !matched_requests.contains(request_index)
                    && request_ordinal < delivery_ordinal
                    && rustc_processes.contains(sender)
                    && kbuild_process_within_lineage(process_parents, *sender, source)
            },
        ) else {
            anyhow::bail!("Kbuild rustc SIGUSR1 delivery has no earlier tgkill request");
        };
        matched_requests.insert(request_index);
    }
    if matched_requests.len() != rustc_sigusr1_requests.len() {
        anyhow::bail!("Kbuild rustc tgkill request has no exact SIGUSR1 delivery");
    }
    validate_kbuild_signal_deliveries(process_parents, process_outcomes, &child_deliveries)
}

#[cfg(unix)]
fn validate_kbuild_exec_pending_signals(
    state: rush_observe::CapturedExecSignalState,
) -> Result<u64> {
    // A blocked SIGCHLD cannot interrupt the new image. It is replay-neutral
    // only while every later mask transition keeps it blocked and no supported
    // signal-consumption path observes it. The transition check below proves
    // the former; every sigpending, sigwait, signalfd, and atomic-unmask wait
    // remains an unmodeled syscall that the ordinary Kbuild gate rejects.
    let child_exit = 1_u64 << (nix::libc::SIGCHLD - 1);
    if state.pending != 0 {
        anyhow::bail!("Kbuild exec boundary has a thread-pending signal");
    }
    if state.shared_pending & !child_exit != 0 {
        anyhow::bail!("Kbuild exec boundary has an unsupported shared-pending signal");
    }
    if state.shared_pending & !state.blocked != 0 {
        anyhow::bail!("Kbuild exec boundary has an unblocked pending child-exit signal");
    }
    Ok(state.shared_pending)
}

#[cfg(unix)]
fn validate_kbuild_pending_signal_mask_attempt(
    pending: u64,
    attempt: &CapturedSignalStateAttempt,
) -> Result<()> {
    if pending == 0 {
        return Ok(());
    }
    let (
        CapturedSignalStateRequest::Mask {
            operation,
            mask: Some(mask),
            ..
        },
        CapturedSignalStateOutcome::MaskReturned { .. },
    ) = (&attempt.request, &attempt.outcome)
    else {
        return Ok(());
    };
    let requested = u64::from_ne_bytes(
        mask.as_slice()
            .try_into()
            .context("Kbuild signal-mask transition is not one native mask")?,
    );
    match *operation {
        libc::SIG_BLOCK => {}
        libc::SIG_UNBLOCK if requested & pending == 0 => {}
        libc::SIG_SETMASK if requested & pending == pending => {}
        libc::SIG_UNBLOCK | libc::SIG_SETMASK => {
            anyhow::bail!("Kbuild exec-pending signal becomes unblocked")
        }
        _ => anyhow::bail!("Kbuild signal-mask transition has an invalid operation"),
    }
    Ok(())
}

#[cfg(unix)]
fn validate_kbuild_signal_returns(
    deliveries: &[(CapturedProcessId, CapturedSignalDelivery)],
    returns: &[(CapturedProcessId, u64)],
) -> Result<()> {
    let mut next_delivery = BTreeMap::new();
    let mut indexed_deliveries = BTreeMap::new();
    let mut caught_deliveries = BTreeSet::new();
    for (target, delivery) in deliveries {
        let index = next_delivery.entry(*target).or_insert(0_u64);
        indexed_deliveries.insert((*target, *index), *delivery);
        if delivery.disposition == CapturedSignalDisposition::Caught {
            caught_deliveries.insert((*target, *index));
        }
        *index = index
            .checked_add(1)
            .context("Kbuild signal-delivery index overflowed")?;
    }
    let mut returned = BTreeSet::new();
    for (target, delivery) in returns {
        let key = (*target, *delivery);
        let child_delivery = indexed_deliveries.get(&key).is_some_and(|candidate| {
            candidate.disposition == CapturedSignalDisposition::Caught
                && matches!(
                    candidate.source,
                    CapturedSignalSource::TracedProcess { process }
                        if process != 0
                )
        });
        if !returned.insert(key) || !child_delivery {
            anyhow::bail!("Kbuild signal return is not bound to its child-exit delivery");
        }
    }
    if returned != caught_deliveries {
        anyhow::bail!("Kbuild caught signal deliveries do not have exact returns");
    }
    Ok(())
}

