    #[test]
    fn directory_output_member_promotion_is_exact_and_direct() {
        let directory = obj_path(b"init".to_vec());
        let output = |root: &str, path: &[u8]| ExternalOutput {
            path: ExternalPathKey {
                root: root.to_string(),
                path: path.to_vec(),
            },
            kind: ExternalOutputKind::File,
            mode: 0o644,
        };
        let outputs = vec![
            output("obj", b"init/version-timestamp.o"),
            output("obj", b"init/.version-timestamp.o.cmd"),
            output("obj", b"init/generated/table.h"),
            output("obj", b"other/ignored"),
            output("src", b"init/ignored"),
        ];
        let mut members = BTreeSet::from([b"built-in.a".to_vec()]);

        assert!(kbuild_add_directory_output_members(
            &mut members,
            &directory,
            &outputs,
        ));
        assert_eq!(
            members,
            BTreeSet::from([
                b".version-timestamp.o.cmd".to_vec(),
                b"built-in.a".to_vec(),
                b"generated".to_vec(),
                b"version-timestamp.o".to_vec(),
            ])
        );
        assert!(!kbuild_add_directory_output_members(
            &mut members,
            &directory,
            &outputs,
        ));
    }

