    #[cfg(unix)]
    #[test]
    fn procfs_fd_directory_requires_exact_self_open() {
        let flags = u64::try_from(libc::O_DIRECTORY | libc::O_NONBLOCK | libc::O_CLOEXEC).unwrap();
        let open = CapturedOpenAttempt {
            syscall_index: 10,
            request: CapturedOpenRequest {
                system_call: CapturedOpenSystemCall::OpenAt,
                path: b"/proc/self/fd".to_vec(),
                directory: None,
                flags,
                mode: 0,
                resolve: 0,
            },
            outcome: CapturedOpenOutcome::Opened {
                descriptor: 3,
                identity: CapturedDescriptorIdentity {
                    target: b"/proc/4321/fd".to_vec(),
                    device: 4,
                    inode: 5,
                    kind: CapturedDescriptorKind::Directory,
                },
                mount_id: 6,
                file_value: None,
            },
        };
        let (descriptor, binding) = kbuild_procfs_self_fd_directory_binding(9, &open)
            .unwrap()
            .expect("exact self fd directory open");
        assert_eq!(descriptor, 3);
        assert_eq!(binding.path, PathBuf::from("/proc/4321/fd"));
        assert!(kbuild_direct_directory_descriptor_binding(9, &open)
            .unwrap()
            .is_none());

        let mut invalid = open.clone();
        invalid.request.path = b"/proc/4321/fd".to_vec();
        assert!(kbuild_procfs_self_fd_directory_binding(9, &invalid)
            .unwrap()
            .is_none());
        let mut invalid = open.clone();
        invalid.request.flags ^= libc::O_NONBLOCK as u64;
        assert!(kbuild_procfs_self_fd_directory_binding(9, &invalid)
            .unwrap()
            .is_none());
        let mut invalid = open.clone();
        invalid.request.flags |= libc::O_NOFOLLOW as u64;
        assert!(kbuild_procfs_self_fd_directory_binding(9, &invalid)
            .unwrap()
            .is_none());
        let mut invalid = open.clone();
        invalid.request.system_call = CapturedOpenSystemCall::OpenAt2;
        assert!(kbuild_procfs_self_fd_directory_binding(9, &invalid)
            .unwrap()
            .is_none());
        let mut invalid = open.clone();
        let CapturedOpenOutcome::Opened {
            identity,
            file_value,
            ..
        } = &mut invalid.outcome
        else {
            unreachable!();
        };
        identity.target = b"/proc/self/fd".to_vec();
        *file_value = Some(CapturedMappedFileValue::Unwitnessed);
        assert!(kbuild_procfs_self_fd_directory_binding(9, &invalid)
            .unwrap()
            .is_none());
    }

