    #[cfg(unix)]
    #[test]
    fn proved_membership_effects_order_concurrent_directory_checkpoints() {
        let batch = |kind_tag, subject| KbuildDirectoryEffectBatch {
            owner: KbuildProcessOwner::Action(0),
            event: KbuildProcessEventKey {
                process: 1,
                syscall_index: 2,
                stream_ordinal: 3,
            },
            effects: vec![KbuildDirectoryEffectDescriptor { kind_tag, subject }],
        };
        let members = vec![b"present".to_vec()];
        let present = KbuildDirectoryEffectSubject::Member(b"present".to_vec());
        let absent = KbuildDirectoryEffectSubject::Member(b"absent".to_vec());

        assert_eq!(
            kbuild_membership_proved_directory_relation(&batch(4, present.clone()), &members)
                .unwrap(),
            Some(0)
        );
        assert_eq!(
            kbuild_membership_proved_directory_relation(&batch(4, absent.clone()), &members)
                .unwrap(),
            Some(1)
        );
        assert_eq!(
            kbuild_membership_proved_directory_relation(&batch(2, present.clone()), &members)
                .unwrap(),
            Some(1)
        );
        assert_eq!(
            kbuild_membership_proved_directory_relation(&batch(2, absent.clone()), &members)
                .unwrap(),
            Some(0)
        );
        assert_eq!(
            kbuild_membership_proved_directory_relation(&batch(0, present), &members).unwrap(),
            None
        );
        assert_eq!(
            kbuild_membership_proved_directory_relation(
                &batch(4, KbuildDirectoryEffectSubject::DirectoryObject),
                &members,
            )
            .unwrap(),
            None
        );

        let mut conflicting = batch(4, KbuildDirectoryEffectSubject::Member(b"present".to_vec()));
        conflicting.effects.push(KbuildDirectoryEffectDescriptor {
            kind_tag: 4,
            subject: absent,
        });
        assert_eq!(
            kbuild_membership_proved_directory_relation(&conflicting, &members).unwrap(),
            None
        );
    }

    #[cfg(unix)]
    #[test]
    fn fresh_directory_orders_unique_retained_creates() {
        let batch = |action_index, kind_tag, subject| KbuildDirectoryEffectBatch {
            owner: KbuildProcessOwner::Action(action_index),
            event: KbuildProcessEventKey {
                process: action_index + 1,
                syscall_index: 2,
                stream_ordinal: 3,
            },
            effects: vec![KbuildDirectoryEffectDescriptor { kind_tag, subject }],
        };
        let directory = batch(0, 4, KbuildDirectoryEffectSubject::DirectoryObject);
        let member = KbuildDirectoryEffectSubject::Member(b"retained".to_vec());
        let create = batch(1, 0, member.clone());
        let members = vec![b"retained".to_vec()];
        let batches = vec![directory.clone(), create.clone()];

        assert_eq!(
            kbuild_fresh_directory_proved_relation(&directory, &batches, &members),
            Some(0)
        );
        assert_eq!(
            kbuild_fresh_directory_proved_relation(&create, &batches, &members),
            Some(0)
        );
        assert_eq!(
            kbuild_fresh_directory_proved_relation(&create, &batches, &[]),
            Some(1)
        );

        let duplicate = batch(2, 0, member);
        let duplicate_batches = vec![directory.clone(), create.clone(), duplicate];
        assert_eq!(
            kbuild_fresh_directory_proved_relation(&create, &duplicate_batches, &members),
            None
        );

        let removed = batch(3, 2, KbuildDirectoryEffectSubject::DirectoryObject);
        let replaced_batches = vec![directory, create.clone(), removed];
        assert_eq!(
            kbuild_fresh_directory_proved_relation(&create, &replaced_batches, &members),
            None
        );
    }

    #[cfg(unix)]
    #[test]
    fn exact_action_side_orders_unresolved_directory_coeffects() {
        let batch = |action_index| KbuildDirectoryEffectBatch {
            owner: KbuildProcessOwner::Action(action_index),
            event: KbuildProcessEventKey {
                process: action_index + 1,
                syscall_index: 2,
                stream_ordinal: 3,
            },
            effects: vec![KbuildDirectoryEffectDescriptor {
                kind_tag: 6,
                subject: KbuildDirectoryEffectSubject::Member(b"member".to_vec()),
            }],
        };

        let batches = vec![batch(4), batch(4)];
        let mut relations = vec![1, 2];
        kbuild_resolve_action_directory_relations(&batches, &mut relations, None);
        assert_eq!(relations, vec![1, 1]);

        let batches = vec![batch(4), batch(4), batch(4)];
        let mut relations = vec![0, 1, 2];
        kbuild_resolve_action_directory_relations(&batches, &mut relations, None);
        assert_eq!(relations, vec![0, 1, 2]);

        let batches = vec![batch(4), batch(4)];
        let mut relations = vec![1, 2];
        kbuild_resolve_action_directory_relations(&batches, &mut relations, Some(4));
        assert_eq!(relations, vec![1, 2]);
    }

    #[cfg(unix)]
    #[test]
    fn exact_phony_goals_root_every_captured_action() {
        let path = |name: &[u8]| ExternalPathKey {
            root: "obj".to_string(),
            path: name.to_vec(),
        };
        let first = path(b"first");
        let second = path(b"second");
        let producers = BTreeMap::from([(first.clone(), 0), (second.clone(), 1)]);
        let action_outputs = vec![vec![first.clone()], vec![second.clone()]];

        assert_eq!(
            kbuild_requested_materialization_roots(
                &[b"first".to_vec()],
                vec![first.clone()],
                &action_outputs,
                &producers,
            )
            .unwrap(),
            vec![first.clone()]
        );
        assert_eq!(
            kbuild_requested_materialization_roots(
                &[b"prepare".to_vec()],
                vec![path(b"prepare")],
                &action_outputs,
                &producers,
            )
            .unwrap(),
            vec![first.clone(), second.clone()]
        );
        assert!(kbuild_requested_materialization_roots(
            &[b"first".to_vec(), b"prepare".to_vec()],
            vec![first, path(b"prepare")],
            &action_outputs,
            &producers,
        )
        .is_err());
        assert!(kbuild_requested_materialization_roots(
            &[b"other".to_vec()],
            vec![path(b"prepare")],
            &action_outputs,
            &producers,
        )
        .is_err());
    }

    #[cfg(unix)]
