    #[cfg(unix)]
    #[test]
    fn unowned_namespace_materializes_exact_seed_values() {
        let temp = tempfile::tempdir().unwrap();
        let output_root = temp.path().join("obj");
        let seed = output_root.join("seed");
        std::fs::create_dir_all(&seed).unwrap();
        std::fs::write(seed.join("value"), b"seed-value").unwrap();
        std::os::unix::fs::symlink("value", seed.join("link")).unwrap();
          let output = output_root.join("generated");
          std::fs::write(&output, b"generated-value").unwrap();
          let output_tree = output_root.join("generated-tree");
          std::fs::create_dir(&output_tree).unwrap();
          std::fs::write(output_tree.join("owned-child"), b"owned-value").unwrap();

          let values = kbuild_unowned_initial_namespace(
              &output_root,
              &BTreeSet::from([output.clone(), output_tree.clone()]),
              &BTreeSet::from([output_tree.clone()]),
          )
          .unwrap();
        assert!(matches!(
            values.get(&seed),
            Some(ExternalInitialInputValue::Directory { .. })
        ));
        assert!(matches!(
            values.get(&seed.join("value")),
            Some(ExternalInitialInputValue::File { bytes, .. }) if bytes == b"seed-value"
        ));
        assert_eq!(
            values.get(&seed.join("link")),
            Some(&ExternalInitialInputValue::Symlink {
                target: b"value".to_vec(),
            })
        );
          assert!(!values.contains_key(&output));
          assert!(!values.contains_key(&output_tree));
          assert!(!values.contains_key(&output_tree.join("owned-child")));
    }

    #[cfg(unix)]
    #[test]
    fn generated_input_provenance_censuses_directory_effect_epochs() {
        let temp = tempfile::tempdir().unwrap();
        let output_root = temp.path().join("private-output-root-token");
        let directory = output_root.join("private-directory-path-token");
        std::fs::create_dir_all(&directory).unwrap();
        let first = directory.join("first");
        let second = directory.join("second");
        std::fs::write(&first, b"first").unwrap();
        std::fs::write(&second, b"second").unwrap();
        let (directory_object, _) = witness_current_kbuild_directory_output(&directory).unwrap();
        let mutation = |owner, stream_ordinal, path: &Path| {
            (
                KbuildProcessOwner::Action(owner),
                KbuildMutationCandidate {
                    process: owner + 1,
                    stream_ordinal,
                    syscall_index: stream_ordinal,
                    kind: KbuildMutationCandidateKind::CreateOrTruncateOpen,
                    object: Some(KbuildOutputObjectIdentity {
                        device: 20 + owner,
                        inode: 30 + owner,
                        mount_id: 40,
                    }),
                    path: path.to_path_buf(),
                    relative: os_bytes(path.strip_prefix(&output_root).unwrap().as_os_str()),
                },
            )
        };
        let mutations = vec![mutation(0, 2, &first), mutation(1, 5, &second)];
        let candidates = BTreeMap::from([
            (
                KbuildProcessOwner::Action(0),
                BTreeSet::from([first.clone()]),
            ),
            (
                KbuildProcessOwner::Action(1),
                BTreeSet::from([second.clone()]),
            ),
            (KbuildProcessOwner::Action(2), BTreeSet::new()),
        ]);
        let final_outputs = KbuildFinalOutputValueSeal {
            graph_digest: [1; 32],
            stream_digest: [2; 32],
            assignment_digest: [3; 32],
            mutation_attribution_digest: [4; 32],
            value_digest: [5; 32],
            declared_output_observations: 0,
            close_observations: 0,
            descriptor_replacement_observations: 0,
            exit_observations: 0,
            post_capture_rename_observations: 0,
            post_capture_directory_observations: 0,
            post_capture_mode_change_observations: 0,
            post_capture_shared_mapping_observations: 0,
            post_capture_symlink_creation_observations: 0,
            persistent_outputs: 0,
            outputs: Vec::new(),
        };
        let declared = BTreeMap::from([(0, Vec::new()), (1, Vec::new()), (2, Vec::new())]);
        let observation = KbuildInputObservation {
            owner: KbuildProcessOwner::Action(2),
            process: 3,
            ordinal: 0,
            stream_ordinal: 4,
            syscall_index: Some(4),
            class: KbuildInputObservationClass::Directory,
            path: directory.clone(),
            object: KbuildInputObjectIdentity {
                device: directory_object.device,
                inode: directory_object.inode,
                mount_id: Some(directory_object.mount_id),
                kind: KbuildInputObjectKind::Directory,
            },
            value: KbuildObservedInputValue::Directory {
                entries: 4,
                digest: [6; 32],
                listing_digest: captured_directory_listing_digest(&[
                    b"first".to_vec(),
                    b"second".to_vec(),
                ])
                .unwrap(),
            },
        };
        let prove_many =
            |observations: &[KbuildInputObservation],
             mutations: &[(KbuildProcessOwner, KbuildMutationCandidate)],
             candidates: &BTreeMap<KbuildProcessOwner, BTreeSet<PathBuf>>,
             anchors: &BTreeMap<u64, KbuildDirectoryPathAnchor>| {
                let mutation_index = KbuildInputMutationIndex::from_events(&mutations).unwrap();
                let directory_effect_paths =
                    mutation_index.directory_effects.keys().cloned().collect();
                let census = kbuild_input_value_census(
                    [1; 32],
                    [2; 32],
                    [3; 32],
                    observations,
                    candidates,
                    &directory_effect_paths,
                )
                .unwrap();
                let provenance = kbuild_input_provenance_partition(
                    [1; 32],
                    [2; 32],
                    [3; 32],
                    &census,
                    [4; 32],
                    observations,
                    mutations,
                )
                .unwrap();
                kbuild_generated_input_provenance(
                    [1; 32],
                    [2; 32],
                    [3; 32],
                    &census,
                    &provenance,
                    [4; 32],
                    test_directory_member_retention(
                        [1; 32],
                        [2; 32],
                        [3; 32],
                        &census,
                        observations,
                        &[b"first".to_vec(), b"second".to_vec()],
                    ),
                    anchors,
                    observations,
                    mutations,
                    &KbuildProcessCausality::default(),
                    &declared,
                    &final_outputs,
                    &output_root,
                )
                .unwrap()
            };
        let prove_with =
            |observation: &KbuildInputObservation,
             mutations: &[(KbuildProcessOwner, KbuildMutationCandidate)],
             candidates: &BTreeMap<KbuildProcessOwner, BTreeSet<PathBuf>>| {
                let observations = std::slice::from_ref(observation);
                let anchors = test_directory_path_anchors(observations);
                prove_many(observations, mutations, candidates, &anchors)
            };
        let prove =
            |observation: &KbuildInputObservation| prove_with(observation, &mutations, &candidates);

        let seal = prove(&observation);
        assert_eq!(
            seal.directory_member_retention().directory_observations(),
            1
        );
        assert_eq!(seal.directory_member_retention().member_names(), 2);
        assert_eq!(seal.directory_members.get(&0).unwrap().len(), 2);
        assert_eq!(seal.directory_anchors.len(), 1);
        let checkpoints = seal.generated_directory_checkpoints();
        assert_eq!(checkpoints.observations(), 1);
        assert_eq!(checkpoints.distinct_directories(), 1);
        assert_eq!(checkpoints.consumer_actions(), 1);
        assert_eq!(checkpoints.member_names(), 2);
        assert_eq!(checkpoints.effect_batches(), 2);
        assert_eq!(checkpoints.effects_before_observations(), 0);
        assert_eq!(checkpoints.observations_before_effects(), 0);
        assert_eq!(checkpoints.causally_unresolved_effects(), 2);
        assert_eq!(checkpoints.before_only_external_action_relations(), 0);
        assert_eq!(checkpoints.after_only_external_action_relations(), 0);
        assert_eq!(checkpoints.unresolved_external_action_relations(), 2);
        assert_eq!(checkpoints.straddling_external_action_relations(), 0);
        assert_eq!(checkpoints.self_effect_batches(), 0);
        assert_eq!(checkpoints.analyzer_effect_batches(), 0);
        assert_eq!(checkpoints.candidate_action_boundary_observations(), 0);
        assert_eq!(seal.directory_checkpoints.len(), 1);
        assert_eq!(seal.directory_checkpoints[0].consumer_action_index, 2);
        assert_eq!(seal.directory_checkpoints[0].observation_ordinal, 0);
        assert_eq!(seal.directory_checkpoints[0].members.len(), 2);
        assert!(seal.directory_checkpoints[0].before_actions.is_empty());
        assert!(seal.directory_checkpoints[0].after_actions.is_empty());
        assert_eq!(
            seal.directory_checkpoints[0].unresolved_actions,
            BTreeSet::from([0, 1])
        );
        assert!(!seal.directory_checkpoints[0].has_self_effect);
        assert!(!seal.directory_checkpoints[0].has_analyzer_effect);
        assert!(!seal.directory_checkpoints[0].candidate_action_boundary);
        assert_eq!(seal.directory_epoch_observations(), 1);
        assert_eq!(seal.analyzer_directory_epoch_observations(), 0);
        assert_eq!(seal.action_directory_epoch_observations(), 1);
        assert_eq!(seal.pre_effect_directory_epoch_observations(), 0);
        assert_eq!(seal.intermediate_directory_epoch_observations(), 1);
        assert_eq!(seal.post_effect_directory_epoch_observations(), 0);
        assert_eq!(seal.self_effect_directory_epoch_observations(), 0);
        assert_eq!(seal.distinct_directory_epoch_paths(), 1);
        let public_seal = serde_json::to_string(&seal.seal).unwrap();
        assert!(!public_seal.contains("private-output-root-token"));
        assert!(!public_seal.contains("private-directory-path-token"));

        let anchor = KbuildDirectoryPathAnchor {
            process: observation.process,
            descriptor: 9,
            path: observation.path.clone(),
            object: observation.object,
            open_syscall_index: 1,
            open_stream_ordinal: 1,
        };
        let anchored = prove_many(
            std::slice::from_ref(&observation),
            &mutations,
            &candidates,
            &BTreeMap::from([(0, anchor)]),
        );
        assert_eq!(anchored.directory_anchors.len(), 1);
        assert_eq!(
            anchored
                .directory_causal_census()
                .path_anchor_proved_observations(),
            1
        );
        assert_eq!(
            anchored
                .directory_causal_census()
                .path_anchor_unproved_paths(),
            0
        );
        assert_ne!(anchored.provenance_digest(), seal.provenance_digest());
        assert!(!serde_json::to_string(&anchored.seal)
            .unwrap()
            .contains("private-directory-path-token"));

        let mut pre_effect_observation = observation.clone();
        pre_effect_observation.stream_ordinal = 1;
        let pre_effect = prove(&pre_effect_observation);
        assert_eq!(pre_effect.pre_effect_directory_epoch_observations(), 1);
        assert_eq!(pre_effect.intermediate_directory_epoch_observations(), 0);
        assert_eq!(pre_effect.post_effect_directory_epoch_observations(), 0);

        let mut analyzer_bootstrap = pre_effect_observation;
        analyzer_bootstrap.owner = KbuildProcessOwner::Analyzer;
        let analyzer_bootstrap = prove(&analyzer_bootstrap);
        assert_eq!(analyzer_bootstrap.directory_epoch_observations(), 1);
        assert_eq!(
            analyzer_bootstrap.analyzer_directory_epoch_observations(),
            1
        );
        assert_eq!(
            analyzer_bootstrap.pre_effect_directory_epoch_observations(),
            1
        );

        let mut analyzer_intermediate = observation.clone();
        analyzer_intermediate.owner = KbuildProcessOwner::Analyzer;
        let analyzer_intermediate = prove(&analyzer_intermediate);
        assert_eq!(analyzer_intermediate.directory_epoch_observations(), 1);
        assert_eq!(
            analyzer_intermediate.intermediate_directory_epoch_observations(),
            1
        );

        let mut post_effect = observation.clone();
        post_effect.stream_ordinal = 6;
        let post_effect = prove(&post_effect);
        assert_eq!(post_effect.pre_effect_directory_epoch_observations(), 0);
        assert_eq!(post_effect.intermediate_directory_epoch_observations(), 0);
        assert_eq!(post_effect.post_effect_directory_epoch_observations(), 1);

        let mut self_effect = observation.clone();
        self_effect.owner = KbuildProcessOwner::Action(1);
        let self_effect = prove(&self_effect);
        assert_eq!(self_effect.intermediate_directory_epoch_observations(), 1);
        assert_eq!(self_effect.self_effect_directory_epoch_observations(), 1);

        let mut mixed_cross_owner = observation.clone();
        mixed_cross_owner.ordinal = 0;
        mixed_cross_owner.stream_ordinal = 1;
        let mut analyzer_observation = observation.clone();
        analyzer_observation.owner = KbuildProcessOwner::Analyzer;
        analyzer_observation.ordinal = 1;
        let mut mixed_self_effect = observation.clone();
        mixed_self_effect.owner = KbuildProcessOwner::Action(1);
        mixed_self_effect.ordinal = 2;
        mixed_self_effect.stream_ordinal = 6;
        let mixed_observations = [mixed_cross_owner, analyzer_observation, mixed_self_effect];
        let mixed_anchors = test_directory_path_anchors(&mixed_observations);
        let mixed = prove_many(&mixed_observations, &mutations, &candidates, &mixed_anchors);
        assert_eq!(mixed.directory_epoch_observations(), 3);
        assert_eq!(
            mixed.directory_member_retention().directory_observations(),
            3
        );
        assert_eq!(mixed.directory_member_retention().member_names(), 6);
        assert_eq!(mixed.analyzer_directory_epoch_observations(), 1);
        assert_eq!(mixed.action_directory_epoch_observations(), 2);
        assert_eq!(mixed.pre_effect_directory_epoch_observations(), 1);
        assert_eq!(mixed.intermediate_directory_epoch_observations(), 1);
        assert_eq!(mixed.post_effect_directory_epoch_observations(), 1);
        assert_eq!(mixed.self_effect_directory_epoch_observations(), 1);

        let shifted_mutations = vec![mutation(0, 3, &first), mutation(1, 5, &second)];
        let shifted_observations = [observation.clone()];
        let shifted_anchors = test_directory_path_anchors(&shifted_observations);
        let shifted = prove_many(
            &shifted_observations,
            &shifted_mutations,
            &candidates,
            &shifted_anchors,
        );
        assert_eq!(shifted.directory_epoch_observations(), 1);
        assert_eq!(shifted.intermediate_directory_epoch_observations(), 1);
        assert_ne!(shifted.provenance_digest(), seal.provenance_digest());

        let same_owner_mutations = vec![mutation(2, 2, &first)];
        let same_owner_candidates = BTreeMap::from([
            (KbuildProcessOwner::Action(0), BTreeSet::new()),
            (KbuildProcessOwner::Action(1), BTreeSet::new()),
            (
                KbuildProcessOwner::Action(2),
                BTreeSet::from([first.clone()]),
            ),
        ]);
        let mut same_owner_observation = observation.clone();
        same_owner_observation.owner = KbuildProcessOwner::Action(2);
        same_owner_observation.stream_ordinal = 3;
        let same_owner = prove_with(
            &same_owner_observation,
            &same_owner_mutations,
            &same_owner_candidates,
        );
        assert_eq!(same_owner.directory_epoch_observations(), 1);
        assert_eq!(same_owner.intermediate_directory_epoch_observations(), 0);
        assert_eq!(same_owner.post_effect_directory_epoch_observations(), 1);
        assert_eq!(same_owner.self_effect_directory_epoch_observations(), 1);

        let directory_mutation = |stream_ordinal, kind| {
            (
                KbuildProcessOwner::Action(2),
                KbuildMutationCandidate {
                    process: 3,
                    stream_ordinal,
                    syscall_index: stream_ordinal,
                    kind,
                    object: None,
                    path: directory.clone(),
                    relative: os_bytes(directory.strip_prefix(&output_root).unwrap().as_os_str()),
                },
            )
        };
        let directory_lifecycle_mutations = vec![
            directory_mutation(2, KbuildMutationCandidateKind::DirectoryCreation),
            directory_mutation(5, KbuildMutationCandidateKind::PathModeChange),
        ];
        let directory_candidates = BTreeMap::from([
            (KbuildProcessOwner::Action(0), BTreeSet::new()),
            (KbuildProcessOwner::Action(1), BTreeSet::new()),
            (
                KbuildProcessOwner::Action(2),
                BTreeSet::from([directory.clone()]),
            ),
        ]);
        let mut directory_lifecycle_observation = observation;
        directory_lifecycle_observation.owner = KbuildProcessOwner::Action(2);
        let directory_lifecycle = prove_with(
            &directory_lifecycle_observation,
            &directory_lifecycle_mutations,
            &directory_candidates,
        );
        assert_eq!(directory_lifecycle.directory_epoch_observations(), 1);
        assert_eq!(
            directory_lifecycle.intermediate_directory_epoch_observations(),
            0
        );
        assert_eq!(
            directory_lifecycle.post_effect_directory_epoch_observations(),
            1
        );
        assert_eq!(
            directory_lifecycle.self_effect_directory_epoch_observations(),
            1
        );

        let metadata_only_mutations = vec![directory_mutation(
            5,
            KbuildMutationCandidateKind::PathModeChange,
        )];
        directory_lifecycle_observation.owner = KbuildProcessOwner::Action(0);
        directory_lifecycle_observation.stream_ordinal = 6;
        let metadata_only = prove_with(
            &directory_lifecycle_observation,
            &metadata_only_mutations,
            &directory_candidates,
        );
        assert_eq!(metadata_only.directory_epoch_observations(), 0);
        assert_eq!(metadata_only.distinct_directory_epoch_paths(), 0);
    }

