    #[cfg(unix)]
    fn test_directory_member_retention(
        graph_digest: [u8; 32],
        stream_digest: [u8; 32],
        assignment_digest: [u8; 32],
        census: &KbuildInputValueCensusSeal,
        observations: &[KbuildInputObservation],
        member_names: &[Vec<u8>],
    ) -> KbuildDirectoryMemberRetention {
        let members = observations
            .iter()
            .filter_map(|observation| {
                matches!(
                    observation.value,
                    KbuildObservedInputValue::Directory { .. }
                )
                .then(|| (observation.ordinal, member_names.to_vec()))
            })
            .collect();
        kbuild_directory_member_retention(
            graph_digest,
            stream_digest,
            assignment_digest,
            census,
            observations,
            &members,
        )
        .unwrap()
    }

    #[cfg(unix)]
    fn test_directory_path_anchors(
        observations: &[KbuildInputObservation],
    ) -> BTreeMap<u64, KbuildDirectoryPathAnchor> {
        observations
            .iter()
            .filter_map(|observation| {
                if !matches!(
                    observation.value,
                    KbuildObservedInputValue::Directory { .. }
                ) {
                    return None;
                }
                let syscall_index = observation.syscall_index?;
                Some((
                    observation.ordinal,
                    KbuildDirectoryPathAnchor {
                        process: observation.process,
                        descriptor: 3,
                        path: observation.path.clone(),
                        object: observation.object,
                        open_syscall_index: syscall_index.checked_sub(1)?,
                        open_stream_ordinal: observation.stream_ordinal.checked_sub(1)?,
                    },
                ))
            })
            .collect()
    }

