    #[cfg(unix)]
    #[test]
    fn socket_create_requires_exact_local_stream_descriptor_state() {
        let identity = CapturedDescriptorIdentity {
            target: b"socket:[123]".to_vec(),
            device: 9,
            inode: 123,
            kind: CapturedDescriptorKind::Socket,
        };
        let mut attempt = CapturedSocketCreateAttempt {
            syscall_index: 7,
            request: CapturedSocketCreateRequest {
                domain: libc::AF_UNIX,
                socket_type: libc::SOCK_STREAM | libc::SOCK_CLOEXEC | libc::SOCK_NONBLOCK,
                protocol: 0,
            },
            outcome: CapturedSocketCreateOutcome::Created {
                descriptor: 5,
                identity: identity.clone(),
                mount_id: 17,
            },
        };
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        let class = kbuild_record_class(&event).unwrap().1;
        assert_eq!(class, KbuildRecordClass::DescriptorStateAttempt);
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );

        attempt.request.domain = libc::AF_INET;
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.domain = libc::AF_UNIX;
        attempt.request.socket_type = libc::SOCK_DGRAM;
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.socket_type = libc::SOCK_STREAM | (1 << 30);
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.socket_type = libc::SOCK_STREAM | libc::SOCK_CLOEXEC;
        attempt.request.protocol = 1;
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.protocol = 0;

        if let CapturedSocketCreateOutcome::Created { descriptor, .. } = &mut attempt.outcome {
            *descriptor = -1;
        } else {
            unreachable!();
        }
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        if let CapturedSocketCreateOutcome::Created {
            descriptor,
            identity,
            ..
        } = &mut attempt.outcome
        {
            *descriptor = 5;
            identity.target = b"socket:[124]".to_vec();
        } else {
            unreachable!();
        }
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        if let CapturedSocketCreateOutcome::Created { identity, .. } = &mut attempt.outcome {
            identity.target = b"socket:[0123]".to_vec();
        } else {
            unreachable!();
        }
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        if let CapturedSocketCreateOutcome::Created {
            identity: result_identity,
            mount_id,
            ..
        } = &mut attempt.outcome
        {
            *result_identity = identity;
            *mount_id = 0;
        } else {
            unreachable!();
        }
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());

        attempt.outcome = CapturedSocketCreateOutcome::Failed(libc::EMFILE);
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptFailed(class))
        );
        attempt.outcome = CapturedSocketCreateOutcome::Failed(0);
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.outcome = CapturedSocketCreateOutcome::Terminated;
        let event = ProcessCaptureStreamEvent::SocketCreateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("terminated while its syscall was in flight"));
    }

    #[cfg(unix)]
    #[test]
    fn socket_connect_requires_an_external_endpoint_witness() {
        let identity = CapturedDescriptorIdentity {
            target: b"socket:[123]".to_vec(),
            device: 9,
            inode: 123,
            kind: CapturedDescriptorKind::Socket,
        };
        let path = b"/missing/socket".to_vec();
        let address_length = std::mem::size_of::<libc::sockaddr_un>() as u32;
        let mut attempt = CapturedSocketConnectAttempt {
            syscall_index: 8,
            request: CapturedSocketConnectRequest {
                descriptor: 5,
                identity: identity.clone(),
                mount_id: 17,
                address_length,
                address: CapturedUnixSocketAddress::Pathname {
                    path: path.clone(),
                    terminated: true,
                },
            },
            outcome: CapturedSocketConnectOutcome::Failed {
                errno: libc::ENOENT,
                identity: identity.clone(),
                mount_id: 17,
            },
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        let class = kbuild_record_class(&event).unwrap().1;
        assert_eq!(class, KbuildRecordClass::DescriptorStateAttempt);
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("no freshness witness"));

        attempt.request.address = CapturedUnixSocketAddress::Pathname {
            path: b"/var/run/nscd/socket".to_vec(),
            terminated: true,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptFailed(class))
        );
        attempt.request.address = CapturedUnixSocketAddress::Pathname {
            path: path.clone(),
            terminated: true,
        };

        let CapturedSocketConnectOutcome::Failed { errno, .. } = &mut attempt.outcome else {
            unreachable!();
        };
        *errno = libc::EINPROGRESS;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.outcome = CapturedSocketConnectOutcome::Connected {
            identity: identity.clone(),
            mount_id: 17,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());

        attempt.outcome = CapturedSocketConnectOutcome::Failed {
            errno: libc::ENOENT,
            identity: identity.clone(),
            mount_id: 18,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.outcome = CapturedSocketConnectOutcome::Failed {
            errno: libc::ENOENT,
            identity: CapturedDescriptorIdentity {
                target: b"socket:[124]".to_vec(),
                inode: 124,
                ..identity.clone()
            },
            mount_id: 17,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());

        attempt.outcome = CapturedSocketConnectOutcome::Failed {
            errno: libc::ENOENT,
            identity: identity.clone(),
            mount_id: 17,
        };
        attempt.request.address_length = std::mem::size_of::<libc::sa_family_t>() as u32;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.address_length = address_length;
        attempt.request.address = CapturedUnixSocketAddress::Pathname {
            path: b"missing\0socket".to_vec(),
            terminated: true,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.address = CapturedUnixSocketAddress::Abstract {
            name: vec![0; usize::try_from(address_length).unwrap()],
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.address = CapturedUnixSocketAddress::Unnamed;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());

        attempt.request.address_length = address_length;
        attempt.request.address = CapturedUnixSocketAddress::Pathname {
            path,
            terminated: true,
        };
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("no freshness witness"));
        attempt.request.descriptor = -1;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.descriptor = 5;
        attempt.request.mount_id = 0;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        attempt.request.mount_id = 17;
        attempt.outcome = CapturedSocketConnectOutcome::Terminated;
        let event = ProcessCaptureStreamEvent::SocketConnectAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("terminated while its syscall was in flight"));
    }

    #[cfg(unix)]
    #[test]
    fn descriptor_duplication_outcomes_require_exact_topology() {
        let source = CapturedDescriptorIdentity {
            target: b"pipe:[123]".to_vec(),
            device: 9,
            inode: 123,
            kind: CapturedDescriptorKind::Fifo,
        };
        let mut duplicate = CapturedDup2Attempt {
            syscall_index: 7,
            request: CapturedDup2Request {
                system_call: CapturedDescriptorDuplicationSystemCall::Dup2,
                source_descriptor: 3,
                source_identity: Some(source.clone()),
                source_mount_id: Some(17),
                target_descriptor: 4,
                target_identity: None,
                target_mount_id: None,
            },
            outcome: CapturedDup2Outcome::Duplicated {
                descriptor: 4,
                identity: source,
                mount_id: 17,
                replaced_file_value: None,
            },
        };
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        let class = kbuild_record_class(&event).unwrap().1;
        assert_eq!(class, KbuildRecordClass::DescriptorStateAttempt);
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );

        duplicate.request.target_identity = Some(CapturedDescriptorIdentity {
            target: b"/dev/shm/output/replaced".to_vec(),
            device: 20,
            inode: 21,
            kind: CapturedDescriptorKind::RegularFile,
        });
        duplicate.request.target_mount_id = Some(22);
        let CapturedDup2Outcome::Duplicated {
            replaced_file_value,
            ..
        } = &mut duplicate.outcome
        else {
            unreachable!();
        };
        *replaced_file_value = Some(CapturedMappedFileValue::WholeFile {
            bytes: 5,
            digest: [23; 32],
            mode: libc::S_IFREG | 0o644,
        });
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );
        let CapturedDup2Outcome::Duplicated {
            replaced_file_value,
            ..
        } = &mut duplicate.outcome
        else {
            unreachable!();
        };
        *replaced_file_value = None;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        duplicate.request.target_identity = None;
        duplicate.request.target_mount_id = None;

        let CapturedDup2Outcome::Duplicated { descriptor, .. } = &mut duplicate.outcome else {
            unreachable!();
        };
        *descriptor = 5;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());

        duplicate.request.system_call = CapturedDescriptorDuplicationSystemCall::Dup;
        duplicate.request.target_descriptor = 5;
        duplicate.request.target_identity = None;
        duplicate.request.target_mount_id = None;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );

        duplicate.request.target_descriptor = 4;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        duplicate.request.target_descriptor = 5;

        duplicate.request.system_call = CapturedDescriptorDuplicationSystemCall::Dup3;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );
        duplicate.request.target_descriptor = 3;
        let CapturedDup2Outcome::Duplicated { descriptor, .. } = &mut duplicate.outcome else {
            unreachable!();
        };
        *descriptor = 3;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert!(kbuild_record_outcome(&event, class).is_err());
        duplicate.request.target_descriptor = 5;
        let CapturedDup2Outcome::Duplicated { descriptor, .. } = &mut duplicate.outcome else {
            unreachable!();
        };
        *descriptor = 5;

        duplicate.outcome = CapturedDup2Outcome::Failed(libc::EBADF);
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptFailed(class))
        );

        duplicate.outcome = CapturedDup2Outcome::Terminated;
        let event = ProcessCaptureStreamEvent::Dup2Attempt {
            process: 10,
            attempt: &duplicate,
        };
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("terminated while its syscall was in flight"));
    }

    #[cfg(unix)]
    #[test]
    fn signal_state_outcomes_are_modeled_after_inherited_state_policy() {
        let mut attempt = CapturedSignalStateAttempt {
            syscall_index: 6,
            request: CapturedSignalStateRequest::Mask {
                operation: libc::SIG_SETMASK,
                mask: None,
                old_mask_is_null: false,
                signal_set_bytes: 8,
            },
            outcome: CapturedSignalStateOutcome::MaskReturned {
                previous: Some(vec![0; 8]),
            },
        };
        let event = ProcessCaptureStreamEvent::SignalStateAttempt {
            process: 10,
            attempt: &attempt,
        };
        let class = kbuild_record_class(&event).unwrap().1;
        assert_eq!(class, KbuildRecordClass::ProcessStateAttempt);
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptSucceeded(class))
        );

        attempt.outcome = CapturedSignalStateOutcome::Failed(libc::EINVAL);
        let event = ProcessCaptureStreamEvent::SignalStateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert_eq!(
            kbuild_record_outcome(&event, class).unwrap(),
            Some(KbuildRecordOutcome::AttemptFailed(class))
        );

        attempt.outcome = CapturedSignalStateOutcome::Terminated;
        let event = ProcessCaptureStreamEvent::SignalStateAttempt {
            process: 10,
            attempt: &attempt,
        };
        assert!(kbuild_record_outcome(&event, class)
            .unwrap_err()
            .to_string()
            .contains("terminated while its syscall was in flight"));
    }

