    #[cfg(unix)]
    #[test]
    fn measured_partial_graph_denominators_reject() {
        let mut coverage = KbuildGraphCaptureCoverage {
            process_lifecycles_observed: 34_779,
            stream_records_observed: 0,
            stream_records_classified: 0,
            command_boundaries_observed: 6_610,
            command_boundaries_captured: 4_378,
            logical_actions_captured: 4_378,
            receipts_discovered: 4_803,
            receipts_ingested: 4_378,
            receiptless_actions: 0,
            persistent_writes_observed: 8_772,
            persistent_writes_attributed: 8_772,
            unmodeled_observations: 0,
        };
        let error = coverage.require_closed().unwrap_err();
        assert!(error
            .to_string()
            .contains("observed command boundaries coverage is 6610/4378"));

        coverage.command_boundaries_observed = 4_378;
        let error = coverage.require_closed().unwrap_err();
        assert!(error
            .to_string()
            .contains("discovered receipts coverage is 4803/4378"));
    }

