    async fn replay_counts(
        snapshot: ExternalAnalysisSnapshot,
        cache_root: &Path,
    ) -> (usize, usize) {
        let cache = Arc::new(
            ActionCache::with_disk(CacheConfig {
                cache_root: cache_root.join("actions"),
                max_size: 0,
                ttl_seconds: 0,
            })
            .unwrap(),
        );
        let engine = ExternalReplayEngine::with_cas(
            snapshot,
            cache,
            ResourceManager::new().unwrap(),
            Arc::new(CasStore::new(cache_root).unwrap()),
        )
        .unwrap();
        match engine.replay().await.unwrap() {
            ExternalReplayStatus::Complete {
                cache_hits,
                executed,
            } => (cache_hits, executed),
            ExternalReplayStatus::AnalysisMismatch { .. } => {
                panic!("unexpected analysis mismatch")
            }
        }
    }

    #[test]
    fn receipt_and_observer_build_one_snapshot() {
        let temp = tempfile::tempdir().unwrap();
        let src = temp.path().join("src");
        let obj = temp.path().join("obj");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::create_dir_all(&obj).unwrap();
        std::fs::write(src.join("input"), b"input\n").unwrap();
        std::fs::write(src.join("Makefile"), b"all:\n").unwrap();
        std::fs::write(obj.join(".config"), b"CONFIG_Feature=y\n").unwrap();
        std::fs::write(obj.join("out"), b"output\n").unwrap();
        let receipt_path = obj.join(".out.cmd");
        let saved_command = format!("cp {} out", src.join("input").display());
        std::fs::write(
            &receipt_path,
            format!(
                "savedcmd_out := {saved_command}\nsource_out := ../src/input\n\
                 deps_out := ../src/input $(wildcard include/config/Feature)\n"
            ),
        )
        .unwrap();
        let invocation = CapturedInvocation {
            executable: PathBuf::from("/bin/sh"),
            argv: vec![
                b"/bin/sh".to_vec(),
                b"-c".to_vec(),
                format!(
                    "{saved_command}; printf receipt > {}",
                    receipt_path.display()
                )
                .into_bytes(),
            ],
            environment: vec![CapturedEnvironmentVariable {
                name: b"PATH".to_vec(),
                value: b"/usr/bin:/bin".to_vec(),
            }],
            working_directory: obj.clone(),
        };
        let capture = KbuildActionCapture {
            schema: KBUILD_CAPTURE_SCHEMA.to_string(),
            analyzer: CapturedInvocation {
                executable: PathBuf::from("/usr/bin/make"),
                argv: vec![b"make".to_vec(), b"out".to_vec()],
                environment: Vec::new(),
                working_directory: src.clone(),
            },
            commands: vec![invocation],
            receipt_path: Some(receipt_path.clone()),
            action_inputs: vec![CapturedInput {
                path: src.join("input"),
                kind: ExternalInputKind::File,
            }],
            persistent_outputs: vec![obj.join("out"), receipt_path.clone()],
            analysis_inputs: vec![CapturedInput {
                path: src.join("Makefile"),
                kind: ExternalInputKind::File,
            }],
            requested_goals: vec![b"out".to_vec()],
        };
        let capture: KbuildActionCapture =
            serde_json::from_slice(&serde_json::to_vec(&capture).unwrap()).unwrap();
        let mut legacy_capture = capture.clone();
        legacy_capture.schema = "org.rushbuild.kbuild-observed-action.v2".to_string();
        let error = snapshot_from_kbuild_capture(
            legacy_capture,
            &src,
            &obj,
            ExternalSignalState::default(),
            0o022,
            external_credential_state(&observed_credentials()).unwrap(),
        )
        .unwrap_err();
        assert!(error
            .to_string()
            .contains("unsupported Kbuild capture schema"));
        let mut empty_capture = capture.clone();
        empty_capture.commands.clear();
        let error = snapshot_from_kbuild_capture(
            empty_capture,
            &src,
            &obj,
            ExternalSignalState::default(),
            0o022,
            ExternalCredentialState::default(),
        )
        .unwrap_err();
        assert!(error
            .to_string()
            .contains("captured action has no commands"));
        let snapshot = snapshot_from_kbuild_capture(
            capture,
            &src,
            &obj,
            ExternalSignalState::default(),
            0o022,
            ExternalCredentialState::default(),
        )
        .unwrap();
        assert_eq!(snapshot.graph.actions.len(), 1);
        assert_eq!(snapshot.graph.actions[0].config_deps, ["CONFIG_Feature"]);
        assert_eq!(snapshot.graph.actions[0].outputs.len(), 2);
        assert_eq!(
            snapshot.graph.actions[0].outputs[0].mode,
            permission_mode(&std::fs::metadata(obj.join("out")).unwrap())
        );
        assert_eq!(
            snapshot.graph.actions[0].outputs[1].mode,
            permission_mode(&std::fs::metadata(&receipt_path).unwrap())
        );
        assert!(!snapshot.analysis_manifest.is_empty());
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn compound_action_replays_commands_in_order_and_then_hits_cache() {
        let temp = tempfile::tempdir().unwrap();
        let src = temp.path().join("src");
        let obj = temp.path().join("obj");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::create_dir_all(&obj).unwrap();
        let output = obj.join("out");
        let sequence = obj.join("sequence");
        let receipt = obj.join(".out.cmd");
        let first_directory = obj.join("first");
        let second_directory = obj.join("second");
        std::fs::create_dir_all(&first_directory).unwrap();
        std::fs::create_dir_all(&second_directory).unwrap();
        let input = second_directory.join("input");
        std::fs::write(&input, b"final\n").unwrap();
        std::fs::write(src.join("Makefile"), b"all:\n").unwrap();
        std::fs::write(obj.join(".config"), b"").unwrap();
        std::fs::write(&output, b"final\n").unwrap();
        std::fs::write(&sequence, b"first\nsecond\n").unwrap();
        let saved_command = format!("cp input {}", output.display());
        let receipt_bytes =
            format!("savedcmd_out := {saved_command}\nsource_out := input\ndeps_out := input\n");
        std::fs::write(&receipt, &receipt_bytes).unwrap();
        let invocation =
            |script: String, step: &[u8], working_directory: PathBuf| CapturedInvocation {
                executable: PathBuf::from("/bin/sh"),
                argv: vec![b"sh".to_vec(), b"-c".to_vec(), script.into_bytes()],
                environment: vec![CapturedEnvironmentVariable {
                    name: b"STEP".to_vec(),
                    value: step.to_vec(),
                }],
                working_directory,
            };
        let capture = KbuildActionCapture {
            schema: KBUILD_CAPTURE_SCHEMA.to_string(),
            analyzer: CapturedInvocation {
                executable: PathBuf::from("/usr/bin/make"),
                argv: vec![b"make".to_vec(), b"out".to_vec()],
                environment: Vec::new(),
                working_directory: src.clone(),
            },
            commands: vec![
                invocation(
                    format!(
                        "test \"$PWD\" = '{}' && printf '%s\\n' \"$STEP\" >> {}",
                        first_directory.display(),
                        sequence.display()
                    ),
                    b"first",
                    first_directory,
                ),
                invocation(
                    format!(
                        "test \"$PWD\" = '{}' && printf '%s\\n' \"$STEP\" >> {}; \
                         {saved_command}; printf '{}' > {}",
                        second_directory.display(),
                        sequence.display(),
                        receipt_bytes.replace('\'', "'\\''"),
                        receipt.display()
                    ),
                    b"second",
                    second_directory,
                ),
            ],
            receipt_path: Some(receipt.clone()),
            action_inputs: vec![CapturedInput {
                path: input,
                kind: ExternalInputKind::File,
            }],
            persistent_outputs: vec![output.clone(), sequence.clone(), receipt.clone()],
            analysis_inputs: vec![CapturedInput {
                path: src.join("Makefile"),
                kind: ExternalInputKind::File,
            }],
            requested_goals: vec![b"out".to_vec()],
        };
        let snapshot = snapshot_from_kbuild_capture(
            capture,
            &src,
            &obj,
            ExternalSignalState::default(),
            0o022,
            external_credential_state(&observed_credentials()).unwrap(),
        )
        .unwrap();
        assert_eq!(snapshot.graph.actions[0].commands.len(), 2);
        assert_ne!(
            snapshot.graph.actions[0].commands[0].environment,
            snapshot.graph.actions[0].commands[1].environment
        );
        assert_ne!(
            snapshot.graph.actions[0].commands[0].working_directory,
            snapshot.graph.actions[0].commands[1].working_directory
        );

        for path in [&output, &sequence, &receipt] {
            std::fs::remove_file(path).unwrap();
        }
        let cache = temp.path().join("cache");
        assert_eq!(replay_counts(snapshot.clone(), &cache).await, (0, 1));
        assert_eq!(std::fs::read(&sequence).unwrap(), b"first\nsecond\n");
        assert_eq!(std::fs::read(&output).unwrap(), b"final\n");
        assert_eq!(std::fs::read(&receipt).unwrap(), receipt_bytes.as_bytes());

        for path in [&output, &sequence, &receipt] {
            std::fs::remove_file(path).unwrap();
        }
        assert_eq!(replay_counts(snapshot, &cache).await, (1, 0));
        assert_eq!(std::fs::read(&sequence).unwrap(), b"first\nsecond\n");
        assert_eq!(std::fs::read(&output).unwrap(), b"final\n");
        assert_eq!(std::fs::read(&receipt).unwrap(), receipt_bytes.as_bytes());
    }

